3 边缘检测边缘检测是一个常见的屏幕后处理效果，用于实现描边效果。常用的边缘检测算子有：
在进行边缘检测时，我们需要对每个像素分别进行一次卷积计算，得到两个方向上的梯度值 $G_x$ 和 $G_y$，而整体的梯度可按下面的公式计算而得：$$G &#x3D; \sqrt{G_x^2 + G_y^2}$$由于上述计算包含了开根号操作，出于性能的考虑，我们有时会使用绝对值操作来代替开根操作：$$G &#x3D; |G_x| + |G_y|$$当得到梯度 G 后，我们就可以据此来判断哪些像素对应了边缘。 下面我们使用 Sobel 算子进行边缘检测，cs 脚本和上面类似： using UnityEngine;using System.Collections;public class EdgeDetection : PostEffectsBase &#123; public Shader edgeDetectShader; private Material edgeDetectMaterial = null; public Material material &#123; get &#123; edgeDetectMaterial = CheckShaderAndCreateMaterial(edgeDetectShader, edgeDetectMaterial); return edgeDetectMaterial; &#125; &#125; // 调整边缘线强度的参数，当值为0时，边缘会叠加到原图像上，值为1时只显示边缘 [Range(0.0f, 1.0f)] public float edgesOnly = 0.0f; // 边缘颜色 public Color edgeColor = Color.black; // 背景颜色 public Color backgroundColor = Color.white; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; material.SetFloat(&quot;_EdgeOnly&quot;, edgesOnly); material.SetColor(&quot;_EdgeColor&quot;, edgeColor); material.SetColor(&quot;_BackgroundColor&quot;, backgroundColor); // 将src作为纹理用material对应的shader处理，结果保存到dest纹理中 Graphics.Blit(src, dest, material); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
然后编写 Shader： Shader &quot;Unity Shaders Book/Chapter 12/Edge Detection&quot; &#123; Properties &#123; // 对应的参数，也可以不定义，因为在这里定义属性是为了显示在材质的属性面板上 // 但这里我们是脚本自动生成材质，不需要我们创建材质 _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _EdgeOnly (&quot;Edge Only&quot;, Float) = 1.0 _EdgeColor (&quot;Edge Color&quot;, Color) = (0, 0, 0, 1) _BackgroundColor (&quot;Background Color&quot;, Color) = (1, 1, 1, 1) &#125; SubShader &#123; Pass &#123; // 屏幕后处理标配 ZTest Always Cull Off ZWrite Off CGPROGRAM #include &quot;UnityCG.cginc&quot; #pragma vertex vert #pragma fragment fragSobel sampler2D _MainTex; // xxx_TexelSize是 Unity 内置的访问纹理纹素大小的变量 // 例如512 * 512 的纹理的纹素大小就是 1/512 // 因为卷积要对相邻纹素操作，所以要用纹素大小计算得到当前纹素相邻的纹素的位置 uniform half4 _MainTex_TexelSize; fixed _EdgeOnly; fixed4 _EdgeColor; fixed4 _BackgroundColor; struct v2f &#123; float4 pos : SV_POSITION; half2 uv[9] : TEXCOORD0; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); half2 uv = v.texcoord; // 计算每个纹理坐标周围的用于卷积的纹理坐标 // 这一步最好在顶点着色器计算以减少性能开销 // 因为顶点到片元的线性插值不会影响相邻坐标的结果 o.uv[0] = uv + _MainTex_TexelSize.xy * half2(-1, -1); o.uv[1] = uv + _MainTex_TexelSize.xy * half2(0, -1); o.uv[2] = uv + _MainTex_TexelSize.xy * half2(1, -1); o.uv[3] = uv + _MainTex_TexelSize.xy * half2(-1, 0); o.uv[4] = uv + _MainTex_TexelSize.xy * half2(0, 0); o.uv[5] = uv + _MainTex_TexelSize.xy * half2(1, 0); o.uv[6] = uv + _MainTex_TexelSize.xy * half2(-1, 1); o.uv[7] = uv + _MainTex_TexelSize.xy * half2(0, 1); o.uv[8] = uv + _MainTex_TexelSize.xy * half2(1, 1); return o; &#125; // 计算每个像素的亮度值 fixed luminance(fixed4 color) &#123; return 0.2125 * color.r + 0.7154 * color.g + 0.0721 * color.b; &#125; // 计算当前像素的梯度值 half Sobel(v2f i) &#123; // Sobel算子 const half Gx[9] = &#123;-1, 0, 1, -2, 0, 2, -1, 0, 1&#125;; const half Gy[9] = &#123;-1, -2, -1, 0, 0, 0, 1, 2, 1&#125;; half texColor; // 两个方向的滤波结果 half edgeX = 0; half edgeY = 0; // 滤波 for (int it = 0; it &lt; 9; it++) &#123; texColor = luminance(tex2D(_MainTex, i.uv[it])); edgeX += texColor * Gx[it]; edgeY += texColor * Gy[it]; &#125; // 得到最终滤波结果，这里的edge显然值越小越可能是边缘 half edge = 1 - abs(edgeX) - abs(edgeY); return edge; &#125; fixed4 fragSobel(v2f i) : SV_Target &#123; // 得到当前像素的梯度值 half edge = Sobel(i); // 计算背景分别为原图和纯色下的边缘颜色值 fixed4 withEdgeColor = lerp(_EdgeColor, tex2D(_MainTex, i.uv[4]), edge); fixed4 onlyEdgeColor = lerp(_EdgeColor, _BackgroundColor, edge); // 利用_EdgeOnly在两者之间插值得到最终的像素值 return lerp(withEdgeColor, onlyEdgeColor, _EdgeOnly); &#125; ENDCG &#125; &#125; FallBack Off&#125;
