4 高斯模糊高斯模糊我们非常熟悉，但还是有一个小技巧需要说明，那就是存储高斯模糊核时不需要全部存储，只需要存储极少的权重即可，因为：
所以一个 5 * 5 的高斯模糊核我们只需要存储 3 个权重即可。 并且为了提高性能，我们使用两个 Pass，第一个 Pass 将会使用竖直方向的一维高斯核对图像进行滤波，第二个 Pass 再使用水平方向的一维高斯核对图像进行滤波，得到最终的目标图像。同时还将利用图像缩放来进一步提高性能，并通过调整高斯滤波的应用次数来控制模糊程度。 cs 脚本如下： using UnityEngine;using System.Collections;public class GaussianBlur : PostEffectsBase &#123; public Shader gaussianBlurShader; private Material gaussianBlurMaterial = null; public Material material &#123; get &#123; gaussianBlurMaterial = CheckShaderAndCreateMaterial(gaussianBlurShader, gaussianBlurMaterial); return gaussianBlurMaterial; &#125; &#125; // 滤波次数 [Range(0, 4)] public int iterations = 3; //下面两个参数都是出于性能考虑 // 模糊范围，在高斯核维数不变的情况下，模糊范围越大模糊程度越高，但过高会造成虚影 [Range(0.2f, 3.0f)] public float blurSpread = 0.6f; // 下采样倍数越高，需要处理的像素数越少，同时也能进一步提高模糊程度，但过大的downSample可能会使图像像素化 [Range(1, 8)] public int downSample = 2; /// 第一个版本，最简单的实现// void OnRenderImage(RenderTexture src, RenderTexture dest) &#123;// if (material != null) &#123;// int rtW = src.width;// int rtH = src.height;// // 分配了一块与屏幕图像大小相同的缓冲区，因为有两个Pass，因此需要一个缓冲存储中间结果// RenderTexture buffer = RenderTexture.GetTemporary(rtW, rtH, 0);//// // 使用Shader中的第1个Pass进行竖直方向一维高斯滤波// Graphics.Blit(src, buffer, material, 0);// // 使用Shader中的第2个Pass进行水平方向一维高斯滤波// Graphics.Blit(buffer, dest, material, 1);// // 释放缓冲区// RenderTexture.ReleaseTemporary(buffer);// &#125; else &#123;// Graphics.Blit(src, dest);// &#125;// &#125; /// 第二个版本，利用缩放对图像下采样，减少需要处理的像素个数// void OnRenderImage (RenderTexture src, RenderTexture dest) &#123;// if (material != null) &#123;// // 声明缓冲区大小是进行缩放，并设置该临时纹理的滤波模式为双线性// // 这样在调用第一个 Pass 时，我们需要处理的像素个数就是原来的几分之一// int rtW = src.width/downSample;// int rtH = src.height/downSample;// RenderTexture buffer = RenderTexture.GetTemporary(rtW, rtH, 0);// buffer.filterMode = FilterMode.Bilinear;//// Graphics.Blit(src, buffer, material, 0);// Graphics.Blit(buffer, dest, material, 1);// RenderTexture.ReleaseTemporary(buffer);// &#125; else &#123;// Graphics.Blit(src, dest);// &#125;// &#125; /// 最终版本，还考虑了滤波次数 void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; // 降采样 int rtW = src.width/downSample; int rtH = src.height/downSample; RenderTexture buffer0 = RenderTexture.GetTemporary(rtW, rtH, 0); buffer0.filterMode = FilterMode.Bilinear; Graphics.Blit(src, buffer0); for (int i = 0; i &lt; iterations; i++) &#123; material.SetFloat(&quot;_BlurSize&quot;, 1.0f + i * blurSpread); RenderTexture buffer1 = RenderTexture.GetTemporary(rtW, rtH, 0); // 垂直方向滤波 Graphics.Blit(buffer0, buffer1, material, 0); // 缓存交替 RenderTexture.ReleaseTemporary(buffer0); buffer0 = buffer1; buffer1 = RenderTexture.GetTemporary(rtW, rtH, 0); // 垂直滤波 Graphics.Blit(buffer0, buffer1, material, 1); RenderTexture.ReleaseTemporary(buffer0); buffer0 = buffer1; &#125; Graphics.Blit(buffer0, dest); RenderTexture.ReleaseTemporary(buffer0); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
Shader 代码如下： Shader &quot;Unity Shaders Book/Chapter 12/Gaussian Blur&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _BlurSize (&quot;Blur Size&quot;, Float) = 1.0 &#125; SubShader &#123; // CGINCLUDE包含的代码相当于头文件的功能，包含在CGINCLUDE内的代码块不需要写在任何Pass中 // 在后面的Pass中可以直接用函数名调用这当中的函数 // 由于我们要用到两个Pass ，并且它们的片元着色器代码是完全相同的，因此这样可以避免代码重复 CGINCLUDE #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; half4 _MainTex_TexelSize; float _BlurSize; struct v2f &#123; float4 pos : SV_POSITION; half2 uv[5]: TEXCOORD0; &#125;; // 垂直滤波的顶点着色器 v2f vertBlurVertical(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); half2 uv = v.texcoord; //垂直方向的五个纹素坐标，用_BlurSize控制采样距离，采样距离越远模糊越严重 o.uv[0] = uv; o.uv[1] = uv + float2(0.0, _MainTex_TexelSize.y * 1.0) * _BlurSize; o.uv[2] = uv - float2(0.0, _MainTex_TexelSize.y * 1.0) * _BlurSize; o.uv[3] = uv + float2(0.0, _MainTex_TexelSize.y * 2.0) * _BlurSize; o.uv[4] = uv - float2(0.0, _MainTex_TexelSize.y * 2.0) * _BlurSize; return o; &#125; // 水平滤波的顶点着色器 v2f vertBlurHorizontal(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); half2 uv = v.texcoord; // 水平方向的五个纹素坐标，用_BlurSize控制采样距离，采样距离越远模糊越严重 o.uv[0] = uv; o.uv[1] = uv + float2(_MainTex_TexelSize.x * 1.0, 0.0) * _BlurSize; o.uv[2] = uv - float2(_MainTex_TexelSize.x * 1.0, 0.0) * _BlurSize; o.uv[3] = uv + float2(_MainTex_TexelSize.x * 2.0, 0.0) * _BlurSize; o.uv[4] = uv - float2(_MainTex_TexelSize.x * 2.0, 0.0) * _BlurSize; return o; &#125; // 共用的片元着色器 fixed4 fragBlur(v2f i) : SV_Target &#123; // 模糊核权值 float weight[3] = &#123;0.4026, 0.2442, 0.0545&#125;; // 滤波 fixed3 sum = tex2D(_MainTex, i.uv[0]).rgb * weight[0]; for (int it = 1; it &lt; 3; it++) &#123; sum += tex2D(_MainTex, i.uv[it*2-1]).rgb * weight[it]; sum += tex2D(_MainTex, i.uv[it*2]).rgb * weight[it]; &#125; return fixed4(sum, 1.0); &#125; ENDCG ZTest Always Cull Off ZWrite Off // 下面的 Pass 中直接调用上面的函数名即可 // 为Pass定义了一个名字，这使得其他Shder可以通过改名字来直接使用该Pass // 因为高斯模糊很常用，定义名字为了方便其他Shader调用 Pass &#123; NAME &quot;GAUSSIAN_BLUR_VERTICAL&quot; CGPROGRAM #pragma vertex vertBlurVertical #pragma fragment fragBlur ENDCG &#125; Pass &#123; NAME &quot;GAUSSIAN_BLUR_HORIZONTAL&quot; CGPROGRAM #pragma vertex vertBlurHorizontal #pragma fragment fragBlur ENDCG &#125; &#125; FallBack &quot;Diffuse&quot;&#125;
渲染效果如下：
5 Bloom 效果Bloom 特效是游戏中常见的一种屏幕效果。这种特效可以模拟真实摄像机的一种图像效果，它让画面中较亮的区域“扩散”到周围的区域中，造成一种朦胧的效果。如下图：
Bloom 的实现原理非常简单：我们首先根据一个阈值提取出图像中的较亮区域，把它们存储在一张渲染纹理中，再利用高斯模糊对这张渲染纹理进行模糊处理，模拟光线扩散的效果，最后再将其和原图像进行混合，得到最终的效果。 首先是 cs 脚本： using UnityEngine;using System.Collections;public class Bloom : PostEffectsBase &#123; public Shader bloomShader; private Material bloomMaterial = null; public Material material &#123; get &#123; bloomMaterial = CheckShaderAndCreateMaterial(bloomShader, bloomMaterial); return bloomMaterial; &#125; &#125; // 和高斯模糊的参数一样 [Range(0, 4)] public int iterations = 3; [Range(0.2f, 3.0f)] public float blurSpread = 0.6f; [Range(1, 8)] public int downSample = 2; // 提取较亮区域时使用的阈值大小 // 尽管在绝大多数情况下，图像的亮度值不会超过1 // 但如果我们开启了HDR，硬件会允许我们把颜色值存储在一个更高精度范围的缓冲中，此时像素的亮度值可能会超过1 // 因此，在这里我们把 luminanceThreshold 的值规定在[O, 4]范围内 [Range(0.0f, 4.0f)] public float luminanceThreshold = 0.6f; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; // 提取阈值传递给材质 material.SetFloat(&quot;_LuminanceThreshold&quot;, luminanceThreshold); int rtW = src.width/downSample; int rtH = src.height/downSample; RenderTexture buffer0 = RenderTexture.GetTemporary(rtW, rtH, 0); buffer0.filterMode = FilterMode.Bilinear; // 使用Shader中第一个Pass来提取图像中的较亮区域 Graphics.Blit(src, buffer0, material, 0); for (int i = 0; i &lt; iterations; i++) &#123; material.SetFloat(&quot;_BlurSize&quot;, 1.0f + i * blurSpread); RenderTexture buffer1 = RenderTexture.GetTemporary(rtW, rtH, 0); // 使用第二个Pass进行垂直滤波 Graphics.Blit(buffer0, buffer1, material, 1); RenderTexture.ReleaseTemporary(buffer0); buffer0 = buffer1; buffer1 = RenderTexture.GetTemporary(rtW, rtH, 0); //使用第三个Pass进行水平滤波 Graphics.Blit(buffer0, buffer1, material, 2); RenderTexture.ReleaseTemporary(buffer0); buffer0 = buffer1; &#125; // 将模糊后的较亮区域设为纹理 material.SetTexture (&quot;_Bloom&quot;, buffer0); // 使用第四个Pass将处理后的亮部叠加到原图上 Graphics.Blit (src, dest, material, 3); RenderTexture.ReleaseTemporary(buffer0); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
然后是 Shader 代码： Shader &quot;Unity Shaders Book/Chapter 12/Bloom&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _Bloom (&quot;Bloom (RGB)&quot;, 2D) = &quot;black&quot; &#123;&#125; _LuminanceThreshold (&quot;Luminance Threshold&quot;, Float) = 0.5 _BlurSize (&quot;Blur Size&quot;, Float) = 1.0 &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; half4 _MainTex_TexelSize; sampler2D _Bloom; float _LuminanceThreshold; float _BlurSize; // 提取亮部区域时的结构体和着色器 struct v2f &#123; float4 pos : SV_POSITION; half2 uv : TEXCOORD0; &#125;; v2f vertExtractBright(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uv = v.texcoord; return o; &#125; fixed luminance(fixed4 color) &#123; return 0.2125 * color.r + 0.7154 * color.g + 0.0721 * color.b; &#125; fixed4 fragExtractBright(v2f i) : SV_Target &#123; fixed4 c = tex2D(_MainTex, i.uv); // 用采样得到的亮度值减去_LuminanceThreshold阈值并截取到[0,1]范围内 // 这样比阈值小的部分就置为0，只剩下了较亮区域 fixed val = clamp(luminance(c) - _LuminanceThreshold, 0.0, 1.0); // 和原像素相乘得到提取后的亮部图像 return c * val; &#125; // 混合亮部图像和原图时的结构体和着色器 struct v2fBloom &#123; float4 pos : SV_POSITION; half4 uv : TEXCOORD0; &#125;; v2fBloom vertBloom(appdata_img v) &#123; v2fBloom o; o.pos = UnityObjectToClipPos (v.vertex); // xy存储主纹理坐标 o.uv.xy = v.texcoord; // zw存储模糊后的亮部图像纹理坐标 o.uv.zw = v.texcoord; // 对zw进行平台差异化处理 #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0.0) o.uv.w = 1.0 - o.uv.w; #endif return o; &#125; fixed4 fragBloom(v2fBloom i) : SV_Target &#123; // 对两个纹理采样直接相加即可 return tex2D(_MainTex, i.uv.xy) + tex2D(_Bloom, i.uv.zw); &#125; ENDCG ZTest Always Cull Off ZWrite Off Pass &#123; CGPROGRAM #pragma vertex vertExtractBright #pragma fragment fragExtractBright ENDCG &#125; // 这里可以直接使用之前的高斯模糊中的Pass UsePass &quot;Unity Shaders Book/Chapter 12/Gaussian Blur/GAUSSIAN_BLUR_VERTICAL&quot; UsePass &quot;Unity Shaders Book/Chapter 12/Gaussian Blur/GAUSSIAN_BLUR_HORIZONTAL&quot; Pass &#123; CGPROGRAM #pragma vertex vertBloom #pragma fragment fragBloom ENDCG &#125; &#125; FallBack Off&#125;
原图如下：
Bloom 效果如下：
6 运动模糊运动模糊是真实世界中的摄像机的一种效果。如果在摄像机曝光时，拍摄场景发生了变化，就会产生模糊的画面。运动模糊在我们的日常生活中是非常常见的，运动模糊效果可以让物体运动看起来更加真实平滑，但在计算机产生的图像中，由于不存在曝光这一物理现象，渲染出来的图像往往都棱角分明，缺少运动模糊。而在现在的许多第一人称或者赛车游戏中，运动模糊是一种必不可少的效果。 运动模糊实现的一种方法是使用累积缓存记录多张连续图像，然后取平均作为运动模糊图像，但是这种方法对于性能的消耗很大，因为想要获取多帧连续图像意味着要渲染一个场景多次。另一种广泛应用的方法是创建和使用速度缓存，这个缓存中存储了各个像素当前的运动速度，然后利用该值来决定模糊的方向和大小。 这一节我们使用类似于第一种方法来实现运动模糊，但不需要在一帧中把场景渲染多次，只要保存之前的渲染结果，不断把当前的渲染图像叠加到之前的渲染图上，从而产生一种运动轨迹的视觉效果。这种方法与原始的利用累积缓存的方法相比性能更好，但模糊效果可能会略有影响。 为此，我们先编写一个脚本让摄像机运动： using UnityEngine;using System.Collections;public class Translating : MonoBehaviour &#123; public float speed = 10.0f; public Vector3 startPoint = Vector3.zero; public Vector3 endPoint = Vector3.zero; public Vector3 lookAt = Vector3.zero; public bool pingpong = true; private Vector3 curEndPoint = Vector3.zero; // Use this for initialization void Start () &#123; transform.position = startPoint; curEndPoint = endPoint; &#125; // Update is called once per frame void Update () &#123; transform.position = Vector3.Slerp(transform.position, curEndPoint, Time.deltaTime * speed); transform.LookAt(lookAt); if (pingpong) &#123; if (Vector3.Distance(transform.position, curEndPoint) &lt; 0.001f) &#123; curEndPoint = Vector3.Distance(curEndPoint, endPoint) &lt; Vector3.Distance(curEndPoint, startPoint) ? startPoint : endPoint; &#125; &#125; &#125;&#125;
然后编写运动模糊的脚本： using UnityEngine;using System.Collections;public class MotionBlur : PostEffectsBase &#123; public Shader motionBlurShader; private Material motionBlurMaterial = null; public Material material &#123; get &#123; motionBlurMaterial = CheckShaderAndCreateMaterial(motionBlurShader, motionBlurMaterial); return motionBlurMaterial; &#125; &#125; // 定义运动模糊在混合图像时使用的混合参数 // blurAmount 的值越大，运动拖尾的效果就越明显 // 为了防止拖尾效果完全替代当前帧的渲染结果，我们把它的值截取在0.0到0.9范围内 [Range(0.0f, 0.9f)] public float blurAmount = 0.5f; // 定义保存之前图像叠加的结果的纹理 private RenderTexture accumulationTexture; // 我们在该脚本不运行时，即调用 OnDisable 函数时立即销毁之前叠加的结果 // 这是因为我们希望在下一次开始应用运动模糊时重新叠加图像 void OnDisable() &#123; DestroyImmediate(accumulationTexture); &#125; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; // 判断当前accumulationTexture是否满足条件按，不满足则创建满足条件的纹理并初始化为当前帧图像 if (accumulationTexture == null || accumulationTexture.width != src.width || accumulationTexture.height != src.height) &#123; DestroyImmediate(accumulationTexture); accumulationTexture = new RenderTexture(src.width, src.height, 0); accumulationTexture.hideFlags = HideFlags.HideAndDontSave; Graphics.Blit(src, accumulationTexture); &#125; // 这个函数表明我们需要进行一个渲染纹理的恢复操作 // 恢复操作发生在渲染到纹理而该纹理又没有被提前清空或销毁的情况下 // 我们要用accumulationTexture混合当前图像，因此不能提前清空 accumulationTexture.MarkRestoreExpected(); // 参数传递给材质 material.SetFloat(&quot;_BlurAmount&quot;, 1.0f - blurAmount); // 把当前屏幕图像叠加到accumulationTexture Graphics.Blit (src, accumulationTexture, material); // 把结果显示到屏幕上 Graphics.Blit (accumulationTexture, dest); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
Shader 代码： Shader &quot;Unity Shaders Book/Chapter 12/Motion Blur&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _BlurAmount (&quot;Blur Amount&quot;, Float) = 1.0 &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; fixed _BlurAmount; struct v2f &#123; float4 pos : SV_POSITION; half2 uv : TEXCOORD0; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uv = v.texcoord; return o; &#125; // 采样RGB，并将其A通道设为_BlurAmount // 以便在后面混合时可以使用它的透明通道进行混合 fixed4 fragRGB (v2f i) : SV_Target &#123; return fixed4(tex2D(_MainTex, i.uv).rgb, _BlurAmount); &#125; // 直接返回采样值 // 这是为了维护渲染纹理的透明通道值，不让其受到混合时使用的透明度值的影响 half4 fragA (v2f i) : SV_Target &#123; return tex2D(_MainTex, i.uv); &#125; ENDCG ZTest Always Cull Off ZWrite Off // 处理RGB通道 // 更新RGB时我们需要设置它的A通道来混合图像，但又不希望A通道的值写入渲染纹理中 Pass &#123; Blend SrcAlpha OneMinusSrcAlpha ColorMask RGB CGPROGRAM #pragma vertex vert #pragma fragment fragRGB ENDCG &#125; // 处理A通道，保证A通道还是原来的值 Pass &#123; Blend One Zero ColorMask A CGPROGRAM #pragma vertex vert #pragma fragment fragA ENDCG &#125; &#125; FallBack Off&#125;
Blur Amount 设置为 0 时的效果：
Blur Amount 设置为 1 时的效果：
明显看到了运动模糊。当然这只是一种简单的实现，当物体运动速度过快时，这种方法可能会造成单独的帧图像变得可见。之后我们会学习如何利用深度纹理重建速度来模拟运动模糊效果。

之前我们学习过关于基础纹理的内容，这些纹理包括法线纹理、渐变纹理和遮罩纹理等。这些纹理尽管用处不同，但它们都属于低维（ 一维或二维）纹理。这一节我们将学习一些更复杂的纹理，但都是我们曾经在图形学中学到过的。包括使用立方体纹理（Cubemap）实现环境映射，以及强大的渲染纹理（Render Texture），最后学习程序纹理（Procedure Texture）。
1 立方体纹理在图形学中我们已经学过环境映射，使用的就是展开的立方体纹理，在 Unity 中，立方体纹理可以通过直接而导入获得，也可以通过脚本生成获得。获得环境的立方体纹理之后，就可以使用该纹理对物体进行渲染，使得物体能够反射周围环境。 1.1 反射想要模拟反射效果很简单，我们只需要通过入射光线的方向和表面法线方向来计算反射方向，再利用反射方向对立方体纹理采样即可。 Shader &quot;Unity Shaders Book/Chapter 10/Reflection&quot; &#123; Properties &#123; _Color (&quot;Color Tint&quot;, Color) = (1, 1, 1, 1) // 控制反射颜色 _ReflectColor (&quot;Reflection Color&quot;, Color) = (1, 1, 1, 1) // 控制材质的反射程度 _ReflectAmount (&quot;Reflect Amount&quot;, Range(0, 1)) = 1 // 环境映射纹理 _Cubemap (&quot;Reflection Cubemap&quot;, Cube) = &quot;_Skybox&quot; &#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; CGPROGRAM #pragma multi_compile_fwdbase #pragma vertex vert #pragma fragment frag #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; fixed4 _Color; fixed4 _ReflectColor; fixed _ReflectAmount; samplerCUBE _Cubemap; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float3 worldPos : TEXCOORD0; fixed3 worldNormal : TEXCOORD1; fixed3 worldViewDir : TEXCOORD2; fixed3 worldRefl : TEXCOORD3; SHADOW_COORDS(4) &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.worldNormal = UnityObjectToWorldNormal(v.normal); o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; o.worldViewDir = UnityWorldSpaceViewDir(o.worldPos); // 计算世界空间下的反射方向 o.worldRefl = reflect(-o.worldViewDir, o.worldNormal); TRANSFER_SHADOW(o); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; fixed3 worldNormal = normalize(i.worldNormal); fixed3 worldLightDir = normalize(UnityWorldSpaceLightDir(i.worldPos)); fixed3 worldViewDir = normalize(i.worldViewDir); fixed3 ambient = UNITY_LIGHTMODEL_AMBIENT.xyz; fixed3 diffuse = _LightColor0.rgb * _Color.rgb * max(0, dot(worldNormal, worldLightDir)); // 使用反射方向对立方体纹理采样 fixed3 reflection = texCUBE(_Cubemap, i.worldRefl).rgb * _ReflectColor.rgb; UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); // 使用lerp函数混合漫反射颜色和环境反射颜色 fixed3 color = ambient + lerp(diffuse, reflection, _ReflectAmount) * atten; return fixed4(color, 1.0); &#125; ENDCG &#125; &#125; FallBack &quot;Reflective/VertexLit&quot;&#125;
得到的效果如下：
1.2 折射我们也可以用环境贴图模拟折射，虽然对于透明物体，折射应该是两次，一次是光线进入物体内部，另一次是光线从物体内部出去，这样才能被我们所看到，但模拟两次折射比较复杂并且会大幅降低 Shader 性能，因此大多数情况下在实时渲染中我们只模拟一次折射，虽然这是不对的，但是渲染效果看起来并不差，在实时渲染中，“只要看起来它是对的，那么它就是对的”，因此我们可以用一次折射来得到想要的效果。 类似于反射，我们只要用光线折射方向对环境纹理采样即可，折射方向的计算我们也在图形学中学过，可以利用折射率和角度的关系得到。和反射一样，我们也可以通过计算折射的函数直接得到折射方向。 Shader &quot;Unity Shaders Book/Chapter 10/Refraction&quot; &#123; Properties &#123; _Color (&quot;Color Tint&quot;, Color) = (1, 1, 1, 1) _RefractColor (&quot;Refraction Color&quot;, Color) = (1, 1, 1, 1) _RefractAmount (&quot;Refraction Amount&quot;, Range(0, 1)) = 1 // 介质的透射比，即两种介质的折射率的比值 _RefractRatio (&quot;Refraction Ratio&quot;, Range(0.1, 1)) = 0.5 _Cubemap (&quot;Refraction Cubemap&quot;, Cube) = &quot;_Skybox&quot; &#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; CGPROGRAM #pragma multi_compile_fwdbase #pragma vertex vert #pragma fragment frag #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; fixed4 _Color; fixed4 _RefractColor; float _RefractAmount; fixed _RefractRatio; samplerCUBE _Cubemap; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float3 worldPos : TEXCOORD0; fixed3 worldNormal : TEXCOORD1; fixed3 worldViewDir : TEXCOORD2; fixed3 worldRefr : TEXCOORD3; SHADOW_COORDS(4) &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.worldNormal = UnityObjectToWorldNormal(v.normal); o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; o.worldViewDir = UnityWorldSpaceViewDir(o.worldPos); // 使用refract函数计算世界空间下的折射方向 // 第一个参数是入射光方向，第二个参数是表面法线，都要归一化 // 第三个参数是入射光线所在介质的折射率和折射光线所在介质的折射率之间的比值 o.worldRefr = refract(-normalize(o.worldViewDir), normalize(o.worldNormal), _RefractRatio); TRANSFER_SHADOW(o); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; fixed3 worldNormal = normalize(i.worldNormal); fixed3 worldLightDir = normalize(UnityWorldSpaceLightDir(i.worldPos)); fixed3 worldViewDir = normalize(i.worldViewDir); fixed3 ambient = UNITY_LIGHTMODEL_AMBIENT.xyz; fixed3 diffuse = _LightColor0.rgb * _Color.rgb * max(0, dot(worldNormal, worldLightDir)); // 使用折射方向对环境纹理采样 fixed3 refraction = texCUBE(_Cubemap, i.worldRefr).rgb * _RefractColor.rgb; UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); // 将漫反射和折射颜色混合 fixed3 color = ambient + lerp(diffuse, refraction, _RefractAmount) * atten; return fixed4(color, 1.0); &#125; ENDCG &#125; &#125; FallBack &quot;Reflective/VertexLit&quot;&#125;
渲染效果如下：
1.3 菲涅尔效果在图形学中我们已经学过菲涅尔效应，菲涅尔项的物理计算非常复杂，但在图形学中有一个著名的近似公式，回顾当时学习的对菲涅尔项的近似公式：
其中 $cos\theta$ 是视线和表面法线的夹角余弦，也可以写成点积形式，这一节我们用该公式进行菲涅尔项的渲染。 Shader &quot;Unity Shaders Book/Chapter 10/Fresnel&quot; &#123; Properties &#123; _Color (&quot;Color Tint&quot;, Color) = (1, 1, 1, 1) // 菲涅尔反射系数，相当于公式中的R0 _FresnelScale (&quot;Fresnel Scale&quot;, Range(0, 1)) = 0.5 _Cubemap (&quot;Reflection Cubemap&quot;, Cube) = &quot;_Skybox&quot; &#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; CGPROGRAM #pragma multi_compile_fwdbase #pragma vertex vert #pragma fragment frag #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; fixed4 _Color; fixed _FresnelScale; samplerCUBE _Cubemap; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float3 worldPos : TEXCOORD0; fixed3 worldNormal : TEXCOORD1; fixed3 worldViewDir : TEXCOORD2; fixed3 worldRefl : TEXCOORD3; SHADOW_COORDS(4) &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.worldNormal = UnityObjectToWorldNormal(v.normal); o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; o.worldViewDir = UnityWorldSpaceViewDir(o.worldPos); o.worldRefl = reflect(-o.worldViewDir, o.worldNormal); TRANSFER_SHADOW(o); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; fixed3 worldNormal = normalize(i.worldNormal); fixed3 worldLightDir = normalize(UnityWorldSpaceLightDir(i.worldPos)); fixed3 worldViewDir = normalize(i.worldViewDir); fixed3 ambient = UNITY_LIGHTMODEL_AMBIENT.xyz; UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); fixed3 reflection = texCUBE(_Cubemap, i.worldRefl).rgb; // 计算菲涅尔项 fixed fresnel = _FresnelScale + (1 - _FresnelScale) * pow(1 - dot(worldViewDir, worldNormal), 5); fixed3 diffuse = _LightColor0.rgb * _Color.rgb * max(0, dot(worldNormal, worldLightDir)); // 将菲涅尔项和漫反射、反射颜色混合 fixed3 color = ambient + lerp(diffuse, reflection, saturate(fresnel)) * atten; return fixed4(color, 1.0); &#125; ENDCG &#125; &#125; FallBack &quot;Reflective/VertexLit&quot;&#125;
当菲涅尔系数为 1 时，得到的就是完整的环境反射效果：
当菲涅尔系数为 0 时，就会得到一个具有边缘光照效果的漫反射物体：
2 渲染纹理在之前的学习中， 一个摄像机的渲染结果会输出到颜色缓冲中，并显示到我们的屏幕上。现代的 GPU 允许我们把整个三维场景渲染到一个中间缓冲中，即渲染目标纹理（Render Target Texture, RTT），而不是传统的帧缓冲或后备缓冲（back buffer）。与之相关的是多重渲染目标（Multiple Render Target, MRT），这种技术指的是 GPU 允许我们把场景同时渲染到多个渲染目标纹理中，而不再需要为每个渲染目标纹理单独渲染完整的场景。延迟渲染就是使用多重渲染目标的一个应用。 Unity 为渲染目标纹理定义了一种专门的纹理类型——渲染纹理（Render Texture）。在 Unity 中使用渲染纹理有两种方式：
一种方式是在 Project 目录下创建一个渲染纹理，然后把某个摄像机的渲染目标设置成该渲染纹理，这样一来该摄像机的渲染结果就会实时更新到渲染纹理中，而不会显示在屏幕上。 使用这种方法，我们还可以选择渲染纹理的分辨率、滤波模式等纹理属性。 另一种方式是在屏幕后处理时使用 GrabPass 命令或 OnRenderimage 函数来获取当前屏幕图像，Unity 会把这个屏幕图像放到一张和屏幕分辨率等同的渲染纹理中，之后我们可以在自定义的 Pass 中把它们当成普通的纹理来处理，从而实现各种屏幕特效。
2.1 镜子效果镜子实现的原理很简单，它使用一个渲染纹理作为输入属性，并把该渲染纹理在水平方向上翻转后直接显示到物体上即可。 我们搭建的场景如下：
白色部分是一个镜子，现在我们还没有使用渲染纹理渲染镜子，要想让镜子显示场景信息，我们要在镜子上安一个虚拟摄像机，并新建一个渲染纹理叫做 Mirror Texture，然后将该摄像机的渲染目标改为渲染纹理：
然后编写 Shader，用渲染纹理渲染镜子，是一个非常简单的二维平面渲染： Shader &quot;Unity Shaders Book/Chapter 10/Mirror&quot; &#123; Properties &#123; _MainTex (&quot;Main Tex&quot;, 2D) = &quot;white&quot; &#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; Pass &#123; CGPROGRAM #pragma vertex vert #pragma fragment frag sampler2D _MainTex; struct a2v &#123; float4 vertex : POSITION; float3 texcoord : TEXCOORD0; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float2 uv : TEXCOORD0; &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uv = v.texcoord; // 水平翻转 x o.uv.x = 1 - o.uv.x; return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; return tex2D(_MainTex, i.uv); &#125; ENDCG &#125; &#125; FallBack Off&#125;
然后为该材质选择渲染纹理，得到的效果如下：
2.2 玻璃效果在 Unity 中，我们还可以在 Unity Shader 中使用一种特殊的 Pass 来完成获取屏幕图像的目的，这就是 GrabPass 。当我们在 Shader 中定义了一个 GrabPass 后， Unity 会把当前屏幕的图像绘制在一张纹理中，以便我们在后续的 Pass 中访问它。我们通常会使用 GrabPass 来实现诸如玻璃等透明材质的模拟，与使用简单的透明混合不同，使用 GrabPass 可以让我们对该物体后面的图像进行更复杂的处理，例如使用法线来模拟折射效果，而不再是简单的和原屏幕颜色进行混合。 需要注意的是，在使用 GrabPass 的时候，我们需要额外小心物体的渲染队列设置。正如之前所说， GrabPass 通常用于渲染透明物体，尽管代码里并不包含混合指令，但我们往往仍然需要把物体的渲染队列设置成透明队列（即”Queue”&#x3D;”Transparent”）。这样才可以保证当渲染该物体时，所有的不透明物体都已经被绘制在屏幕上，从而获取正确的屏幕图像。 在本节中，我们将会使用 GrabPass 来模拟一个玻璃效果。我们首先使用一张法线纹理来修改模型的法线信息，然后使用了之前的反射方法，通过一个 Cubemap 来模拟玻璃的反射，而在模拟折射时，则使用了 GrabPass 获取玻璃后面的屏幕图像，并使用切线空间下的法线对屏幕纹理坐标偏移后，再对屏幕图像进行采样来模拟近似的折射效果。 Shader &quot;Unity Shaders Book/Chapter 10/Glass Refraction&quot; &#123; Properties &#123; _MainTex (&quot;Main Tex&quot;, 2D) = &quot;white&quot; &#123;&#125; //玻璃的材质纹理 _BumpMap (&quot;Normal Map&quot;, 2D) = &quot;bump&quot; &#123;&#125; //玻璃的法线纹理 _Cubemap (&quot;Environment Cubemap&quot;, Cube) = &quot;_Skybox&quot; &#123;&#125; //环境纹理 _Distortion (&quot;Distortion&quot;, Range(0, 100)) = 10 //用于控制模拟折射时图像的扭曲程度 //用于控制折射程度，值为0时该玻璃只包含反射，值为1时该玻璃只包含折射 _RefractAmount (&quot;Refract Amount&quot;, Range(0.0, 1.0)) = 1.0 &#125; SubShader &#123; // 一定要在设置为透明队列 Tags &#123; &quot;Queue&quot;=&quot;Transparent&quot; &quot;RenderType&quot;=&quot;Opaque&quot; &#125; // 定义一个抓取屏幕的Pass // 字符串表示抓取得到的屏幕图像将会被存入哪个纹理中，后需要使用这个名字 GrabPass &#123; &quot;_RefractionTex&quot; &#125; // 渲染玻璃所需的 Pass Pass &#123; CGPROGRAM #pragma vertex vert #pragma fragment frag #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; float4 _MainTex_ST; sampler2D _BumpMap; float4 _BumpMap_ST; samplerCUBE _Cubemap; float _Distortion; fixed _RefractAmount; // 对应上面抓取屏幕存入的纹理名称 sampler2D _RefractionTex; // 得到该纹理的纹素大小，用于对屏幕图像的采样坐标进行偏移 float4 _RefractionTex_TexelSize; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; float4 tangent : TANGENT; float2 texcoord: TEXCOORD0; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float4 scrPos : TEXCOORD0; float4 uv : TEXCOORD1; float4 TtoW0 : TEXCOORD2; float4 TtoW1 : TEXCOORD3; float4 TtoW2 : TEXCOORD4; &#125;; v2f vert (a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); // 通过顶点在裁剪空间下的坐标计算被抓取的屏幕图像空间的采样坐标 o.scrPos = ComputeGrabScreenPos(o.pos); o.uv.xy = TRANSFORM_TEX(v.texcoord, _MainTex); o.uv.zw = TRANSFORM_TEX(v.texcoord, _BumpMap); float3 worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; fixed3 worldNormal = UnityObjectToWorldNormal(v.normal); fixed3 worldTangent = UnityObjectToWorldDir(v.tangent.xyz); fixed3 worldBinormal = cross(worldNormal, worldTangent) * v.tangent.w; o.TtoW0 = float4(worldTangent.x, worldBinormal.x, worldNormal.x, worldPos.x); o.TtoW1 = float4(worldTangent.y, worldBinormal.y, worldNormal.y, worldPos.y); o.TtoW2 = float4(worldTangent.z, worldBinormal.z, worldNormal.z, worldPos.z); return o; &#125; fixed4 frag (v2f i) : SV_Target &#123; float3 worldPos = float3(i.TtoW0.w, i.TtoW1.w, i.TtoW2.w); fixed3 worldViewDir = normalize(UnityWorldSpaceViewDir(worldPos)); // 获取切线空间的法线 fixed3 bump = UnpackNormal(tex2D(_BumpMap, i.uv.zw)); // 使用法线坐标和_Distortion属性以及纹素大小计算对屏幕图像采样坐标的偏移 // _Distortion属性的值越大，偏移就越大，玻璃背后的物体的扭曲程度也就越大 // 另外，使用切线空间下的法线方向来进行偏移，是因为该空间下的法线可以反映顶点局部空间下的法线方向 float2 offset = bump.xy * _Distortion * _RefractionTex_TexelSize.xy; // 使用偏移和之前计算的屏幕图像空间的采样坐标获得校正后的的屏幕图像空间采样坐标 // 乘以z分量是为了让变形程度随着摄像机距离而发生变化，显得更加真实 i.scrPos.xy = offset * i.scrPos.z + i.scrPos.xy; // 对屏幕图像空间采样坐标做透视除法之后得到真正的屏幕坐标，再对屏幕图像采样得到折射颜色 fixed3 refrCol = tex2D(_RefractionTex, i.scrPos.xy/i.scrPos.w).rgb; // 将切线空间法线转换到世界空间 bump = normalize(half3(dot(i.TtoW0.xyz, bump), dot(i.TtoW1.xyz, bump), dot(i.TtoW2.xyz, bump))); // 计算反射方向 fixed3 reflDir = reflect(-worldViewDir, bump); // 主纹理采样 fixed4 texColor = tex2D(_MainTex, i.uv.xy); // 环境纹理采样并混合主纹理颜色得到反射颜色 fixed3 reflCol = texCUBE(_Cubemap, reflDir).rgb * texColor.rgb; // 最终颜色是反射颜色和折射颜色和线性组合，线性系数由之前定义的折射程度控制 fixed3 finalColor = reflCol * (1 - _RefractAmount) + refrCol * _RefractAmount; return fixed4(finalColor, 1); &#125; ENDCG &#125; &#125; FallBack &quot;Diffuse&quot;&#125;
渲染效果如下：
3 程序纹理程序纹理（Procedural Texture）指的是那些由计算机生成的图像，我们通常使用一些特定的算法来创建个性化图案或非常真实的自然元素， 例如木头、石子等。使用程序纹理的好处在于我们可以使用各种参数来控制纹理的外观，而这些属性不仅仅是那些颜色属性，甚至可以是完全不同类型的图案属性，这使得我们可以得到更加丰富的动画和视觉效果。 3.1 实现简单的程序纹理我们使用一个 C# 脚本生成波点纹理： using UnityEngine;using System.Collections;using System.Collections.Generic;//为了让脚本能在编辑器模式下运行[ExecuteInEditMode]public class ProceduralTextureGeneration : MonoBehaviour &#123; // 声明一个材质，这个材质将使用该脚本生成的程序纹理 public Material material = null; // 声明该程序纹理的各种参数 #region Material properties // 纹理尺寸 [SerializeField, SetProperty(&quot;textureWidth&quot;)] private int m_textureWidth = 512; public int textureWidth &#123; get &#123; return m_textureWidth; &#125; set &#123; m_textureWidth = value; _UpdateMaterial(); &#125; &#125; // 背景颜色 [SerializeField, SetProperty(&quot;backgroundColor&quot;)] private Color m_backgroundColor = Color.white; public Color backgroundColor &#123; get &#123; return m_backgroundColor; &#125; set &#123; m_backgroundColor = value; _UpdateMaterial(); &#125; &#125; // 波点颜色 [SerializeField, SetProperty(&quot;circleColor&quot;)] private Color m_circleColor = Color.yellow; public Color circleColor &#123; get &#123; return m_circleColor; &#125; set &#123; m_circleColor = value; _UpdateMaterial(); &#125; &#125; // 模糊因子，用于模糊圆形波点的边界 [SerializeField, SetProperty(&quot;blurFactor&quot;)] private float m_blurFactor = 2.0f; public float blurFactor &#123; get &#123; return m_blurFactor; &#125; set &#123; m_blurFactor = value; _UpdateMaterial(); &#125; &#125; #endregion // 声明一个Texture2D的纹理变量用于保存生成的纹理 private Texture2D m_generatedTexture = null; // 初始化 void Start () &#123; // 判断材质是否为空，如果为空就从该脚本所在的物体上获取材质 if (material == null) &#123; Renderer renderer = gameObject.GetComponent&lt;Renderer&gt;(); if (renderer == null) &#123; Debug.LogWarning(&quot;Cannot find a renderer.&quot;); return; &#125; material = renderer.sharedMaterial; &#125; // 调用_UpdateMaterial()函数生成程序纹理 _UpdateMaterial(); &#125; // 确保材质不为空，然后生成程序纹理并设置为该物体的材质的主纹理 private void _UpdateMaterial() &#123; if (material != null) &#123; m_generatedTexture = _GenerateProceduralTexture(); material.SetTexture(&quot;_MainTex&quot;, m_generatedTexture); &#125; &#125; private Color _MixColor(Color color0, Color color1, float mixFactor) &#123; Color mixColor = Color.white; mixColor.r = Mathf.Lerp(color0.r, color1.r, mixFactor); mixColor.g = Mathf.Lerp(color0.g, color1.g, mixFactor); mixColor.b = Mathf.Lerp(color0.b, color1.b, mixFactor); mixColor.a = Mathf.Lerp(color0.a, color1.a, mixFactor); return mixColor; &#125; // 生成程序纹理 private Texture2D _GenerateProceduralTexture() &#123; Texture2D proceduralTexture = new Texture2D(textureWidth, textureWidth); // 定义圆与圆之间的距离 float circleInterval = textureWidth / 4.0f; // 圆的半径 float radius = textureWidth / 10.0f; // 边缘模糊系数 float edgeBlur = 1.0f / blurFactor; for (int w = 0; w &lt; textureWidth; w++) &#123; for (int h = 0; h &lt; textureWidth; h++) &#123; // 计算每个像素的颜色，初始化为背景颜色 Color pixel = backgroundColor; // 画 9 个园 for (int i = 0; i &lt; 3; i++) &#123; for (int j = 0; j &lt; 3; j++) &#123; // 计算当前圆的圆心 Vector2 circleCenter = new Vector2(circleInterval * (i + 1), circleInterval * (j + 1)); // 计算当前像素和圆心的距离 float dist = Vector2.Distance(new Vector2(w, h), circleCenter) - radius; // 模糊边界 Color color = _MixColor(circleColor, new Color(pixel.r, pixel.g, pixel.b, 0.0f), Mathf.SmoothStep(0f, 1.0f, dist * edgeBlur)); // 混合颜色 pixel = _MixColor(pixel, color, color.a); &#125; &#125; proceduralTexture.SetPixel(w, h, pixel); &#125; &#125; proceduralTexture.Apply(); return proceduralTexture; &#125;&#125;
上面在定义属性时，每个属性都使用了 get&#x2F;set 的方法，为了在面板上修改属性时仍可以执行 set 函数，还需要使用一个开源插件 SetProperty ，这使得当我们修改了材质属性时，可以执行_UpdateMaterial 函数来使用新的属性重新生成程序纹理。 SetPropertyAttribute.cs 文件很简单： // Copyright (c) 2014 Luminary LLC// Licensed under The MIT License (See LICENSE for full text)using UnityEngine;using System.Collections;public class SetPropertyAttribute : PropertyAttribute&#123; public string Name &#123; get; private set; &#125; public bool IsDirty &#123; get; set; &#125; public SetPropertyAttribute(string name) &#123; this.Name = name; &#125;&#125;
然后我们将该脚本赋给一个立方体，在该立方体的属性面板中会出现调整我们之前定义的程序纹理属性的组件：
我们调整这些参数就可以生成不同的程序纹理，Shader 使用之前的单张纹理 Shader，不同参数得到的纹理效果如下：
3.2 Unity 的程序材质在 Unity 中，有一类专门使用程序纹理的材质，叫做程序材质 (Procedural Materials) 。这类材质和我们之前使用的那些材质在本原上是一样的，不同的是，它们使用的纹理不是普通的纹理，而是程序纹理。需要注意的是，程序材质和它使用的程序纹理并不是在 Unity 中创建的，而是使用了一个名为 Substance Designer 的软件在 Unity 外部生成的。 Substance Designer 是一个非常出色的纹理生成工具，很多 3A 的游戏项目都使用了由它生成的材质。 我们可以从 Unity 的资源商店或网络中获取到很多免费或付费的 Substance 材质。这些材质都是以 sbsar 为后缀的，我们可以直接把这些材质像其他资源一样拖入 Unity 项目中。然后生成各种各样的程序纹理。
可以看出，程序材质的自由度很高，而且可以和 Shader 配合得到非常出色的视觉效果，它是一种非常强大的材质类型。

尽管游戏渲染一般都是以照相写实主义（photorealism）作为主要目标，但也有许多游戏使用了非真实感渲染（Non-Photorealistic Rendering, NPR）的方法来渲染游戏画面。非真实感渲染的一个主要目标是，使用一些渲染方法使得画面达到和某些特殊的绘画风格相似的效果，例如卡通、水彩风格等。
1 卡通风格的渲染卡通风格是游戏中常见的一种渲染风格。使用这种风格的游戏画面通常有一些共有的特点，例如物体都被黑色的线条描边，以及分明的明暗变化等。 要实现卡通渲染有很多方法，其中之一就是使用**基于色调的着色技术 (tone-based shading)**。实现中，我们往往会使用漫反射系数对一张一维纹理进行采样，以控制漫反射的色调，我们在之前的渐变纹理中实现过这样的效果。卡通风格的高光效果也和我们之前学习的光照不同。在卡通风格中，模型的高光往往是一块块分界明显的纯色区域。 除了光照模型不同外，卡通风格通常还需要在物体边缘部分绘制轮廓。在前两节我们曾使用屏幕后处理技术对屏幕图像进行描边。在本节，我们将会使用基于模型的描边方法，这种方法的实现更加简单，而且在很多情况下也能得到不错的效果。 1.1 渲染轮廓线在实时渲染中，轮廓线的渲染是应用非常广泛的一种效果。近 20 年来，有许多绘制模型轮廓线的方法被先后提出来，在《RTR3》中作者将这些方法分为了 5 类：
基于观察角度和表面法线的轮廓线渲染。这种方法使用视角方向和表面法线的点乘结果来得到轮廓线的信息。这种方法简单快速，可以在一个 Pass 中就得到渲染结果，但局限性很大，很多模型渲染出来的描边效果都不尽如人意。 过程式几何轮廓线渲染。这种方法的核心是使用两个 Pass 渲染。第一个 Pass 渲染背面的面片，并使用某些技术让它的轮廓可见；第二个 Pass 再正常渲染正面的面片。这种方法的优点在于快速有效，并且适用于绝大多数表面平滑的模型，但它的缺点是不适合类似于立方体这样的平整模型。 基于图像处理的轮廓线渲染。我们之前使用的边缘检测的方法就属于这个类别。这种方法的优点在于，可以适用于任何种类的模型。但它也有自身的局限所在，一些深度和法线变化很小的轮廓无法被检测出来，例如桌子上的纸张。 基于轮廓边检测的轮廓线渲染。上面提到的各种方法，一个最大的问题是，无法控制轮廓线的风格渲染。对于一些情况，我们希望可以渲染出独特风格的轮廓线，例如水墨风格等。为此，我们希望可以检测出精确的轮廓边，然后直接渲染它们。检测一条边是否是轮廓边的公式很简单，我们只需要检查和这条边相邻的两个三角面片是否满足以下条件：
$$(\vec n_0·\vec v&gt;0) \neq (\vec n_1·\vec v&gt;0)$$ 其中 $\vec n_0$ 和 $\vec n_1$ 是两个相邻三角面片的法向量，$\vec v$ 是从视角到该边上任意顶点的方向。上述公式本质在于检查两个相邻的三角面片是否一个朝正面、一个朝背面。我们可以在几何着色器 (Geometry Shader) 的帮助下实现上面的检测过程。当然，这种方法也有缺点，除了实现相对复杂外，它还会有动画连贯性的问题。也就是说，由于是逐帧单独提取轮廓，所以在帧与帧之间会出现跳跃性。
最后一个种类就是混合了上述的几种渲染方法。例如，首先找到精确的轮廓边，把模型和轮廓边渲染到纹理中，再使用图像处理的方法识别出轮廓线，并在图像空间下进行风格化渲染。
在本节中，我们将会在 Unity 中使用过程式几何轮廓线渲染的方法来对模型进行轮廓描边。我们将使用两个 Pass 渲染模型：在第一个 Pass 中，我们会使用轮廓线颜色渲染整个背面的面片，并在视角空间下把模型顶点沿着法线方向向外扩张一段距离，以此来让背部轮廓线可见。代码如下： viewPos = viewPos + viewNormal * Outline;
但是，如果直接使用顶点法线进行扩展，对于一些内凹的模型，就可能发生背面面片遮挡正面面片的情况。为了尽可能防止出现这样的情况，在扩张背面顶点之前，我们首先对顶点法线的 z 分量进行处理，使它们等于一个定值，然后把法线归一化后再对顶点进行扩张。这样的好处在于，扩展后的背面更加扁平化，从而降低了遮挡正面面片的可能性。代码如下： viewNormal.z = -0.5;viewNormal = normalize(viewNormal);viewPos = viewPos + viewNormal * Outline;
1.2 添加高光前面提到过，卡通风格中的高光往往是模型上一块块分界明显的纯色区域。为了实现这种效果，我们就不能再使用之前学习的光照模型。类似于 Blinn-Phong 光照的高光计算，我们先计算法线和半程向量的点积，但不进行指数计算，而是将点积结果和一个阈值对比，如果小于该阈值，则高光系数为 0，否则高光系数为 1。 float spec = dot(worldNormal, worldHalfDir);spec = step(threshold, spec);
step 函数是 CG 的内置函数，它比较参考值和给定值的大小，如果给定值大于参考值返回 1，否则返回 0。 但是，这种粗暴的判断方法会在高光区域的边界造成锯齿，如下图。
出现这种问题的原因在于，高光区域的边缘不是平滑渐变的，而是由 0 突变到 1 。要想对其进行抗锯齿处理，我们可以在边界处很小一块区域内进行平滑处理： float spec = dot(worldNormal, worldHalfDir);spec = lerp(0, 1, smoothstep(-w, w, spec - threshold));
smoothstep 函数是 CG 的内置函数，其中 w 是一个很小的值，当 spec - threshold 小于 -w 时返回 0，当 spec - threshold 大于 w 时返回 1，在 [-w, w] 之间时，在 0 到 1 之间插值。这样的效果是，我们可以在 [-w, w] 区间内，即高光区域的边界附近，得到一个从 0 到 1 平滑变化的 spec 值，从而实现抗锯齿的目的。尽管我们可以把 w 设为一个很小的定值，但在下面的实现中，我们选择使用邻域像素之间的近似导数值，这可以通过 CG 的 fwidth 函数来得到。 1.3 实现实现代码如下： Shader &quot;Unity Shaders Book/Chapter 14/Toon Shading&quot; &#123; Properties &#123; _Color (&quot;Color Tint&quot;, Color) = (1, 1, 1, 1) _MainTex (&quot;Main Tex&quot;, 2D) = &quot;white&quot; &#123;&#125; //用于控制漫反射色调的渐变纹理 _Ramp (&quot;Ramp Texture&quot;, 2D) = &quot;white&quot; &#123;&#125; //用于控制轮廓线宽度， _Outline (&quot;Outline&quot;, Range(0, 1)) = 0.1 _OutlineColor (&quot;Outline Color&quot;, Color) = (0, 0, 0, 1) _Specular (&quot;Specular&quot;, Color) = (1, 1, 1, 1) //计算高光反射时的阈值 _SpecularScale (&quot;Specular Scale&quot;, Range(0, 0.1)) = 0.01 &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; //渲染轮廓线的Pass Pass &#123; //描边在非真实感渲染中很常用，方便后面调用 NAME &quot;OUTLINE&quot; //剔除掉正面的部分，只渲染背面 Cull Front CGPROGRAM #pragma vertex vert #pragma fragment frag #include &quot;UnityCG.cginc&quot; float _Outline; fixed4 _OutlineColor; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; &#125;; struct v2f &#123; float4 pos : SV_POSITION; &#125;; v2f vert (a2v v) &#123; v2f o; //模型空间下的顶点和法线变换到视角空间下，为了让描边再观察空间达到最好的效果 float4 pos = mul(UNITY_MATRIX_MV, v.vertex); float3 normal = mul((float3x3)UNITY_MATRIX_IT_MV, v.normal); //扩张顶点位置 normal.z = -0.5; pos = pos + float4(normalize(normal), 0) * _Outline; //变换到裁剪空间下 o.pos = mul(UNITY_MATRIX_P, pos); return o; &#125; float4 frag(v2f i) : SV_Target &#123; //用轮廓线颜色渲染整个背面 return float4(_OutlineColor.rgb, 1); &#125; ENDCG &#125; //计算光照的Pass Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; //剔除背面 Cull Back CGPROGRAM #pragma vertex vert #pragma fragment frag #pragma multi_compile_fwdbase #include &quot;UnityCG.cginc&quot; #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; #include &quot;UnityShaderVariables.cginc&quot; fixed4 _Color; sampler2D _MainTex; float4 _MainTex_ST; sampler2D _Ramp; fixed4 _Specular; fixed _SpecularScale; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; float4 texcoord : TEXCOORD0; float4 tangent : TANGENT; &#125;; struct v2f &#123; float4 pos : POSITION; float2 uv : TEXCOORD0; float3 worldNormal : TEXCOORD1; float3 worldPos : TEXCOORD2; SHADOW_COORDS(3) &#125;; v2f vert (a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos( v.vertex); o.uv = TRANSFORM_TEX (v.texcoord, _MainTex); o.worldNormal = UnityObjectToWorldNormal(v.normal); o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; TRANSFER_SHADOW(o); return o; &#125; float4 frag(v2f i) : SV_Target &#123; fixed3 worldNormal = normalize(i.worldNormal); fixed3 worldLightDir = normalize(UnityWorldSpaceLightDir(i.worldPos)); fixed3 worldViewDir = normalize(UnityWorldSpaceViewDir(i.worldPos)); fixed3 worldHalfDir = normalize(worldLightDir + worldViewDir); fixed4 c = tex2D (_MainTex, i.uv); fixed3 albedo = c.rgb * _Color.rgb; fixed3 ambient = UNITY_LIGHTMODEL_AMBIENT.xyz * albedo; //阴影和衰减 UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); fixed diff = dot(worldNormal, worldLightDir); //半兰伯特漫反射系数乘以阴影值得到最终的漫反射系数 diff = (diff * 0.5 + 0.5) * atten; //利用漫反射系数对渐变纹理采样并计算漫反射颜色 fixed3 diffuse = _LightColor0.rgb * albedo * tex2D(_Ramp, float2(diff, diff)).rgb; //按照公式计算高光 fixed spec = dot(worldNormal, worldHalfDir); fixed w = fwidth(spec) * 2.0; fixed3 specular = _Specular.rgb * lerp(0, 1, smoothstep(-w, w, spec + _SpecularScale - 1)) * step(0.0001, _SpecularScale); return fixed4(ambient + diffuse + specular, 1.0); &#125; ENDCG &#125; &#125; FallBack &quot;Diffuse&quot;&#125;
渲染效果如下：
2 素描风格的渲染另一个非常流行的非真实感渲染是素描风格的渲染。微软研究院的 Praun 等人在 2001 年的 SIGGRAPH 上发表了一篇非常著名的论文。在这篇文章中，他们使用了提前生成的素描纹理来实现实时的素描风格渲染，这些纹理组成了一个色调艺术映射 (Tonal Art Map, TAM), 如下图：
从左到右纹理中的笔触逐渐增多，用于模拟不同光照下的漫反射效果，从上到下则对应了每张纹理的多级渐远纹理 (MipMaps) 。这些多级渐远纹理的生成并不是简单的对上一层纹理进行降采样，而是需要保持笔触之间的间隔，以便更真实地模拟素描效果。 本节将会实现简化版的论文中提出的算法，我们不考虑多级渐远纹理的生成，而直接使用 6 张素描纹理进行渲染。在渲染阶段，我们首先在顶点着色阶段计算逐顶点的光照，根据光照结果来决定 6 张纹理的混合权重，并传递给片元着色器。然后，在片元着色器中根据这些权重来混合 6 张纹理的采样结果。 Shader &quot;Unity Shaders Book/Chapter 14/Hatching&quot; &#123; Properties &#123; _Color (&quot;Color Tint&quot;, Color) = (1, 1, 1, 1) // 纹理的平铺系数，值越大模型上素描线条越密 _TileFactor (&quot;Tile Factor&quot;, Float) = 1 _Outline (&quot;Outline&quot;, Range(0, 1)) = 0.1 _Hatch0 (&quot;Hatch 0&quot;, 2D) = &quot;white&quot; &#123;&#125; _Hatch1 (&quot;Hatch 1&quot;, 2D) = &quot;white&quot; &#123;&#125; _Hatch2 (&quot;Hatch 2&quot;, 2D) = &quot;white&quot; &#123;&#125; _Hatch3 (&quot;Hatch 3&quot;, 2D) = &quot;white&quot; &#123;&#125; _Hatch4 (&quot;Hatch 4&quot;, 2D) = &quot;white&quot; &#123;&#125; _Hatch5 (&quot;Hatch 5&quot;, 2D) = &quot;white&quot; &#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; //渲染轮廓线 UsePass &quot;Unity Shaders Book/Chapter 14/Toon Shading/OUTLINE&quot; //渲染素描效果 Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; CGPROGRAM #pragma vertex vert #pragma fragment frag #pragma multi_compile_fwdbase #include &quot;UnityCG.cginc&quot; #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; #include &quot;UnityShaderVariables.cginc&quot; fixed4 _Color; float _TileFactor; sampler2D _Hatch0; sampler2D _Hatch1; sampler2D _Hatch2; sampler2D _Hatch3; sampler2D _Hatch4; sampler2D _Hatch5; struct a2v &#123; float4 vertex : POSITION; float4 tangent : TANGENT; float3 normal : NORMAL; float2 texcoord : TEXCOORD0; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float2 uv : TEXCOORD0; //存储混合六张纹理的权重 fixed3 hatchWeights0 : TEXCOORD1; fixed3 hatchWeights1 : TEXCOORD2; float3 worldPos : TEXCOORD3; SHADOW_COORDS(4) &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); //根据_TileFactor得到纹理坐标 o.uv = v.texcoord.xy * _TileFactor; //计算逐顶点光照，使用漫反射系数计算混合不同纹理的权重 fixed3 worldLightDir = normalize(WorldSpaceLightDir(v.vertex)); fixed3 worldNormal = UnityObjectToWorldNormal(v.normal); fixed diff = max(0, dot(worldLightDir, worldNormal)); //权重初始化为0 o.hatchWeights0 = fixed3(0, 0, 0); o.hatchWeights1 = fixed3(0, 0, 0); //把diff缩放到[0,7] float hatchFactor = diff * 7.0; //把[0,7]均匀的分成七个子区间，判断hatchFactor所处的区间，以决定混合权重 if (hatchFactor &gt; 6.0) &#123; // Pure white, do nothing &#125; else if (hatchFactor &gt; 5.0) &#123; o.hatchWeights0.x = hatchFactor - 5.0; &#125; else if (hatchFactor &gt; 4.0) &#123; o.hatchWeights0.x = hatchFactor - 4.0; o.hatchWeights0.y = 1.0 - o.hatchWeights0.x; &#125; else if (hatchFactor &gt; 3.0) &#123; o.hatchWeights0.y = hatchFactor - 3.0; o.hatchWeights0.z = 1.0 - o.hatchWeights0.y; &#125; else if (hatchFactor &gt; 2.0) &#123; o.hatchWeights0.z = hatchFactor - 2.0; o.hatchWeights1.x = 1.0 - o.hatchWeights0.z; &#125; else if (hatchFactor &gt; 1.0) &#123; o.hatchWeights1.x = hatchFactor - 1.0; o.hatchWeights1.y = 1.0 - o.hatchWeights1.x; &#125; else &#123; o.hatchWeights1.y = hatchFactor; o.hatchWeights1.z = 1.0 - o.hatchWeights1.y; &#125; o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; TRANSFER_SHADOW(o); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; fixed4 hatchTex0 = tex2D(_Hatch0, i.uv) * i.hatchWeights0.x; fixed4 hatchTex1 = tex2D(_Hatch1, i.uv) * i.hatchWeights0.y; fixed4 hatchTex2 = tex2D(_Hatch2, i.uv) * i.hatchWeights0.z; fixed4 hatchTex3 = tex2D(_Hatch3, i.uv) * i.hatchWeights1.x; fixed4 hatchTex4 = tex2D(_Hatch4, i.uv) * i.hatchWeights1.y; fixed4 hatchTex5 = tex2D(_Hatch5, i.uv) * i.hatchWeights1.z; //留白 fixed4 whiteColor = fixed4(1, 1, 1, 1) * (1 - i.hatchWeights0.x - i.hatchWeights0.y - i.hatchWeights0.z - i.hatchWeights1.x - i.hatchWeights1.y - i.hatchWeights1.z); fixed4 hatchColor = hatchTex0 + hatchTex1 + hatchTex2 + hatchTex3 + hatchTex4 + hatchTex5 + whiteColor; UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); return fixed4(hatchColor.rgb * _Color.rgb * atten, 1.0); &#125; ENDCG &#125; &#125; FallBack &quot;Diffuse&quot;&#125;
渲染效果如下：

在上一节中，我们学习的屏幕后处理效果都只是在屏幕颜色图像上进行各种操作来实现的。然而，很多时候我们不仅需要当前屏幕的颜色信息，还希望得到深度和法线信息。例如，在进行边缘检测时，直接利用颜色信息会使检测到的边缘信息受物体纹理和光照等外部因素的影响，得到很多我们不需要的边缘点。一种更好的方法是，我们可以在深度纹理和法线纹理上进行边缘检测，这些图像不会受纹理和光照的影响，而仅仅保存了当前渲染物体的模型信息，通过这样的方式检测出来的边缘更加可靠。在本节中，我们将学习如何在 Unity 中获取深度纹理和法线纹理来实现特定的屏幕后处理效果。
1 获取深度和法线纹理虽然在 Unity 里获取深度和法线纹理的代码非常简单，但是我们有必要在这之前首先了解它们背后的实现原理。 1.1 原理深度纹理实际就是一张渲染纹理，只不过他里面存储的像素值不是颜色值，而是一个高精度的深度值。由于被存储在一张纹理中，深度纹理里的深度值范围是 [0, 1]，而且通常是非线性分布的。这些深度值来自于顶点变换后得到的归一化设备坐标 NDC，回顾之前学习过的投影变换，下图显示了正交投影过程：
下图显示了透视投影过程：
深度值就来自于经过透视除法后的 NDC 中顶点坐标的 z 分量的值，由于 NDC 中 z 分量的范围在 [-1, 1]，因此还要把它映射到 [0, 1] 以存储在纹理中。 那么 Unity 是怎么得到这样一张深度纹理的呢？在 Unity 中，深度纹理可以直接来自于真正的深度缓存，也可以是由一个单独的 Pass 渲染而得，这取决于使用的渲染路径和硬件。通常来讲，当使用延迟渲染路径时，深度纹理理所当然可以访问到，因为延迟渲染会把这些信息渲染到 G-buffer 中 。而当无法直接获取深度缓存时，深度和法线纹理是通过一个单独的 Pass 渲染而得的 。具体实现是，Unity 会使用着色器替换（Shader Replacement）技术选择那些渲染类型（即 SubShader 的 RenderType 标签）为 Opaque 的物体，判断他们使用的渲染队列是否小于等于 2500（(内置的 Background、Geometry 和 AlphaTest 渲染队列均在此范围内），如果满足条件就把它渲染到深度和法线纹理中，因此，要想让物体能够出现在深度和法线纹理中，就必须正确设置 RenderType 标签。 在 Unity 中，我们可以选择让一个摄像机生成一张深度纹理或是一张深度＋法线纹理。当选择前者，即只需要一张单独的深度纹理时， Unity 会直接获取深度缓存或是按之前讲到的着色器替换技术，选取需要的不透明物体，并使用它投射阴影时使用的 Pass（即 LightMode 被设置为ShadowCaster 的 Pass）来得到深度纹理。如果 Shader 中不包含这样一个 Pass, 那么这个物体就不会出现在深度纹理中（当然，它也不能向其他物体投射阴影）。深度纹理的精度通常是 24 位或 16 位，这取决于使用的深度缓存的精度。如果选择生成一张深度＋法线纹理， Unity 会创建一张和屏幕分辨率相同、精度为 32 位（每个通道为 8 位）的纹理，其中观察空间下的法线信息会被编码进纹理的 R 和 G 通道，而深度信息会被编码进 B 和 A 通道。 法线信息的获取在延迟渲染中是可以非常容易就得到的， Unity 只需要合并深度和法线缓存即可。而在前向渲染中，默认情况下是不会创建法线缓存的，因此 Unity 底层使用了一个单独的 Pass 把整个场景再次渲染一遍来完成。这个 Pass 被包含在 Unity 内置的一个 Unity Shader 中，我们可以在内置的 builtin_ shaders-xxx/DefaultResources/Camera-DepthNormaITexture.shader 文件中找到这个用于渲染深度和法线信息的 Pass。 1.2 获取在 Unity 中，获取深度纹理是非常简单的，只需要在在脚本中设置摄像机的 depthTextureMode 即可，然后就可以在 Shader 中直接访问特定的纹理属性了。我们可以使用下面的代码获取深度纹理： camera.depthTextureMode = DepthTextureMode.Depth;
一旦设置好了上面的摄像机模式后，我们就可以在 Shader 中通过声明 _CameraDepthTexture 变量来访问它。 同理，如果想要获取深度＋法线纹理，我们只需要在代码中这样设置： camera.depthTextureMode = DepthTextureMode.DepthNormals;
然后在 Shader 中通过声明 _CameraDepthNormalsTexture 变量来访问它。 我们还可以组合这些模式，让一个摄像机同时产生一张深度和深度 + 法线纹理： camera.depthTextureMode |= DepthTextureMode.Depth;camera.depthTextureMode |= DepthTextureMode.DepthNormals;
当在 Shader 中访问到深度纹理 _CameraDepthTexture 后，我们就可以使用当前像素的纹理坐标对它进行采样，绝大多数情况下直接使用 Tex2D 即可，但在某些平台可能需要一些特殊处理， Unity 为我们提供了一个统一的宏 SAMPLE_DEPTH_TEXTURE，用来处理这些由于平台差异造成的问题。而我们只需要在 Shader 中使用即可： float d = SAMPLE_DEPTH_TEXTURE (_CameraDepthTexture, i.uv);
当通过纹理采样得到深度值后，这些深度值往往是非线性的，这种非线性来自于透视投影使 用的裁剪矩阵。 然而，在我们的计算过程中通常是需要线性的深度值，也就是说，我们需要把投 影后的深度值变换到线性空间下，例如视角空间下的深度值。Unity 提供了两个辅助函数来进行转换，LinearEyeDepth 负责把深度纹理的采样结果转换到视角空间下的深度值，Linear01Depth 则会返回一个范围在 [0, 1] 的线性深度值。转换这部分的推导可以查看《Unity Shader 入门精要》13.1.2 节的内容。 如果我们需要获取深度＋法线纹理，可以直接使用 tex2D 函数对 _CameraDepthNormalsTexture 进行采样，得到里面存储的深度和法线信息。Unity 提供了辅助函数来为我们对这个采样结果进行解码，从而得到深度值和法线方向。这个函数是 DecodeDepthNormal，该函数的第一个参数是对深度＋法线纹理的采样结果，这个采样结果是 Unity 对深度和法线信息编码后的结果，它的 xy 分量存储的是视角空间下的法线信息，而深度信息被编码进了 zw 分量。通过调用 DecodeDepthNormal 函数对采样结果解码后，我们就可以得到解码后的深度值和法线。这个深度值是范围在 [0, 1] 的线性深度值（这与单独的深度纹理中存储的深度值不同），而得到的法线则是视角空间下的法线方向。DecodeDepthNormal 函数如下： inline void DecodeDepthNormal (float4 enc, out float depth, out float3 normal)&#123; depth = DecodeFloatRG(enc.ze); normal = DecodeViewNormalStereo(enc);&#125;
我们也可以自己用 DecodeFloatRG 和 DecodeViewNormalStereo 函数解码。 2 再谈运动模糊在上一节中，我们学习了如何通过混合多张屏幕图像来模拟运动模糊的效果。但是，另一种应用更加广泛的技术则是使用速度映射图。速度映射图中存储了每个像素的速度，然后使用这个速度来决定模糊的方向和大小。速度缓冲的生成有多种方法，一种方法是把场景中所有物体的速度渲染到一张纹理中。但这种方法的缺点在于需要修改场景中所有物体的 Shader 代码，使其添加计算速度的代码并输出到一个渲染纹理中。 《GPU Gems3》在第 27 章中介绍了一种生成速度映射图的方法。这种方法利用深度纹理在片元着色器中为每个像素计算其在世界空间下的位置，这是通过使用当前的视角＊投影矩阵的逆矩阵对 NDC 下的顶点坐标进行变换得到的，当得到世界空间中的顶点坐标后，我们使用前一帧的视角＊投影矩阵对其进行变换， 得到该位置在前一帧中的 NDC 坐标。然后，我们计算前一帧和当前帧的位置差，生成该像素的速度。这种方法的优点是可以在一个屏幕后处理步骤中完成整个效果的模拟，但缺点是需要在片元着色器中进行两次矩阵乘法的操作，对性能有所影响。 我们首先来编写 cs 脚本： using UnityEngine;using System.Collections;public class MotionBlurWithDepthTexture : PostEffectsBase &#123; public Shader motionBlurShader; private Material motionBlurMaterial = null; public Material material &#123; get &#123; motionBlurMaterial = CheckShaderAndCreateMaterial(motionBlurShader, motionBlurMaterial); return motionBlurMaterial; &#125; &#125; //由于要用到摄像机的视角和投影矩阵，因此要定义一个Cmaera类型的变量以获取该脚本所在的摄像机组件 private Camera myCamera; public Camera camera &#123; get &#123; if (myCamera == null) &#123; myCamera = GetComponent&lt;Camera&gt;(); &#125; return myCamera; &#125; &#125; //定义运动模糊时模糊图像使用的大小 [Range(0.0f, 1.0f)] public float blurSize = 0.5f; //用于保存前一帧的视角*投影矩阵 private Matrix4x4 previousViewProjectionMatrix; //当脚本可用时，设置摄像机的状态以获取深度纹理 void OnEnable() &#123; camera.depthTextureMode |= DepthTextureMode.Depth; previousViewProjectionMatrix = camera.projectionMatrix * camera.worldToCameraMatrix; &#125; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; material.SetFloat(&quot;_BlurSize&quot;, blurSize); // 给材质传递前一帧的视角 * 投影矩阵 material.SetMatrix(&quot;_PreviousViewProjectionMatrix&quot;, previousViewProjectionMatrix); // 计算当前帧的视角 * 投影矩阵 Matrix4x4 currentViewProjectionMatrix = camera.projectionMatrix * camera.worldToCameraMatrix; // 求逆 Matrix4x4 currentViewProjectionInverseMatrix = currentViewProjectionMatrix.inverse; // 给材质传递前帧的视角 * 投影矩阵的逆矩阵 material.SetMatrix(&quot;_CurrentViewProjectionInverseMatrix&quot;, currentViewProjectionInverseMatrix); // 更新前一帧的视角 * 投影矩阵 previousViewProjectionMatrix = currentViewProjectionMatrix; Graphics.Blit (src, dest, material); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
然后编写 Shader： Shader &quot;Unity Shaders Book/Chapter 13/Motion Blur With Depth Texture&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _BlurSize (&quot;Blur Size&quot;, Float) = 1.0 &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; half4 _MainTex_TexelSize; // Unity提供的深度纹理 sampler2D _CameraDepthTexture; // 两个矩阵由脚本传递而来 float4x4 _CurrentViewProjectionInverseMatrix; float4x4 _PreviousViewProjectionMatrix; half _BlurSize; struct v2f &#123; float4 pos : SV_POSITION; half2 uv : TEXCOORD0; half2 uv_depth : TEXCOORD1; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); // 主纹理和深度纹理采样坐标是一样的 o.uv = v.texcoord; o.uv_depth = v.texcoord; // 平台差异化处理 #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) o.uv_depth.y = 1 - o.uv_depth.y; #endif return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; // 获取当前像素的深度值，通过对深度纹理采样得到 float d = SAMPLE_DEPTH_TEXTURE(_CameraDepthTexture, i.uv_depth); // 构造该像素的NDC坐标，通过对深度纹理进行反映射得到 // 因为深度纹理的深度是从NDC的z坐标映射到[0, 1]范围的，所以再映射回去作为z分量 // NDC的xy分量通过纹理坐标的xy映射而来 float4 H = float4(i.uv.x * 2 - 1, i.uv.y * 2 - 1, d * 2 - 1, 1); // 对NDC进行VP变换的逆变换并将结果除以w分量，以得到世界空间下的顶点坐标 float4 D = mul(_CurrentViewProjectionInverseMatrix, H); float4 worldPos = D / D.w; // 当前屏幕空间坐标 float4 currentPos = H; // 用计算得到的世界空间坐标乘以前一帧的VP变换矩阵得到前一帧的屏幕空间坐标，同样要记得除以w分量 float4 previousPos = mul(_PreviousViewProjectionMatrix, worldPos); previousPos /= previousPos.w; // 计算前一帧和后一帧屏幕坐标的差以得到该像素的速度 float2 velocity = (currentPos.xy - previousPos.xy)/2.0f; float2 uv = i.uv; float4 c = tex2D(_MainTex, uv); // 利用该速度值对该像素的邻域像素进行采样，_BlurSize控制采样距离 // 采样结果相加后取平均得到模糊效果 uv += velocity * _BlurSize; for (int it = 1; it &lt; 3; it++, uv += velocity * _BlurSize) &#123; float4 currentColor = tex2D(_MainTex, uv); c += currentColor; &#125; c /= 3; return fixed4(c.rgb, 1.0); &#125; ENDCG Pass &#123; ZTest Always Cull Off ZWrite Off CGPROGRAM #pragma vertex vert #pragma fragment frag ENDCG &#125; &#125; FallBack Off&#125;
没有运动模糊的效果如下：
使用上面的方法得到的运动模糊效果如下：
3 全局雾效雾效（Fog）是游戏里经常使用的一种效果。 Unity 内置的雾效可以产生基于距离的线性或指数雾效。然而，要想在自己编写的顶点／片元着色器中实现这些雾效，我们需要在 Shader 中添加 #pragma multi_compile_fog 指令，同时还需要使用相关的内置宏，例如 UNITY_FOG_COORDS 、UNITY_TRANSFER_FOG 和 UNTTY_APPLY_FOG 等。这种方法的缺点在于，我们不仅需要为场景中所有物体添加相关的渲染代码，而且能够实现的效果也非常有限。当我们需要对雾效进行一些个性化操作时，例如使用基于高度的雾效等，仅仅使用 Unity 内置的雾效就变得不再可行。 在本节中，我们将会学习一种基于屏幕后处理的全局雾效的实现。使用这种方法，我们不需要更改场景内渲染的物体所使用的 Shader 代码，而仅仅依靠一次屏幕后处理的步骤即可。这种方法的自由性很高，我们可以方便地模拟各种雾效，例如均匀的雾效、基于距离的线性&#x2F;指数雾效、基于高度的雾效等。 基于屏幕后处理的全局雾效的关键是，根据深度纹理来重建每个像素在世界空间下的位置。尽管我们在模拟运动模糊时已经实现了这个要求，即构建出当前像素的 NDC 坐标，再通过当前摄像机的视角＊投影矩阵的逆矩阵来得到世界空间下的像素坐标，但是这样的实现需要在片元着色器中进行矩阵乘法的操作，而这通常会影响游戏性能。在本节中，我们将会学习一个快速从深度纹理中重建世界坐标的方法。 这种方法首先对图像空间下的视锥体射线（从摄像机出发，指向图像上的某点的射线）进行插值，这条射线存储了该像素在世界空间下到摄像机的方向信息。然后，我们把该射线和线性化后的视角空间下的深度值相乘，再加上摄像机的世界位置，就可以得到该像素在世界空间下的位置。当我们得到世界坐标后，就可以轻松地使用各个公式来模拟全局雾效了。 3.1 重建世界坐标我们知道，坐标系中的一个顶点坐标可以通过它相对于另一个顶点坐标的偏移量来求得建像素的世界坐标就是基于这样的思想。我们只需要知道摄像机在世界空间下的位置，以及世界空间下该像素相对于摄像机的偏移量，把它们相加就可以得到该像素的世界坐标。整个过程可以使用下面的代码来表示： float4 worldPos = _WorldSpaceCameraPos + linearDepth * interpolatedRay;
其中，_WorldSpaceCameraPos 可以通过内置变量直接访问，linearDepth * interpolatedRay 则可以计算得到该像素相对于摄像机的偏移量，linearDepth 是由深度纹理得到的线性深度值， interpolatedRay 是由顶点着色器输出并插值后得到的射线，它不仅包含了该像素到摄像机的方向，也包含了距离信息。linearDepth 的获取我们已经学习过了，因此，现在来看 interpolatedRay 的求法。 interpolatedRay 来源于对近裁剪平面的 4 个角的某个特定向量的插值，这 4 个向量包含了它们到摄像机的方向和距离信息，我们可以利用摄像机的近裁剪平面距离、 FOV、横纵比计算而得，如下图：
为了方便计算，我们可以先计算两个辅助向量—— $toTop$ 和 $toRight$，他们是起点位于近裁剪平面中心，分别指向摄像机正上方和正右方的向量，计算公式如下：$$halfHeight &#x3D; Near \times tan(\frac{FOV}{2}) \toTop &#x3D; HalfHeight · camera.up \toRight &#x3D; HalfHeight · camera.right$$其中，$Near$ 是近裁剪平面的距离，$FOV$ 是竖直方向的视角范围，$camera.up$ 、 $camera.right$ 分别对应了摄像机的正上方和正右方。当得到这两个辅助向量后，我们就可以计算 4 个角相对于摄像机的方向了。以左上角TL为例：$$TL &#x3D; camera.forward · Near + toTop - toRight$$通过看图，上式很容易理解，同理其他三个角的向量：$$TR &#x3D; camera.forward · Near + toTop + toRight \BL &#x3D; camera.forward · Near - toTop - toRight \BR &#x3D; camera.forward · Near - toTop + toRight$$注意，上面求得的 4 个向量不仅包含了方向信息，它们的模对应了 4 个点到摄像机的空间距离。由于我们得到的线性深度值并非是点到摄像机的欧式距离，而是在 z 方向上的距离，如下图：
因此我们不能直接使用深度值和 4 个角的单位方向的乘积来计算它们到摄像机的偏移量，不过想要把深度值转换成到摄像机的欧式距离也很简单，我们以 TL 点为例，根据相似三角形原理，TL 所在的射线上，像素的深度值和它到摄像机的实际距离的比等于近裁剪平面的距离和 TL 向量的模的比，即：$$\frac{depth}{dist} &#x3D; \frac{Near}{|TL|}$$由此即可得到 TL 射线上的点距离摄像机的欧氏距离：$$dist &#x3D; depth \times \frac{|TL|}{Near}$$由于 4 个点相互对称，因此其他 3 个向量的模和 TL 相等，即我们可以使用同一个因子：$$scale &#x3D; \frac{|TL|}{|Near|}$$和单位向量相乘，得到它们对应的向量值：$$Ray_{TL} &#x3D; \frac{TL}{|TL|}\times scale \Ray_{TR} &#x3D; \frac{TR}{|TR|}\times scale \Ray_{BL} &#x3D; \frac{BL}{|BL|}\times scale \Ray_{BR} &#x3D; \frac{BR}{|BR|}\times scale$$屏幕后处理的原理是使用特定的材质去渲染一个刚好填充整个屏幕的四边形面片。这个四边形面片的 4 个顶点就对应了近裁剪平面的 4 个角。因此，我们可以把上面的计算结果传递给顶点着色器，顶点着色器根据当前的位置选择它所对应的向量，然后再将其输出，经插值后传递给片元着色器得到 interpolatedRay，我们就可以直接利用一开始提到的公式重建该像素在世界空间的位置了。 3.2 雾的计算在简单的雾效实现中，我们需要计算一个雾效系数 f，作为混合原颜色和雾的颜色的混合系数： float3 afterFog = f * fogColor + (1 - f) * oriColor
这个雾效系数 f 有很多计算方法。在 Unity 内置的雾效实现中，支待三种雾的计算方式，给定距离 z 后，f 的计算方式如下:
线性：
$$f &#x3D; \frac{d_{max} - |z|}{d_{max} - d_{min}}$$ 其中 $d_{min}$ 和 $d_{max}$ 分别表示受雾影响的最小距离和最大距离。
指数：
$$f &#x3D; e^{-d·|z|}$$ 其中 d 是控制雾的浓度的参数。
指数平方：
$$f &#x3D; e^{-(d-|z|)^2}$$ 其中 d 是控制雾的浓度的参数。 在本节中，我们将使用类似线性雾的计算方式，计算基于高度的雾效。具体方法是，用给定一点在世界空间下的高度 y 后替换线性计算公式中的距离 z。 3.3 实现首先是 cs 脚本： using UnityEngine;using System.Collections;public class FogWithDepthTexture : PostEffectsBase &#123; public Shader fogShader; private Material fogMaterial = null; public Material material &#123; get &#123; fogMaterial = CheckShaderAndCreateMaterial(fogShader, fogMaterial); return fogMaterial; &#125; &#125; //我们需要获取摄像机的相关参数，如近裁剪平面的距离、FOV等，同时还需要获取摄像机在世界空间下的前方、上方和右方等方向 //因此我们用两个变量存储摄像机的Camera组件和Transform组件 private Camera myCamera; public Camera camera &#123; get &#123; if (myCamera == null) &#123; myCamera = GetComponent&lt;Camera&gt;(); &#125; return myCamera; &#125; &#125; private Transform myCameraTransform; public Transform cameraTransform &#123; get &#123; if (myCameraTransform == null) &#123; myCameraTransform = camera.transform; &#125; return myCameraTransform; &#125; &#125; //定义模拟雾效的各个参数 [Range(0.0f, 3.0f)] public float fogDensity = 1.0f; public Color fogColor = Color.white; //受雾效影响的最小高度和最大高度 public float fogStart = 0.0f; public float fogEnd = 2.0f; //设置相机状态获取深度纹理 void OnEnable() &#123; camera.depthTextureMode |= DepthTextureMode.Depth; &#125; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; //计算近裁剪平面4个角对应的向量 Matrix4x4 frustumCorners = Matrix4x4.identity; float fov = camera.fieldOfView; float near = camera.nearClipPlane; float aspect = camera.aspect; float halfHeight = near * Mathf.Tan(fov * 0.5f * Mathf.Deg2Rad); Vector3 toRight = cameraTransform.right * halfHeight * aspect; Vector3 toTop = cameraTransform.up * halfHeight; Vector3 topLeft = cameraTransform.forward * near + toTop - toRight; float scale = topLeft.magnitude / near; topLeft.Normalize(); topLeft *= scale; Vector3 topRight = cameraTransform.forward * near + toRight + toTop; topRight.Normalize(); topRight *= scale; Vector3 bottomLeft = cameraTransform.forward * near - toTop - toRight; bottomLeft.Normalize(); bottomLeft *= scale; Vector3 bottomRight = cameraTransform.forward * near + toRight - toTop; bottomRight.Normalize(); bottomRight *= scale; frustumCorners.SetRow(0, bottomLeft); frustumCorners.SetRow(1, bottomRight); frustumCorners.SetRow(2, topRight); frustumCorners.SetRow(3, topLeft); material.SetMatrix(&quot;_FrustumCornersRay&quot;, frustumCorners); material.SetFloat(&quot;_FogDensity&quot;, fogDensity); material.SetColor(&quot;_FogColor&quot;, fogColor); material.SetFloat(&quot;_FogStart&quot;, fogStart); material.SetFloat(&quot;_FogEnd&quot;, fogEnd); Graphics.Blit (src, dest, material); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
然后编写 Shader： Shader &quot;Unity Shaders Book/Chapter 13/Fog With Depth Texture&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _FogDensity (&quot;Fog Density&quot;, Float) = 1.0 _FogColor (&quot;Fog Color&quot;, Color) = (1, 1, 1, 1) _FogStart (&quot;Fog Start&quot;, Float) = 0.0 _FogEnd (&quot;Fog End&quot;, Float) = 1.0 &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; float4x4 _FrustumCornersRay; sampler2D _MainTex; half4 _MainTex_TexelSize; sampler2D _CameraDepthTexture; half _FogDensity; fixed4 _FogColor; float _FogStart; float _FogEnd; struct v2f &#123; float4 pos : SV_POSITION; half2 uv : TEXCOORD0; half2 uv_depth : TEXCOORD1; float4 interpolatedRay : TEXCOORD2; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uv = v.texcoord; o.uv_depth = v.texcoord; #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) o.uv_depth.y = 1 - o.uv_depth.y; #endif // 找到对应的顶点的向量，虽然有很多if判断，但实际上我们渲染的四边形只有4个顶点，因此对性能不会有太大影响 int index = 0; if (v.texcoord.x &lt; 0.5 &amp;&amp; v.texcoord.y &lt; 0.5) &#123; index = 0; &#125; else if (v.texcoord.x &gt; 0.5 &amp;&amp; v.texcoord.y &lt; 0.5) &#123; index = 1; &#125; else if (v.texcoord.x &gt; 0.5 &amp;&amp; v.texcoord.y &gt; 0.5) &#123; index = 2; &#125; else &#123; index = 3; &#125; #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) index = 3 - index; #endif o.interpolatedRay = _FrustumCornersRay[index]; return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; //得到像素的线性深度 float linearDepth = LinearEyeDepth(SAMPLE_DEPTH_TEXTURE(_CameraDepthTexture, i.uv_depth)); //按照公式计算该像素对应的世界空间坐标 float3 worldPos = _WorldSpaceCameraPos + linearDepth * i.interpolatedRay.xyz; // 按照公式计算雾效系数f，使用_FogDensity控制雾效浓度 float fogDensity = (_FogEnd - worldPos.y) / (_FogEnd - _FogStart); fogDensity = saturate(fogDensity * _FogDensity); fixed4 finalColor = tex2D(_MainTex, i.uv); //利用雾效系数混合原颜色和雾效颜色 finalColor.rgb = lerp(finalColor.rgb, _FogColor.rgb, fogDensity); return finalColor; &#125; ENDCG Pass &#123; ZTest Always Cull Off ZWrite Off CGPROGRAM #pragma vertex vert #pragma fragment frag ENDCG &#125; &#125; FallBack Off&#125;
渲染效果如下：
4 再谈边缘检测之前我们使用 Sobel 算子对屏幕图像进行边缘检测，实现描边的效果。但是，这种直接利用颜色信息进行边缘检测的方法会产生很多我们不希望得到的边缘线，如下图：
可以看出，物体的纹理、阴影等位置也被描上黑边，而这往往不是我们希望看到的。在本节中我们将学习如何在深度和法线纹理上进行边缘检测，这些图像不会受纹理和光照的影响，而仅仅保存了当前渲染物体的模型信息，通过这样的方式检测出来的边缘更加可靠。如下图：
本节使用 Roberts 算子来进行边缘检测，它使用的卷积核如下图：
Roberts 算子的本质就是计算左上角和右下角的差值，乘以右上角和左下角的差值，作为评估边缘的依据。我们在实现中取对角方向的深度或法线值，比较它们之间的差值，如果超过某个阈值（可由参数控制），就认为它们之间存在一条边。 首先是 cs 脚本： using UnityEngine;using System.Collections;public class EdgeDetectNormalsAndDepth : PostEffectsBase &#123; public Shader edgeDetectShader; private Material edgeDetectMaterial = null; public Material material &#123; get &#123; edgeDetectMaterial = CheckShaderAndCreateMaterial(edgeDetectShader, edgeDetectMaterial); return edgeDetectMaterial; &#125; &#125; [Range(0.0f, 1.0f)] public float edgesOnly = 0.0f; public Color edgeColor = Color.black; public Color backgroundColor = Color.white; //采样距离 public float sampleDistance = 1.0f; //邻域的深度相差多少会认为存在一条边，灵敏度如果很大，那么很小的变化也会认为是边缘 public float sensitivityDepth = 1.0f; //邻域的法线相差多少会认为存在一条边，灵敏度如果很大，那么很小的变化也会认为是边缘 public float sensitivityNormals = 1.0f; //设置摄像机产生深度+法线纹理 void OnEnable() &#123; GetComponent&lt;Camera&gt;().depthTextureMode |= DepthTextureMode.DepthNormals; &#125; //正常情况下OnRenderImage函数会在所有不透明和透明物体渲染完后被调用 //但我们希望边缘检测只对不透明物体描边，因此使用下面的ImageEffectOpaque声明 //使得OnRenderImage函数在不透明物体渲染完后立即调用 [ImageEffectOpaque] void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; material.SetFloat(&quot;_EdgeOnly&quot;, edgesOnly); material.SetColor(&quot;_EdgeColor&quot;, edgeColor); material.SetColor(&quot;_BackgroundColor&quot;, backgroundColor); material.SetFloat(&quot;_SampleDistance&quot;, sampleDistance); material.SetVector(&quot;_Sensitivity&quot;, new Vector4(sensitivityNormals, sensitivityDepth, 0.0f, 0.0f)); Graphics.Blit(src, dest, material); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
重点是 Shader： Shader &quot;Unity Shaders Book/Chapter 13/Edge Detection Normals And Depth&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _EdgeOnly (&quot;Edge Only&quot;, Float) = 1.0 _EdgeColor (&quot;Edge Color&quot;, Color) = (0, 0, 0, 1) _BackgroundColor (&quot;Background Color&quot;, Color) = (1, 1, 1, 1) _SampleDistance (&quot;Sample Distance&quot;, Float) = 1.0 _Sensitivity (&quot;Sensitivity&quot;, Vector) = (1, 1, 1, 1) &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; sampler2D _MainTex; half4 _MainTex_TexelSize; fixed _EdgeOnly; fixed4 _EdgeColor; fixed4 _BackgroundColor; float _SampleDistance; half4 _Sensitivity; //深度+法线纹理 sampler2D _CameraDepthNormalsTexture; struct v2f &#123; float4 pos : SV_POSITION; half2 uv[5]: TEXCOORD0; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); half2 uv = v.texcoord; o.uv[0] = uv; #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) uv.y = 1 - uv.y; #endif //四个对角线邻域的纹理坐标，在顶点着色器计算出坐标之后插值传递给片元着色器以减少性能开销 o.uv[1] = uv + _MainTex_TexelSize.xy * half2(1,1) * _SampleDistance; o.uv[2] = uv + _MainTex_TexelSize.xy * half2(-1,-1) * _SampleDistance; o.uv[3] = uv + _MainTex_TexelSize.xy * half2(-1,1) * _SampleDistance; o.uv[4] = uv + _MainTex_TexelSize.xy * half2(1,-1) * _SampleDistance; return o; &#125; //用来判断深度+法线纹理上的两个采样点的深度和法线的差异 half CheckSame(half4 center, half4 sample) &#123; //解码得到两个采样点的法线和深度值 //法线并没有解码成真正的法线值，直接使用了xy分量 //这是因为我们只需要两个法线的差异，不需要知道真正的法线是什么 half2 centerNormal = center.xy; float centerDepth = DecodeFloatRG(center.zw); half2 sampleNormal = sample.xy; float sampleDepth = DecodeFloatRG(sample.zw); // 计算法线的差异乘以灵敏度 half2 diffNormal = abs(centerNormal - sampleNormal) * _Sensitivity.x; // 差异的xy分量相加和阈值比较，如果小于该阈值返回1，否则返回0 int isSameNormal = (diffNormal.x + diffNormal.y) &lt; 0.1; // 计算深度差异乘以灵敏度 float diffDepth = abs(centerDepth - sampleDepth) * _Sensitivity.y; // 同上对比两个深度值差异是否满足条件 int isSameDepth = diffDepth &lt; 0.1 * centerDepth; // 将法线和深度差异的结果相乘返回 return isSameNormal * isSameDepth ? 1.0 : 0.0; &#125; fixed4 fragRobertsCrossDepthAndNormal(v2f i) : SV_Target &#123; half4 sample1 = tex2D(_CameraDepthNormalsTexture, i.uv[1]); half4 sample2 = tex2D(_CameraDepthNormalsTexture, i.uv[2]); half4 sample3 = tex2D(_CameraDepthNormalsTexture, i.uv[3]); half4 sample4 = tex2D(_CameraDepthNormalsTexture, i.uv[4]); half edge = 1.0; edge *= CheckSame(sample1, sample2); edge *= CheckSame(sample3, sample4); fixed4 withEdgeColor = lerp(_EdgeColor, tex2D(_MainTex, i.uv[0]), edge); fixed4 onlyEdgeColor = lerp(_EdgeColor, _BackgroundColor, edge); return lerp(withEdgeColor, onlyEdgeColor, _EdgeOnly); &#125; ENDCG Pass &#123; ZTest Always Cull Off ZWrite Off CGPROGRAM #pragma vertex vert #pragma fragment fragRobertsCrossDepthAndNormal ENDCG &#125; &#125; FallBack Off&#125;
渲染效果如下：
只显示描边：
当我们增大采样距离，得到的效果如下：
视觉上就是描边更粗了。 本节实现的描边效果是基于整个屏幕空间进行的，也就是说，场景内的所有物体都会被添加描边效果。但有时，我们希望只对特定的物体进行描边，例如当玩家选中场景中的某个物体后， 我们想要在该物体周围添加一层描边效果。这时，我们可以使用 Unity 提供的 Graphics.DrawMesh 或 Graphics.DrawMeshNow 函数把需要描边的物体再次渲染一遍（在所有不透明物体渲染完毕之后），然后再使用本节提到的边缘检测算法计算深度或法线纹理中每个像素的梯度值，判断它们是否小于某个阈值，如果是，就在 Shader 中使用 clip 函数将该像素剔除掉，从而显示出原来的物体颜色。

很多时候，向规则的事物里添加一些“杂乱无章”的效果往往会有意想不到的效果。而这些“杂乱无章”的效果来源就是噪声。在本节中，我们将会学习如何使用噪声来模拟火焰消融、波光粼粼、云雾飘渺等各种特效。
1 消融效果消融 (dissolve) 效果常见于游戏中的角色死亡、地图烧毁等效果。在这些效果中，消融往往从不同的区域开始，并向看似随机的方向扩张，最后整个物体都将消失不见。消融效果的原理非常简单，概括来说就是噪声纹理＋透明度测试。我们使用对噪声纹理采样的结果和某个控制消融程度的阈值比较，如果小于阈值，就使用 clip 函数把它对应的像素裁剪掉，这些部分就对应了图中被“烧毁”的区域。而镂空区域边缘的烧焦效果则是将两种颜色混合，再用 pow 函数处理后，与原纹理颜色混合后的结果。 Shader &quot;Unity Shaders Book/Chapter 15/Dissolve&quot; &#123; Properties &#123; // 用于控制消融程度，值为1时物体完全消融 _BurnAmount (&quot;Burn Amount&quot;, Range(0.0, 1.0)) = 0.0 // 模拟烧焦效果时的线宽，值越大，火焰边缘的蔓延范围越广 _LineWidth(&quot;Burn Line Width&quot;, Range(0.0, 0.2)) = 0.1 // 主纹理 _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; // 法线纹理 _BumpMap (&quot;Normal Map&quot;, 2D) = &quot;bump&quot; &#123;&#125; // 火焰边缘的两种颜色值 _BurnFirstColor(&quot;Burn First Color&quot;, Color) = (1, 0, 0, 1) _BurnSecondColor(&quot;Burn Second Color&quot;, Color) = (1, 0, 0, 1) // 噪声纹理 _BurnMap(&quot;Burn Map&quot;, 2D) = &quot;white&quot;&#123;&#125; &#125; SubShader &#123; Tags &#123; &quot;RenderType&quot;=&quot;Opaque&quot; &quot;Queue&quot;=&quot;Geometry&quot;&#125; Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; // 关闭剔除，因为模型消融会使内部构造显现出来 Cull Off CGPROGRAM #include &quot;Lighting.cginc&quot; #include &quot;AutoLight.cginc&quot; #pragma multi_compile_fwdbase #pragma vertex vert #pragma fragment frag fixed _BurnAmount; fixed _LineWidth; sampler2D _MainTex; sampler2D _BumpMap; fixed4 _BurnFirstColor; fixed4 _BurnSecondColor; sampler2D _BurnMap; float4 _MainTex_ST; float4 _BumpMap_ST; float4 _BurnMap_ST; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; float4 tangent : TANGENT; float4 texcoord : TEXCOORD0; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float2 uvMainTex : TEXCOORD0; float2 uvBumpMap : TEXCOORD1; float2 uvBurnMap : TEXCOORD2; float3 lightDir : TEXCOORD3; float3 worldPos : TEXCOORD4; SHADOW_COORDS(5) &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uvMainTex = TRANSFORM_TEX(v.texcoord, _MainTex); o.uvBumpMap = TRANSFORM_TEX(v.texcoord, _BumpMap); o.uvBurnMap = TRANSFORM_TEX(v.texcoord, _BurnMap); // 光线从模型空间变换到切线空间，因为用到了法线纹理，要在切线空间计算光照 TANGENT_SPACE_ROTATION; o.lightDir = mul(rotation, ObjSpaceLightDir(v.vertex)).xyz; // 为了得到阴影信息，计算世界空间下的顶点位置以及阴影纹理的采样坐标 o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; TRANSFER_SHADOW(o); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; // 对噪声纹理采样 fixed3 burn = tex2D(_BurnMap, i.uvBurnMap).rgb; // 采样值和控制消融程度的参数相减传递给clip函数 // 当结果小于0时该像素会被剔除，从而不显示到屏幕上 clip(burn.r - _BurnAmount); // 切线空间的光照方向 float3 tangentLightDir = normalize(i.lightDir); // 对法线纹理采样 fixed3 tangentNormal = UnpackNormal(tex2D(_BumpMap, i.uvBumpMap)); // 反射率 fixed3 albedo = tex2D(_MainTex, i.uvMainTex).rgb; // 环境光 fixed3 ambient = UNITY_LIGHTMODEL_AMBIENT.xyz * albedo; // 在切线空间计算漫反射 fixed3 diffuse = _LightColor0.rgb * albedo * max(0, dot(tangentNormal, tangentLightDir)); // 计算烧焦的颜色，要在宽度为_LineWidth范围内模拟一个烧焦的颜色变化 // 首先计算混合系数t，如果t的值为1说明位于消融的边界，t为0时像素为正常的模型颜色 fixed t = 1 - smoothstep(0.0, _LineWidth, burn.r - _BurnAmount); // 使用t混合两种烧焦颜色 fixed3 burnColor = lerp(_BurnFirstColor, _BurnSecondColor, t); // 使用pow对结果进行处理得到最终的烧焦颜色 burnColor = pow(burnColor, 5); UNITY_LIGHT_ATTENUATION(atten, i, i.worldPos); // 再次使用t来混和光照颜色和烧焦颜色，使用step函数保证_BurnAmount为0时不显示任何消融效果 fixed3 finalColor = lerp(ambient + diffuse * atten, burnColor, t * step(0.0001, _BurnAmount)); return fixed4(finalColor, 1); &#125; ENDCG &#125; // 投射阴影的Pass // 因为用到了透明度测试，因此不能用默认的阴影投射Pass，不然被剔除的部分也会投射阴影造成穿帮 Pass &#123; // 正确设置tags Tags &#123; &quot;LightMode&quot; = &quot;ShadowCaster&quot; &#125; CGPROGRAM #pragma vertex vert #pragma fragment frag // 对应的编译指令 #pragma multi_compile_shadowcaster #include &quot;UnityCG.cginc&quot; fixed _BurnAmount; sampler2D _BurnMap; float4 _BurnMap_ST; struct v2f &#123; // 使用Unity内置宏定义投射阴影需要的变量，已经包含了各种需要用到的变量 V2F_SHADOW_CASTER; float2 uvBurnMap : TEXCOORD1; &#125;; // 使用Unity内置的宏来计算阴影需要一些特定的输入 // 比如TRANSFER_SHADOW_CASTER_NORMALOFFSET会使用名称v作为输入结构体，v中需要包含顶点位置和顶点法线 // 内置的appdata_base结构体提供了这些必要的变量 v2f vert(appdata_base v) &#123; v2f o; // 使用内置的宏填充上面声明的各种变量 TRANSFER_SHADOW_CASTER_NORMALOFFSET(o) o.uvBurnMap = TRANSFORM_TEX(v.texcoord, _BurnMap); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; fixed3 burn = tex2D(_BurnMap, i.uvBurnMap).rgb; clip(burn.r - _BurnAmount); // 剔除片元后，使用内置的宏计算阴影投射 SHADOW_CASTER_FRAGMENT(i) &#125; ENDCG &#125; &#125; FallBack &quot;Diffuse&quot;&#125;
接下来编写一个 cs 脚本来随着时间控制材质的 _BurnAmount 属性： using UnityEngine;using System.Collections;public class BurnHelper : MonoBehaviour &#123; public Material material; [Range(0.01f, 1.0f)] public float burnSpeed = 0.3f; private float burnAmount = 0.0f; void Start () &#123; if (material == null) &#123; Renderer renderer = gameObject.GetComponentInChildren&lt;Renderer&gt;(); if (renderer != null) &#123; material = renderer.material; &#125; &#125; if (material == null) &#123; this.enabled = false; &#125; else &#123; material.SetFloat(&quot;_BurnAmount&quot;, 0.0f); &#125; &#125; void Update () &#123; burnAmount = Mathf.Repeat(Time.time * burnSpeed, 1.0f); material.SetFloat(&quot;_BurnAmount&quot;, burnAmount); &#125;&#125;
最终的效果如下：
2 水波效果在模拟实时水面的过程中，我们往往也会使用噪声纹理。此时，噪声纹理通常会用作一个高度图，以不断修改水面的法线方向。为了模拟水不断流动的效果，我们会使用和时间相关的变量来对噪声纹理进行采样，当得到法线信息后，再进行正常的反射＋折射计算，得到最后的水面波动效果。在本节中，我们将会使用一个由噪声纹理得到的法线贴图，实现一个包含菲涅耳反射的水面效果。 首先我们定义一个平面作为水面，类似于之前我们利用反射和折射实现透明玻璃的效果，我们使用一张立方体纹理 (Cubemap) 作为环境纹理，模拟反射；使用 GrabPass 来获取当前屏幕的渲染纹理，并使用切线空间下的法线方向对像素的屏幕坐标进行偏移，再使用该坐标对渲染纹理进行屏幕采样，从而模拟近似的折射效果。但与之前的实现不同，水波的法线纹理是由一张噪声纹理生成而得，而且会随着时间不断平移变化，模拟波光粼粼的效果。此外，我们没有使用一个定值来混合反射和折射的颜色，而是使用之前提到的菲涅耳系数来动态决定混合系数，我们使用如下公式计算菲涅尔系数：$$fresnel &#x3D; pow(1-max(0,\vec v ·\vec n),4)$$其中 $\vec v$ 和 $\vec n$ 分别对应了视角方向和法线方向，他们之间的夹角越小，得到的菲涅尔系数就越小，反射越弱，折射越强。 // Upgrade NOTE: replaced &#x27;_Object2World&#x27; with &#x27;unity_ObjectToWorld&#x27;// Upgrade NOTE: replaced &#x27;mul(UNITY_MATRIX_MVP,*)&#x27; with &#x27;UnityObjectToClipPos(*)&#x27;Shader &quot;Unity Shaders Book/Chapter 15/Water Wave&quot; &#123; Properties &#123; // 用于控制水面颜色 _Color (&quot;Main Color&quot;, Color) = (0, 0.15, 0.115, 1) // 水面波纹材质纹理 _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; // 噪声纹理生成的法线纹理 _WaveMap (&quot;Wave Map&quot;, 2D) = &quot;bump&quot; &#123;&#125; // 环境纹理 _Cubemap (&quot;Environment Cubemap&quot;, Cube) = &quot;_Skybox&quot; &#123;&#125; // 控制法线纹理再x和y方向上的平移速度 _WaveXSpeed (&quot;Wave Horizontal Speed&quot;, Range(-0.1, 0.1)) = 0.01 _WaveYSpeed (&quot;Wave Vertical Speed&quot;, Range(-0.1, 0.1)) = 0.01 // 控制模拟折射时的扭曲程度 _Distortion (&quot;Distortion&quot;, Range(0, 100)) = 10 &#125; SubShader &#123; // 透明队列，在所有不透明物体之后渲染 Tags &#123; &quot;Queue&quot;=&quot;Transparent&quot; &quot;RenderType&quot;=&quot;Opaque&quot; &#125; // 获取屏幕图像作为渲染纹理 GrabPass &#123; &quot;_RefractionTex&quot; &#125; Pass &#123; Tags &#123; &quot;LightMode&quot;=&quot;ForwardBase&quot; &#125; CGPROGRAM #include &quot;UnityCG.cginc&quot; #include &quot;Lighting.cginc&quot; #pragma multi_compile_fwdbase #pragma vertex vert #pragma fragment frag fixed4 _Color; sampler2D _MainTex; float4 _MainTex_ST; sampler2D _WaveMap; float4 _WaveMap_ST; samplerCUBE _Cubemap; fixed _WaveXSpeed; fixed _WaveYSpeed; float _Distortion; sampler2D _RefractionTex; float4 _RefractionTex_TexelSize; struct a2v &#123; float4 vertex : POSITION; float3 normal : NORMAL; float4 tangent : TANGENT; float4 texcoord : TEXCOORD0; &#125;; struct v2f &#123; float4 pos : SV_POSITION; float4 scrPos : TEXCOORD0; float4 uv : TEXCOORD1; float4 TtoW0 : TEXCOORD2; float4 TtoW1 : TEXCOORD3; float4 TtoW2 : TEXCOORD4; &#125;; v2f vert(a2v v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); // 根据裁剪空间坐标计算被抓取的屏幕图像的采样坐标 o.scrPos = ComputeGrabScreenPos(o.pos); // 纹理坐标转换 o.uv.xy = TRANSFORM_TEX(v.texcoord, _MainTex); o.uv.zw = TRANSFORM_TEX(v.texcoord, _WaveMap); // 构造切线空间到世界空间的变换矩阵，并存储世界空间下的顶点坐标 float3 worldPos = mul(unity_ObjectToWorld, v.vertex).xyz; fixed3 worldNormal = UnityObjectToWorldNormal(v.normal); fixed3 worldTangent = UnityObjectToWorldDir(v.tangent.xyz); fixed3 worldBinormal = cross(worldNormal, worldTangent) * v.tangent.w; o.TtoW0 = float4(worldTangent.x, worldBinormal.x, worldNormal.x, worldPos.x); o.TtoW1 = float4(worldTangent.y, worldBinormal.y, worldNormal.y, worldPos.y); o.TtoW2 = float4(worldTangent.z, worldBinormal.z, worldNormal.z, worldPos.z); return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; // 得到世界坐标 float3 worldPos = float3(i.TtoW0.w, i.TtoW1.w, i.TtoW2.w); // 根据世界坐标计算世界空间的视角方向 fixed3 viewDir = normalize(UnityWorldSpaceViewDir(worldPos)); // 计算法线纹理当前在x和y方向的偏移量 float2 speed = _Time.y * float2(_WaveXSpeed, _WaveYSpeed); // 对法线纹理采样两次，为了得到两层交叉的水面波动效果 fixed3 bump1 = UnpackNormal(tex2D(_WaveMap, i.uv.zw + speed)).rgb; fixed3 bump2 = UnpackNormal(tex2D(_WaveMap, i.uv.zw - speed)).rgb; // 两次采样结果相加并归一化得到切线空间下的法线方向 fixed3 bump = normalize(bump1 + bump2); // 利用切线空间的法线方向计算对屏幕图像的采样坐标偏移 float2 offset = bump.xy * _Distortion * _RefractionTex_TexelSize.xy; // 偏移量乘以z分量是为了得到深度越大折射程度越大的效果 i.scrPos.xy = offset * i.scrPos.z + i.scrPos.xy; // 经过透视除法后对屏幕图像采样得到模拟的折射颜色 fixed3 refrCol = tex2D( _RefractionTex, i.scrPos.xy/i.scrPos.w).rgb; // 法线转换到世界空间 bump = normalize(half3(dot(i.TtoW0.xyz, bump), dot(i.TtoW1.xyz, bump), dot(i.TtoW2.xyz, bump))); // 采样得到水波颜色，也要随时间偏移 fixed4 texColor = tex2D(_MainTex, i.uv.xy + speed); // 根据世界空间下的法线方向和视线方向计算得到反射方向 fixed3 reflDir = reflect(-viewDir, bump); // 利用反射方向对环境贴图采样，并结合水波颜色得到最终的反射颜色 fixed3 reflCol = texCUBE(_Cubemap, reflDir).rgb * texColor.rgb * _Color.rgb; // 计算菲涅尔系数 fixed fresnel = pow(1 - saturate(dot(viewDir, bump)), 4); // 利用菲涅尔系数结合反射颜色和折射颜色 fixed3 finalColor = reflCol * fresnel + refrCol * (1 - fresnel); return fixed4(finalColor, 1); &#125; ENDCG &#125; &#125; // 不要投射阴影，因此关掉FallBack FallBack Off&#125;
为了用噪声纹理生成法线纹理，我们在该噪声纹理的属性面板中把纹理类型改为 Normal map，并勾选 Create from grayscale，使其从灰度值生成法线纹理：
渲染效果如下：
此时我们的视线方向和水面法线夹角大，反射强，折射弱，我们更容易看到水面的颜色，而水面的颜色是环境反射颜色和水波本身颜色的结合；当我们减小视线方向和水面法线夹角时，效果如下：
此时反射弱，折射强，我们不容易看到水面本身的颜色，更容易透过水面看到折射后的扭曲的地面。 3 再谈全局雾效我们之前学习了如何使用深度纹理来实现一种基于屏幕后处理的全局雾效。我们由深度纹理重建每个像素在世界空间下的位置，再使用一个基于高度的公式来计算雾效的混合系数，最后使用该系数来混合雾的颜色和原屏幕颜色。这样实现的效果在同一高度下雾的浓度是相同的，但很多时候我们希望可以模拟一种不均匀的雾效，同时让雾不断飘动，使雾看起来更加飘渺，这就可以通过使用噪声纹理来实现。 大部分代码和之前的全局雾效一样，只不过加入了噪声相关的参数和属性，并在 Shader 的片元着色器中对雾效混合系数的计算添加了噪声的影响。 首先是 cs 脚本： using UnityEngine;using System.Collections;public class FogWithNoise : PostEffectsBase &#123; public Shader fogShader; private Material fogMaterial = null; public Material material &#123; get &#123; fogMaterial = CheckShaderAndCreateMaterial(fogShader, fogMaterial); return fogMaterial; &#125; &#125; private Camera myCamera; public Camera camera &#123; get &#123; if (myCamera == null) &#123; myCamera = GetComponent&lt;Camera&gt;(); &#125; return myCamera; &#125; &#125; private Transform myCameraTransform; public Transform cameraTransform &#123; get &#123; if (myCameraTransform == null) &#123; myCameraTransform = camera.transform; &#125; return myCameraTransform; &#125; &#125; [Range(0.1f, 3.0f)] public float fogDensity = 1.0f; public Color fogColor = Color.white; public float fogStart = 0.0f; public float fogEnd = 2.0f; // 定义噪声纹理的变量 public Texture noiseTexture; // 噪声纹理在x和y方向的移动速度，模拟飘渺的效果 [Range(-0.5f, 0.5f)] public float fogXSpeed = 0.1f; [Range(-0.5f, 0.5f)] public float fogYSpeed = 0.1f; // 控制噪声程度，值为0代表不应用噪声，得到和之前一样的均匀雾效 [Range(0.0f, 3.0f)] public float noiseAmount = 1.0f; // 脚本可用时，摄像机生成深度纹理 void OnEnable() &#123; GetComponent&lt;Camera&gt;().depthTextureMode |= DepthTextureMode.Depth; &#125; void OnRenderImage (RenderTexture src, RenderTexture dest) &#123; if (material != null) &#123; Matrix4x4 frustumCorners = Matrix4x4.identity; float fov = camera.fieldOfView; float near = camera.nearClipPlane; float aspect = camera.aspect; float halfHeight = near * Mathf.Tan(fov * 0.5f * Mathf.Deg2Rad); Vector3 toRight = cameraTransform.right * halfHeight * aspect; Vector3 toTop = cameraTransform.up * halfHeight; Vector3 topLeft = cameraTransform.forward * near + toTop - toRight; float scale = topLeft.magnitude / near; topLeft.Normalize(); topLeft *= scale; Vector3 topRight = cameraTransform.forward * near + toRight + toTop; topRight.Normalize(); topRight *= scale; Vector3 bottomLeft = cameraTransform.forward * near - toTop - toRight; bottomLeft.Normalize(); bottomLeft *= scale; Vector3 bottomRight = cameraTransform.forward * near + toRight - toTop; bottomRight.Normalize(); bottomRight *= scale; frustumCorners.SetRow(0, bottomLeft); frustumCorners.SetRow(1, bottomRight); frustumCorners.SetRow(2, topRight); frustumCorners.SetRow(3, topLeft); material.SetMatrix(&quot;_FrustumCornersRay&quot;, frustumCorners); material.SetFloat(&quot;_FogDensity&quot;, fogDensity); material.SetColor(&quot;_FogColor&quot;, fogColor); material.SetFloat(&quot;_FogStart&quot;, fogStart); material.SetFloat(&quot;_FogEnd&quot;, fogEnd); material.SetTexture(&quot;_NoiseTex&quot;, noiseTexture); material.SetFloat(&quot;_FogXSpeed&quot;, fogXSpeed); material.SetFloat(&quot;_FogYSpeed&quot;, fogYSpeed); material.SetFloat(&quot;_NoiseAmount&quot;, noiseAmount); Graphics.Blit (src, dest, material); &#125; else &#123; Graphics.Blit(src, dest); &#125; &#125;&#125;
然后是 Shader： Shader &quot;Unity Shaders Book/Chapter 15/Fog With Noise&quot; &#123; Properties &#123; _MainTex (&quot;Base (RGB)&quot;, 2D) = &quot;white&quot; &#123;&#125; _FogDensity (&quot;Fog Density&quot;, Float) = 1.0 _FogColor (&quot;Fog Color&quot;, Color) = (1, 1, 1, 1) _FogStart (&quot;Fog Start&quot;, Float) = 0.0 _FogEnd (&quot;Fog End&quot;, Float) = 1.0 _NoiseTex (&quot;Noise Texture&quot;, 2D) = &quot;white&quot; &#123;&#125; _FogXSpeed (&quot;Fog Horizontal Speed&quot;, Float) = 0.1 _FogYSpeed (&quot;Fog Vertical Speed&quot;, Float) = 0.1 _NoiseAmount (&quot;Noise Amount&quot;, Float) = 1 &#125; SubShader &#123; CGINCLUDE #include &quot;UnityCG.cginc&quot; float4x4 _FrustumCornersRay; sampler2D _MainTex; half4 _MainTex_TexelSize; sampler2D _CameraDepthTexture; half _FogDensity; fixed4 _FogColor; float _FogStart; float _FogEnd; sampler2D _NoiseTex; half _FogXSpeed; half _FogYSpeed; half _NoiseAmount; struct v2f &#123; float4 pos : SV_POSITION; float2 uv : TEXCOORD0; float2 uv_depth : TEXCOORD1; float4 interpolatedRay : TEXCOORD2; &#125;; v2f vert(appdata_img v) &#123; v2f o; o.pos = UnityObjectToClipPos(v.vertex); o.uv = v.texcoord; o.uv_depth = v.texcoord; #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) o.uv_depth.y = 1 - o.uv_depth.y; #endif int index = 0; if (v.texcoord.x &lt; 0.5 &amp;&amp; v.texcoord.y &lt; 0.5) &#123; index = 0; &#125; else if (v.texcoord.x &gt; 0.5 &amp;&amp; v.texcoord.y &lt; 0.5) &#123; index = 1; &#125; else if (v.texcoord.x &gt; 0.5 &amp;&amp; v.texcoord.y &gt; 0.5) &#123; index = 2; &#125; else &#123; index = 3; &#125; #if UNITY_UV_STARTS_AT_TOP if (_MainTex_TexelSize.y &lt; 0) index = 3 - index; #endif o.interpolatedRay = _FrustumCornersRay[index]; return o; &#125; fixed4 frag(v2f i) : SV_Target &#123; // 还原像素对应的点在世界空间的位置 float linearDepth = LinearEyeDepth(SAMPLE_DEPTH_TEXTURE(_CameraDepthTexture, i.uv_depth)); float3 worldPos = _WorldSpaceCameraPos + linearDepth * i.interpolatedRay.xyz; // 计算采样坐标偏移 float2 speed = _Time.y * float2(_FogXSpeed, _FogYSpeed); // 利用偏移量对噪声纹理采样，结果减去0.5并乘以控制噪声程度的属性得到最终的噪声值 float noise = (tex2D(_NoiseTex, i.uv + speed).r - 0.5) * _NoiseAmount; // 利用噪声计算雾效混合系数 float fogDensity = (_FogEnd - worldPos.y) / (_FogEnd - _FogStart); fogDensity = saturate(fogDensity * _FogDensity * (1 + noise)); // 利用雾效混合系数混合雾效颜色和原颜色 fixed4 finalColor = tex2D(_MainTex, i.uv); finalColor.rgb = lerp(finalColor.rgb, _FogColor.rgb, fogDensity); return finalColor; &#125; ENDCG Pass &#123; CGPROGRAM #pragma vertex vert #pragma fragment frag ENDCG &#125; &#125; FallBack Off&#125;
渲染效果如下：
4 噪声纹理从何而来噪声纹理一般属于程序纹理，它们都是由计算机利用某些算法生成的。Perlin 噪声和Worley 噪声是两种最常使用的噪声类型，上面的全局雾效使用的噪声纹理就是由 Perlin 噪声生成而来。 Perlin 噪声可以用于生成更自然的噪声纹理，而 Worley 噪声则通常用于模拟诸如石头、水、纸张等多孔噪声。更多关于噪声纹理的内容可以查看 Understanding Perlin Noise 以及其他博客。

这部分我们将使用 C++ 从零开始实现一个光线追踪器。首先需要实现一些在简单的光线追踪器中要用到的基本工具类，包含三维向量类、光线类，以及一些之后可能频繁用到的工具函数。

1 三维向量类尽管在正规的光线追踪器中使用更多的是四维向量，比如齐次坐标和带有 A 通道的颜色，但是对于我们这个简化的光线追踪器来说，三维向量已经足够了，我们可以使用三维向量表示位置、方向、颜色等，为了区分这三种表示，我们给三维向量类 vec3起两个别名 point3 和 color 以方便之后代码的编写和阅读，但他们实质上没有任何区别，我们没有为了不同的表示构造一个专门的类，这意味着一个颜色和一个位置可以进行相加，这在正常的光线追踪工程实现中是不被允许的，但我们毕竟是简化版本，只要在使用的时候注意即可。
我们首先在该类中实现一些基本的方法：
/*  实现三维向量类，用于存储位置、向量、颜色等*/#pragma once#ifndef VEC3_H#define VEC3_H#include &lt;cmath&gt;#include &lt;iostream&gt;using std::sqrt;// 定义类及常用方法class vec3&#123;public:    double e[3];public:    vec3() : e&#123; 0,0,0 &#125; &#123;&#125;    vec3(double e0, double e1, double e2) : e&#123; e0, e1, e2 &#125; &#123;&#125;    double x() const &#123; return e[0]; &#125;    double y() const &#123; return e[1]; &#125;    double z() const &#123; return e[2]; &#125;    vec3 operator-() const &#123; return vec3(-e[0], -e[1], -e[2]); &#125;    double operator[](int i) const &#123; return e[i]; &#125;    double&amp; operator[](int i) &#123; return e[i]; &#125;    vec3&amp; operator+=(const vec3&amp; v) &#123;        e[0] += v[0];        e[1] += v[1];        e[2] += v[2];        return *this;    &#125;    vec3&amp; operator*=(const double t) &#123;        e[0] *= t;        e[1] *= t;        e[2] *= t;        return *this;    &#125;    vec3&amp; operator/=(const double t) &#123;        return *this *= 1/t;    &#125;    double length_squared() const &#123;        return e[0] * e[0] + e[1] * e[1] + e[2] * e[2];    &#125;    double length() const &#123;        return sqrt(length_squared());    &#125;&#125;;// 定义vec3的别名，分别用于存储点和颜色，提升代码可读性using point3 = vec3;using color = vec3;#endif

在工程实践中，文件开头的 #pragma once 是必须的，否则可能因为头文件重复包含导致编译错误，定义类时的判断：
#ifndef VEC3_H#define VEC3_H...#endif

也是必须的，同样是为了防止重复编译。
然后实现一些对向量操作的工具函数，大部分是运算符重载，以让我们可以按照之前的习惯操作三维向量：
/*******一些工具函数*******/inline std::ostream&amp; operator&lt;&lt;(std::ostream&amp; out, const vec3&amp; v) &#123;    return out &lt;&lt; v.e[0] &lt;&lt; &#x27; &#x27; &lt;&lt; v.e[1] &lt;&lt; &#x27; &#x27; &lt;&lt; v.e[2];&#125;inline vec3 operator+(const vec3&amp; u, const vec3&amp; v) &#123;    return vec3(u.e[0] + v.e[0], u.e[1] + v.e[1], u.e[2] + v.e[2]);&#125;inline vec3 operator-(const vec3&amp; u, const vec3&amp; v) &#123;    return vec3(u.e[0] - v.e[0], u.e[1] - v.e[1], u.e[2] - v.e[2]);&#125;// 对应元素相乘inline vec3 operator*(const vec3&amp; u, const vec3&amp; v) &#123;    return vec3(u.e[0] * v.e[0], u.e[1] * v.e[1], u.e[2] * v.e[2]);&#125;// 向量和标量运算inline vec3 operator*(double t, const vec3&amp; v) &#123;    return vec3(t * v.e[0], t * v.e[1], t * v.e[2]);&#125;inline vec3 operator*(const vec3&amp; v, double t) &#123;    return t * v;&#125;inline vec3 operator/(const vec3&amp; v, double t) &#123;    return (1 / t) * v;&#125;// 点乘inline double dot(const vec3&amp; u, const vec3&amp; v) &#123;    return u.e[0] * v.e[0] + u.e[1] * v.e[1] + u.e[2] * v.e[2];&#125;// 叉乘inline vec3 cross(const vec3&amp; u, const vec3&amp; v) &#123;    return vec3(u.e[1] * v.e[2] - u.e[2] * v.e[1],        u.e[2] * v.e[0] - u.e[0] * v.e[2],        u.e[0] * v.e[1] - u.e[1] * v.e[0]);&#125;// 单位化inline vec3 normalize(vec3 v) &#123;    return v / v.length();&#125;// 向数组中写入一个颜色，用于最后的图像输出，用到了指针的引用传递// 注意输入的color是[0,1]范围的void write_color(unsigned char*&amp; p, color pixel_color)&#123;    *p++ = (unsigned char)(255.999 * pixel_color.x());    *p++ = (unsigned char)(255.999 * pixel_color.y());    *p++ = (unsigned char)(255.999 * pixel_color.z());&#125;

2 光线类光线类是基于三维向量类的，我们按照图形学中射线的定义来实现一个光线类，给定空间中一个位置和一个方向就可以确定一条射线，再给定时间 t，就可以得到射线上任意一点：
/*    实现光线类*/#pragma once#ifndef RAY_H#define RAY_H#include &quot;vec3.h&quot;class ray&#123;public:    ray() &#123;&#125;    ray(const point3&amp; origin, const vec3&amp; direction) :        orig(origin), dir(direction) &#123;&#125;    point3 origin() &#123; return orig; &#125;    vec3 direction() &#123; return dir; &#125;    point3 at(double t) const &#123;        return orig + t * dir;    &#125;public:    point3 orig;    vec3 dir;&#125;;#endif

3 图像输出我们所有渲染结果最终都要输出到一张图片中，我们可以选择任何输出格式，这里使用了非常方便的开源的图像工具 stb_image ，将结果保存到数组中然后使用 stbi_write_png 函数保存为 PNG 格式图片。我们用一个生成渐变图片的例子来了解图像输出流程。
首先定义一个 ray_color 函数，根据给定的方向机型简单的线性插值，以混合两种不同的颜色：
// 根据归一化的方向的y坐标线性混合白色和蓝色，以得到自上而下的蓝白色渐变效果color ray_color(ray&amp; r)&#123;    vec3 unit_dir = normalize(r.direction());    // 归一化后y的范围是[-1,1]，将其映射到[0,1]作为混合系数    auto t = 0.5 * (unit_dir.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

我们定义相机所在位置为 (0, 0, 0)，屏幕（输出的图片）比例为 16 : 9，因此我们的视口比例也要和最终的图片比例一致，然后从屏幕左上角开始遍历，从相机向屏幕投射光线，根据该光线方向通过 ray_color 函数计算插值颜色显示到屏幕上。场景大致如下：

下面实现主函数：
#include &lt;iostream&gt;#include &lt;string&gt;#define STB_IMAGE_WRITE_IMPLEMENTATION#include &quot;stb_image_write.h&quot;#include &quot;vec3.h&quot;#include &quot;ray.h&quot;int main()&#123;    /*******图片属性*******/     // 宽高比    const auto aspect_ratio = 16.0 / 9.0;    const int image_width = 400;    // 使用static_cast可以明确告诉编译器，这种损失精度的转换是在知情的情况下进行的    // 也可以让阅读程序的其他程序员明确你转换的目的而不是由于疏忽    const int image_height = static_cast&lt;int&gt;(image_width / aspect_ratio);    const int channel = 3;    /*******相机属性*******/    // 视口高度设为两个单位    auto viewport_height = 2.0;    // 视口宽度根据屏幕宽高比计算    auto viewport_width = aspect_ratio * viewport_height;    // 原点到视口平面距离为1个单位    auto focal_length = 1.0;    // 相机原点    auto origin = point3(0, 0, 0);    // 视口宽的一半    auto horizontal = vec3(viewport_width, 0, 0);    // 视口高的一半    auto vertical = vec3(0, viewport_height, 0);    // 相当于将(0,0,0)移动到视口平面的左下角，也就是得到左下角的点的位置    auto lower_left_corner = origin - horizontal / 2 - vertical / 2 - vec3(0, 0, focal_length);        /****图片保存，保存为png格式****/    std::string SavePath = &quot;D:\\TechStack\\ComputerGraphics\\Ray Tracing in One Weekend Series\\Results\\&quot;;    std::string filename = &quot;BlendColor.png&quot;;    std::string filepath = SavePath + filename;     // 3通道图像存在一维数组    unsigned char* odata = (unsigned char*)malloc(image_width * image_height * channel);    unsigned char* p = odata;    /******渲染部分*****/    for (int j = image_height - 1; j &gt;= 0; --j) &#123;        // 标准错误流显示进度信息，可以刷新显示        std::cerr &lt;&lt; &quot;\rScanlines remaining: &quot; &lt;&lt; j &lt;&lt; &#x27; &#x27; &lt;&lt; std::flush;        for (int i = 0; i &lt; image_width; ++i) &#123;            // x方向偏移            auto u = double(i) / (image_width - 1);            // y方向偏移            auto v = double(j) / (image_height - 1);            ray r(origin, lower_left_corner + u * horizontal + v * vertical - origin);            color pixel_color = ray_color(r);            write_color(p, pixel_color);        &#125;    &#125;    stbi_write_png(filepath.c_str(), image_width, image_height, channel, odata, 0);    std::cerr &lt;&lt; &quot;\nDone.\n&quot;;&#125;

得到的结果如下：

现在我们已经有了光线和物体，接下来可以实现一些看起来更加真实的效果，从漫反射材质开始。

1 简单的漫反射材质回顾漫反射的形成原理，光线打到物体表面后一部分光会折射进入物体，并在物体内部发生各种次表面散射后从物体表面的某个方向再折射出去，因此漫反射的颜色主要取决于环境光颜色，并用物体自身的颜色去调节这些来自环境的光线，因此也可以认为漫反射反映了物体自身的颜色。从宏观来看漫反射就像是光线向各个方向均匀散射，而在我们的简单实现中可以认为光线在物体表面的反射方向是随机的，比如三根光线打到两个物体的夹缝处，他们可能产生完全不同的行为：

因此要模拟漫反射材质，我们首先要能够随机生成漫反射弹射光线。可以使用如下方法生成：

光线与物体表面相交于一点 $p$
在 $p + \vec n$ 处构造一个与点 $p$ 相切的单位球体，其中 $\vec n$ 是点 $p$ 处的法线
随机在单位球体中选择一点 $s$ ，漫反射弹射光线的方向就是 $s - p &#x3D; \vec{ps}$


为此我们要先增加一些工具函数用于在单位球体内生成随机点，由于直接生成单位球体内的点并不是很方便实现，我们可以先生成单位立方体内的点，即三个维度的坐标都在 [-1, 1] 范围内，然后判断该点是否在球体内，如果不在球体内就重新随机选择，直到满足条件。
//utilities.h...// 生成分量在[0,1]之间的随机向量inline vec3 random_vec() &#123;    return vec3(random_double(), random_double(), random_double());&#125;// 生成分量在[min,max]之间的随机向量inline vec3 random_vec(double min, double max) &#123;    return vec3(random_double(min, max), random_double(min, max), random_double(min, max));&#125;// 生成单位球体内随机一点inline point3 random_in_unit_sphere() &#123;    while (true) &#123;        auto p = random_vec(-1, 1);        if (p.length_squared() &gt;= 1) continue;        return p;    &#125;&#125;

然后修改 ray_color 函数：
// 得到光线颜色color ray_color(ray&amp; r, const hittable&amp; world) &#123;    hit_record rec;    // 计算漫反射颜色    if (world.hit(r, 0, infinity, rec)) &#123;        // 随机选择漫反射光线弹射方向        point3 target = rec.p + rec.normal + random_in_unit_sphere();        ray bounce = ray(rec.p, target - rec.p);        // 只有0.5的光线发生下一次弹射，其他的被吸收        return 0.5 * ray_color(bounce, world);    &#125;    vec3 unit_direction = normalize(r.direction());    auto t = 0.5 * (unit_direction.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

这样就可以递归的计算光线弹射多次所得到的漫反射颜色了。
2 限制光线弹射次数上面的实现中，没有递归结束的条件，也就是限制光线弹射的次数，因此需要加一个递归深度来限制光线的弹射次数：
// 得到光线颜色color ray_color(ray&amp; r, const hittable&amp; world, int depth) &#123;    hit_record rec;    // 限制弹射次数    if (depth &lt;= 0) return color(0, 0, 0);    // 计算漫反射颜色    if (world.hit(r, 0, infinity, rec)) &#123;        // 随机选择漫反射光线弹射方向        point3 target = rec.p + rec.normal + random_in_unit_sphere();        ray bounce = ray(rec.p, target - rec.p);        // 只有0.5的光线发生下一次弹射，其他的被吸收        return 0.5 * ray_color(bounce, world, depth - 1);    &#125;    vec3 unit_direction = normalize(r.direction());    auto t = 0.5 * (unit_direction.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

然后修改主函数：
#include &lt;iostream&gt;#include &lt;string&gt;#define STB_IMAGE_WRITE_IMPLEMENTATION#include &quot;stb_image_write.h&quot;#include &quot;hittable_list.h&quot;#include &quot;sphere.h&quot;#include &quot;color.h&quot;#include &quot;camera.h&quot;int main()&#123;    /****图片保存，保存为png格式****/    std::string SavePath = &quot;D:\\TechStack\\ComputerGraphics\\Ray Tracing in One Weekend Series\\Results\\&quot;;    std::string filename = &quot;Diffuse.png&quot;;    std::string filepath = SavePath + filename;        /*******图片属性*******/     const auto aspect_ratio = 16.0 / 9.0;    const int image_width = 400;    const int image_height = static_cast&lt;int&gt;(image_width / aspect_ratio);    const int channel = 3;    const int samples_per_pixel = 100;    // 光线弹射次数    const int max_depth = 50;    /*******创建相机*******/    camera cam;    /*******创建场景*******/    hittable_list world;    world.add(make_shared&lt;sphere&gt;(point3(0, 0, -1), 0.5));    world.add(make_shared&lt;sphere&gt;(point3(0, -100.5, -1), 100));    /******渲染部分*****/    unsigned char* odata = (unsigned char*)malloc(image_width * image_height * channel);    unsigned char* p = odata;    for (int j = image_height - 1; j &gt;= 0; --j) &#123;        std::cerr &lt;&lt; &quot;\rScanlines remaining: &quot; &lt;&lt; j &lt;&lt; &#x27; &#x27; &lt;&lt; std::flush;        for (int i = 0; i &lt; image_width; ++i) &#123;            color pixel_color(0, 0, 0);            for (int s = 0; s &lt; samples_per_pixel; ++s) &#123;                // 在像素内部随机采样                auto u = (i + random_double()) / (image_width - 1);                auto v = (j + random_double()) / (image_height - 1);                ray r = cam.get_ray(u, v);                pixel_color += ray_color(r, world, max_depth);            &#125;            write_color(p, pixel_color, samples_per_pixel);        &#125;    &#125;    stbi_write_png(filepath.c_str(), image_width, image_height, channel, odata, 0);    std::cerr &lt;&lt; &quot;\nDone.\n&quot;;&#125;

得到如下效果：

使用固定弹射次数会导致很多没用的计算，仅仅渲染上面这样一张图就要用掉近三分钟，效率非常低，并且固定弹射次数会影响最终渲染效果。之前在图形学中我们学习过，更好的限制光线弹射次数的方法是使用俄罗斯轮盘赌算法（RR），该算法在保证期望正确的情况下大幅提高了渲染效率，因此我们用 RR 算法来限制光线弹射次数：
// 得到光线颜色color ray_color(ray&amp; r, const hittable&amp; world) &#123;    hit_record rec;    // 俄罗斯轮盘赌的生存概率    auto RR = 0.8;    // 计算漫反射颜色    // 这里的t的下界设为0.001是为了防止一些光线弹射到物体上得到的t非常接近0，比如可能出现0.000001这样的值    if (world.hit(r, 0.001, infinity, rec)) &#123;        // 以一定概率停止弹射        if (random_double() &gt;= RR) return color(0, 0, 0);        // 随机选择漫反射光线弹射方向        point3 target = rec.p + rec.normal + random_in_unit_sphere();        ray bounce = ray(rec.p, target - rec.p);        // 要记得除以生存概率才能得到正确的期望        return 0.5 * ray_color(bounce, world) / RR;    &#125;    vec3 unit_direction = normalize(r.direction());    auto t = 0.5 * (unit_direction.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

主函数中之前做的修改可以 Ctrl + Z 了，现在无需做任何修改，得到的效果如下：

渲染这张图只用了不到 20 秒，效率大幅提升并且渲染效果更好。
3 伽马校正在上面的例子中我们设置了一半的光线被吸收，一半的光线被反射，在现实中这个球体看起来应该更亮一些，呈现灰色，但上面的渲染结果中球体颜色非常暗，尤其是球体下的阴影处，这是因为我们没有进行伽马校正（Gamma Correction）。
伽马校正中的伽马一词来源伽马曲线。通常，伽马曲线的表达式如下：$$L_{out} &#x3D; L_{in}^\gamma$$其中指数部分的发音就是伽马。最开始的时候，人们使用伽马曲线来对拍摄的图像进行伽马编码。事情的起因可以从在真实环境中拍摄一张图片说起。摄像机的原理可以简化为，把进入到镜头内的光线亮度编码成图像中的像素。如果采集到的亮度是 0，像素就是 0，亮度是 1，像素就是 1，亮度是 0.5，像素就是 0.5。如果我们只用 8 位空间来存储像素的每个通道的话，这意味着 0~1 区间可以对应 256 种不同的亮度值。但是，后来人们发现，人眼有一个有趣的特性，就是对光的灵敏度在不同亮度上是不一样的。在正常的光照条件下，人眼对较暗区域的变化更加敏感，如下图：

颜色越暗，我们就感觉从左到右的变化越明显。所以亮度上的线性变化对人眼的感知来说是非均匀的。
另一个例子可以说明这个现象，当一个屋子的光照由一盏灯增加到两盏灯的时候，人眼对这种亮度变化的感知性要远远大于从 101 盏灯增加到 102 盏灯的变化，但是从物理上来说这两种变化基本是相同的。
所以，如果使用 8 位空间来存储每个通道的话，我们仍然把 0.5 亮度编码成值为 0.5 的像素，那么暗部和亮部区域我们都使用了 128 种颜色来表示，但实际上，对亮部区域使用这么多颜色是种存储浪费。一种更好的方法是，我们应该把把更多的空间来存储更多的暗部区域，这样存储空间就可以被充分利用起来了。摄影设备如果使用了 8 位空间来存储照片的话，会使用大约为 0.45 的编码伽马来对输入的亮度进行编码，得到一张编码后的图像。因此，图像中 0.5 像素值对应的亮度其实并不是 0.5，而大约为 0.22。这是因为：$$0.5 \approx 0.22^{0.45}$$如上所见，对拍摄图像使用的伽马编码使得我们可以充分利用图像的存储空间。但当把图片放到显示器里显示时，我们应该对图像再进行一次解码操作，使得屏幕输出的亮度和捕捉到的亮度是符合线性的。
这时，人们发现了一个奇妙的巧合—— CRT 显示器本身几乎已经自动做了这个解码操作。在早期，CRT（Cathode Ray Tube，阴极射线管）几乎是唯一的显示设备。这类设备的显示机制是，使用一个电压轰击它屏幕上的一种图层，这个图层就可以发亮，我们就可以看到图像了。但 CRT 显示器有一个特性，它的输入电压和显示出来的亮度关系不是线性的，也就是说，如果我们把输入电压调高两倍，屏幕亮度并没有提高两倍。我们把显示器的这个伽马曲线称为**显示伽马 (diplay gamma)**。非常巧合的是，CRT 的显示伽马值大约就是编码伽马的倒数。CRT 显示器的这种特性，正好补偿了图像捕捉设备的伽马曲线。虽然现在 CRT 设备很少见了，并且后来出现的显示设备有着不同的伽马响应曲线，但是，人们仍在硬件上做了调整来提供兼容性。
随后，微软联合爱普生、惠普提供了 sRGB 颜色空间标准，推荐显示器的显示伽马值为 2.2，并配合 0.45 的编码伽马就可以保证最后伽马曲线之间可以相互抵消（因为 $2.2 \times 0.45 \approx 1$ ）。绝大多数的摄像机、 PC 和打印机都使用了上述的 sRGB 标准。
对于我们的渲染来说，如果我们直接输出渲染结果而不做任何处理，在经过显示器的显示伽马处理后，就会导致颜色偏暗的现象。因此我们在计算像素颜色时有必要进行伽马校正。
为了简化计算我们假设显示伽马为 2.0，因此我们的编码伽马为 0.5，在写入像素的时候对像素的最终颜色值进行伽马编码，就可以让颜色显示正常了：
// 输入的color是[0,1]范围的inline void write_color(unsigned char*&amp; p, color pixel_color, int samples_per_pixel)&#123;    auto r = pixel_color.x();    auto g = pixel_color.y();    auto b = pixel_color.z();    auto scale = 1.0 / samples_per_pixel;    // 伽马校正，假设显示gamma=2.0    r = sqrt(scale * r);    g = sqrt(scale * g);    b = sqrt(scale * b);    *p++ = (unsigned char)(256 * clamp(r, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(g, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(b, 0.0, 0.999));&#125;

经过伽马矫正后的渲染结果如下：

4 True Lambertian Reflection现在回顾上面在单位球体内选取随机点的实现。这样的实现会使得选取到的随机反射方向大概率接近法线，而以很小的概率接近掠射角方向，这是因为整个球体中大部分位置和表面交点的连线都接近法线方向，只有很小一部分接近掠射角方向，这代表我们随机选取的反射方向不是均匀分布的，但这似乎是合理的，因为越接近掠射角代表光线越接近该交点的切线方向，所以对最终颜色的贡献也更小。
而 True Lambertian Reflection 并不是这样的， True Lambertian Reflection 的随机方向更均匀，因为它是在单位球面上随机取点并构成反射方向，这样显然随机选取的反射方向会更加均匀。
我们可以通过先在球面内随机取点，并将其单位化，以得到球面上随机一点：
// 生成单位球面上随机一点inline vec3 random_unit_vector() &#123;    return normalize(random_in_unit_sphere());&#125;

然后修改 ray_color 部分：
color ray_color(ray&amp; r, const hittable&amp; world) &#123;    hit_record rec;    auto RR = 0.8;    if (world.hit(r, 0.001, infinity, rec)) &#123;        if (random_double() &gt;= RR) return color(0, 0, 0);        // 这次使用球面上的随机点        //point3 target = rec.p + rec.normal + random_in_unit_sphere();        point3 target = rec.p + rec.normal + random_unit_vector();        ray bounce = ray(rec.p, target - rec.p);        return 0.5 * ray_color(bounce, world) / RR;    &#125;    vec3 unit_direction = normalize(r.direction());    auto t = 0.5 * (unit_direction.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

得到的效果如下：

可以注意到和之前的结果中两个不同的视觉变化：

阴影变得不那么明显了
物体变得稍微亮了一点

这两种变化都是由于光线散射更均匀，向法线附近散射的光线更少而产生的。对于漫反射物体，它们会显得更亮是因为更多的光线会反射到相机上。对于阴影，因为向法线附近散射的光线更少，所以大球体表面和上面的小球体的夹缝处就会有更多的光线散射出去，而不是在夹缝处一直弹射。
5 另一种散射方法除了上面的在球体内随机取点和在球面上随机取点之外，还有一种随机散射的方法。在之前的方法中我们选取了一个单位球，这个单位球的球心相比于光线和表面的交点偏移了一个法线，但很难解释我们为什么这么做。一个更直观的方法是不进行法线偏移，在单位球体内随机取一点作为光线和物体的交点 p 的偏移，然后用偏移后的点 p 和原来的点 p 构成随机反射方向。这相当于以 p 为球心，在一个半球上随机取点构成反射方向，在实现中要注意如果偏移后的点 p 落入了下半球，意味着反射光线指向了物体内部，这是错误的，此时要对偏移量取反，以保证反射光线和该点的法线在同一个半球。
// 在半球内随机取点inline vec3 random_in_hemisphere(const vec3&amp; normal) &#123;    vec3 in_unit_sphere = random_in_unit_sphere();    // 判断该偏移量是否落入了下半球，如果落入下半球则偏移量应该取反    if (dot(in_unit_sphere, normal) &gt; 0.0)        return in_unit_sphere;    else        return -in_unit_sphere;&#125;

然后修改 ray_color 部分：
// 得到光线颜色color ray_color(ray&amp; r, const hittable&amp; world) &#123;    hit_record rec;    auto RR = 0.8;    if (world.hit(r, 0.001, infinity, rec)) &#123;        if (random_double() &gt;= RR) return color(0, 0, 0);        // 在法线偏移的单位球体内部随机取一点得到反射方向        //point3 target = rec.p + rec.normal + random_in_unit_sphere();        // 在法线偏移的单位球体表面随机取一点得到反射方向        //point3 target = rec.p + rec.normal + random_unit_vector();        // 在以交点为球心的半径为 1 的半球内随机取一点得到反射方向        point3 target = rec.p + random_in_hemisphere(rec.normal);        ray bounce = ray(rec.p, target - rec.p);        return 0.5 * ray_color(bounce, world) / RR;    &#125;    vec3 unit_direction = normalize(r.direction());    auto t = 0.5 * (unit_direction.y() + 1.0);    return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

得到的效果如下：

以上三种散射方法没有对错之分，在后面场景变得越来越复杂之后，可以通过尝试切换这三种漫反射渲染器来观察不同的方法对渲染效果的影响。

有了基本工具类，现在我们可以回顾图形学中的知识，从最简单的渲染一个球体开始，逐渐熟悉光线追踪的实现。
1 渲染一个球体在光线追踪中如果投射出的光线碰到了物体，就计算该点的颜色作为像素值，那么我们从最简单的情形开始，渲染一个球体，我们在 z &#x3D; -1 处放置一个球体，然后计算投射出的每一条光线和该球体是否有交点，如果有的话我们将该像素设置为一个定值，这样就可以在屏幕上显示出这个球体了。
计算光线和空间中球体是否有交点我们在图形学中已经学过，非常简单，对于射线 $P(t)$ 和一个空间中球心在 $C$ ，半径为 $r$  的球体，如果射线上的点在球面上，则满足：$$(P(t)−C)⋅(P(t)−C)&#x3D;r^2$$将 $P(t) &#x3D; A + t \vec b$ 代入得：$$(A+t\vec b−C)⋅(A+t\vec b−C)&#x3D;r^2$$再展开即可得到关于 $t$ 的一元二次方程：$$t^2 \vec b⋅\vec b+2t\vec b⋅(A−C)+(A−C)⋅(A−C)−r^2&#x3D;0$$只需要判断这个一元二次方程有没有实数根即可。于是我们可以写出判断光线是否和球体相交的函数：
// 判断光线是否与球体相交bool hit_sphere(const point3&amp; center, double radius, ray&amp; r) &#123;	vec3 oc = r.origin() - center;	auto a = dot(r.direction(), r.direction());	auto b = 2.0 * dot(oc, r.direction());	auto c = dot(oc, oc) - radius * radius;	auto discriminant = b * b - 4 * a * c;	return (discriminant &gt; 0);&#125;

然后在之前的 ray_color 函数中加上判断光线是否和球体相交的代码：
// 得到光线颜色color ray_color(ray&amp; r)&#123;	//放置在 z = -1 处的一个半径为0.5的球体	if (hit_sphere(point3(0, 0, -1), 0.5, r)) return color(1, 0, 0);	vec3 unit_dir = normalize(r.direction());	// 归一化后y的范围是[-1,1]，将其映射到[0,1]作为混合系数	auto t = 0.5 * (unit_dir.y() + 1.0);	return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

效果如下：

需要注意的是，现在我们只考虑了是否有实数根，并没有考虑 t 的正负，这会导致即使把球体放到 z &#x3D; 1 处，也能得到和上图相同的结果，这相当于我们看到了在相机后面的物体，这个问题之后我们会解决。
2 表面法线2.1 可视化物体表面法线我们计算光线与物体交点的光照时首先需要知道该交点的法线，对于一个球体来说，表面上任意一点的法线方向就是该点和球心连线的方向并从球心向外指。因此我们只要计算出投射的光线和球体的交点就可以得到该点的法向量，由于法向量是单位向量，每个分量范围都在 [-1, 1] ，因此我们可以将每个分量都映射到 [0, 1]，作为颜色值显示出来。
为此我们先修改刚才的 hit_sphere 使其返回交点的 t 值，由于我们的球体放在 z &#x3D; -1 处，所以两个交点都一定是正实数，我们返回较小的那个一根即可，即：$$t_{return} &#x3D; \frac{-b - \sqrt{b^2-4ac} }{2a}$$因为只能看到离我们最近的点，修改后的代码如下：
// 判断光线是否与球体相交double hit_sphere(const point3&amp; center, double radius, ray&amp; r) &#123;	vec3 oc = r.origin() - center;	auto a = dot(r.direction(), r.direction());	auto b = 2.0 * dot(oc, r.direction());	auto c = dot(oc, oc) - radius * radius;	auto discriminant = b * b - 4 * a * c;	if (discriminant &lt; 0) &#123;		return -1.0;	&#125;	else &#123;		return (-b - sqrt(discriminant)) / (2.0 * a);	&#125;&#125;

同时修改 ray_color 函数：
// 得到光线颜色color ray_color(ray&amp; r)&#123;	//放置在 z = -1 处的一个半径为0.5的球体，计算交点法线作为颜色返回	auto t = hit_sphere(point3(0, 0, -1), 0.5, r);	if (t &gt; 0)	&#123;		vec3 normal = normalize(r.at(t) - vec3(0, 0, -1));		return (normal + vec3(1, 1, 1)) * 0.5;	&#125;	vec3 unit_dir = normalize(r.direction());	// 归一化后y的范围是[-1,1]，将其映射到[0,1]作为混合系数	t = 0.5 * (unit_dir.y() + 1.0);	return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

渲染效果如下：

2.2 代码优化上面的 hit_sphere 函数有一些可以优化的地方，首先两个相同向量的点乘，可以通过我们在 vec3 类中定义的 length_squared() 方法得到，另外考虑方程的求根公式：$$\frac{-b \pm \sqrt{b^2-4ac} }{2a}$$如果把 b 替换成 2h，可以得到：$$\frac{-2h \pm \sqrt{(2h)^2-4ac} }{2a}$$展开整理得：$$\frac{-h \pm \sqrt{h^2-ac} }{a}$$于是我们只需要计算 b 的一半即可：
// 判断光线是否与球体相交double hit_sphere(const point3&amp; center, double radius, ray&amp; r) &#123;	vec3 oc = r.origin() - center;	auto a = r.direction().length_squared();	auto h = dot(oc, r.direction());	auto c = dot(oc, oc) - radius * radius;	auto discriminant = h * h - a * c;	if (discriminant &lt; 0) &#123;		return -1.0;	&#125;	else &#123;		return (-h - sqrt(discriminant)) / a;	&#125;&#125;

3 多个物体3.1 实现物体类在实际场景中我们不可能只有一个物体，并且物体也不可能只是球体，还可能有有各种各样的模型，因此为了能让所有模型都可以放置到场景中并计算我们投射光线和物体的交点，我们可以先定义一个可计算交点的抽象物体类 hittable，这个类定义一个纯虚函数 hit 用来判断物体和光线的交点，然后再以该抽象类为基类，实现各种物体类即可，这样一来，不同的物体的 hit 函数有可以有不同的实现了。
hit 函数也和我们上面写的稍有不同，除了要接收一根光线作为参数外，还要有一个限定范围 $t_{min}$ 和 $t_{max}$，只有当交点的 t 在这个范围内才会与物体相交，这部分也在之前的图形学中也有学过，同时这个范围也可以用于后面计算多个物体中最近的交点。
此外，光线可能和物体有多个交点，我们需要取在限定范围内的离我们最近的交点，把该交点及其法线等属性记录下来，因此还要定义一个存储交点属性的结构体。
最后还需要考虑一个问题，交点是物体的正面还是背面？这对我们渲染来说非常重要，尤其是一些双面不同的物体。这可以通过光线和法线的点乘来判断，如果光线和交点的法线反向，这说明交点在物体的正面，因为法线都是从物体中心指向表面的；相反如果光线和交点的法线同向，这说明交点在物体的背面。同向和反向实际上是两个向量的夹角，因此点乘即可。如果交点在物体背面，那么计算光照时用到的法线应该是这个点表面法线的反方向，所以要对原法线取反。如下图：

现在我们可以开始实现上面的思路了，首先是抽象类和结构体的定义：
/*    抽象类hittable，所有物体都继承该类*/#pragma once#ifndef HITTABLE_H#define HITTABLE_H// utilities.h 包含了常用的工具函数并整合了常用头文件，避免循环嵌套，我们在后面会实现#include &quot;utilities.h&quot;struct hit_record &#123;    point3 p;           //交点    vec3 normal;        //交点法线    double t;           //交点t值    bool front_face;    //交点是否在物体的正面    // 如果交点在物体的背面，则法线应该取反方向，以用于计算光照    inline void set_face_normal(ray&amp; r, vec3&amp; outward_normal) &#123;        front_face = dot(r.direction(), outward_normal) &lt; 0;        normal = front_face ? outward_normal : -outward_normal;    &#125;&#125;;class hittable &#123;public:    // 纯虚函数，在派生类中实现    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const = 0;&#125;;#endif

接下来实现一个球体类：
/*    球体类sphere，派生于基类hittable*/#pragma once#ifndef SPHERE_H#define SPHERE_H#include &quot;hittable.h&quot;// 球体类以hittable抽象类为基类class sphere : public hittable &#123;public:    sphere() &#123;&#125;    sphere(point3 cen, double r) : center(cen), radius(r) &#123;&#125;;    // 重载虚函数    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;public:    point3 center;    double radius;&#125;;bool sphere::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const&#123;    vec3 oc = r.origin() - center;    auto a = r.direction().length_squared();    auto half_b = dot(oc, r.direction());    auto c = oc.length_squared() - radius * radius;    auto discriminant = half_b * half_b - a * c;    if (discriminant &lt; 0) return false;    auto sqrtd = sqrt(discriminant);    // 找到满足条件的最近的交点    auto root = (-half_b - sqrtd) / a;    if (root &lt; t_min || t_max &lt; root) &#123;        root = (-half_b + sqrtd) / a;        if (root &lt; t_min || t_max &lt; root)            return false;    &#125;    // 记录该交点的相关信息    rec.t = root;    rec.p = r.at(rec.t);    // 法线记得归一化    vec3 outward_normal = (rec.p - center) / radius;    // 判断交点在正面还是背面，并设置正确的法线方向    rec.set_face_normal(r, outward_normal);    return true;&#125;;#endif

3.2 实现物体列表类现在我们已经有了可以与光线相交的物体的基类 hittable，可以在其基础上实现各种物体类，接下来我们要定义一个类来存储多个物体，代码比较容易理解：
/*	物体列表类hittable_list*/#pragma once#ifndef HITTABLE_LIST_H#define HITTABLE_LIST_H#include &quot;hittable.h&quot;#include &lt;memory&gt;#include &lt;vector&gt;using std::shared_ptr;using std::make_shared;class hittable_list : public hittable &#123;public:    hittable_list() &#123;&#125;    hittable_list(shared_ptr&lt;hittable&gt; object) &#123; add(object); &#125;    void clear() &#123; objects.clear(); &#125;    void add(shared_ptr&lt;hittable&gt; object) &#123; objects.push_back(object); &#125;    // 一个物体列表的hit函数用于得到光线和这个列表中所有物体最近的一个交点    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;public:    std::vector&lt;shared_ptr&lt;hittable&gt;&gt; objects;&#125;;bool hittable_list::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const&#123;    hit_record temp_rec;    bool hit_anything = false;    // 记录当前的最近的t    auto closest_so_far = t_max;    // 遍历每一个物体    for (const auto&amp; object : objects) &#123;        if (object-&gt;hit(r, t_min, closest_so_far, temp_rec)) &#123;            hit_anything = true;            // 更新最近的t            closest_so_far = temp_rec.t;            rec = temp_rec;        &#125;    &#125;    return hit_anything;&#125;#endif

3.3 关于智能指针上面的物体列表类中使用了智能指针，在之后的代码中我们也会经常使用，智能指针能帮助我们自动管理内存，防止内存泄漏，一般来说初始化一个智能指针可以使用如下形式的代码：
shared_ptr&lt;double&gt; double_ptr = make_shared&lt;double&gt;(0.37);shared_ptr&lt;vec3&gt;   vec3_ptr   = make_shared&lt;vec3&gt;(1.414214, 2.718281, 1.618034);shared_ptr&lt;sphere&gt; sphere_ptr = make_shared&lt;sphere&gt;(point3(0,0,0), 1.0);

auto 支持对智能指针类型的自动推导，因此我们写起来会更方便：
auto double_ptr = make_shared&lt;double&gt;(0.37);auto vec3_ptr   = make_shared&lt;vec3&gt;(1.414214, 2.718281, 1.618034);auto sphere_ptr = make_shared&lt;sphere&gt;(point3(0,0,0), 1.0);

声明后就可以像正常指针一样使用了。更多关于智能指针的内容可以查看 C++ 与 STL 部分的笔记。
4 常用常量和工具函数接下来需要定义一些常用的常量以及角度转弧度等工具函数，并将一些类的头文件整合起来，使代码组织更整洁。
/*	常用常量及工具函数	整合包含其他头文件*/#pragma once#ifndef UTILITIES_H#define UTILITIES_H#include &lt;cmath&gt;#include &lt;limits&gt;#include &lt;memory&gt;using std::shared_ptr;using std::make_shared;using std::sqrt;// 常量const double infinity = std::numeric_limits&lt;double&gt;::infinity();const double pi = 3.1415926535897932385;// 工具函数inline double degrees_to_radians(double degrees) &#123;	return degrees * pi / 180.0;&#125;// 常用头文件#include &quot;ray.h&quot;#include &quot;vec3.h&quot;#endif UTILITIES_H

5 再次可视化法线使用上面实现的一系列代码，再次实现一个可视化法线的效果，首先修改 ray_color 函数：
// 得到光线颜色color ray_color(ray&amp; r, const hittable&amp; world) &#123;	hit_record rec;	// 计算和世界中的物体的交点的法线	if (world.hit(r, 0, infinity, rec)) &#123;		return 0.5 * (rec.normal + color(1, 1, 1));	&#125;	vec3 unit_direction = normalize(r.direction());	auto t = 0.5 * (unit_direction.y() + 1.0);	return (1.0 - t) * color(1.0, 1.0, 1.0) + t * color(0.5, 0.7, 1.0);&#125;

然后是主函数：
#include &lt;iostream&gt;#include &lt;string&gt;#include &quot;utilities.h&quot;#define STB_IMAGE_WRITE_IMPLEMENTATION#include &quot;stb_image_write.h&quot;#include &quot;hittable_list.h&quot;#include &quot;sphere.h&quot;#include &quot;color.h&quot;int main()&#123;    /****图片保存，保存为png格式****/    std::string SavePath = &quot;D:\\TechStack\\ComputerGraphics\\Ray Tracing in One Weekend Series\\Results\\&quot;;    std::string filename = &quot;WorldSphereNormal.png&quot;;    std::string filepath = SavePath + filename;        /*******图片属性*******/     // 宽高比    const auto aspect_ratio = 16.0 / 9.0;    const int image_width = 400;    // 使用static_cast可以明确告诉编译器，这种损失精度的转换是在知情的情况下进行的    // 也可以让阅读程序的其他程序员明确你转换的目的而不是由于疏忽    const int image_height = static_cast&lt;int&gt;(image_width / aspect_ratio);    const int channel = 3;    /*******相机属性*******/    // 视口高度设为两个单位    auto viewport_height = 2.0;    // 视口宽度根据屏幕宽高比计算    auto viewport_width = aspect_ratio * viewport_height;    // 原点到视口平面距离为1个单位    auto focal_length = 1.0;    // 相机原点    auto origin = point3(0, 0, 0);    // 视口宽的一半    auto horizontal = vec3(viewport_width, 0, 0);    // 视口高的一半    auto vertical = vec3(0, viewport_height, 0);    // 相当于将(0,0,0)移动到视口平面的左下角，也就是得到左下角的点的位置    auto lower_left_corner = origin - horizontal / 2 - vertical / 2 - vec3(0, 0, focal_length);    /*******场景属性*******/    hittable_list world;    // 向场景中添加两个球体    world.add(make_shared&lt;sphere&gt;(point3(0, 0, -1), 0.5));    world.add(make_shared&lt;sphere&gt;(point3(0, -100.5, -1), 100));    /******渲染部分*****/    // 3通道图像存在一维数组中    unsigned char* odata = (unsigned char*)malloc(image_width * image_height * channel);    unsigned char* p = odata;    for (int j = image_height - 1; j &gt;= 0; --j) &#123;        // 标准错误流显示进度信息，单行刷新显示        std::cerr &lt;&lt; &quot;\rScanlines remaining: &quot; &lt;&lt; j &lt;&lt; &#x27; &#x27; &lt;&lt; std::flush;        for (int i = 0; i &lt; image_width; ++i) &#123;            // x方向偏移            auto u = double(i) / (image_width - 1);            // y方向偏移            auto v = double(j) / (image_height - 1);            ray r(origin, lower_left_corner + u * horizontal + v * vertical - origin);            color pixel_color = ray_color(r, world);            write_color(p, pixel_color);        &#125;    &#125;    stbi_write_png(filepath.c_str(), image_width, image_height, channel, odata, 0);    std::cerr &lt;&lt; &quot;\nDone.\n&quot;;&#125;

渲染效果如下：

上一节渲染的球体边缘可以明显看到锯齿，为了得到更好的效果我们需要实现一个简单的反走样算法，并且实现一个相机类，以便于管理虚拟摄像机和之后的各种场景采样任务。

1 生成随机数的工具函数首先我们要向 utilities.h 中添加两个生成随机数的函数，用于在像素内部随机采样，一个生成 [0 ,1] 之间的随机数，另一个可以定制随机数范围，在 C++ 11 中可以不使用传统的 rand() 实现，可以使用 &lt;random&gt; 中提供的方法实现：
// utilities.h...    #include &lt;random&gt;    ...    // 生成[0,1]之间的随机数inline double random_double() &#123;    // 0~1之间的均匀分布    static std::uniform_real_distribution&lt;double&gt; distribution(0.0, 1.0);    // random_device用于生成均匀整数，用来给mt19937播种，类似于之前的srand()    static std::mt19937 generator(std::random_device&#123;&#125;());    // 生成符合分布的随机数    return distribution(generator);&#125;// 生成[min,max]之间的随机数inline double random_double(double min, double max) &#123;    return min + (max - min) * random_double();&#125;...

2 实现相机类现在我们实现一个相机类来管理虚拟摄像机以及场景中的各种采样任务，我们先使用之前的轴对齐摄像机作为默认构造方法，来实现一个简单的相机类，只需要把之前主函数中的设置相机的代码拿过来组织一下即可：
/*    相机类camera*/#pragma once#ifndef CAMERA_H#define CAMERA_H#include &quot;utilities.h&quot;class camera &#123;public:    camera() &#123;        auto aspect_ratio = 16.0 / 9.0;        auto viewport_height = 2.0;        auto viewport_width = aspect_ratio * viewport_height;        auto focal_length = 1.0;        origin = point3(0, 0, 0);        horizontal = vec3(viewport_width, 0.0, 0.0);        vertical = vec3(0.0, viewport_height, 0.0);        lower_left_corner = origin - horizontal / 2 - vertical / 2 - vec3(0, 0, focal_length);    &#125;    ray get_ray(double u, double v) const &#123;        return ray(origin, lower_left_corner + u * horizontal + v * vertical - origin);    &#125;private:    point3 origin;    point3 lower_left_corner;    vec3 horizontal;    vec3 vertical;&#125;;#endif

3 反走样光线追踪中最简单的反走样就是在一个像素内部投射出多条光线，将他们的得到的颜色混合起来作为该像素的颜色。
在实现时，我们可以将多根光线的颜色先全部累加到像素中，然后在 write_color 函数中将该像素颜色除以采样数量即可。在此之前我们先在 utilities.h 中添加一个截断函数，用于将给定值截取在指定范围内，同时修改 write_color 函数：
// utilities.h...// 将给定的数字截取到[min,max]范围内inline double clamp(double x, double min, double max) &#123;    if (x &lt; min) return min;    if (x &gt; max) return max;    return x;&#125;// 向数组中写入一个颜色，用到了指针的引用传递// 输入的color是[0,1]范围的inline void write_color(unsigned char*&amp; p, color pixel_color, int samples_per_pixel)&#123;    auto r = pixel_color.x();    auto g = pixel_color.y();    auto b = pixel_color.z();    auto scale = 1.0 / samples_per_pixel;    r *= scale;    g *= scale;    b *= scale;    *p++ = (unsigned char)(256 * clamp(r, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(g, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(b, 0.0, 0.999));&#125;...

4 测试反走样效果接下来修改主函数，测试一下反走样实现效果：
#include &lt;iostream&gt;#include &lt;string&gt;#define STB_IMAGE_WRITE_IMPLEMENTATION#include &quot;stb_image_write.h&quot;#include &quot;hittable_list.h&quot;#include &quot;sphere.h&quot;#include &quot;color.h&quot;#include &quot;camera.h&quot;int main()&#123;    /****图片保存，保存为png格式****/    std::string SavePath = &quot;D:\\TechStack\\ComputerGraphics\\Ray Tracing in One Weekend Series\\Results\\&quot;;    std::string filename = &quot;Antialiasing.png&quot;;    std::string filepath = SavePath + filename;        /*******图片属性*******/     // 宽高比    const auto aspect_ratio = 16.0 / 9.0;    const int image_width = 400;    // 使用static_cast可以明确告诉编译器，这种损失精度的转换是在知情的情况下进行的    // 也可以让阅读程序的其他程序员明确你转换的目的而不是由于疏忽    const int image_height = static_cast&lt;int&gt;(image_width / aspect_ratio);    const int channel = 3;    // 每个像素的采样数量    const int samples_per_pixel = 100;    /*******创建相机*******/    camera cam;    /*******创建场景*******/    hittable_list world;    // 向场景中添加两个球体    world.add(make_shared&lt;sphere&gt;(point3(0, 0, -1), 0.5));    world.add(make_shared&lt;sphere&gt;(point3(0, -100.5, -1), 100));    /******渲染部分*****/    // 3通道图像存在一维数组中    unsigned char* odata = (unsigned char*)malloc(image_width * image_height * channel);    unsigned char* p = odata;    for (int j = image_height - 1; j &gt;= 0; --j) &#123;        // 标准错误流显示进度信息，单行刷新显示        std::cerr &lt;&lt; &quot;\rScanlines remaining: &quot; &lt;&lt; j &lt;&lt; &#x27; &#x27; &lt;&lt; std::flush;        for (int i = 0; i &lt; image_width; ++i) &#123;            color pixel_color(0, 0, 0);            for (int s = 0; s &lt; samples_per_pixel; ++s) &#123;                // 在像素内部随机采样                auto u = (i + random_double()) / (image_width - 1);                auto v = (j + random_double()) / (image_height - 1);                ray r = cam.get_ray(u, v);                pixel_color += ray_color(r, world);            &#125;            write_color(p, pixel_color, samples_per_pixel);        &#125;    &#125;    stbi_write_png(filepath.c_str(), image_width, image_height, channel, odata, 0);    std::cerr &lt;&lt; &quot;\nDone.\n&quot;;&#125;

