我们也可以使用球体作为光源：

5 其他轴对齐矩形现在我们增加其他两个平面的轴对齐矩形的实现：
// xz平面矩形class xz_rect : public hittable &#123;public:    xz_rect() &#123;&#125;    xz_rect(double _x0, double _x1, double _z0, double _z1, double _k,        shared_ptr&lt;material&gt; mat)        : x0(_x0), x1(_x1), z0(_z0), z1(_z1), k(_k), mp(mat) &#123;&#125;;    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        output_box = aabb(point3(x0, k - 0.0001, z0), point3(x1, k + 0.0001, z1));        return true;    &#125;public:    shared_ptr&lt;material&gt; mp;    double x0, x1, z0, z1, k;&#125;;bool xz_rect::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    auto t = (k - r.origin().y()) / r.direction().y();    if (t &lt; t_min || t &gt; t_max)        return false;    auto x = r.origin().x() + t * r.direction().x();    auto z = r.origin().z() + t * r.direction().z();    if (x &lt; x0 || x &gt; x1 || z &lt; z0 || z &gt; z1)        return false;    rec.u = (x - x0) / (x1 - x0);    rec.v = (z - z0) / (z1 - z0);    rec.t = t;    auto outward_normal = vec3(0, 1, 0);    rec.set_face_normal(r, outward_normal);    rec.mat_ptr = mp;    rec.p = r.at(t);    return true;&#125;// yz平面矩形class yz_rect : public hittable &#123;public:    yz_rect() &#123;&#125;    yz_rect(double _y0, double _y1, double _z0, double _z1, double _k,        shared_ptr&lt;material&gt; mat)        : y0(_y0), y1(_y1), z0(_z0), z1(_z1), k(_k), mp(mat) &#123;&#125;;    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        output_box = aabb(point3(k - 0.0001, y0, z0), point3(k + 0.0001, y1, z1));        return true;    &#125;public:    shared_ptr&lt;material&gt; mp;    double y0, y1, z0, z1, k;&#125;;bool yz_rect::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    auto t = (k - r.origin().x()) / r.direction().x();    if (t &lt; t_min || t &gt; t_max)        return false;    auto y = r.origin().y() + t * r.direction().y();    auto z = r.origin().z() + t * r.direction().z();    if (y &lt; y0 || y &gt; y1 || z &lt; z0 || z &gt; z1)        return false;    rec.u = (y - y0) / (y1 - y0);    rec.v = (z - z0) / (z1 - z0);    rec.t = t;    auto outward_normal = vec3(1, 0, 0);    rec.set_face_normal(r, outward_normal);    rec.mat_ptr = mp;    rec.p = r.at(t);    return true;&#125;

6 创建 Cornell Box有了矩形物体，我们可以创建一个著名的 Cornell Box 场景：
// Cornell Box场景hittable_list cornell_box() &#123;    hittable_list objects;    auto red = make_shared&lt;lambertian&gt;(color(.65, .05, .05));    auto white = make_shared&lt;lambertian&gt;(color(.73, .73, .73));    auto green = make_shared&lt;lambertian&gt;(color(.12, .45, .15));    auto light = make_shared&lt;diffuse_light&gt;(color(15, 15, 15));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 555, green));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 0, red));    objects.add(make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, light));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 0, white));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 555, white));    objects.add(make_shared&lt;xy_rect&gt;(0, 555, 0, 555, 555, white));    return objects;&#125;

修改主函数：
int main() &#123;    ...    switch (0) &#123;        ...        default:        case 6:            world = cornell_box();            aspect_ratio = 1.0;            image_width = 600;            samples_per_pixel = 200;            background = color(0,0,0);            lookfrom = point3(278, 278, -800);            lookat = point3(278, 278, 0);            vfov = 40.0;            break;    &#125;    ...

得到的效果如下：

由于光源太小，导致图片中噪声非常大。

之前在图形学中我们学过参与介质（participating media）的实现原理，比如烟雾，这一节我们来实现一个恒定密度的参与介质。

1 恒定密度介质因为我们之前所有的实现都是基于“表面”的，而参与介质是基于“体积”的，这二者之间还是有很大的不同的，但是一个简单的办法是可以把整个参与介质看作是由表面构成的，但这个表面可以在物体内部，只要在一定范围内的点都算作该物体的表面，所以都可以和光线发生作用。
我们在图形学中学过，光线穿过烟雾会在其内部发生各种散射，我们可以用一个概率模型来描述这种过程，如果一个烟雾的密度越大，那么光线在其中发生散射的几率也就越大，如果光线越稀薄，光线就越有可能直接穿过介质而不发生散射，如下图：

我们认为光线在烟雾中走过 $\Delta L$ 距离发生散射的几率是：$$probability &#x3D; C·\Delta L$$其中 $C$ 与介质的密度成正比，于是对于一个随机数就可以用上面的式子计算得到概率，并把这个概率认为是散射发生的距离。如果散射发生的距离大于光线在介质中传播的距离，说明光线没有击中介质，而是直接穿过。
因此一个恒定密度的介质只需要一个密度和边界就可以描述，边界使用另一个物体来确定，相当于该物体形状的烟雾，一个恒定密度的介质类的实现如下：
/** 恒定密度的参与介质类*/#pragma once#ifndef CONSTANT_MEDIUM_H#define CONSTANT_MEDIUM_H#include &quot;utilities.h&quot;#include &quot;hittable.h&quot;#include &quot;material.h&quot;#include &quot;texture.h&quot;class constant_medium : public hittable &#123;public:    constant_medium(shared_ptr&lt;hittable&gt; b, double d, shared_ptr&lt;texture&gt; a)        : boundary(b),        neg_inv_density(-1 / d),        phase_function(make_shared&lt;isotropic&gt;(a))    &#123;&#125;    constant_medium(shared_ptr&lt;hittable&gt; b, double d, color c)        : boundary(b),        neg_inv_density(-1 / d),        phase_function(make_shared&lt;isotropic&gt;(c))    &#123;&#125;    virtual bool hit(        ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        return boundary-&gt;bounding_box(time0, time1, output_box);    &#125;public:    shared_ptr&lt;hittable&gt; boundary;          // 边界    shared_ptr&lt;material&gt; phase_function;    // 各向同性材质，保证光线向各个方向等概率均匀散射    double neg_inv_density;                 // 密度的负倒数&#125;;bool constant_medium::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    // 用于debug    const bool enableDebug = false;    const bool debugging = enableDebug &amp;&amp; random_double() &lt; 0.00001;    // 求光线和边界的两个交点    hit_record rec1, rec2;    if (!boundary-&gt;hit(r, -infinity, infinity, rec1))        return false;    if (!boundary-&gt;hit(r, rec1.t + 0.0001, infinity, rec2))        return false;    if (debugging) std::cerr &lt;&lt; &quot;\nt_min=&quot; &lt;&lt; rec1.t &lt;&lt; &quot;, t_max=&quot; &lt;&lt; rec2.t &lt;&lt; &#x27;\n&#x27;;    if (rec1.t &lt; t_min) rec1.t = t_min;    if (rec2.t &gt; t_max) rec2.t = t_max;    if (rec1.t &gt;= rec2.t)        return false;    if (rec1.t &lt; 0)        rec1.t = 0;    // 光线在介质中的距离    const auto ray_length = r.direction().length();    const auto distance_inside_boundary = (rec2.t - rec1.t) * ray_length;    // 光线发生散射的距离，两个相乘的数都是小于1的负数，所以密度越大值越小    const auto hit_distance = neg_inv_density * log(random_double());    // 发生散射的距离大于光线在介质中的距离则没有发生散射，直接穿过介质    if (hit_distance &gt; distance_inside_boundary)        return false;    // 散射发生的位置    rec.t = rec1.t + hit_distance / ray_length;    rec.p = r.at(rec.t);    if (debugging) &#123;        std::cerr &lt;&lt; &quot;hit_distance = &quot; &lt;&lt; hit_distance &lt;&lt; &#x27;\n&#x27;            &lt;&lt; &quot;rec.t = &quot; &lt;&lt; rec.t &lt;&lt; &#x27;\n&#x27;            &lt;&lt; &quot;rec.p = &quot; &lt;&lt; rec.p &lt;&lt; &#x27;\n&#x27;;    &#125;    // 法线方向这些属性可以随便设置    rec.normal = vec3(1, 0, 0);    rec.front_face = true;    rec.mat_ptr = phase_function;    return true;&#125;#endif

上面的实现中我们默认光线一旦出了介质就不会再在介质中弹射了，因此只适用于凸多边形物体，不适用于凹多边形物体。其中控制光线向各个方向等概率散射的材质在 material.h 中定义：
// 各向同性材质class isotropic : public material &#123;public:    isotropic(color c) : albedo(make_shared&lt;solid_color&gt;(c)) &#123;&#125;    isotropic(shared_ptr&lt;texture&gt; a) : albedo(a) &#123;&#125;    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered    ) const override &#123;        // 光线向各个方向等概率均匀散射        scattered = ray(rec.p, random_in_unit_sphere(), r_in.time());        attenuation = albedo-&gt;value(rec.u, rec.v, rec.p);        return true;    &#125;public:    shared_ptr&lt;texture&gt; albedo;&#125;;

2 用烟雾渲染 Cornell Box我们使用上面实现的介质新建一个 Cornell Box 场景：
// 烟雾Cornell Box场景hittable_list cornell_smoke() &#123;    hittable_list objects;    auto red = make_shared&lt;lambertian&gt;(color(.65, .05, .05));    auto white = make_shared&lt;lambertian&gt;(color(.73, .73, .73));    auto green = make_shared&lt;lambertian&gt;(color(.12, .45, .15));    auto light = make_shared&lt;diffuse_light&gt;(color(7, 7, 7));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 555, green));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 0, red));    objects.add(make_shared&lt;xz_rect&gt;(113, 443, 127, 432, 554, light));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 555, white));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 0, white));    objects.add(make_shared&lt;xy_rect&gt;(0, 555, 0, 555, 555, white));    shared_ptr&lt;hittable&gt; box1 = make_shared&lt;box&gt;(point3(0, 0, 0), point3(165, 330, 165), white);    box1 = make_shared&lt;rotate_y&gt;(box1, 15);    box1 = make_shared&lt;translate&gt;(box1, vec3(265, 0, 295));    shared_ptr&lt;hittable&gt; box2 = make_shared&lt;box&gt;(point3(0, 0, 0), point3(165, 165, 165), white);    box2 = make_shared&lt;rotate_y&gt;(box2, -18);    box2 = make_shared&lt;translate&gt;(box2, vec3(130, 0, 65));    objects.add(make_shared&lt;constant_medium&gt;(box1, 0.01, color(0, 0, 0)));    objects.add(make_shared&lt;constant_medium&gt;(box2, 0.01, color(1, 1, 1)));    return objects;&#125;

主函数修改：
int main() &#123;    ...    switch (sence) &#123;        ...        default:        case 7:            world = cornell_smoke();            aspect_ratio = 1.0;            image_width = 600;            samples_per_pixel = 200;            lookfrom = point3(278, 278, -800);            lookat = point3(278, 278, 0);            vfov = 40.0;            break;    ...&#125;

