现在我们新建一个非常复杂的场景来测试到目前为止光线追踪器的全部特性，生成我们的第二张光线追踪“大片”。

1 创建新场景创建一个包含所有特性的场景：
// 新特性最终场景hittable_list final_scene() &#123;    // 高低起伏的盒子组成地面    hittable_list boxes1;    auto ground = make_shared&lt;lambertian&gt;(color(0.48, 0.83, 0.53));    const int boxes_per_side = 20;    for (int i = 0; i &lt; boxes_per_side; i++) &#123;        for (int j = 0; j &lt; boxes_per_side; j++) &#123;            auto w = 100.0;            auto x0 = -1000.0 + i * w;            auto z0 = -1000.0 + j * w;            auto y0 = 0.0;            auto x1 = x0 + w;            auto y1 = random_double(1, 101);            auto z1 = z0 + w;            boxes1.add(make_shared&lt;box&gt;(point3(x0, y0, z0), point3(x1, y1, z1), ground));        &#125;    &#125;    hittable_list objects;    // 构建地面的BVH树    objects.add(make_shared&lt;bvh_node&gt;(boxes1, 0, 1));    // 光源    auto light = make_shared&lt;diffuse_light&gt;(color(7, 7, 7));    objects.add(make_shared&lt;xz_rect&gt;(123, 423, 147, 412, 554, light));    // 移动的球体    auto center1 = point3(400, 400, 200);    auto center2 = center1 + vec3(30, 0, 0);    auto moving_sphere_material = make_shared&lt;lambertian&gt;(color(0.7, 0.3, 0.1));    objects.add(make_shared&lt;sphere&gt;(center1, center2, 0, 1, 50, moving_sphere_material));    // 透明球体    objects.add(make_shared&lt;sphere&gt;(        point3(260, 150, 45), point3(260, 150, 45), 0, 1, 50, make_shared&lt;dielectric&gt;(1.5)));    // 金属球体    objects.add(make_shared&lt;sphere&gt;(        point3(0, 150, 145), point3(0, 150, 145), 0, 1, 50, make_shared&lt;metal&gt;(color(0.8, 0.8, 0.9), 1.0)        ));    // 参与介质    auto boundary = make_shared&lt;sphere&gt;(        point3(360, 150, 145), point3(360, 150, 145), 0, 1, 70, make_shared&lt;dielectric&gt;(1.5));    objects.add(boundary);    objects.add(make_shared&lt;constant_medium&gt;(boundary, 0.01, color(0.2, 0.4, 0.9)));    boundary = make_shared&lt;sphere&gt;(        point3(0, 0, 0), point3(0, 0, 0), 0, 1, 5000, make_shared&lt;dielectric&gt;(1.5));    objects.add(make_shared&lt;constant_medium&gt;(boundary, .0001, color(1, 1, 1)));    // 地球    auto emat = make_shared&lt;lambertian&gt;(make_shared&lt;image_texture&gt;(        &quot;D:\\TechStack\\ComputerGraphics\\Ray Tracing in One Weekend Series\\Project\\Textures\\earthmap.jpg&quot;));    objects.add(make_shared&lt;sphere&gt;(        point3(400, 200, 400), point3(400, 200, 400), 0, 1, 100, emat));    // 噪声纹理    auto pertext = make_shared&lt;noise_texture&gt;(4);    objects.add(make_shared&lt;sphere&gt;(        point3(220, 280, 300), point3(220, 280, 300), 0, 1, 80, make_shared&lt;lambertian&gt;(pertext)));    // 一堆小球    hittable_list boxes2;    auto white = make_shared&lt;lambertian&gt;(color(.73, .73, .73));    int ns = 1000;    for (int j = 0; j &lt; ns; j++) &#123;        auto center = random_vec(0, 165);        boxes2.add(make_shared&lt;sphere&gt;(            center, center, 0, 1, 10, white));    &#125;    // 旋转平移一堆小球    objects.add(make_shared&lt;translate&gt;(        make_shared&lt;rotate_y&gt;(            make_shared&lt;bvh_node&gt;(boxes2, 0.0, 1.0), 15),        vec3(-100, 270, 395)        )    );    return objects;&#125;

2 渲染效果修改主函数：
int main() &#123;    ...    switch (sence) &#123;        ...        default:        case 8:            world = final_scene();            aspect_ratio = 1.0;            image_width = 800;            samples_per_pixel = 10000;            min_bounce = 95;            background = color(0,0,0);            lookfrom = point3(478, 278, -600);            lookat = point3(278, 278, 0);            vfov = 40.0;            break;    ...&#125;

渲染效果如下：

上一节中我们实现了光源和矩形物体，并初步创建了一个 Cornell Box 场景，但场景中还缺少两个立方体，并且立方体和墙面之间存在一定的旋转角度，因此这一节我们需要实现一个立方体物体类，并且支持旋转和平移。

1 轴对齐立方体先使用轴对齐矩形实现一个轴对齐立方体类：
#pragma once#ifndef BOX_H#define BOX_H#include &quot;utilities.h&quot;#include &quot;aarect.h&quot;#include &quot;hittable_list.h&quot;class box : public hittable &#123;public:    box() &#123;&#125;    box(const point3&amp; p0, const point3&amp; p1, shared_ptr&lt;material&gt; ptr);    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        output_box = aabb(box_min, box_max);        return true;    &#125;public:    point3 box_min;    point3 box_max;    hittable_list sides;&#125;;box::box(const point3&amp; p0, const point3&amp; p1, shared_ptr&lt;material&gt; ptr) &#123;    box_min = p0;    box_max = p1;    sides.add(make_shared&lt;xy_rect&gt;(p0.x(), p1.x(), p0.y(), p1.y(), p1.z(), ptr));    sides.add(make_shared&lt;xy_rect&gt;(p0.x(), p1.x(), p0.y(), p1.y(), p0.z(), ptr));    sides.add(make_shared&lt;xz_rect&gt;(p0.x(), p1.x(), p0.z(), p1.z(), p1.y(), ptr));    sides.add(make_shared&lt;xz_rect&gt;(p0.x(), p1.x(), p0.z(), p1.z(), p0.y(), ptr));    sides.add(make_shared&lt;yz_rect&gt;(p0.y(), p1.y(), p0.z(), p1.z(), p1.x(), ptr));    sides.add(make_shared&lt;yz_rect&gt;(p0.y(), p1.y(), p0.z(), p1.z(), p0.x(), ptr));&#125;bool box::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    return sides.hit(r, t_min, t_max, rec);&#125;#endif

然后将 box 添加到 Cornell Box 场景中：
// Cornell Box场景hittable_list cornell_box() &#123;    hittable_list objects;    auto red = make_shared&lt;lambertian&gt;(color(.65, .05, .05));    auto white = make_shared&lt;lambertian&gt;(color(.73, .73, .73));    auto green = make_shared&lt;lambertian&gt;(color(.12, .45, .15));    auto light = make_shared&lt;diffuse_light&gt;(color(15, 15, 15));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 555, green));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 0, red));    objects.add(make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, light));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 0, white));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 555, white));    objects.add(make_shared&lt;xy_rect&gt;(0, 555, 0, 555, 555, white));    objects.add(make_shared&lt;box&gt;(point3(130, 0, 65), point3(295, 165, 230), white));    objects.add(make_shared&lt;box&gt;(point3(265, 0, 295), point3(430, 330, 460), white));    return objects;&#125;

得到的效果：

2 Instances接下来我们要实现立方体的旋转，更一般地，我们不止要让立方体旋转，而是要让场景中的所有物体都能够运动，运动包括平移和旋转。在光线追踪器中，这些都是通过 Instances 来实现的，Instances 可以认为是一个几何变换器，可以将传入的物体按照给定的参数和方式进行变换，因此我们要实现这些几何变换的 Instances 类。
2.1 平移首先是平移变换类，在光线追踪器中实现物体平移不是通过真的把物体移动到某个位置，因为物体一旦被放入场景再去变换位置就需要费很大的功夫，所以实现物体平移是通过向反方向移动光线来实现的，比如：

要把粉色的正方形沿 x 轴向右移动两个单位，我们可以通过把光线沿 x 轴向左移动两个单位来实现。
注意和之前实现的移动的球体做区分，这里的移动不是在一段时间内的运动，而是改变场景中物体的摆放方式。
平移变换类的实现如下：
// 平移变换class translate : public hittable &#123;public:    translate(shared_ptr&lt;hittable&gt; p, const vec3&amp; displacement)        : ptr(p), offset(displacement) &#123;&#125;    virtual bool hit(        ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override;public:    shared_ptr&lt;hittable&gt; ptr;    vec3 offset;&#125;;bool translate::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    // 光线向反方向平移    ray moved_r(r.origin() - offset, r.direction(), r.time());        // 计算交点，这里计算出的交点是相对坐标，物体还在原本的地方    if (!ptr-&gt;hit(moved_r, t_min, t_max, rec))        return false;    // 把物体和光线的交点加上偏移，得到平移后的物体和光线的交点在世界空间的绝对坐标    // 这才相当于把物体移动了    rec.p += offset;    rec.set_face_normal(moved_r, rec.normal);    return true;&#125;bool translate::bounding_box(double time0, double time1, aabb&amp; output_box) const &#123;    if (!ptr-&gt;bounding_box(time0, time1, output_box))        return false;    output_box = aabb(        output_box.min() + offset,        output_box.max() + offset);    return true;&#125;

2.2 旋转旋转的思路和平移一样，也是先反方向旋转光线，得到交点后对交点再进行正向旋转，不同的是旋转后交点法线也要相应变换，在 Shader 学习中我们知道对法线变换要用变换矩阵的逆转置矩阵，旋转矩阵是正交矩阵，逆转置矩阵就是其本身。
绕 y 轴旋转的实现如下：
// 绕y轴旋转class rotate_y : public hittable &#123;public:    rotate_y(shared_ptr&lt;hittable&gt; p, double angle);    virtual bool hit(        ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        output_box = bbox;        return hasbox;    &#125;public:    shared_ptr&lt;hittable&gt; ptr;    double sin_theta;    double cos_theta;    bool hasbox;    aabb bbox;&#125;;// 构造函数，计算旋转后的bounding box及其他的基本成员rotate_y::rotate_y(shared_ptr&lt;hittable&gt; p, double angle) : ptr(p) &#123;    auto radians = degrees_to_radians(angle);    sin_theta = sin(radians);    cos_theta = cos(radians);    hasbox = ptr-&gt;bounding_box(0, 1, bbox);    point3 min(infinity, infinity, infinity);    point3 max(-infinity, -infinity, -infinity);    // 遍历bounding box的每个顶点，并进行变换    for (int i = 0; i &lt; 2; i++) &#123;        for (int j = 0; j &lt; 2; j++) &#123;            for (int k = 0; k &lt; 2; k++) &#123;                auto x = i * bbox.max().x() + (1 - i) * bbox.min().x();                auto y = j * bbox.max().y() + (1 - j) * bbox.min().y();                auto z = k * bbox.max().z() + (1 - k) * bbox.min().z();                auto newx = cos_theta * x + sin_theta * z;                auto newz = -sin_theta * x + cos_theta * z;                vec3 tester(newx, y, newz);                for (int c = 0; c &lt; 3; c++) &#123;                    min[c] = fmin(min[c], tester[c]);                    max[c] = fmax(max[c], tester[c]);                &#125;            &#125;        &#125;    &#125;    bbox = aabb(min, max);&#125;bool rotate_y::hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const &#123;    auto origin = r.origin();    auto direction = r.direction();    // 光线向反方向旋转    origin[0] = cos_theta * r.origin()[0] - sin_theta * r.origin()[2];    origin[2] = sin_theta * r.origin()[0] + cos_theta * r.origin()[2];    // 因为光线方向实际上是两个点的差，所以也可以直接应用变换矩阵    direction[0] = cos_theta * r.direction()[0] - sin_theta * r.direction()[2];    direction[2] = sin_theta * r.direction()[0] + cos_theta * r.direction()[2];    ray rotated_r(origin, direction, r.time());    // 得到的交点同样是相对的坐标    if (!ptr-&gt;hit(rotated_r, t_min, t_max, rec))        return false;    auto p = rec.p;    auto normal = rec.normal;    // 将交点进行旋转    p[0] = cos_theta * rec.p[0] + sin_theta * rec.p[2];    p[2] = -sin_theta * rec.p[0] + cos_theta * rec.p[2];    // 法线也要旋转，法线变换应该用原变换矩阵的逆转置矩阵，旋转矩阵正交因此逆转置矩阵就是原矩阵    normal[0] = cos_theta * rec.normal[0] + sin_theta * rec.normal[2];    normal[2] = -sin_theta * rec.normal[0] + cos_theta * rec.normal[2];    rec.p = p;    rec.set_face_normal(rotated_r, normal);    return true;&#125;

3 完整的 Cornell Box利用实现的立方体和几何变换类，来得到完整的 Cornell Box 场景：
// Cornell Box场景hittable_list cornell_box() &#123;    hittable_list objects;    auto red = make_shared&lt;lambertian&gt;(color(.65, .05, .05));    auto white = make_shared&lt;lambertian&gt;(color(.73, .73, .73));    auto green = make_shared&lt;lambertian&gt;(color(.12, .45, .15));    auto light = make_shared&lt;diffuse_light&gt;(color(15, 15, 15));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 555, green));    objects.add(make_shared&lt;yz_rect&gt;(0, 555, 0, 555, 0, red));    objects.add(make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, light));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 0, white));    objects.add(make_shared&lt;xz_rect&gt;(0, 555, 0, 555, 555, white));    objects.add(make_shared&lt;xy_rect&gt;(0, 555, 0, 555, 555, white));    shared_ptr&lt;hittable&gt; box1 = make_shared&lt;box&gt;(point3(0, 0, 0), point3(165, 330, 165), white);    box1 = make_shared&lt;rotate_y&gt;(box1, 15);    box1 = make_shared&lt;translate&gt;(box1, vec3(265, 0, 295));    objects.add(box1);    shared_ptr&lt;hittable&gt; box2 = make_shared&lt;box&gt;(point3(0, 0, 0), point3(165, 165, 165), white);    box2 = make_shared&lt;rotate_y&gt;(box2, -18);    box2 = make_shared&lt;translate&gt;(box2, vec3(130, 0, 65));    objects.add(box2);    return objects;&#125;

效果如下：

背包问题是动态规划中最经典的问题之一，也是机试中最常出现的问题。背包问题大体可分为九种类型。
1 0-1背包问题AcWing02. 01背包问题
有 N 件物品和一个容量是 V 的背包。每件物品只能使用一次。第 i 件物品的体积是 vi，价值是 wi。求解将哪些物品装入背包，可使这些物品的总体积不超过背包容量，且总价值最大。输出最大价值。
0-1 背包是最简单的背包问题，定义状态 $dp[i][curv]$ 表示将前 i 件物品放入体积为 curv 的背包所能获得的最大价值，其中 $(curv \leq V)$，对于第 i 件物品，只存在拿与不拿两种情况，如果不拿第 i 件物品，那么问题就转化为“前 i - 1 件物品放入容量为 curv 的背包中所能获得的最大价值”，于是价值为 $dp[i-1][curv]$；如果拿第 i 件物品，那么问题就转化为“前 i - 1 件物品放入剩下的容量为 curv - vi 的背包中所能获得的最大价值”，此时能获得的最大价值就是 $dp[i-1][curv-vi]$ 再加上通过放入第 i 件物品获得的价值 wi，因此状态转移方程如下： dp[i][curv] = max(dp[i-1][curv], dp[i-1][curv-v[i]] + w[i]);
于是可以写出代码： #include&lt;iostream&gt;#include&lt;vector&gt;using namespace std;class solution &#123;public: int ZeroOnePack(vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, int n, int v) &#123; vector&lt;vector&lt;int&gt;&gt; dp(n + 1, vector&lt;int&gt;(v + 1, 0)); for(int i = 1; i &lt;= n; ++i) &#123; for(int curv = 1; curv &lt;= v; ++curv) &#123; dp[i][curv] = dp[i-1][curv]; if(curv &gt;= volume[i-1]) dp[i][curv] = max(dp[i][curv], dp[i-1][curv - volume[i-1]] + value[i-1]); &#125; &#125; return dp[n][v]; &#125;&#125;;int main() &#123; int n, v; cin &gt;&gt; n &gt;&gt; v; vector&lt;int&gt; volume(n); vector&lt;int&gt; value(n); for(int i = 0; i &lt; n; ++i) &#123; cin &gt;&gt; volume[i] &gt;&gt; value[i]; &#125; solution ans; cout &lt;&lt; ans.ZeroOnePack(volume, value, n, v) &lt;&lt; endl; return 0;&#125;
因为状态 i 至于状态 i - 1 有关，因此可以使用一维数组优化： class solution &#123;public: int ZeroOnePack(vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, int n, int v) &#123; vector&lt;int&gt; dp(v + 1, 0); for(int i = 1; i &lt;= n; ++i) &#123; // 注意体积必须逆序遍历，否则就需要一个额外的数组来存储上一次的状态 for(int curv = v; curv &gt;= volume[i-1]; --curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume[i-1]] + value[i-1]); &#125; &#125; return dp[v]; &#125;&#125;;
需要注意的是使用一维数组的话，遍历体积 curv 的时候要从大到小遍历，因为如果从小到大遍历，那么后面需要的 dp[curv - volume[i-1]] + value[i-1] 就不是第 i - 1 的状态了，而是更新过的第 i 次的状态。此外遍历体积 curv 只需要遍历到当前物品的体积 volume[i-1] 即可，因为背包体积比当前物品体积小的话，一定装不进去，状态不需要更新，沿用前一次的状态即可。 如果将题目的要求改为必须将背包装满所能获得的最大价值，只需要修改动态规划的边界条件即可。现在的边界条件是 dp 数组全部初始化为 0 ，因为题目没有要求全部装满，只要不超过就可以，所以对于任意体积的背包，初始时都不装物品，最大价值都是 0；当要求背包必须装满时，初始化动态数组 dp 只有 $dp[0][0] &#x3D; 0$，这代表将体积为 0 的背包用一个体积为0 的物体装满获得的最大价值为 0，而其它情况都初始化为 INT_MIN ，这代表其他体积的背包还没有装满，不符合要求，所以获得的价值也不存在。 0-1 背包问题虽然简单，但后面几乎所有的背包问题都是 0-1 背包问题的变体，都要用到 0-1 背包的方法去解决，因此 0-1 背包是最重要的背包问题。 2 完全背包问题 AcWing03. 完全背包问题
有 N 种物品和一个容量是 V 的背包，每种物品都有无限件可用。第 i 种物品的体积是 vi，价值是 wi。求解将哪些物品装入背包，可使这些物品的总体积不超过背包容量，且总价值最大。输出最大价值。
完全背包问题与 0-1 背包非常相似，只是这一次每件物品可以无限次数使用，如果还按照求解 0-1 背包时的思路，定义状态 $dp[i][curv]$ 表示将前 i 种物品放入体积为 curv 的背包所能获得的最大价值，这时要求解的总状态数还是 NV 个，但求解每个状态时就不是 $O(1)$ 复杂度了，而是 $O(curv &#x2F; vi)$ 的复杂度，因为一个物体最多可以放入 curv &#x2F; vi 次。于是总复杂度就是：$$O(NV \times \sum{\frac{curv}{vi}} )$$是比较大的。因此我们要考虑对它进行一些优化，稍微试用一下贪心的思想，对于每件物品 i，如果有物品 j 比它的重量小，价值大，那么就不需要考虑物品 i 了，因为我们任何情况下都可将价值小费用高的 i 换成物美价廉的 j，得到至少不会更差的方案。对于随机生成的数据，这个方法往往会大大减少物品的件数，从而加快速度。然而这个并不能改善最坏情况的复杂度，因为有可能特别设计的数据会一件物品也去不掉。而且这个优化方案往往需要 $O(N^2)$ 的时间。 一个更好的优化方案是，首先将费用大于容量 V 的物品去掉，然后使用类似计数排序的做法，计算出费用相同的物品中价值最高的是哪个，这个过程只需要 $O(V+N)$ 时间，但可能会需要额外的空间，比如借助哈希表。 一般来说，我们不需要用上面如此复杂的思路，但是经过这些推导可以加深对问题的理解。同时也说明了 0-1 背包的重要性，因为以上思路全都是基于 0-1 背包，针对完全背包问题进行优化的。 解决这个问题更直接的思路一般是转化为 0-1 背包问题，事实上大多数的背包问题都可以这样做，再一次说明了 0-1 背包有多重要。 具体思路是：因为每件物品 i 最多只能选 V &#x2F; vi 件，因此我们可以把物品 i 拆分成 V &#x2F; vi 件体积和价值完全一样的物品，然后就转化成了一个 0-1 背包问题。 这样的思路完全没有改进基本思路的时间复杂度，但这却给了我们将完全背包问题转化为 0-1 背包问题的基本思路：将一种物品拆成多件物品。 于是我们可以进一步优化，将物品 i 拆成体积为 $vi * 2^k$ ，价值为 $wi*2^k$ 的若干件物品，这里用了二进制的思想，因为不管最优策略选几件第 i 种物品，总可以表示成若干个$2^k$ 件物品的和。这样我们把物品拆成了 $O(logV &#x2F; vi)$ 件物品，是一个很大的优化。 但还有更好的方法，和 0-1 背包问题一样的 $O(NV)$ 复杂度的方法。我们只需要把 0-1 背包问题的一维数组解法遍历体积 curv 的顺序从逆序改为正序即可。之前逆序遍历是因为每件物品只能选一次，所以第 i 件物品的状态必须从没有选择第 i 件物品的状态 i - 1 得来，而现在物品 i 可以选择多次，所以第 i 种物品的状态恰好需要从已选入第 i 种物品的子结果转移而来。 class solution &#123;public: int CompletePack(vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, int n, int v) &#123; vector&lt;int&gt; dp(v + 1, 0); for(int i = 1; i &lt;= n; ++i) &#123; for(int curv = volume[i-1]; curv &lt;= v; ++curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume[i-1]] + value[i-1]); &#125; &#125; return dp[v]; &#125;&#125;;
上面的两种遍历顺序可以颠倒，这在特定数据量的情况下可以做出常数级别的优化。 完全背包问题也是一个简单问题，但往往简单问题才更需要深刻理解，因为复杂的问题也都只是简单问题的变体。 因为 0-1 背包和完全背包是两个最基础的背包问题，因此我们可以将这两个问题的求解方法抽象成两个函数，在之后更复杂的问题中，可能会转换成这两种问题，直接调用这两个函数即可： void ZeroOnePack(vector&lt;int&gt;&amp; dp, int volume, int value, int v)&#123; for(int curv = v; curv &gt;= volume; --curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125;&#125;void CompletePack(vector&lt;int&gt;&amp; dp, int volume, int value, int v)&#123; for(int curv = volume; curv &lt;= v; ++curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125;&#125;
3 多重背包问题AcWing04. 多重背包问题 I
有 N 种物品和一个容量是 V 的背包。第 i 种物品最多有 si 件，每件体积是 vi，价值是 wi。求解将哪些物品装入背包，可使物品体积总和不超过背包容量，且价值总和最大。输出最大价值。
多重背包问题同样可以转化为 0-1 背包实现，只需要把物品 i 拆分成 si 件同样的物品即可，然后我们按照 0-1 背包的方法求解。因此对于每件物品，只需要增加一重循环，遍历物品数量，代表这个物品拿几次： #include&lt;iostream&gt;#include&lt;vector&gt;using namespace std;class solution &#123;public: int MultiPack(vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, vector&lt;int&gt;&amp; amount, int n, int v) &#123; vector&lt;int&gt; dp(v + 1, 0); for(int i = 1; i &lt;= n; ++i) &#123; // 因为是基于0-1背包，所以要逆序遍历 for(int curv = v; curv &gt;= volume[i-1]; --curv) &#123; for(int s = 0; s &lt;= amount[i-1] &amp;&amp; curv &gt;= s * volume[i-1]; ++s) dp[curv] = max(dp[curv], dp[curv - s * volume[i-1]] + s * value[i-1]); &#125; &#125; return dp[v]; &#125;&#125;;int main() &#123; int n, v; cin &gt;&gt; n &gt;&gt; v; vector&lt;int&gt; volume(n); vector&lt;int&gt; value(n); vector&lt;int&gt; amount(n); for(int i = 0; i &lt; n; ++i) &#123; cin &gt;&gt; volume[i] &gt;&gt; value[i] &gt;&gt; amount[i]; &#125; solution ans; cout &lt;&lt; ans.MultiPack(volume, value, amount, n, v) &lt;&lt; endl; return 0;&#125;
AcWing05. 多重背包问题 II
问题相同，但数据范围变为：0 &lt; N ≤ 10000 &lt; V ≤ 20000 &lt; vi, wi, si ≤ 2000
数据量过大的时候，上面的方法将物品拆分成了 si 件，复杂度太高，于是可以借鉴之前的二进制优化，将物品拆分成 $O(logsi)$ 件，具体的做法是将物品 i 拆分成系数为 $1, 2, 4, … , 2^{k-1},si-2^k+1$ 的若干件物品，其中 $si-2^k+1$ 其实就是物品总数减去之前拆分的数量总和，这样可以保证所有拆分的物品的系数加起来等于物品 i 的数量 si。例如，物品 i 的数量为 13 件，那么就拆分成系数为 1，2，4，6 的四件物品，四件物品的体积和价值为物品 i 的体积和价值乘以对应的系数。然后再利用 0-1 背包求解。另外如果物品 i 的数量 si 使得 si * vi 大于了背包总容量 V，那么问题就转化成了一个完全背包问题，因为相当于物品 i 可以在不超过背包容量的前提下无限次使用。于是可以写出代码： class solution &#123;public: void ZeroOnePack(vector&lt;int&gt;&amp; dp, int volume, int value, int v) &#123; for(int curv = v; curv &gt;= volume; --curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125; &#125; void CompletePack(vector&lt;int&gt;&amp; dp, int volume, int value, int v) &#123; for(int curv = volume; curv &lt;= v; ++curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125; &#125; int MultiPack(vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, vector&lt;int&gt;&amp; amount, int n, int v) &#123; vector&lt;int&gt; dp(v + 1, 0); for(int i = 1; i &lt;= n; ++i) &#123; if(volume[i-1] * amount[i-1] &gt; v) &#123; CompletePack(dp, volume[i-1], value[i-1], v); &#125; else &#123; int k = 1, s = amount[i-1]; while(s - k &gt;= 0) &#123; ZeroOnePack(dp, k * volume[i-1], k * value[i-1], v); s -= k; k *= 2; &#125; ZeroOnePack(dp, s * volume[i-1], s * value[i-1], v); &#125; &#125; return dp[v]; &#125;&#125;;
二进制拆分方法是求解多重背包问题的一般写法，时间复杂度较好并且不难理解。实际上多重背包问题也有 $O(NV)$ 的解法，利用了单调队列优化状态求解过程，但已经超出了常规算法的范畴，证明起来也比较困难，不在我们的讨论范围内。 4 混合背包问题AcWing07. 混合背包问题
有 N 种物品和一个容量是 V 的背包。物品一共有三类：
第一类物品只能用1次（01背包）； 第二类物品可以用无限次（完全背包）； 第三类物品最多只能用 sisi 次（多重背包）；
每种体积是 vi，价值是 wi。求解将哪些物品装入背包，可使物品体积总和不超过背包容量，且价值总和最大。输出最大价值。 输入第一行两个整数，N，V，用空格隔开，分别表示物品种数和背包容积。 接下来有 N 行，每行三个整数 vi, wi, si，用空格隔开，分别表示第 i 种物品的体积、价值和数量。
si &#x3D; −1 表示第 i 种物品只能用1次； si &#x3D; 0 表示第 i 种物品可以用无限次； si &gt; 0 表示第 i 种物品可以使用 si 次；
混合背包是较为困难的背包问题，但经过前面的推导，实际上只要对三类物品分别应用上面的三个过程就可以。之前的代码都是全部读取数据后再处理，但实际上不需要全部读取，每读一件物品就可以更新一次 dp 数组了。 #include&lt;iostream&gt;#include&lt;vector&gt;using namespace std;class solution &#123;public: // 0-1 背包 void ZeroOnePack(vector&lt;int&gt;&amp; dp, int volume, int value, int total) &#123; for(int curv = total; curv &gt;= volume; --curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125; &#125; // 完全背包 void CompletePack(vector&lt;int&gt;&amp; dp, int volume, int value, int total) &#123; for(int curv = volume; curv &lt;= total; ++curv) &#123; dp[curv] = max(dp[curv], dp[curv - volume] + value); &#125; &#125; // 多重背包 void MultiPack(vector&lt;int&gt;&amp; dp, int volume, int value, int amount, int total) &#123; if(amount * volume &gt; total) &#123; CompletePack(dp, volume, value, total); &#125; else &#123; int k = 1; while(amount - k &gt;= 0) &#123; ZeroOnePack(dp, k * volume, k * value, total); amount -= k; k *= 2; &#125; ZeroOnePack(dp, amount * volume, amount * value, total); &#125; &#125;&#125;;int main()&#123; int n,v; cin &gt;&gt; n &gt;&gt; v; // 不要求必须装满，所以初始化为0 vector&lt;int&gt; dp(v + 1, 0); solution ans; for(int i = 0; i &lt; n; ++i) &#123; int volume, value, amount; cin &gt;&gt; volume &gt;&gt; value &gt;&gt; amount; if (amount &lt; 0) ans.ZeroOnePack(dp, volume, value, v); else if (amount == 0) ans.CompletePack(dp, volume, value, v); else ans.MultiPack(dp, volume, value, amount, v); &#125; cout &lt;&lt; dp[v] &lt;&lt; endl; return 0;&#125;
5 二维费用的背包问题二维费用的背包问题是指：对于每件物品，具有两种不同的费用；选择这件物品必须同时付出这两种代价；对于每种代价都有一个可付出的最大值（背包容量）。问怎样选择物品可以得到最大的价值。设这两种代价分别为代价 1 和代价 2 ，第 i 件物品所需的两种代价分别为 a[i] 和 b[i]。两种代价可付出的最大值（两种背包容量）分别为 V 和 U。物品的价值为 value[i]。 这相当于在之前的基础上费用增加了一维，所以动态规划的状态也增加一维即可，于是原来的状态转移方程： dp[i][curv] = max(dp[i-1][curv], dp[i-1][curv - volume[i]] + value[i]);
就可以改写为： dp[i][cur_v][cur_u] = max(dp[i-1][cur_v][cur_u], dp[i-1][cur_v - a[i]][cur_u - b[i]] + value[i])
显然也可以不用三维数组，改用二维数组，当问题类似于 0-1 背包时，逆序遍历，类似于完全背包时，正序遍历，类似于多重背包时应用多重背包的解法。 当然，实际的题目中往往不会显式的告诉我们有两种代价，题目一般是这样描述的： AcWing08. 二维费用的背包问题
有 N 件物品和一个容量是 V 的背包，背包能承受的最大重量是 M。每件物品只能用一次。体积是 vi，重量是 mi，价值是 wi。求解将哪些物品装入背包，可使物品总体积不超过背包容量，总重量不超过背包可承受的最大重量，且价值总和最大。输出最大价值。
背包能承受的最大重量就相当于增加了一个代价——重量。于是我们就要同时考虑体积和重量两种代价。按照上面的思路，只要在 0-1 背包的基础上增加一重循环，遍历重量即可。 #include&lt;iostream&gt;#include&lt;vector&gt;using namespace std;class solution &#123;public: void ZeroOnePack( vector&lt;vector&lt;int&gt;&gt;&amp; dp, int volume, int weight, int value, int total_v, int total_w ) &#123; for(int cur_v = total_v; cur_v &gt;= volume; --cur_v) &#123; for(int cur_w = total_w; cur_w &gt;= weight; --cur_w) &#123; dp[cur_v][cur_w] = max(dp[cur_v][cur_w], dp[cur_v - volume][cur_w - weight] + value); &#125; &#125; &#125;&#125;;int main()&#123; int n,v,m; cin &gt;&gt; n &gt;&gt; v &gt;&gt; m; vector&lt;vector&lt;int&gt;&gt; dp(v + 1, vector&lt;int&gt;(m + 1, 0)); solution ans; for(int i = 0; i &lt; n; ++i) &#123; int volume, weight, value; cin &gt;&gt; volume &gt;&gt; weight &gt;&gt; value; ans.ZeroOnePack(dp, volume, weight, value, v, m); &#125; cout &lt;&lt; dp[v][m] &lt;&lt;endl; return 0;&#125;
6 分组背包问题AcWing09. 分组背包问题
有 N 组物品和一个容量是 V 的背包。每组物品有若干个，同一组内的物品最多只能选一个。每件物品的体积是 vij，价值是 wij，其中 i 是组号，j 是组内编号。求解将哪些物品装入背包，可使物品总体积不超过背包容量，且总价值最大。输出最大价值。
同样是 0-1 背包问题的变体，只是这次的一个物品变成了一组物品，相当于我们每次拿一个物品的时候，可以用同组内的其他物品替换。因此只要遍历所有组，更新 dp 状态，在更新时遍历组内每一个物品即可。 #include&lt;iostream&gt;#include&lt;vector&gt;using namespace std;class solution &#123;public: void GroupPack( vector&lt;int&gt;&amp; dp, int amount_in_group, vector&lt;int&gt;&amp; volume, vector&lt;int&gt;&amp; value, int total_v ) &#123; for(int cur_v = total_v; cur_v &gt;= 0; --cur_v) &#123; for(int cur_index = 0; cur_index &lt; amount_in_group; ++cur_index) &#123; if(cur_v &gt;= volume[cur_index]) dp[cur_v] = max(dp[cur_v], dp[cur_v - volume[cur_index]] + value[cur_index]); &#125; &#125; &#125;&#125;;int main()&#123; int n, v; cin &gt;&gt; n &gt;&gt; v; vector&lt;int&gt; dp(v + 1, 0); solution ans; for(int i = 0; i &lt; n ; ++i) &#123; int amount; cin &gt;&gt; amount; vector&lt;int&gt; volume(amount); vector&lt;int&gt; value(amount); for(int j = 0; j &lt; amount; ++j) &#123; cin &gt;&gt; volume[j] &gt;&gt; value[j]; &#125; ans.GroupPack(dp, amount, volume, value, v); &#125; cout &lt;&lt; dp[v] &lt;&lt;endl; return 0;&#125;
7 有依赖的背包问题AcWing10. 有依赖的背包问题 背包问题的终极难度，对于机试、面试来说，属实没必要，碰到就算倒霉。 8 背包问题求方案数AcWing11. 背包问题求方案数
有 N 件物品和一个容量是 V 的背包。每件物品只能使用一次。第 i 件物品的体积是 vi，价值是 wi。求解将哪些物品装入背包，可使这些物品的总体积不超过背包容量，且总价值最大。输出最优选法的方案数。注意答案可能很大，请输出答案模 $10^9+7$ 的结果。
求解方案数一般都要用的动态规划状态之间的递加，主要思考如何递加。除了之前的记录最大价值的数组 dp 外，再定义一个记录达到最大价值的方案数的数组 cnt，因为是 0-1 背包问题，只有两种可能的情况：
选择当前物品得到的总价值比之前的价值高，即 dp[curv] &lt; dp[curv-volume] + value，此时最大价值的方案数和之前一样，不会发生改变，相当于用当前物品替换之前的一件物品，即 cnt[curv] = cnt[curv - volume] 选择当前物品得到的总价值和之前的价值一样高，即 dp[curv] == dp[curv-volume] + value，这时达到最大价值的方案数增加了 cnt[curv - volume]，因为原本不超过 curv 的最大总价值方案数是 cnt[curv]，现在选择当前物品也可以达到这个最大价值，因此达到这个最大价值的方案总数就增加了 cnt[curv - volume] 种，即 cnt[curv] += cnt[curv - volume]
初始化 cnt 数组每一项都为 1， 因为每一个体积都不装物品也至少是一种方案，最后编码时记得取模即可： #include&lt;iostream&gt;#include&lt;vector&gt;#include&lt;algorithm&gt;#include &lt;climits&gt;using namespace std;const int mod = 1e9 + 7;;class solution &#123; public: void ZeroOnePack(vector&lt;int&gt;&amp; dp, vector&lt;int&gt;&amp; cnt, int volume, int value, int total) &#123; for(int curv = total; curv &gt;= volume; --curv) &#123; if(dp[curv] &lt; dp[curv - volume] + value) &#123; dp[curv] = dp[curv - volume] + value; cnt[curv] = cnt[curv - volume] % mod; &#125; else if(dp[curv] == dp[curv - volume] + value) &#123; cnt[curv] = (cnt[curv] + cnt[curv - volume]) % mod; &#125; &#125; &#125;&#125;;int main()&#123; int n, v; cin &gt;&gt; n &gt;&gt; v; vector&lt;int&gt; dp(v + 1, 0); vector&lt;int&gt; cnt(v + 1, 1); solution ans; for(int i = 0; i &lt; n; ++i) &#123; int volume, value; cin &gt;&gt; volume &gt;&gt; value; ans.ZeroOnePack(dp, cnt, volume, value, v); &#125; cout &lt;&lt; cnt[v] % mod &lt;&lt;endl; return 0;&#125;
9 背包问题求具体方案AcWing12. 背包问题求具体方案
有 N 件物品和一个容量是 V 的背包。每件物品只能使用一次。第 i 件物品的体积是 vi，价值是 wi。求解将哪些物品装入背包，可使这些物品的总体积不超过背包容量，且总价值最大。输出字典序最小的方案。这里的字典序是指：所选物品的编号所构成的序列。物品的编号范围是 1…N
因为要保证字典序最小，那我们就要保证编号小的物品优先选到，也就是说，假设存在一个包含第 1 个物品的最优解，为了确保字典序最小那么我们必然要选该物品。那么问题就转化成从 2～N 这些物品中找到最优解。于是状态定义应该稍作修改，dp[i][curv] 表示从第 i 个物品到第 n 个物品总容量为 curv 的最大价值，于是状态转移也要相应的修改： dp[i][curv] = max(dp[i+1][curv], dp[i+1][curv - volume[i]] + value[i]);
显然遍历物品的次序也要变为从后向前遍历。那么如何根据结果还原出路径呢？ 我们拿着背包，即总体积 V，从第一个物品开始遍历，如果 dp[i][curv] == dp[i+1][curv - volume[i]] + value[i] ，说明选择了第 i 个物品，于是将 i 加入结果，总体积 V 减去物品 i 的体积，这样就可以还原出字典序最小的一个物品选取方案了。 #include &lt;iostream&gt;#include &lt;vector&gt;using namespace std;int main()&#123; int n, v; cin &gt;&gt; n &gt;&gt; v; vector&lt;int&gt; volume(n + 1); vector&lt;int&gt; value(n + 1); for(int i = 1; i &lt;=n; ++i) &#123; cin &gt;&gt; volume[i] &gt;&gt; value[i]; &#125; vector&lt;vector&lt;int&gt;&gt; dp(n + 2, vector&lt;int&gt;(v + 1, 0)); for(int i = n; i &gt; 0; --i) &#123; for(int curv = 0; curv &lt;= v; ++curv) &#123; dp[i][curv] = dp[i+1][curv]; if(curv &gt;= volume[i]) dp[i][curv] = max(dp[i][curv], dp[i+1][curv - volume[i]] + value[i]); &#125; &#125; int curv = v; for(int i = 1; i &lt;= n; ++i) &#123; if(curv - volume[i] &gt;= 0 &amp;&amp; dp[i][curv] == dp[i+1][curv - volume[i]] + value[i]) &#123; cout &lt;&lt; i &lt;&lt; &quot; &quot;; curv -= volume[i]; &#125; &#125; return 0;&#125;
10 相关题目零钱兑换 给你一个整数数组 coins ，表示不同面额的硬币；以及一个整数 amount ，表示总金额。 计算并返回可以凑成总金额所需的最少的硬币个数 。如果没有任何一种硬币组合能组成总金额，返回 -1 。 你可以认为每种硬币的数量是无限的。
完全背包问题，并且背包必须被装满。唯一的区别是，这次不是求最大价值，而是求最小数量，这相当于每个硬币的体积是 coins[i]，价值都是 1，求把背包装满的最小价值，只要把 max 改为 min 即可： dp[curv] = min(dp[curv], dp[curv-coins[i]] + 1);
代码： class Solution &#123;public: int coinChange(vector&lt;int&gt;&amp; coins, int amount) &#123; // 要求装满，初始化只有dp[0] = 0 vector&lt;int&gt; dp(amount + 1, INT_MAX); dp[0] = 0; for(int&amp; c : coins) &#123; // 完全背包，顺序遍历 for(int curv = c; curv &lt;= amount; ++curv) &#123; if(dp[curv - c] != INT_MAX) //防止越界 dp[curv] = min(dp[curv], dp[curv - c] + 1); &#125; &#125; return dp[amount] == INT_MAX ? -1 : dp[amount]; &#125;&#125;;
一和零 给你一个二进制字符串数组 strs 和两个整数 m 和 n 。 请你找出并返回 strs 的最大子集的长度，该子集中最多有 m 个 0 和 n 个 1 。 如果 x 的所有元素也是 y 的元素，集合 x 是集合 y 的子集 。
经典的二维费用 0-1 背包，两种费用分别是 0 和 1 的最大数量，每个物品的价值都是 1，直接写出优化后的代码： class Solution &#123;public: int calone(string s) &#123; int ans = 0; for(auto&amp; c: s) &#123; if(c == &#x27;1&#x27;) ++ans; &#125; return ans; &#125; int findMaxForm(vector&lt;string&gt;&amp; strs, int m, int n) &#123; vector&lt;vector&lt;int&gt;&gt; dp(m+1, vector&lt;int&gt;(n+1, 0)); for(auto&amp; s : strs) &#123; int ones = calone(s); int zeros = s.size() - ones; for(int i = m; i &gt;= zeros; --i) &#123; for(int j = n; j &gt;= ones; --j) &#123; dp[i][j] = max(dp[i][j], dp[i - zeros][j - ones] + 1); &#125; &#125; &#125; return dp[m][n]; &#125;&#125;;
最后一块石头的重量 II 有一堆石头，用整数数组 stones 表示。其中 stones[i] 表示第 i 块石头的重量。每一回合，从中选出任意两块石头，然后将它们一起粉碎。假设石头的重量分别为 x 和 y，且 x &lt;&#x3D; y。那么粉碎的可能结果如下：
如果 x &#x3D;&#x3D; y，那么两块石头都会被完全粉碎； 如果 x !&#x3D; y，那么重量为 x 的石头将会完全粉碎，而重量为 y 的石头新重量为 y-x。
最后，最多只会剩下一块石头。返回此石头最小的可能重量 。如果没有石头剩下，就返回 0
题目的难点在于如何转化为背包问题，原问题相当于把石头分为两堆，使得两堆石头的差值最小，进一步可以转化为：如果所有石头的总重量是 sum，那么我们要把所有石头装入容量为 sum&#x2F;2 的背包，并使背包内石头的总重量尽可能大，最终剩下的石头的最小重量就是 sum 减去两倍的背包内石头重量。这样转化的具体思路见详解为何能转换为背包问题。 转化后就是一个普通的 0-1 背包问题： class Solution &#123;public: int lastStoneWeightII(vector&lt;int&gt;&amp; stones) &#123; int sum = accumulate(stones.begin(), stones.end(), 0); int total = sum / 2; vector&lt;int&gt; dp(sum + 1, 0); for(int i = 0; i &lt; stones.size(); ++i) &#123; for(int curv = total; curv &gt;= stones[i]; --curv) &#123; dp[curv] = max(dp[curv], dp[curv - stones[i]] + stones[i]); &#125; &#125; return sum - 2 * dp[total]; &#125;&#125;;
分割等和子集 给你一个只包含正整数的非空数组 nums 。请你判断是否可以将这个数组分割成两个子集，使得两个子集的元素和相等。
0-1 背包问题，并且要求把背包装满，这道题只问了是否可以，因此状态转移更简单： class Solution &#123;public: bool canPartition(vector&lt;int&gt;&amp; nums) &#123; int sum = accumulate(nums.begin(), nums.end(), 0); if(sum % 2 != 0) return false; int total = sum / 2; vector&lt;bool&gt; dp(total + 1, false); dp[0] = true; for(auto&amp; x : nums) &#123; for(int curv = total; curv &gt;= x; --curv) &#123; dp[curv] = dp[curv] || dp[curv - x]; &#125; &#125; return dp[total]; &#125;&#125;;
目标和 给你一个整数数组 nums 和一个整数 target 。 向数组中的每个整数前添加 &#39;+&#39; 或 &#39;-&#39; ，然后串联起所有整数，可以构造一个表达式。 返回可以通过上述方法构造的、运算结果等于 target 的不同表达式的数目。
问题可以转化为将数组中的数分为两组，且两组数字的和的差值为 target。假设数组中所有数字总和为 sum，那么问题等价于将数组中的数放入容量为 (sum+target)&#x2F;2 的背包中，且必须装满的方案总数。于是就是一个简单的 0-1 背包求方案总数的问题。只要注意特殊情况的判断即可，如果 (sum+target)&#x2F;2 不是整数则无法分配，如果 target 的绝对值比数组中所有数字的总和都大也无法分配。 class Solution &#123;public: int findTargetSumWays(vector&lt;int&gt;&amp; nums, int target) &#123; int sum = accumulate(nums.begin(), nums.end(), 0); int total = sum + target; if(abs(target) &gt; sum || total % 2 != 0) return 0; total /= 2; vector&lt;int&gt; dp(total + 1, 0); dp[0] = 1; for(auto&amp; x : nums) &#123; for(int curv = total; curv &gt;= x; --curv) &#123; dp[curv] += dp[curv - x]; &#125; &#125; return dp[total]; &#125;&#125;;
零钱兑换 II 给你一个整数数组 coins 表示不同面额的硬币，另给一个整数 amount 表示总金额。 请你计算并返回可以凑成总金额的硬币组合数。如果任何硬币组合都无法凑出总金额，返回 0 。 假设每一种面额的硬币有无限个。
完全背包求方案数，且背包必须装满： class Solution &#123;public: int change(int amount, vector&lt;int&gt;&amp; coins) &#123; vector&lt;int&gt; dp(amount + 1, 0); dp[0] = 1; for(auto&amp; c : coins) &#123; for(int curv = c; curv &lt;= amount; ++curv) &#123; dp[curv] += dp[curv - c]; &#125; &#125; return dp[amount]; &#125;&#125;;
组合总和 Ⅳ 给你一个由不同整数组成的数组 nums ，和一个目标整数 target 。请你从 nums 中找出并返回总和为 target 的元素组合的个数。
由于每个数字可以使用多次，因此这也是一个完全背包求方案数问题。与上面的完全背包求方案数问题稍有不同的是，这里不同顺序代表不同的组合，也就是物品的顺序不同也代表一种不同的方案，所以对于每一个当前容积的背包 curv，把背包装满的方案数等于所有 curv-x 的背包的方案数的总和，x 是每个体积小于 curv 的物品，即： for(auto&amp; x : nums)&#123; if(x &lt;= curv) dp[curv] += dp[curv - x];&#125;
因此我们只需要改变完全背包原本的内外层遍历即可： class Solution &#123;public: int combinationSum4(vector&lt;int&gt;&amp; nums, int target) &#123; vector&lt;unsigned long long&gt; dp(target + 1, 0); dp[0] = 1; for(int curv = 1; curv &lt;= target; ++curv) &#123; for(auto&amp; x : nums) &#123; if(curv &gt;= x) &#123; dp[curv] += dp[curv - x]; &#125; &#125; &#125; return dp[target]; &#125;&#125;;
盈利计划 集团里有 n 名员工，他们可以完成各种各样的工作创造利润。 第 i 种工作会产生 profit[i] 的利润，它要求 group[i] 名成员共同参与。如果成员参与了其中一项工作，就不能参与另一项工作。 工作的任何至少产生 minProfit 利润的子集称盈利计划 。并且工作的成员总数最多为 n 。 有多少种计划可以选择？因为答案很大，所以返回结果模 10^9 + 7 的值。
显然是一个二维费用的 0-1 背包问题，但第二个费用限制是至少产生 minProfit 的价值，与之前稍有不同，但总体思路还是完全一样的，注意对于至少产生 minProfit 的处理，非常巧妙： class Solution &#123;public: int profitableSchemes(int n, int minProfit, vector&lt;int&gt;&amp; group, vector&lt;int&gt;&amp; profit) &#123; vector&lt;vector&lt;int&gt;&gt; dp(n + 1, vector&lt;int&gt;(minProfit + 1)); for (int i = 0; i &lt;= n; i++) &#123; dp[i][0] = 1; &#125; int len = group.size(), MOD = (int)1e9 + 7; for (int i = 1; i &lt;= len; i++) &#123; int members = group[i - 1], earn = profit[i - 1]; for (int j = n; j &gt;= members; j--) &#123; for (int k = minProfit; k &gt;= 0; k--) &#123; dp[j][k] = (dp[j][k] + dp[j - members][max(0, k - earn)]) % MOD; &#125; &#125; &#125; return dp[n][minProfit]; &#125;&#125;;

上一节我们实现了基于蒙特卡洛积分的渲染方程并了解了重要性采样在光线追踪中的作用。这一节我们根据不同的概率密度来直接生成随机方向。经过上一节的推导，我们知道了之前实现的散射函数中的随机方向对应的概率密度是什么，但是没有显式的用概率密度去直接产生随机方向，而是用一个均匀分布（单位球面上随机取点）加上一个法线偏移达到这样的效果。这一节我们来实现直接生成给定概率密度的随机方向。

1 相对于 Z 轴的随机方向我们先实现相对于 Z 轴的随机方向，也就是假设所有着色点的法线都是 Z 轴，之后再将他们转换到真实法线方向上。
在之前的推导中我们知道，球面上的随机方向的概率密度是和俯仰角 $\theta$ 有关的，对于给定的随机方向概率密度 $p(direction)&#x3D;f(\theta)$，方位角和俯仰角的一维概率密度函数为：$$p(\phi) &#x3D; \frac{1}{2\pi},\ p(\theta) &#x3D; 2\pi f(\theta)sin\theta$$对于两个均匀生成的随机数 $r_1$ 、$r_2$，有：$$r_1 &#x3D; \int_0^\phi \frac{1}{2\pi} dt$$可以求得：$$\phi &#x3D; 2\pi r_1$$同理：$$r_2 &#x3D; \int_0^\theta2\pi f(t)sin(t)dt$$之前推到过， lambertian 材质的散射光线的概率密度函数为：$$p(direction)&#x3D;f(\theta)&#x3D;\frac{cos\theta}{\pi}$$代入上式中得：$$r_2 &#x3D; \int_0^\theta2\pi \frac{cost}{\pi}sin(t)dt&#x3D;1-cos^2\theta$$于是可以求得：$$cos\theta &#x3D; \sqrt{1-r_2}$$极坐标和直角坐标的转换公式为：

将解出来的 $\phi$ 和 $\theta$ 带入得到：

于是我们可以实现该函数：
// 生成概率分布为cos(theta)/pi的随机方向inline vec3 random_cosine_direction() &#123;	auto r1 = random_double();	auto r2 = random_double();	// 方向是单位向量，所以z坐标就是cos(theta)	auto z = sqrt(1 - r2);	auto phi = 2 * pi * r1;	auto x = cos(phi) * sqrt(r2);	auto y = sin(phi) * sqrt(r2);	return vec3(x, y, z);&#125;

我们可以利用这个方法生成其他概率分布的随机方向，只要替换推导过程中的 $f(\theta)$ 即可，比如均匀半球分布 $\frac{1}{2\pi}$，均匀球面分布 $\frac{1}{4\pi}$ 等。
2 相对于法线的随机方向接下来我们将上面生成的围绕 z 轴的随机方向转换为围绕着色点法线的随机方向。这实际上就是一个坐标系转化的过程，回顾最简单的线性代数知识，向量 (x, y, z) 表示的是三个方向上的标准正交基的和，标准正交基就是一个坐标系的三个坐标轴，由于向量只有方向，没有位置，因此用这三个数组合任意的标准正交基都可以得到这个标准正交基下的一个向量，所以我们只要求出法线所在的坐标系下的三个标准正交基，再用 (x, y, z) 组合，就可以得到法线坐标系下的随机方向了。
得到法线坐标系的标准正交基很简单，类似于之前相机类中实现的方法，我们可以随机选一个不平行于法线 $\vec n$ 的向量 $\vec a$，二者叉乘得到一个向量 $\vec t$，再用 $\vec t$ 和法线 $\vec n$ 叉乘得到向量 $\vec s$，则 $\vec n$ 、 $\vec s$ 、 $\vec t$  就构成一组标准正交基。
至于随机选一个不平行于法线 $\vec n$ 的向量 $\vec a$，我们可以直接给定  $\vec a$ 就是 (1, 0, 0)，为了保证不和法线平行，当法线接近 (1, 0, 0) 的时候，  $\vec a$ 就改为 (0, 1, 0)。
标准正交基的实现如下：
/** 标准正交基Orthonormal basis类*/#pragma once#ifndef ONB_H#define ONB_H#include &quot;utilities.h&quot;class onb &#123;public:    onb() &#123;&#125;    inline vec3 operator[](int i) const &#123; return axis[i]; &#125;    vec3 u() const &#123; return axis[0]; &#125;    vec3 v() const &#123; return axis[1]; &#125;    vec3 w() const &#123; return axis[2]; &#125;    vec3 local(double a, double b, double c) const &#123;        return a * u() + b * v() + c * w();    &#125;    vec3 local(const vec3&amp; a) const &#123;        return a.x() * u() + a.y() * v() + a.z() * w();    &#125;    void build_from_w(const vec3&amp;);public:    vec3 axis[3];&#125;;void onb::build_from_w(const vec3&amp; n) &#123;    axis[2] = normalize(n);    vec3 a = (fabs(w().x()) &gt; 0.9) ? vec3(0, 1, 0) : vec3(1, 0, 0);    axis[1] = normalize(cross(w(), a));    axis[0] = cross(w(), v());&#125;#endif

现在我们可以修改 lambertian 材质的散射函数：
// lambertian材质类，在单位球面上采样得到散射方向class lambertian : public material &#123;public:    lambertian(const color&amp; a) : albedo(make_shared&lt;solid_color&gt;(a)) &#123;&#125;    lambertian(shared_ptr&lt;texture&gt; a) : albedo(a) &#123;&#125;    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered, double&amp; pdf    ) const override &#123;        // 构建法线空间的标准正交基        onb uvw;        uvw.build_from_w(rec.normal);        // 得到法线空间下概率分布为cos(theta)/pi的随机方向        auto direction = uvw.local(random_cosine_direction());        scattered = ray(rec.p, normalize(direction), r_in.time());        attenuation = albedo-&gt;value(rec.u, rec.v, rec.p);        // 采样光线的概率密度，即cos(theta)/pi        pdf = dot(uvw.w(), scattered.direction()) / pi;        return true;    &#125;    // 散射光线的概率密度    double scattering_pdf(        const ray&amp; r_in, const hit_record&amp; rec, const ray&amp; scattered    ) const &#123;        auto cosine = dot(rec.normal, normalize(scattered.direction()));        return cosine &lt; 0 ? 0 : cosine / pi;    &#125;public:    shared_ptr&lt;texture&gt; albedo;   //反射率&#125;;

得到的效果：

到目前为止我们实际上没有对之前的实现有什么实质性的更改，只是换了一种实现方式，所以得到的效果自然也是差不多的。但是改变实现方式是为了能够实现重要性采样，下一节我们将直接对光源进行采样。

现在我们有了光线在平面随机散射的 pdf 和直接对光源采样的 pdf，接下来我们可以混合这两种 pdf 得到混合概率密度，使用概率密度的好处之一正是 pdf 支持线性组合。

因为我们要混和多种 pdf，最好的方法就是新建一个类去管理他们：
/** 概率密度函数*/#pragma once#ifndef PDF_H#define PDF_H#include &quot;utilities.h&quot;class pdf &#123;public:    virtual ~pdf() &#123;&#125;    virtual double value(const vec3&amp; direction) const = 0;    virtual vec3 generate() const = 0;&#125;;#endif

然后我们将之前的随机散射的 pdf 作为派生类实现：
// 法线周围随机散射的pdfclass cosine_pdf : public pdf &#123;public:    cosine_pdf(const vec3&amp; w) &#123; uvw.build_from_w(w); &#125;    virtual double value(const vec3&amp; direction) const override &#123;        auto cosine = dot(normalize(direction), uvw.w());        return (cosine &lt;= 0) ? 0 : cosine / pi;    &#125;    virtual vec3 generate() const override &#123;        return uvw.local(random_cosine_direction());    &#125;public:    onb uvw;&#125;;

然后实现一个向场景中某个物体的方向采样光线的 pdf 类，这样我们可以不只向光源方向采样，还可以支持场景中的其他物体：
// 向场景中某个物体方向采样的pdfclass hittable_pdf : public pdf &#123;public:    hittable_pdf(shared_ptr&lt;hittable&gt; p, const point3&amp; origin) : ptr(p), o(origin) &#123;&#125;    virtual double value(const vec3&amp; direction) const override &#123;        return ptr-&gt;pdf_value(o, direction);    &#125;    virtual vec3 generate() const override &#123;        return ptr-&gt;random(o);    &#125;public:    point3 o;    shared_ptr&lt;hittable&gt; ptr;&#125;;

这里我们新调用了 hittable 类中的两个方法 value 和 random，因此要在抽象类中声明：
class hittable &#123;public:    // 纯虚函数，在派生类中实现    // 计算光线与物体的交点    virtual bool hit(ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const = 0;    // 计算物体的包围盒    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const = 0;    // 虚函数，不要求所有派生类都实现    // 计算对该物体方向采样的pdf    virtual double pdf_value(const point3&amp; o, const vec3&amp; v) const &#123;        return 0.0;    &#125;    // 生成对该物体方向采样的随机光线    virtual vec3 random(const vec3&amp; o) const &#123;        return vec3(1, 0, 0);    &#125;&#125;;

然后在 xz 平面物体类中实现这两个函数：
// xz平面矩形class xz_rect : public hittable &#123;public:    ...    /**********作为光源平面用到的方法*********/    // 计算随机采样的pdf    virtual double pdf_value(const point3&amp; origin, const vec3&amp; v) const override &#123;        hit_record rec;        if (!this-&gt;hit(ray(origin, v), 0.001, infinity, rec))            return 0;        // 光源平面面积        auto area = (x1 - x0) * (z1 - z0);        // 光源采样点到着色点的距离平方        auto distance_squared = rec.t * rec.t * v.length_squared();        // 光线和光源平面法线cos        auto cosine = fabs(dot(v, rec.normal) / v.length());        // 概率密度        return distance_squared / (cosine * area);    &#125;    // 随机采样一点，作为随机采样的方向    virtual vec3 random(const point3&amp; origin) const override &#123;        auto random_point = point3(random_double(x0, x1), k, random_double(z0, z1));        return random_point - origin;    &#125;    ...&#125;;

然后开始实现混合 pdf 类：
// 混合pdfclass mixture_pdf : public pdf &#123;public:    mixture_pdf(shared_ptr&lt;pdf&gt; p0, shared_ptr&lt;pdf&gt; p1) &#123;        p[0] = p0;        p[1] = p1;    &#125;    virtual double value(const vec3&amp; direction) const override &#123;        return 0.5 * p[0]-&gt;value(direction) + 0.5 * p[1]-&gt;value(direction);    &#125;    virtual vec3 generate() const override &#123;        if (random_double() &lt; 0.5)            return p[0]-&gt;generate();        else            return p[1]-&gt;generate();    &#125;public:    shared_ptr&lt;pdf&gt; p[2];&#125;;

我们这里只是简单的把两个 pdf 平均起来。
然后修改 ray_color 函数：
// 得到光线颜色color ray_color(    ray&amp; r, const color&amp; background, const hittable&amp; world,     shared_ptr&lt;hittable&gt;&amp; lights, int depth, double RR) &#123;    hit_record rec;    // 光线弹射指定次数后开始用RR算法终止递归    if (depth &lt; 0 &amp;&amp; random_double() &gt;= RR) return color(0, 0, 0);        // 如果光线没有打到任何物体，返回背景颜色    // 这里的t的下界设为0.001是为了防止一些光线弹射到物体上得到的t非常接近0，比如可能出现0.000001这样的值    if (!world.hit(r, 0.001, infinity, rec))        return background;            // 根据物体材质得到光线传播方向、反射率及自发光颜色    ray scattered;    color albedo;    color emitted = rec.mat_ptr-&gt;emitted(r, rec, rec.u, rec.v, rec.p);    // 采样光线的概率密度    double pdf_val;    // 对于光源，不会发生散射，返回光源颜色    if (!rec.mat_ptr-&gt;scatter(r, rec, albedo, scattered, pdf_val))        return emitted;    // 混合 pdf    auto p0 = make_shared&lt;hittable_pdf&gt;(lights, rec.p);    auto p1 = make_shared&lt;cosine_pdf&gt;(rec.normal);    mixture_pdf mixed_pdf(p0, p1);    // 使用混合pdf采样光线    scattered = ray(rec.p, mixed_pdf.generate(), r.time());    pdf_val = mixed_pdf.value(scattered.direction());    // 渲染方程    return emitted        + albedo * rec.mat_ptr-&gt;scattering_pdf(r, rec, scattered)        * ray_color(scattered, background, world, lights, depth - 1, RR) / pdf_val / RR;&#125;

然后修改主函数：
/*******创建场景*******/hittable_list world;shared_ptr&lt;hittable&gt; lights;...int sence = 6;switch (sence) &#123;    ...    case 6: // Cornell Box 场景        world = cornell_box();        lights = make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, shared_ptr&lt;material&gt;());        aspect_ratio = 1.0;        image_width = 600;        samples_per_pixel = 10000;        min_bounce = 95;        background = color(0, 0, 0);        lookfrom = point3(278, 278, -800);        lookat = point3(278, 278, 0);        vfov = 40.0;        break;    ...&#125;

得到的效果：

到目前为止我们实际上没有对之前的实现有什么实质性的更改，只是换了一种实现方式，所以得到的效果自然也是差不多的。但是改变实现方式是为了能够实现重要性采样，这一节我们将直接对光源进行采样。

1 对光源采样的 PDF对光源直接采样就是把渲染方程中的对 $\omega$ 的积分改为对光源面积 $A$ 的积分，因此要做一个积分变量的替换，图形学中我们用立体角公式已经推导过 $d\omega$ 和 $dA$ 的关系：$$d\omega &#x3D; \frac{dA·cos\theta’}{||x - p||^2}$$回顾我们之前改写的蒙特卡洛计算渲染方程：$$color_{out} &#x3D; \frac{albedo·s(direction)·color_{in}}{p(direction)}$$我们只需要解出对光源采样的 $p(direction)$ 即可。因为无论对 $\omega$ 采样还是对光源 $A$ 采样，得到的方向的概率应该都是一样的，所以：$$p(direction)·d\omega &#x3D; \frac{1}{A}·dA$$其中 $\frac{1}{A}$ 是对光源面积 $A$ 均匀采样的概率密度，把上面 $d\omega$ 和 $dA$ 的关系式带入即可得到：$$p(direction) &#x3D; \frac{||x-p||^2}{cos\theta’·A}$$也就是对光源采样的概率密度函数。这实际上和我们图形学中推导的，通过积分变量替换改写渲染方程，再用对光源采样的 $pdf&#x3D;\frac{1}{A}$ 进行蒙特卡洛积分计算是完全一样的，只是这里我们把整个积分替换的系数和对光源采样的 pdf 统一写成了对方向 $\omega$ 在光源方向上采样的 pdf。
2 实现有了上面的公式我们可以改写 ray_color 函数：
// 得到光线颜色color ray_color(ray&amp; r, const color&amp; background, const hittable&amp; world, int depth, double RR) &#123;    hit_record rec;    // 光线弹射指定次数后开始用RR算法终止递归    if (depth &lt; 0 &amp;&amp; random_double() &gt;= RR) return color(0, 0, 0);        // 如果光线没有打到任何物体，返回背景颜色    // 这里的t的下界设为0.001是为了防止一些光线弹射到物体上得到的t非常接近0，比如可能出现0.000001这样的值    if (!world.hit(r, 0.001, infinity, rec))        return background;            // 根据物体材质得到光线传播方向、反射率及自发光颜色    ray scattered;    color albedo;    color emitted = rec.mat_ptr-&gt;emitted(rec.u, rec.v, rec.p);    // 采样光线的概率密度    double pdf;    // 对于光源，不会发生散射，返回光源颜色    if (!rec.mat_ptr-&gt;scatter(r, rec, albedo, scattered, pdf))        return emitted;    // 光源平面随机采样一点    auto on_light = point3(random_double(213, 343), 554, random_double(227, 332));    // 光源到着色点p的方向    auto to_light = on_light - rec.p;    // 得到距离用于之后计算pdf    auto distance_squared = to_light.length_squared();    // 方向归一化用于得到cos(theta&#x27;)    to_light = normalize(to_light);    if (dot(to_light, rec.normal) &lt; 0)        return emitted;    auto light_cosine = fabs(to_light.y());    if (light_cosine &lt; 0.000001)        return emitted;    // 光源面积    double light_area = (343 - 213) * (332 - 227);    // 计算直接对光源采样的pdf    pdf = distance_squared / (light_cosine * light_area);    scattered = ray(rec.p, to_light, r.time());    // 渲染方程    return emitted        + albedo * rec.mat_ptr-&gt;scattering_pdf(r, rec, scattered)        * ray_color(scattered, background, world, depth - 1, RR) / pdf / RR;&#125;

然后修改主函数：
...case 6: // Cornell Box 场景world = cornell_box();aspect_ratio = 1.0;image_width = 600;samples_per_pixel = 10;min_bounce = 45;background = color(0, 0, 0);lookfrom = point3(278, 278, -800);lookat = point3(278, 278, 0);vfov = 40.0;...

每个像素只采样 10 根光线，得到的效果：

比之前每个像素采样 100 根光线的噪声还要小很多。
3 单向光源可以看到上面的结果中，噪声主要集中在光源附近，这是因为光源是双面的，光源和天花板之间有一个很小的缝隙，为了解决这个问题我们可以让光源只向下发光，修改光源材质的 emitted 函数：
// 自发光材质，用作光源class diffuse_light : public material &#123;public:    diffuse_light(shared_ptr&lt;texture&gt; a) : emit(a) &#123;&#125;    diffuse_light(color c) : emit(make_shared&lt;solid_color&gt;(c)) &#123;&#125;    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered    ) const override &#123;        return false;    &#125;        // 只有正面发光    virtual color emitted(        const ray&amp; r_in, const hit_record&amp; rec, double u, double v, const point3&amp; p) const override &#123;        if (rec.front_face)            return emit-&gt;value(u, v, p);        else            return color(0, 0, 0);    &#125;public:    shared_ptr&lt;texture&gt; emit;&#125;;

然后实现一个翻转类，使得我们能够翻转光源法线，使它的法线全部指向 -y 方向：
// 翻转光源法线，使其只有正面发光class flip_face : public hittable &#123;public:    flip_face(shared_ptr&lt;hittable&gt; p) : ptr(p) &#123;&#125;    virtual bool hit(        ray&amp; r, double t_min, double t_max, hit_record&amp; rec) const override &#123;        if (!ptr-&gt;hit(r, t_min, t_max, rec))            return false;        rec.front_face = !rec.front_face;        return true;    &#125;    virtual bool bounding_box(double time0, double time1, aabb&amp; output_box) const override &#123;        return ptr-&gt;bounding_box(time0, time1, output_box);    &#125;public:    shared_ptr&lt;hittable&gt; ptr;&#125;;

然后在场景中调用翻转：
// Cornell Box场景hittable_list cornell_box() &#123;    ...    objects.add(make_shared&lt;flip_face&gt;(make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, light)));    ...    return objects;&#125;

同时修改 ray_color 函数：
// 得到光线颜色color ray_color(ray&amp; r, const color&amp; background, const hittable&amp; world, int depth, double RR) &#123;    hit_record rec;    ...    color emitted = rec.mat_ptr-&gt;emitted(r, rec, rec.u, rec.v, rec.p);    ...    // 渲染方程    return emitted        + albedo * rec.mat_ptr-&gt;scattering_pdf(r, rec, scattered)        * ray_color(scattered, background, world, depth - 1, RR) / pdf / RR;&#125;

得到的效果：

到目前为止我们已经实现了一个完整的光线追踪器，但距离真正的光线追踪其还差极为艰难的一步，也就是我们之前在渲染 Cornell Box 的时候提到的，画面噪声很大是因为光源太小，由于我们对散射光线的随机采样是使用最基本的采样方式，所以当光源很小的时候，光线打到光源的概率就很小，也就导致了噪声过大。从这一节开始我们就来解决这个问题。
1 再谈渲染方程首先我们来回顾图形学中学过的渲染方程：
实际上在前面的光线追踪器中我们已经实现了这个渲染方程，但是只实现了一个特殊情况，现在我们来深入分析一下我们是如何实现的。 我们是在 ray_color 函数中实现这个渲染方程的，渲染方程中的入射光线和出射光线的强度在我们的代码中其实就是 ray_color 函数计算的颜色。 ray_color 函数的r_in 参数最开始传入的是我们从像素中投射出的视线，也就是观察方向，我们根据观察方向通过材质的散射函数随机采样出一条对于我们来说真正的入射光线，然后递归的计算这个入射光线的颜色，并返回 albedo * ray_color，其中反射率 albedo 就是出射光线和入射光线的比值，乘以入射光线颜色，自然就得到了出射光线的颜色，也就是我们最终观察到的颜色。整个过程不断递归，每次传入 ray_color 函数的入射光线实际上是上一次计算的入射光线，是本次计算的出射光线。 但是我们发现在 ray_color 函数中并没有体现出 BRDF 的存在。这是由于我们实现的是一个特殊情况。 首先我们对渲染方程中的 BRDF 项做一些变形。我们知道 BRDF 可以表示为：
从公式上看，BRDF 计算的是从每个散射方向 $\omega_r$ 出射的光的能量，和从每个入射方向 $\omega_i$ 上入射的光被着色点吸收的全部能量（在法线方向上投影的能量）的比值。双向反射分布函数的意义在于既描述了光线能量的反射比率，也描述了光线散射方向的分布。 如果一个材质会发生散射，那么就会存在一个散射光线的分布，这个分布是关于方向的，我们称之为散射光线的概率密度函数 $s(direction)$，根据上面的 BRDF 公式，我们可以把 BRDF 改写为：$$BRDF &#x3D; \frac{albedo·s(direction)}{cos\theta}$$其中反射率是出射光线和入射光线的比值，描述光线的能量反射比率，散射光线的概率密度函数描述了光线散射方向的概率分布，这和上面的 BRDF 表达式是一致的。 接下来将这个 BRDF 表达式带入渲染方程中，其中夹角余弦可以写成表面法线和入射光线的点乘。于是我们可以得到：$$color_{out} &#x3D; color_{emit} + \int_{\Omega^+}albedo·s(direction)·color_{in}$$这和我们代码中的： // 得到光线颜色color ray_color(ray&amp; r, const color&amp; background, const hittable&amp; world, int depth, double RR) &#123; ... return emitted + attenuation * ray_color(scattered, background, world, depth - 1, RR);&#125;
是一致的，只是代码中缺少了散射光线的概率密度函数 $s(direction)$。这是为什么呢？ 在我们实现的材质中，以漫反射 lambertian 材质为例，它的计算散射方向的方法是：使用表面法线偏移着色点 p 作为单位球的球心，在该单位球面上均匀采样一点并连接该点和点 p ，形成的向量即为散射方向。这样计算出的散射方向并不是在以点 p 为球心的半球上均匀分布的，所以概率密度并不是的 $\frac{1}{2\pi}$，而是与散射光线和法线的夹角余弦 $cos\theta$ 成正比的，我们可以推导出这个概率密度函数。
为什么概率密度和 $cos\theta$ 成正比？ 可以这样理解，首先概率密度函数的积分是概率，对于 cos 函数，从 0 到 $\pi&#x2F;4$ 的积分和从 $\pi&#x2F;4$ 到 $\pi&#x2F;2$ 的积分显然是不同的，这说明我们取到的散射方向和法线的夹角在 0 到 $\pi&#x2F;4$ 的概率比在 $\pi&#x2F;4$ 到 $\pi&#x2F;2$ 的概率更大。 在我们的代码中， lambertian 材质的散射光线方向是法线方向加上一个单位球面上随机生成的方向，也就是说，最终得到的散射光线方向是两个向量的和。如果单位球面上随机生成的方向和法线的夹角刚好是 45 度，那么他和法线的和向量与法线的夹角一定小于 45 度，如果想要和向量的夹角为 45 度，那么随机生成的向量夹角就要大于 45 度。这说明我们在一个单位球面上均匀的取随机点作为一个向量与法线相加得到散射方向，大部分的点得到的散射方向会在 0 到 $\pi&#x2F;4$ 范围内，只有一小部分才会使最终的散射方向在 $\pi&#x2F;4$ 到 $\pi&#x2F;2$ 范围内，因此也就对应了不均匀的概率。
接下来我们推导这个概率密度函数是什么。首先我们知道，方向表示为单位立体角 $d\omega$，单位立体角是球面上的一块面积 $dA$ 和半径平方的比值，在图形学中我们推导过：$$d\omega &#x3D; \frac{dA}{r^2} &#x3D; \frac{r^2sin\theta \ d\theta \ d\phi}{r^2} &#x3D; sin\theta \ d\theta \ d\phi$$于是对于半球面上的均匀采样，有：$$\int_0^{2\pi}\int_0^{\pi&#x2F;2}pdf·sin\theta \ d\theta \ d\phi &#x3D; 1$$而单位半球面的积分就是半球的表面积 $2\pi$，于是半球面上的均匀分布就是：$$pdf(x) &#x3D; \frac{1}{2\pi}$$同理，我们现在要求的概率密度函数和 $cos\theta$ 成正比，于是可以表示为：$$pdf(x) &#x3D; C·cos\theta$$带入上面的积分有：$$\int_0^{2\pi}\int_0^{\pi&#x2F;2}C·cos\theta·sin\theta \ d\theta \ d\phi &#x3D; 1$$半球面上对 $cos\theta$ 积分结果为 $\pi$，因此：$$C·\pi &#x3D; 1$$于是可以得到我们实现的 lambertian 材质的散射光线的概率密度函数为：$$s(direction) &#x3D; \frac{cos\theta}{\pi}$$接下来继续回顾图形学中的知识，我们求解渲染方程使用的是蒙特卡洛积分的方法，也就是按照某个概率分布 $p(x)$ 对被积变量进行随机采样，于是原积分可以通过如下方式计算：$$F_N &#x3D; \frac{1}{N}\sum_{i&#x3D;1}^{N}\frac{f(X_i)}{p(X_i)},\ X_i \sim p(x)$$那么现在的渲染方程就可以通过蒙特卡洛积分计算：$$color_{out} &#x3D; color_{emit} + \sum \frac{albedo·s(direction)·color_{in}}{p(direction)}$$如果我们选择对光线随机采样的概率密度和散射光线本身的概率密度分布一致，即：$$p(direction) &#x3D; s(direction) &#x3D; \frac{cos\theta}{\pi}$$显然渲染方程变为：$$color_{out} &#x3D; color_{emit} + \sum albedo·color_{in}$$也就是我们现在代码中的： // 得到光线颜色color ray_color(ray&amp; r, const color&amp; background, const hittable&amp; world, int depth, double RR) &#123; ... return emitted + attenuation * ray_color(scattered, background, world, depth - 1, RR) / RR;&#125;
也就是说，在我们之前的实现中，隐式的把对光线随机采样的概率密度设置为了永远和散射光线的概率密度一样，无论是漫反射材质还是金属材质又或者是其他材质，我们不关注他们散射光线的概率密度什么，反正我们采样的概率密度和它们一致，所以渲染方程永远可以表示为上面那样。 那么这样做为什么可以得到正确的结果呢？之前我们在图形学中也提到过，随机采样的概率分布越接近该变量原本的概率分布，蒙特卡洛积分收敛的也就越好，这会在之后展开讨论。 现在为了实现更一般的渲染方程，我们需要改写现在的代码。 首先修改材质抽象类，为散射光线的计算加入采样光线的 pdf： class material &#123;public: virtual bool scatter( ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered ) const &#123; return false; &#125;; // 带有采样pdf的散射函数 virtual bool scatter( ray&amp; r_in, const hit_record&amp; rec, color&amp; albedo, ray&amp; scattered, double&amp; pdf ) const &#123; return false; &#125;; // 计算材质散射光线的pdf virtual double scattering_pdf( const ray&amp; r_in, const hit_record&amp; rec, const ray&amp; scattered ) const &#123; return 0; &#125; virtual color emitted(double u, double v, const point3&amp; p) const &#123; return color(0, 0, 0); &#125;&#125;;
然后修改 lambertian 材质的散射函数： // lambertian材质类，在单位球面上采样得到散射方向class lambertian : public material &#123;public: lambertian(const color&amp; a) : albedo(make_shared&lt;solid_color&gt;(a)) &#123;&#125; lambertian(shared_ptr&lt;texture&gt; a) : albedo(a) &#123;&#125; virtual bool scatter( ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered, double&amp; pdf ) const override &#123; // 这里省略了rec.p + rec.normal + random_unit_vector() - rec.p中的rec.p; auto scatter_direction = rec.normal + random_unit_vector(); // 如果散射方向为0，则取法线方向作为散射方向 if (scatter_direction.near_zero()) &#123; scatter_direction = rec.normal; &#125; // 散射光线时刻和入射光线一样 scattered = ray(rec.p, normalize(scatter_direction), r_in.time()); attenuation = albedo-&gt;value(rec.u, rec.v, rec.p); // 采样光线的概率密度 pdf = dot(rec.normal, scattered.direction()) / pi; return true; &#125; // 散射光线的概率密度 double scattering_pdf( const ray&amp; r_in, const hit_record&amp; rec, const ray&amp; scattered ) const &#123; auto cosine = dot(rec.normal, normalize(scattered.direction())); return cosine &lt; 0 ? 0 : cosine / pi; &#125;public: shared_ptr&lt;texture&gt; albedo; //反射率&#125;;
最后修改 ray_color 函数： // 得到光线颜色color ray_color(ray&amp; r, const color&amp; background, const hittable&amp; world, int depth, double RR) &#123; hit_record rec; // 光线弹射指定次数后开始用RR算法终止递归 if (depth &lt; 0 &amp;&amp; random_double() &gt;= RR) return color(0, 0, 0); // 如果光线没有打到任何物体，返回背景颜色 // 这里的t的下界设为0.001是为了防止一些光线弹射到物体上得到的t非常接近0，比如可能出现0.000001这样的值 if (!world.hit(r, 0.001, infinity, rec)) return background; // 根据物体材质得到光线传播方向、反射率及自发光颜色 ray scattered; color albedo; color emitted = rec.mat_ptr-&gt;emitted(rec.u, rec.v, rec.p); // 采样光线的概率密度 double pdf; // 对于光源，不会发生散射，返回光源颜色 if (!rec.mat_ptr-&gt;scatter(r, rec, albedo, scattered, pdf)) return emitted; // 渲染方程 return emitted + albedo * rec.mat_ptr-&gt;scattering_pdf(r, rec, scattered) * ray_color(scattered, background, world, depth - 1, RR) / pdf / RR;&#125;
可以得到和之前一样的效果：
如果我们把采样光线改为在半球上均匀采样，此时采样光线的 pdf 就是 $\frac{1}{2\pi}$ ，于是我们只要修改： virtual bool scatter( ray&amp; r_in, const hit_record&amp; rec, color&amp; attenuation, ray&amp; scattered, double&amp; pdf ) const override &#123; //auto scatter_direction = rec.normal + random_unit_vector(); // 改为半球均匀采样 auto scatter_direction = random_in_hemisphere(rec.normal); if (scatter_direction.near_zero()) &#123; scatter_direction = rec.normal; &#125; scattered = ray(rec.p, normalize(scatter_direction), r_in.time()); attenuation = albedo-&gt;value(rec.u, rec.v, rec.p); // 采样光线的概率密度 //pdf = dot(rec.normal, scattered.direction()) / pi; pdf = 0.5 / pi; return true; &#125;
得到的效果：
使用什么样的采样 pdf 完全取决于我们的选择，但是使用什么样的 pdf 效果好刚才已经给出了答案，随机采样的 pdf 形状越接近函数原本的形状，蒙特卡洛估计收敛的效果就会越好。下面我们来推导这是为什么。 2 重要性采样要了解重要性采样的原理就要先深入理解蒙特卡洛积分，首先我们来分析为什么蒙特卡洛积分可以得到原积分的估计值。根据蒙特卡洛积分的计算方法：$$F_N &#x3D; \frac{1}{N}\sum_{i&#x3D;1}^{N}\frac{f(X_i)}{p(X_i)},\ X_i \sim p(x)$$首先我们把积分变量看做了一个随机变量 X，然后构造了一个随机采样的分布 p(X)，利用这个分布我们可以构造一个新的随机变量：$$Y &#x3D; \frac{f(X)}{p(X)}$$概率论告诉我们的如果一个随机变量 X 的期望是 E(X)，那么随机变量 f(X) 的期望就是 E(f(X))，于是蒙特卡洛积分 $F_N$ 的期望就是：$$E[F_N] &#x3D; E[\frac{1}{N}\sum_{i&#x3D;1}^N\frac{f(X_i)}{p(X_i)}]$$也就是：$$E[F_N] &#x3D; \frac{1}{N} \sum_{i&#x3D;1}^NE[Y_i]$$连续型随机变量的期望就是对概率密度函数的积分，所以：$$E[Y_i] &#x3D; \int_a^b \frac{f(x)}{p(x)}p(x)dx &#x3D; \int_a^b{f(x)}dx$$带入上式得：$$E[F_N] &#x3D; \frac{1}{N} \sum_{i&#x3D;1}^N\int_a^b{f(x)}dx &#x3D; \int_a^b{f(x)}dx$$以上证明过程表明，若我们根据公式来构造一个新的随机变量 $F_N$ ，则 $F_N$ 的期望就是原积分的结果，随着 N 的增加，$F_N$ 就越逼近理论上的积分值，即蒙特卡洛积分是原积分的一个无偏估计。 接下来我们看蒙特卡洛估计的方差：$$\sigma^2[F_N] &#x3D; \sigma^2[\frac{1}{N}\sum_{i&#x3D;1}^N\frac{f(X_i)}{p(X_i)}]$$即：$$\sigma^2[F_N] &#x3D; \frac{1}{N^2}\sum_{i&#x3D;1}^N\sigma^2[Y_i]$$于是可以得到：$$\sigma^2[F_N] &#x3D; \frac{1}{N^2}N\sigma^2[Y]&#x3D;\frac{1}{N}\sigma^2[Y]$$所以蒙特卡洛积分的标准差就是：$$\sigma[F_N] &#x3D; \frac{1}{\sqrt{n}}\sigma[Y]$$这个结果告诉我们，估计值的不稳定来源于随机变量 Y 的取值不稳定。换句话说，如果随机变量：$$Y_i &#x3D; \frac{f(X_i)}{p(X_i)}$$因不同 $X_i$ 的取值变化地越剧烈，就会造成 Y 的方差较大，也就导致估计值的收敛速度越慢。这证明了，如果 p(x) 的形状越接近 f(x)，则有益于最终结果的收敛。 上述思想就是“重要性采样”的方法，即对积分值有重要贡献，即 f(x) 较大的被积函数区间，我们以较大概率生成处于这个区间附近的随机变量，就可以快速逼近理论值。 应用到光线追踪中，光源方向的光线对最终渲染方程积分结果的贡献更大，如果使用我们现在的均匀随机采样，由于光源很小，得到光源方向的光线的概率就很小，自然对最终结果的估计就会产生较大的偏差，体现在画面上就是有很大的噪声。于是为了消除噪声，我们应该使用重要性采样，生成更多光源方向的光线。 当然，如果我们采样更多的随机光线到光源，会导致积分结果过大，也就是画面过亮，而产生不正确的效果，因此我们需要降低这些样本的权重，在蒙特卡洛积分的公式中，除以概率密度函数就是为了解决这个问题，概率密度大的样本取到的相对概率大，除以这个概率可以削弱该样本的权重，以抵消这种不均衡。

到此为止关于漫反射材质的全部内容就都完成了，现在只剩最后一步——用我们新的实现方式修改金属和电介质材质，使得新的光线追踪器支持镜面反射和折射。

1 统一管理散射光线对于镜面反射和折射，如果用新的渲染方程会出现 pdf 值为 0 的情况，因此我们使用之前隐式的渲染方程，也就是采样 pdf 和光线散射 pdf 一致。为此我们首先需要新增一个结构体来统一管理散射光线，然后根据散射光线的类型选择对应的渲染方程：
// 统一管理散射光线struct scatter_record &#123;    ray specular_ray;           // 散射光线    bool is_specular;           // 是否是镜面反射，金属或者电介质为true    color attenuation;          // 反射率    shared_ptr&lt;pdf&gt; pdf_ptr;    // 散射光线pdf，如果是金属或者电介质就是空指针&#125;;

然后修改材质抽象类：
class material &#123;public:    // 散射函数    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, scatter_record&amp; srec    ) const &#123;        return false;    &#125;;    // 计算材质散射光线的pdf    virtual double scattering_pdf(        const ray&amp; r_in, const hit_record&amp; rec, const ray&amp; scattered    ) const &#123;        return 0;    &#125;    // 自发光，可选    virtual color emitted(        const ray&amp; r_in, const hit_record&amp; rec, double u, double v, const point3&amp; p) const &#123;        return color(0, 0, 0);    &#125;&#125;;

接下来用新的结构体和方法改写之前实现的 Lambertian 材质：
// lambertian材质类，在单位球面上采样得到散射方向class lambertian : public material &#123;public:    lambertian(const color&amp; a) : albedo(make_shared&lt;solid_color&gt;(a)) &#123;&#125;    lambertian(shared_ptr&lt;texture&gt; a) : albedo(a) &#123;&#125;    // 采样散射光线    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, scatter_record&amp; srec    ) const override &#123;        srec.is_specular = false;        srec.attenuation = albedo-&gt;value(rec.u, rec.v, rec.p);        // 采样光线的概率密度        srec.pdf_ptr = make_shared&lt;cosine_pdf&gt;(rec.normal);        return true;    &#125;        // 材质本身散射光线的概率密度    double scattering_pdf(        const ray&amp; r_in, const hit_record&amp; rec, const ray&amp; scattered    ) const &#123;        auto cosine = dot(rec.normal, normalize(scattered.direction()));        return cosine &lt; 0 ? 0 : cosine / pi;    &#125;public:    shared_ptr&lt;texture&gt; albedo;   //反射率&#125;;

接下来修改主函数：
/*******创建场景*******/hittable_list world;auto lights = make_shared&lt;hittable_list&gt;();lights-&gt;add(make_shared&lt;xz_rect&gt;(213, 343, 227, 332, 554, shared_ptr&lt;material&gt;()));// 对透光的玻璃也进行额外采样lights-&gt;add(make_shared&lt;sphere&gt;(        point3(190, 90, 190), point3(190, 90, 190), 0, 1, 90, shared_ptr&lt;material&gt;()));...

2 金属和电介质有了统一管理散射光线的方法，我们可以修改之前的金属材质：
// 金属材质类class metal : public material &#123;public:    metal(const color&amp; a, const double f) : albedo(a), fuzz(f &lt; 1 ? f : 1) &#123;&#125;    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, scatter_record&amp; srec    ) const override &#123;        vec3 reflected = reflect(normalize(r_in.direction()), rec.normal);        srec.specular_ray = ray(rec.p, reflected + fuzz * random_in_unit_sphere());        srec.attenuation = albedo;        srec.is_specular = true;        srec.pdf_ptr = nullptr;        return true;    &#125;public:    color albedo;   //反射率    double fuzz;    //Glossy反射扰动系数&#125;;

同时修改电介质材质类：
// 电介质材质类class dielectric : public material &#123;public:    dielectric(double index_of_refraction) : ir(index_of_refraction) &#123;&#125;    virtual bool scatter(        ray&amp; r_in, const hit_record&amp; rec, scatter_record&amp; srec    ) const override &#123;        srec.is_specular = true;        srec.pdf_ptr = nullptr;        // 电介质不吸收任何光，全部被折射或者反射，所以衰减系数恒为1        srec.attenuation = color(1.0, 1.0, 1.0);        // 如果是正面，则是从空气进入介质，反之从介质折射出去        double refraction_ratio = rec.front_face ? (1.0 / ir) : ir;        // 入射光线记得单位化，折射函数传入的参数都是单位向量        vec3 unit_direction = normalize(r_in.direction());        // 计算是否发生折射        double cos_theta = fmin(dot(-unit_direction, rec.normal), 1.0);        double sin_theta = sqrt(1.0 - cos_theta * cos_theta);        bool cannot_refract = refraction_ratio * sin_theta &gt; 1.0;        vec3 direction;        if (cannot_refract || reflectance(cos_theta, refraction_ratio) &gt; random_double())            direction = reflect(unit_direction, rec.normal);        else            direction = refract(unit_direction, rec.normal, refraction_ratio);                srec.specular_ray = ray(rec.p, direction, r_in.time());        return true;    &#125;public:    double ir;  //介质折射率private:    static double reflectance(double cosine, double ref_idx) &#123;        // 使用Schlick&#x27;s近似计算菲涅尔项        auto r0 = (1 - ref_idx) / (1 + ref_idx);        r0 = r0 * r0;        return r0 + (1 - r0) * pow((1 - cosine), 5);    &#125;&#125;;

然后修改 ray_color 函数：
#pragma once#include &quot;hittable.h&quot;#include &quot;pdf.h&quot;// 得到光线颜色color ray_color(    ray&amp; r,     const color&amp; background,     const hittable&amp; world,     shared_ptr&lt;hittable&gt;&amp; lights,     int depth,     double RR) &#123;    hit_record rec;    // 光线弹射指定次数后开始用RR算法终止递归    if (depth &lt; 0 &amp;&amp; random_double() &gt;= RR) return color(0, 0, 0);        // 如果光线没有打到任何物体，返回背景颜色    // 这里的t的下界设为0.001是为了防止一些光线弹射到物体上得到的t非常接近0，比如可能出现0.000001这样的值    if (!world.hit(r, 0.001, infinity, rec))        return background;            // 根据物体材质得到光线传播方向、反射率及自发光颜色    scatter_record srec;    color emitted = rec.mat_ptr-&gt;emitted(r, rec, rec.u, rec.v, rec.p);    // 对于光源，不会发生散射，返回光源颜色    if (!rec.mat_ptr-&gt;scatter(r, rec, srec))        return emitted;    // 如果是高光反射或折射，采用之前的渲染方程，隐式的使采样pdf和散射pdf保持一致    if (srec.is_specular) &#123;        return srec.attenuation            * ray_color(srec.specular_ray, background, world, lights, depth - 1, RR) / RR;    &#125;    // 对光源采样的pdf    auto light_ptr = make_shared&lt;hittable_pdf&gt;(lights, rec.p);    // 混合pdf    mixture_pdf p(light_ptr, srec.pdf_ptr);    // 采样光线    ray scattered = ray(rec.p, p.generate(), r.time());    // 采样光线的pdf值    auto pdf_val = p.value(scattered.direction());    // 渲染方程    return emitted        + srec.attenuation * rec.mat_ptr-&gt;scattering_pdf(r, rec, scattered)        * ray_color(scattered, background, world, lights, depth - 1, RR) / pdf_val / RR;&#125;

然后修改场景：
// Cornell Box场景hittable_list cornell_box() &#123;    hittable_list objects;    ...    shared_ptr&lt;material&gt; aluminum = make_shared&lt;metal&gt;(color(0.8, 0.85, 0.88), 0.0);    shared_ptr&lt;hittable&gt; box1 = make_shared&lt;box&gt;(point3(0, 0, 0), point3(165, 330, 165), aluminum);    box1 = make_shared&lt;rotate_y&gt;(box1, 15);    box1 = make_shared&lt;translate&gt;(box1, vec3(265, 0, 295));    objects.add(box1);    auto glass = make_shared&lt;dielectric&gt;(1.5);    objects.add(make_shared&lt;sphere&gt;(        point3(190, 90, 190), point3(190, 90, 190), 0, 1, 90, glass));    return objects;&#125;

3 对球体和物体列表采样上面的主函数中我们对透明玻璃球也进行了额外采样，因此类似于之前光源所在的 zx 平面，现在我们需要实现球体和物体列表的 pdf_value 函数和 random 函数，对球体采样的具体推导过程可以查看《RayTracingTheRestOfYourLife》第 12.3 节，这里直接给出代码，首先修改球体类：
class sphere : public hittable &#123;public:    ...    double pdf_value(const point3&amp; o, const vec3&amp; v) const &#123;        hit_record rec;        if (!this-&gt;hit(ray(o, v), 0.001, infinity, rec))            return 0;        auto cos_theta_max = sqrt(1 - radius * radius / (center0 - o).length_squared());        auto solid_angle = 2 * pi * (1 - cos_theta_max);        return  1 / solid_angle;    &#125;    vec3 random(const point3&amp; o) const &#123;        vec3 direction = center0 - o;        auto distance_squared = direction.length_squared();        onb uvw;        uvw.build_from_w(direction);        return uvw.local(random_to_sphere(radius, distance_squared));    &#125;        ...&#125;;

工具函数新增：
// 在球体外对球体随机采样inline vec3 random_to_sphere(double radius, double distance_squared) &#123;    auto r1 = random_double();    auto r2 = random_double();    auto z = 1 + r2 * (sqrt(1 - radius * radius / distance_squared) - 1);    auto phi = 2 * pi * r1;    auto x = cos(phi) * sqrt(1 - z * z);    auto y = sin(phi) * sqrt(1 - z * z);    return vec3(x, y, z);&#125;

然后是物体列表 hittable_list ：
class hittable_list : public hittable &#123;public:    ...    double hittable_list::pdf_value(const point3&amp; o, const vec3&amp; v) const &#123;        auto weight = 1.0 / objects.size();        auto sum = 0.0;        for (const auto&amp; object : objects)            sum += weight * object-&gt;pdf_value(o, v);        return sum;    &#125;    vec3 hittable_list::random(const vec3&amp; o) const &#123;        auto int_size = static_cast&lt;int&gt;(objects.size());        return objects[random_int(0, int_size - 1)]-&gt;random(o);    &#125;    ...&#125;;

4 最后一步最后一步我们来处理掉之前图片中有时会出现的黑点或者异常像素，这是因为一些不好的采样计算出了很大的或者 NaN 的颜色，使得整个像素受损，因此我们可以在写颜色的时候处理这种情况：
// 向数组中写入一个颜色，用到了指针的引用传递// 输入的color是[0,1]范围的inline void write_color(unsigned char*&amp; p, color pixel_color, int samples_per_pixel)&#123;    auto r = pixel_color.x();    auto g = pixel_color.y();    auto b = pixel_color.z();    // 处理异常像素值    if (r != r) r = 0.0;    if (g != g) g = 0.0;    if (b != b) b = 0.0;    auto scale = 1.0 / samples_per_pixel;    // 伽马校正，假设显示gamma=2.0    r = sqrt(scale * r);    g = sqrt(scale * g);    b = sqrt(scale * b);    *p++ = (unsigned char)(256 * clamp(r, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(g, 0.0, 0.999));    *p++ = (unsigned char)(256 * clamp(b, 0.0, 0.999));&#125;

最后看一下效果：

完结撒花！

《深度探索C++对象模型》第二章重点梳理。主要内容包括：
默认构造函数的构建操作 拷贝构造函数的构建操作 使用列表进行初始化的背后工作
1 默认构造函数有一种常见的说法是，如果定义一个类的时候没有显式的为其声明构造函数，那么编译器将会自动生成默认的构造函数，但一般来说编译器生成的默认构造函数对于程序而言是没有任何用处的，编译器生成默认构造函数完全是为了满足编译器的需要，而不是我们所编写的程序的需要。但在一些情况下，编译器生成的默认构造函数是有用的，下面将讨论这些情况。 1.1 带有默认构造函数的类对象成员如果一个类没有显式声明构造函数，但包含一个声明了构造函数的类对象成员，那么这个类的默认构造函数就是有用的。编译器会为这个类生成一个默认构造函数，但这个生成操作只在构造函数真正需要被调用的时候才进行。 例如，有下面的代码： class Foo &#123; public: Foo(), Foo(int)... &#125;;class Bar &#123; public: Foo foo; char *str; &#125;;void foo_bar()&#123; Bar bar; if(str) &#123; ... &#125; ...&#125;
类 Bar 中包含一个对象成员 foo，该对象有显式声明的构造函数，因此编译器会为 Bar 生成默认构造函数，这个默认构造函数会调用 Foo 的构造函数来初始化对象成员 foo，但不会初始化 Bar 的 str 成员，因为初始化对象成员是编译器需要的，编译器必须为每个对象分配内存，而初始化一个字符指针对于编译器来说不需要。所以编译器生成的默认构造函数看起来就是这样： inline Bar::Bar()&#123; foo.Foo::Foo();&#125;
编译器自动生成的构造函数、析构函数、拷贝构造、assignment 等都被指定为内联函数，如果函数太复杂不适合做成内联，就会生成一个显式的非内联静态（explicit non-inline static）函数实体。 为了让程序正确运行，我们需要把 str 成员也初始化，但这不能指望编译器来生成，需要手动实现： Bar::Bar() &#123;str = 0;&#125;
这时，虽然显式声明了构造函数，但这个构造函数没有初始化对象成员 foo，所以也还是没有满足编译器的需求，因此编译器还是会自动生成构造函数，但这时编译器不会单独生成一个函数了，而是会在用户定义的构造函数上进行扩展，加入编译器需要的代码： Bar::Bar() &#123; foo.Foo::Foo(); // 编译器加入的代码 str = 0; // 用户定义的代码&#125;
如果一个类中有多个对象成员，这些成员都有显式定义的构造函数，那么编译器自动生成构造函数时会按照对象成员的声明顺序调用他们的构造函数，比如： class Dopey &#123; public: Dopey(); ...);class Sneezy &#123; public: Sneezy(int); Sneezy(); ...); class Bashful &#123; public: Bashful(); ...) ; class Snow_White &#123; public: Dopey dopey; Sneezy sneezy; Bashful bashful; // 显式定义的构造函数 Snow_White() : sneezy(1024) &#123; mumble = 2048; &#125;private: int mumble; &#125;;
这时编译器自动扩展后的构造函数如下： Snow_White::Snow_White() : sneezy(1024)&#123; // 编译器加入的代码 dopey.Dopey::dopey(); sneezy.Sneezy::sneezy(1024); bashful.Bashful::bashful(); // 用户定义的代码 mumble = 2048;&#125;
1.2 带有默认构造函数的基类如果一个没有显式定义构造函数的类派生于一个有显式构造函数的基类，那么这个派生类的默认构造函数是有用的。派生类自动生成的默认构造函数将调用上一层基类的默认构造函数（根据声明次序）。 如果程序员为这个派生类声明了多个构造函数，但就是没有默认构造函数，那么编译器会扩展程序员声明的所有构造函数，将调用所有必要的默认构造函数的代码加入这些构造函数中，这些必要的默认构造函数就包括其父类的默认构造函数，以及其对象成员的默认构造函数。 1.3 带有虚函数的类对于以下两种情况，默认构造函数也是有用的：
带有虚函数的类 该类派生自一个继承链，这个继承链中有一个或多个带有虚函数的基类
这两种情况下编译器将会在默认构造函数中加入对虚函数表的操作，因此是有用的。 例如有下图的继承关系：
执行下面的代码： class Widget &#123;public: virtual void flip() = 0; ...&#125;;void flip(const Widget&amp; widget)&#123; widget.flip();&#125;void foo()&#123; Bell b; Whistle w; flip(b); flip(w);&#125;
在编译期间，编译器会进行如下两个扩展操作：
编译器会产生一张虚函数表 vtbl，其中存放类的虚函数地址 每一个类对象中，编译器会生成一个额外的指针成员 vptr，指向类的虚函数表
此外，widget.flip() 的虚拟引发（virtual invocation）操作会被重新改写，以使用 widget 的 vptr 和 vtbl 中的 flip() 条目： (*widget.vptr[1]) (&amp;widget)
其中 1 表示 flip() 在虚函数表中的索引，&amp;widget 表示要交给被调用的某个 flip() 函数实体的 this 指针。 为了让这个机制发挥功效，编译器必须为每一个 Widget （或其派生类）的对象的 vptr 设定初值，放置适当的 virtual table 地址。对于 class 所定义的每一个构造函数，编译器会安插一些代码来做这样的事情。对于那些未声明任何构造函数的类，编译器会为它们生成一个默认构造函数，以便正确地初始化每一个 class object 的 vptr。 1.4 继承于虚拟基类的类虚拟继承的实现方法在不同的编译器之间有极大的差异，但是每一种实现方法都必须保证虚拟基类（virtual base class）子对象（subobject）在其每一个派生类对象中的位置能够在执行期准备妥当。例如有如下继承关系：
有下面的代码： class X &#123;public: int i;&#125;;class A : public virtual X &#123;public: int j;&#125;;class B : public virtual X &#123;public: double d;&#125;;class C : public A, public B &#123;public: int k;&#125;;// 无法在编译期决定 pa-&gt;X::i 的位置void foo(const A* pa)&#123; pa-&gt;i = 1024;&#125;main()&#123; foo(new A); foo(new C); ...&#125;
在编译期间编译器无法确定函数 foo 中 pa-&gt;X::i 的实际位置，因为 pa 的类型可以改变，其中包含的基类子对象的位置并不确定，因此编译器必须改变对虚拟基类成员进行存取操作的代码（例如上面的 pa-&gt;i = 1024 就是在对虚拟基类的成员进行存取操作），使得 pa-&gt;X::i 可以延迟到执行期才确定下来。 编译器通过在派生类对象中添加一个指向虚拟基类的指针来完成上述操作，任何对虚拟基类成员的存取操作都可以通过该指针完成，比如上面的代码会被编译器改写为： void foo(const A* pa)&#123; pa-&gt;__vbcX-&gt;i = 1024;&#125;
其中 __vbcX 是编译器为派生类对象生成的指向 virtual base class X 的指针。 __vbcX 是在对象构造期间产生的，对于类中声明的每一个构造函数，编译器都会加入构建 __vbcX 的代码，如果类中没有声明任何构造函数，那么编译器会生成一个默认构造函数来完成这件事。 1.5 总结以上四种情况，会导致 C++ 编译器必须为没有显式声明构造函数的类生成（合成）一个默认构造函数。C++ 将这些默认构造函数称为 implicit nontrivial default constructors。 被生成（合成）出来的 constructor 只能满足编译器（而非程序）的需要，这样的构造函数之所以被称为 nontrivial ，是因为他们完成了一些对编译器来说必要的工作：
调用对象成员的构造函数 调用基类的构造函数 为对象初始化指向虚函数表的指针 为对象初始化其 virtual base class 的指针
至于不存在这四种情况而又没有显式声明构造函数的类，我们说它拥有的是 implicit trivial default constructors，这样的构造函数没有任何用处，实际上也不会被生成出来。 在生成（合成）的构造函数中，只有基类子对象和对象成员会被初始化，其他所有的非静态成员变量，如 int，*int，int[] 等，都不会被初始化，因为这些初始化或许对程序而言有用，但对编译器来说并不必要。 因此，以下两种常见说法是完全错误的：
任何没有显式声明默认构造函数的类都会由编译器产生一个默认构造函数 编译器生成的默认构造函数会将类中所有成员明确初始化
2 拷贝构造函数有三种情况，会以一个对象的内容作为另一个对象的初值：
使用一个对象对另一个对象进行初始化：
class X &#123;...&#125;;X x;// 明确以一个对象对另一个对象初始化X xx = x;
对象作为函数参数传递：
extern void foo (X x);void bar()&#123; X xx; // 以对象作为函数参数 foo(xx);&#125;
对象作为函数返回值：
X foo()&#123; X xx; ... return xx;&#125;
如果程序员在类中明确定义了一个拷贝构造函数（copy constructor），即以本类型作为参数的构造函数，比如： X::X(const X&amp; X);Y::Y(const Y&amp; y, int = 0);
那么在上述情况下，拷贝构造函数将被调用。但如果类中没有用户显式定义的拷贝构造函数，编译器将如何完成拷贝操作呢？ 2.1 Default Memberwise（逐成员的） Initialization当用户没有显式定义拷贝构造函数时，编译器内部是以 Default Memberwise Initialization（默认逐成员初始化） 方法完成该操作的。也就是把每一个内建的或派生的成员变量（指针或其他变量）的值，从某个对象拷贝到另一个对象身上，但它并不会拷贝其中的类对象成员（member class object），而是以递归的方式进行 Memberwise Initialization。 例如，有一个字符串类： class String &#123;public: //...没有定义拷贝构造函数private: char* str; int len;&#125;;
当我们把一个字符串对象作为另一个对象的初值时： String noun(&quot;Book&quot;);String verb = noun;
Default Memberwise Initialization 将会像下面这样： verb.str = noun.str;verb.len = noun.len;
如果一个 String 对象作为另一个类的成员： class word &#123;public: //...没有定义拷贝构造函数private: int _occurs; String _word;&#125;
那么 word 对象的 Default Memberwise Initialization 将会直接拷贝成员 _occurs，然后在 _word 身上递归的进行 Memberwise Initialization，即递归的调用 String 对象的 Default Memberwise Initialization。 一个类对象可以从两种方式复制得到，一种是被初始化（即我们现在讨论的），另一种是被指定（assignment），将会之后的章节讨论。这两个操作分别是以 copy constructor 和 copy assignment operator 完成的。拷贝构造函数和上一节的默认构造函数一样，只在必要的时候才由编译器产生出来，因此“如果一个 class 未定义出 copy constructor，编译器就自动为它自动生成一个”这句话是不对的。并且拷贝构造函数也被分为有用的（nontrivial）和无用的（trivial），只有 nontrivial 的拷贝构造函数才会被生成或者合成到现有代码中，而决定一个拷贝构造函数是否是 nontrivial 的标准在于这个类是否展现出所谓的 “bitwise copy semantics”。 2.2 bitwise copy semantics（逐位次拷贝语义）现有下面的程序： #include &quot;word.h&quot;word noun(&quot;Book&quot;);void foo()&#123; word verb = noun;&#125;
显然 verb 是根据 noun 来初始化的，但是在没有看过 word 类的声明之前，我们无法预测这个初始化操作的程序行为，如果 word 类的设计者定义了一个拷贝构造函数，verb 的初始化就会调用它，但如果没有显式定义的拷贝构造函数，编译器是否会为 word 类生成一个拷贝构造函数呢？这就得视 word 类是否展现出 “bitwise copy semantics” 而定。 举例说明，比如 word 类有如下定义： // 以下声明展现了 bitwise copy semanticsclass word&#123;public: word(const char*); ~word() &#123;delete [] str;&#125; ...private: int cnt; char* str;&#125;;
这种情况下并不需要合成出一个拷贝构造函数，因为上面的声明展现出了 default copy semantics，于是 verb 的初始化也就不需要以一个函数调用进行。但如果 word 类的声明如下： // 以下声明没有展现 bitwise copy semanticsclass word&#123;public: word(const String&amp;); ~word(); ...private: int cnt; String str;&#125;;
其中 String 类显式声明了拷贝构造函数： class String &#123;public: String(const char*); String(const String&amp;); //显式声明了拷贝构造函数 ~String();private: char* str; int len;&#125;;
在这个情况下，编译器必须合成出一个拷贝构造函数，以便调用对象成员的拷贝构造函数： inline word::word(const word&amp; wd)&#123; str.String::String(wd.str); cnt = wd.cnt;&#125;
可以看到生成出来的拷贝构造函数也会将非对象成员进行复制。 一个类在四种情况下不会展现出 bitwise copy semantics，即会由编译器生成拷贝构造函数：
当 class 中包含一个对象成员而后者的类声明有一个拷贝构造函数时（这个拷贝构造函数可以是被用户显式声明的，就像前面的 String 那样，也可以是被编译器合成的，像 word 那样） 当 class 继承自一个 base class 而后者存在有一个 copy constructor 时（同样可以是用户定义的，也可以是编译器生成的） 当 class 声明了一个或多个 virtual functions 时 当 class 派生自一个继承串链，其中有一个或多个 virtual base classes 时
前两种情况中，编译器必须将对象成员或基类的拷贝构造函数调用代码安插到生成的拷贝构造函数中，而后两种情况较为复杂，下面具体讨论。 2.3 重新设定 Virtual Table 指针首先是第三种情况。当类中声明了虚函数时，编译器会为类生成一个虚函数表，并在每一个类对象中增加一个指向虚函数表的指针 vptr，因此在拷贝构造函数中必须要对对象的 vptr 进行正确的赋值，否则后果不堪设想，所以这种情况下编译器必须生成拷贝构造函数。 假设有下面的类： class ZooAnimal &#123; public: ZooAnimal(); virtual ~ZooAnimal(); virtual void animate(); virtual void draw(); //...private: //一些成员变量&#125;; class Bear : public ZooAnimal &#123; public: Bear(); virtual ~Bear(); virtual void animate() override; virtual void draw() override; virtual void dance(); //...private: //一些成员变量&#125;;
ZooAnimal 对象以另一个 ZooAnimal 对象作为初值，或者 Bear 对象以另一个 Bear 对象作为初值都可以直接靠 bitwise copy semantics 来完成，比如： Bear yogi;Bear winnie = yogi;
yogi 会被 Bear 的默认构造函数初始化，在构造函数中，yogi 的 vptr 被设定指向 Bear 类的虚函数表（靠编译器安插代码完成），因此直接把 yogi 的 vptr 值复制给 winnie 是完全没问题的，二者的关系如下图：
但是当一个基类对象以一个派生类对象作为初值进行初始化时，其 vptr 复制操作就不是这么简单了，如果直接把派生类对象的 vptr 复制给基类对象，就会发生严重错误。例如： ZooAnimal franny = yogi;franny.draw();
如果 franny 的 vptr 被复制为 yogi 的 vptr，那么相当于一个 ZooAnimal 类的对象会调用 Bear 派生类的函数实体，这就会发生严重错误。因此编译器必须保证在拷贝构造函数中为基类对象设定正确的 vptr 值。 事实上，上述代码执行的会是 ZooAnimal 的 draw 方法，因为 franny 是一个 ZooAnimal 对象，yogi 中的 Bear 部分已经在 franny 初始化时被切割（sliced）掉了，如果 franny 被声明为一个指针或者引用，那么 franny.draw() 才会调用 Bear 的 draw 方法。 也就是说，编译器自动生成的拷贝构造函数会明确设定基类对象的 vptr 指向基类的虚函数表，而不是直接从派生类中复制 vptr 的值。
2.4 处理 Virtual Base Class Subobject接下来讨论第四种情况。一个类对象以另一个对象作为初值，而后者有一个 virtual base class subobject，那么也会使 bitwise copy semantics 失效，从而编译器必须生成拷贝构造函数。 之前学习过，编译器必须保证 virtual base class subobject 在其每一个派生类对象中的位置能够在执行期准备妥当，但 bitwise copy semantics 可能会破坏这个位置，所以编译器必须生成一个拷贝构造函数来处理这一事件。 比如有下面的声明： class Raccoon : public virtual ZooAnimal &#123;public: Raccoon() &#123;...&#125; Raccoon(int val) &#123;...&#125; // ...private: //一些必要的数据&#125;;
类之间的继承关系如下：
显然，编译器首先会安插一些代码在 Raccoon 的构造函数中，包括：调用基类 ZooAnimal 的默认构造函数，设定 Raccoon 的 vptr 值，定位出 Raccoon 中 ZooAnimal 子对象的位置等。 虽然 Raccoon 类中含有一个虚拟基类子对象，但当我们用 Raccoon 对象初始化另一个 Raccoon 对象时，也不会出现额外的问题，只依靠 bitwise copy 即可。问题在于“用派生类对象初始化一个基类对象”，比如现在有一个 RedPanda 类继承于 Raccoon 类： class RedPanda : public Raccoon &#123;public: RedPanda() &#123;...&#125; RedPanda(int val) &#123;...&#125; // ...private: //一些必要的数据&#125;
类继承关系如下：
使用一个 RedPanda 对象初始化 Raccoon 对象： RedPanda little_red;Raccoon little_critter = little_red;
这时，只依靠 bitwise copy 就不够了，编译器必须明确的将 little_critter 的 virtual base class subobject 指针初始化，以指出 virtual base class subobject 在哪。 这种情况下，为了正确完成 little_critter 的初值设定，编译器必须生成一个拷贝构造函数，安插一些代码以设定 virtual base class subobject 指针的初值，对每一个成员执行必要的逐成员初始化，以及其他内存相关工作。
2.5 总结我们已经讨论过所有四种情况，这四种情况实际上和上一节默认构造函数的四种情况一致。在这些情况下，类不再保持 bitwise copy semantics，并且默认拷贝构造函数未被声明的话，会被视为 nontrivial，于是编译器为了正确处理“以一个对象作为另一个对象初值”的情况，必须生成或合成一个拷贝构造函数。 3 使用列表初始化成员C++ 中书写构造函数有一种特殊的写法，就是使用列表对类成员进行初始化，这一节来了解使用列表对成员进行初始化的背后发生了什么。 首先来看这样的一个类的构造函数： class word &#123; //不声明访问权限默认为private String _name; int _cnt;public: word() &#123; _name = 0; _cnt = 0; &#125;&#125;;
这样写构造函数自然没有问题，但效率很低，编译器会先产生一个临时的 String 对象，然后将它初始化，再以一个 assigment 运算符将临时的对象指定给 _name 成员，最后再摧毁临时对象。所以经过编译器扩展后的代码看起来就是这样： word::word()&#123; //调用String的默认构造函数 _name.String::String(); //产生临时对象 String temp = String(0); //降临时对象指定给_name _name.String::operator=(temp); //摧毁临时对象 temp.String::~String(); _cnt = 0;&#125;
但如果我们把构造函数写成这样： word::word() : _name(0)&#123; _cnt = 0;&#125;
编译器将会将代码扩展成这样： word::word()&#123; _name.String::String(0); _cnt = 0;&#125;
所以使用列表是较好的方式，因此最好坚持列表初始化的代码习惯： word::word() : _name(0), _cnt(0) &#123;&#125;
但有时我们不得不在函数体中指定成员初始值，比如要用一个成员初始化另一个成员，这时我们需要了解列表初始化背后到底发生了什么。 编译器会逐个操作初始化列表，以适当的次序将代码安插在构造函数体内，并且安插的代码会在用户定义的代码之前。这里的“适当的次序”是指成员变量在类中声明的次序，而不是初始化列表中书写的顺序。例如： class X &#123; int i; int j;public: X(int val) : j(val), i(j) &#123;&#125;&#125;;
这里看起来是用 val 初始化 j，再用 j 初始化 i，但实际上列表初始化会按照成员声明次序扩展代码，因此会先为 i 赋值，但此时 j 还没有被赋值，因此会得到错误的结果。这时我们可以将构造函数写成这样，来避免问题： class X &#123; int i; int j;public: X(int val) : j(val) &#123; i = j; &#125;&#125;;
因为编译器扩展的代码会在用户定义代码之前，所以会先为 j 赋值，再为 i 赋值。 总结一下，当存在以下情况时，尽量选择使用列表队成员进行初始化：
初始化一个 reference 成员时 初始化一个 const 成员时 当调用一个基类的构造函数，而它拥有一组参数时 当调用一个对象成员的构造函数，而它拥有一组参数时
4 总结最后总结构造函数的执行过程：
在派生类构造函数中，所有虚基类和上一层基类的构造函数首先会按顺序被调用，以生成基类子对象 上述完成后，对象的 vptr 会被初始化，指向正确的虚函数表 如果有成员初始化列表的话，将在 vptr 被设定后扩展开来，以免其中调用了虚函数 如果有对象成员且其有构造函数，调用对象成员的构造函数 最后执行程序员提供的初始化代码

《深度探索C++对象模型》第四章重点梳理。主要内容包括：
调用不同成员函数的背后工作 虚函数详解 内联函数的背后工作
1 调用不同成员函数的背后工作C++ 类中包括三种成员函数：非静态成员函数、静态成员函数和虚函数。这三种成员函数被调用时，编译器会进行不同的背后工作。 1.1 非静态成员函数C+＋的设计准则之一就是：非静态成员函数必须至少和一般的非成员函数有相同的效率。所以 C++ 的做法就是在非静态成员函数被调用时，编译器将其转化为一般的非成员函数，并传入一个对象的指针。 假设有一个成员函数： float Point3d::magnitude() const&#123; return sqrt(_x * _x + _y * _y + _z * _z);&#125;
下面是转化步骤：
改写函数的 signature（函数原型）以安插一个额外的参数到成员函数中，作为对对象成员的存取管道，该额外参数即为 this 指针，如果成员函数是 const，则传入参数也为 const 将对每一个成员变量的存取操作改为经由 this 指针的存取操作 将成员函数重写为一个外部非成员函数，并对函数名进行编码，使其有一个独一无二的内部名称
转化后的的函数如下： extern float magnitude_7Point3dFv(const Point3d* this)&#123; return sqrt( this-&gt;_x * this-&gt;_x + this-&gt;_y * this-&gt;_y + this-&gt;_z * this-&gt;_z);&#125;
对函数的调用： Point3d* ptr = new Point3d();ptr-&gt;magnitude();
也被转化为： magnitude_7Point3dFv(ptr);
1.2 静态成员函数静态成员函数类似于非静态成员函数，编译器同样将其转化为一般的外部非成员函数，唯一的区别在于，传入的参数不是 this 指针，而是一个被强制转化后的指针，编译器将 0 强制转化为对象指针传入函数，所以一个静态成员函数转化后是这样： extern float magnitude_7Point3dFv((Point3d*) 0)&#123; ...&#125;
也正因为这样的转化，决定了我们所熟悉的静态成员函数的特性：
无需经由类对象调用，通过类名即可调用，因为无需传入具体的对象指针，0 指针只作为一个执行静态成员函数的绑定对象指针，除此之外没有任何功能 不能够直接存取类中的非静态成员，因为指针是 0，实际不指向任何对象实体 不能声明为 const，virtual 等
1.3 虚拟成员函数虚成员函数在调用时被转化为经由 vptr 指向的虚函数表中的索引值调用： Point3d* ptr = new Point3d();(*ptr-&gt;vptr[1]) (ptr);
其中传入的 ptr 也是 this 指针，1 是该函数在虚函数表中的索引。 2 虚函数详解之前我们已经了解了虚函数的一般模型：每一个类有一个虚函数表，其中存放该类中所有有作用的虚函数地址，然后每个对象内含一个成员变量 vptr，指向虚函数表。这一节中我们根据不同继承情况，深入了解该模型内部原理。 2.1 单一继承任何情况下，一个 class 只会有一个 virtual table 。每一个 table 内含其对应的 class object 中所有 active virtual functions 函数实体的地址。这些 active virtual functions 包括：
这个 class 所定义的函数实体。它会改写 (overriding) 一个可能存在的 base class virtual function 实体 继承自 base class 的函数实体。这是在 derived class 决定不改写 base class virtual function 时才会出现的情况 一个纯虚函数调用（pure_virtual_called() ）实体，它既可以扮演纯虚函数的空间占用者，也可以当作执行期的异常处理函数，当调用一个基类中的纯虚函数（即未被定义）时，会抛出异常并终止程序
单一继承情况下的虚函数表布局如下图：
可以看到 Point2d 继承自 Point 类，重写的函数会覆盖基类虚函数，比如析构函数，以及在 Point2d 中实现的纯虚函数等，而没有重写的函数则直接复制基类虚函数表中该函数的地址，比如 Point::z() 函数。 回顾上一节提到的虚函数在编译时的转化，假设现在有如下调用： ptr-&gt;z();
则会被编译器转化为： (*ptr-&gt;vptr[4]) (ptr);
于是这样的形式就可以提供给程序足够的信息，使其在执行期知道调用哪一个函数实体，因为：
虽然不知道 ptr 指向的具体对象类型，但是我们知道经由 ptr 可以访问到该对象的 vptr，从而访问到类的虚函数表 虽然不知道哪一个函数实体 z() 会被调用，但是所有类的 z() 函数实体地址都放在虚函数表中下标为 4 的地方
这正是指针和虚函数所支持的多态的内部原理之一。在一个单一继承体系中，这样的机制的行为十分良好，不但有效率而且很容易塑造出模型来。但是在多重继承和虚拟继承之中，就没有这么简单了。 2.2 多重继承在多重继承之下，一个 derived class 内含 n 个虚函数表，n 表示上一层基类数目，其中第一个基类子对象指向的表为主要表格，其他的为次要表格，第一个基类的虚函数和派生类自己的虚函数都放在主要表格中。针对每一个虚函数表，派生类对象中都有对应的 vptr，当我们将一个派生类对象指定给第一个基类或者派生类的指针时，处理的是主要表格，其他情况处理的是次要表格。 多重继承情况下，虚函数表布局如下图：
上图中的 * 表示需要调整 this 指针，当我们将派生类对象指定给第二个或之后的基类指针时，会存在一些需要调整 this 指针以支持正确的虚函数的情况，一般来说有以下三种情况（对应上面三个星号）：
第一种情况：通过指向第二个基类的指针调用派生类的虚函数：
Base2 *ptr = new Derived;delete ptr;
上面的代码中 ptr 首先会被编译器调整至指向基类对象中的第二个基类子对象，编译器的调整代码如下： Derived *temp = new Derived;Base2 *ptr = temp ? temp + sizeof(Base1) : 0;
这样才能保证后续正确地访问或调用与第二个基类有关的成员和方法。但接下来的 delete ptr 需要调用析构函数，此时需要将 ptr 再向后调整至指向派生类对象起始地址，才能正确执行析构函数删除整个派生类对象。
第二种情况：通过一个指向派生类的指针，调用第二个基类中一个继承而来的虚函数，在这种情况派生类指针需要调整至指向第二个基类子对象
Derived *pder = new Derived;pder-&gt;mumble();//pedr必须向前调整sizeof(Base1)个字节以指向第二个基类子对象
第三种情况发生于一个语言扩充性质之下：允许一个 virtual function 的返回值类型有所变化，可能是 base type，也可能是 publicly derived type。这一点可以通过上图中的 clone() 函数说明，clone() 函数的派生版本返回一个派生类对象，默默地改写了两个基类函数实体，当我们通过第二个基类指针调用 clone() 函数时，需要调整 this 指针：
Base2 *pb1 = new Derived;// 返回值必须调整以指向第二个基类子对象Base2 *pb2 = pb1-&gt;clone();
当进行 pb1-&gt;clone() 时，pb1 会被调整指向派生类对象的起始地址，于是会调用 clone() 函数的派生版本，它会传回一个新的派生类对象，当该对象被指定给第二个基类的指针时，需要调整以指向第二个基类子对象。 2.3 虚拟继承虚拟继承的情况非常复杂，即使只有唯一的一个虚基类，他们的关系也不会像单一继承情况那样简单，因为虚基类和派生类不再相符，两者之间同样需要进行 this 指针转化。 当一个 virtual base class 从另一个 virtual base class 派生而来，并且两者都支持 virtual functions 和 nonstatic data members 时，编译器对于 virtual base class 的支持简直就像进了迷宫一样。总之一个建议是，不要在虚基类中声明非静态成员变量。 3 内联函数的背后工作下表对比了不同类型成员函数的执行效率：
可以看到内联函数的效率占据绝对优势。在以往的学习中我们被告知，inline 函数将会在被调用的时候在调用处产生函数实体，这个操作称为扩展，即把内联函数代码扩展到调用处替换函数调用代码。 但实际上不是所有声明为 inline 的函数都能成为内联函数，inline 只是一种请求，只有这个请求被接受才会在函数调用处扩展 inline 代码。那么编译器如何决定是否接受这个请求呢？ 编译器有一套复杂的算法来决定是否将函数认定为 inline，通常是计算 assignments、function calls、virtual function calls 等操作的次数。每个操作（表达式）种类有一个权值，而 inline 函数的复杂度就以这些操作的总和来决定。当其执行成本比一般的函数调用及返回机制所带来的负荷低，就被认定为 inline。 一般而言，处理一个 inline 函数包括以下两个阶段：
分析函数定义，以决定是否认定为 inline，如果函数因其复杂度，或因其建构问题，被判断为不可成为 inline，则它会被转为一个 static 函数，并在被编译模块内产生对应的函数定义。 真正的 inline 函数扩展操作是在调用的那个地方进行，这会带来参数的求值操作以及临时性对象的管理问题，接下来具体讨论。
3.1 有副作用的参数inline 函数是如何被扩展的？下面一个例子可以说明问题，假设有如下内联函数： inline int min(int i, int j)&#123; return i &lt; j ? i : j;&#125;
下面是三个调用操作： int minval;int val1 = 1024;int val2 = 2048;/**（1）**/minval = min(val1, val2);/**（2）**/minval = min(1024, 2048);/**（3）**/minval = min(foo(), bar() + 1);
以上三个调用会被扩展为： /**（1）**/minval = val1 &lt; val2 ? val1 : val2;/**（2）**/minval = 1024;/**（3）**/int t1, t2;t1 = foo();t2 = bar() + 1;minval = t1 &lt; t2 ? t1 : t2;
第（3）个调用把函数调用作为参数传入 inline 函数，这可能导致实际参数的多次求值操作，因此被认为是有副作用的参数，所以在扩展时使用了临时变量。而传入常量则会直接执行表达式，并将内联函数扩展为赋值操作。 3.2 局部变量如果我们修改 inline 函数，引入局部变量： inline int min(int i, int j)&#123; int minval = i &lt; j ? i : j return minval;&#125;
然后调用： int minval;int val1 = 1024;int val2 = 2048;minval = min(val1, val2);
则会被扩展为： int min_lv_minval = val1 &lt; val2 ? val1 : val2;minval = min_lv_minval
inline 函数中的局部变量会被保留，并产生一个拥有唯一编码名字的临时变量。如果 inline 函数在同一个 scope 中被调用多次，那么每次都会产生一组名字不同的临时变量。 inline 函数中的局部变量，再加上有副作用的参数，可能会导致大量临时性对象的产生。特别是它被调用多次的时候，例如： minval = min(val1, val2) + min(foo(), foo() + 1);
会被扩展为： // 为局部变量产生的临时变量int min_lv_minval_00;int min_lv_minval_01;// 为副作用参数产生的临时变量int t1, t2;t1 = foo();t2 = foo() + 1;min_lv_minval_00 = val1 &lt; val2 ? val1 : val2;min_lv_minval_01 = t1 &lt; t2 ? t1 : t2;minval = min_lv_minval_00 + min_lv_minval_01;
内联函数对于封装提供了一种必要的支持，可以有效存取封装于 class 中的 nonpublic 数据。它同时也是 C 程序中大量使用的#define （前置处理宏）的一个安全代替品，特别是如果宏中的参数有副作用的话。然而一个 inline 函数如果被调用太多次的话，会产生大量的扩展码，使程序的大小暴涨，并且由于参数带有副作用或者 inline 函数中有局部变量，会产生大量临时对象，编译器无法将它们移除。此外，inline 中再有 inline，可能会使一个表面上看起来简单的 inline 因其连锁复杂度而没办法扩展开来。对于既要安全又要效率的程序， inline 函数提供了一个强而有力的工具。然而，与 non-inline 函数比起来，它们需要更加小心地处理。

之前我们实现过一个光线追踪器，从这一节开始我们要实现一个运行在 CPU 上的简单的光栅化渲染器，并在实现过程中进一步理解渲染管线的流程和各种细节。首先从配置环境和熟悉 OpenGL 开始。
1 环境配置我们使用 GLFW 和 GLAD 来显示最终渲染的图片，这些可以参照LearnOpenGL CN上的教程来进行配置。 使用 GLM 作为数学库，下载地址：Releases · g-truc&#x2F;glm · GitHub 也可以使用和光线追踪器中一样的 STB 图像库来输出图片。 2 OpenGL 基础下面是一个简单的 OpenGL 程序，但展示了所有 OpenGL 程序的通用流程和框架，包含详细注释： #include &lt;glad/glad.h&gt;#include &lt;GLFW/glfw3.h&gt;#include &lt;iostream&gt;// 一些回调函数// 每当窗口改变大小，GLFW会调用这个函数并填充相应的参数供你处理// 这里我们在改变窗口大小的时候也改变视口大小void framebuffer_size_callback(GLFWwindow* window, int width, int height)&#123; glViewport(0, 0, width, height);&#125;// 检测是否按下 ESC 键，如果按下则将WindowShouldClose属性设置为true，这样既可退出渲染循环void processInput(GLFWwindow* window)&#123; if (glfwGetKey(window, GLFW_KEY_ESCAPE) == GLFW_PRESS) glfwSetWindowShouldClose(window, true);&#125;// 图像设置const unsigned int SCR_WIDTH = 800;const unsigned int SCR_HEIGHT = 600;// 顶点着色器代码，存放在字符串中const char* vertexShaderSource = &quot;#version 330 core
&quot;&quot;layout (location = 0) in vec3 aPos;
&quot;&quot;void main()
&quot;&quot;&#123;
&quot;&quot; gl_Position = vec4(aPos.x, aPos.y, aPos.z, 1.0);
&quot;&quot;&#125;\0&quot;;// 片元着色器代码const char* fragmentShaderSource = &quot;#version 330 core
&quot;&quot;out vec4 FragColor;
&quot;&quot;void main()
&quot;&quot;&#123;
&quot;&quot; FragColor = vec4(1.0f, 0.5f, 0.2f, 1.0f);
&quot;&quot;&#125;
\0&quot;;int main()&#123; // 初始化 GLFW，并配置版本信息等 glfwInit(); glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3); glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 3); glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE); // 使用 GLFW 创建一个窗口 GLFWwindow* window = glfwCreateWindow(SCR_WIDTH, SCR_HEIGHT, &quot;LearnOpenGL&quot;, NULL, NULL); if (window == NULL) &#123; std::cout &lt;&lt; &quot;Failed to create GLFW window&quot; &lt;&lt; std::endl; glfwTerminate(); return -1; &#125; glfwMakeContextCurrent(window); // 注册回调函数 glfwSetFramebufferSizeCallback(window, framebuffer_size_callback); // GLAD 用来来管理OpenGL的函数指针，使其在不同版本不同硬件上能够正确运行 // 因此在使用 OpenGL 函数前需要先初始化 GLAD if (!gladLoadGLLoader((GLADloadproc)glfwGetProcAddress)) &#123; std::cout &lt;&lt; &quot;Failed to initialize GLAD&quot; &lt;&lt; std::endl; return -1; &#125; // 创建并编译顶点着色器代码 unsigned int vertexShader = glCreateShader(GL_VERTEX_SHADER); glShaderSource(vertexShader, 1, &amp;vertexShaderSource, NULL); glCompileShader(vertexShader); // 检查编译错误 int success; char infoLog[512]; glGetShaderiv(vertexShader, GL_COMPILE_STATUS, &amp;success); if (!success) &#123; glGetShaderInfoLog(vertexShader, 512, NULL, infoLog); std::cout &lt;&lt; &quot;ERROR::SHADER::VERTEX::COMPILATION_FAILED
&quot; &lt;&lt; infoLog &lt;&lt; std::endl; &#125; // 创建并编译片元着色器代码 unsigned int fragmentShader = glCreateShader(GL_FRAGMENT_SHADER); glShaderSource(fragmentShader, 1, &amp;fragmentShaderSource, NULL); glCompileShader(fragmentShader); // 检查编译错误 glGetShaderiv(fragmentShader, GL_COMPILE_STATUS, &amp;success); if (!success) &#123; glGetShaderInfoLog(fragmentShader, 512, NULL, infoLog); std::cout &lt;&lt; &quot;ERROR::SHADER::FRAGMENT::COMPILATION_FAILED
&quot; &lt;&lt; infoLog &lt;&lt; std::endl; &#125; // 将着色器代码链接为一个着色器程序 unsigned int shaderProgram = glCreateProgram(); glAttachShader(shaderProgram, vertexShader); glAttachShader(shaderProgram, fragmentShader); glLinkProgram(shaderProgram); // 检查链接错误 glGetProgramiv(shaderProgram, GL_LINK_STATUS, &amp;success); if (!success) &#123; glGetProgramInfoLog(shaderProgram, 512, NULL, infoLog); std::cout &lt;&lt; &quot;ERROR::SHADER::PROGRAM::LINKING_FAILED
&quot; &lt;&lt; infoLog &lt;&lt; std::endl; &#125; // ；链接完成后即可删除着色器对象 glDeleteShader(vertexShader); glDeleteShader(fragmentShader); // 定义一个三角形 float vertices[] = &#123; -0.5f, -0.5f, 0.0f, // left 0.5f, -0.5f, 0.0f, // right 0.0f, 0.5f, 0.0f // top &#125;; // 创建顶点缓冲区VBA和顶点数组缓冲区VAO unsigned int VBO, VAO; glGenVertexArrays(1, &amp;VAO); glGenBuffers(1, &amp;VBO); // 绑定顶点数组缓冲 glBindVertexArray(VAO); // 绑定顶点缓冲，顶点缓冲是GL_ARRAY_BUFFER类型 glBindBuffer(GL_ARRAY_BUFFER, VBO); // 将上面的顶点数据复制到顶点缓冲中 glBufferData(GL_ARRAY_BUFFER, sizeof(vertices), vertices, GL_STATIC_DRAW); // 链接顶点属性，即告诉OpenGL如何解析顶点数据 glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 3 * sizeof(float), (void*)0); glEnableVertexAttribArray(0); // 解除缓冲区绑定，非必要 glBindBuffer(GL_ARRAY_BUFFER, 0); glBindVertexArray(0); // 渲染循环 while (!glfwWindowShouldClose(window)) &#123; // 是否按下ESC关闭窗口 processInput(window); // 设置清空屏幕缓冲所用的颜色 glClearColor(0.2f, 0.3f, 0.3f, 1.0f); // 用设置的颜色清空颜色缓冲，可选的还有深度缓冲和模板缓冲 glClear(GL_COLOR_BUFFER_BIT); // 渲染 glUseProgram(shaderProgram); glBindVertexArray(VAO); glDrawArrays(GL_TRIANGLES, 0, 3); // 使用双缓冲渲染，屏幕显示前缓冲区，渲染在后缓冲进行，因此每一帧交换缓冲区 glfwSwapBuffers(window); glfwPollEvents(); &#125; // 释放资源 glDeleteVertexArrays(1, &amp;VAO); glDeleteBuffers(1, &amp;VBO); glDeleteProgram(shaderProgram); glfwTerminate(); return 0;&#125;
程序运行效果如图：

上一节完成了环境配置和测试，这一节开始搭建一个渲染管线的框架，之后就都在此框架上加入各种功能和算法。

1 统一管理全局变量首先我们使用一个头文件 Global.h 来统一管理我们用到的所有头文件、全局变量和类声明，为了之后使用方便：
#pragma once#ifndef GLOBEL_H#define GLOBEL_H#define STB_IMAGE_IMPLEMENTATION#include &quot;stb_image.h&quot;#define STB_IMAGE_WRITE_IMPLEMENTATION#include &quot;stb_image_write.h&quot;#include &lt;glm/glm.hpp&gt;#include &lt;glm/gtc/matrix_transform.hpp&gt;#include &lt;glm/gtc/type_ptr.hpp&gt;#include &lt;iostream&gt;#include &lt;fstream&gt;#include &lt;sstream&gt;#include &lt;string&gt;#include &lt;cstdlib&gt;#include &lt;cmath&gt;#include &lt;vector&gt;// MVP变换矩阵glm::mat4 ModelMatrix;glm::mat4 ViewMatrix;glm::mat4 ProjectMatrix;// 视口变换矩阵glm::mat4 ViewPortMatrix;// 法线变换矩阵glm::mat3 NormalMatrix;const float PI = 3.14159265359;// 环境光const glm::vec3 Ambient = glm::vec3(0.5, 0.5, 0.5);// 相机类class Camera;// 渲染管线类class Draw;// 材质类class Material;// 平行光class DirectionLight;// 聚光灯class SpotLight;// 点光源class PointLight;#endif

2 FrameBuffer 类和光线追踪器中一样，我们使用一个 unsigned char 数组来存放像素，但这次我们使用 RGBA 四个通道。为了保证整个代码结构清晰，我们封装一个 FrameBuffer 类来管理颜色缓冲，后续还可以加入深度缓冲。
/** FrameBuffer 类，管理颜色缓冲和深度缓冲*/#pragma once#include &quot;Global.h&quot;class FrameBuffer &#123;public:	int Width, Height;	std::vector&lt;unsigned char&gt; colorBuffer;	~FrameBuffer() = default;	FrameBuffer(const int&amp; w = 800, const int&amp; h = 600) &#123;		Width = w;		Height = h;		//RGBA四个通道，数组大小为宽*高*4		colorBuffer.resize(w * h * 4, 0);	&#125;	// 重设缓冲区大小	void Resize(const int&amp; w, const int&amp; h) &#123;		Width = w;		Height = h;		colorBuffer.resize(w * h * 4, 0);	&#125;	// 使用给定的颜色清空颜色缓冲，不要使用vector下标访问，会很慢，直接使用指针操作	void ClearColorBuffer(const glm::vec4&amp; color) &#123;		unsigned char* p = colorBuffer.data();		for (int i = 0; i &lt; Width * Height * 4; i += 4) &#123;			*(p + i) = (unsigned char)color.r;			*(p + i + 1) = (unsigned char)color.g;			*(p + i + 2) = (unsigned char)color.b;			*(p + i + 3) = (unsigned char)color.a;		&#125;	&#125;	// 将颜色写入对应位置	void WritePoint(const int&amp; x, const int&amp; y, const glm::vec4&amp; color) &#123;		if (x &lt; 0 || x &gt;= Width || y &lt; 0 || y &gt;= Height)			return;		int xy = (y * Width + x);		unsigned char* p = colorBuffer.data();		*(p + xy * 4) = (unsigned char)color.r;		*(p + xy * 4 + 1) = (unsigned char)color.g;		*(p + xy * 4 + 2) = (unsigned char)color.b;		*(p + xy * 4 + 3) = (unsigned char)color.a;	&#125;&#125;;

3 管理顶点数据顶点是我们光栅化渲染器的输入数据，所以理所应当用一个类来管理。一个顶点包含的数据有：模型坐标、顶点颜色、顶点法线、纹理坐标。注意位置坐标使用的是四维齐次坐标，在模型空间和世界空间的坐标都是 x, y, z 加上恒为 1 的 w，所以要用四维向量。
/** 顶点Vertex类和*/#pragma once#ifndef VERTEX_H#define VERTEX_H#include &quot;Global.h&quot;class Vertex &#123;public:	glm::vec4 position;	glm::vec4 color;	glm::vec2 texcoord;	glm::vec3 normal;	Vertex() = default;	~Vertex() = default;	Vertex(		const glm::vec4&amp; _pos,		const glm::vec4&amp; _color,		const glm::vec2&amp; _tex,		const glm::vec3&amp; _normal	) :		position(_pos), color(_color), texcoord(_tex), normal(_normal) &#123;&#125;	Vertex(		const glm::vec3&amp; _pos,		const glm::vec4&amp; _color = glm::vec4(0, 0, 0, 0),		const glm::vec2&amp; _tex = glm::vec2(0, 0),		const glm::vec3&amp; _normal = glm::vec3(0, 0, 1)	) :		position(_pos, 1.0f), color(_color), texcoord(_tex), normal(_normal) &#123;&#125;	Vertex(const Vertex&amp; v) :position(v.position), color(v.color), texcoord(v.texcoord), normal(v.normal) &#123;&#125;&#125;;#endif

4 渲染管线思路输入输出都定义完了，接下来开始一步一步实现渲染管线。通常的 OpenGL 渲染管线流程如下：

输入顶点数据和图元类型（点、直线、三角形等基本图元）
顶点着色器对顶点进行处理，将坐标变换到世界坐标，计算纹理坐标和顶点颜色等，输出到中间结构体（v2f）
对 v2f 进行图元装配过程，也就是为每个三角形指定顶点数据与索引
将顶点变换到摄像机的观察空间
进行投影，将顶点变换到裁剪空间
进行裁剪和面剔除工作，将看不见的图元进行裁剪，剔除背向面，减少后续计算量
执行齐次除法，将顶点变换到 NDC（标准设备坐标）
执行视口变换，最终将顶点转换到屏幕坐标（从三维变成二维）
光栅化，计算图形在屏幕上最终覆盖的像素点
用顶点数据插值，在像素点位置生成新的 v2f
逐像素运行片元着色器，进行纹理采样、光照计算等，输出该点最终颜色值（RGBA）
执行透明度测试-&gt;模板测试-&gt;深度测试，丢弃掉一些片元
执行混合操作

5 V2F 类上述过程中，一个重要的结构体是 v2f，因此首先我们需要定义一个 v2f 类：
#pragma once#ifndef V2F_H#define V2F_H#include &quot;Global.h&quot;#include &quot;math.h&quot;class V2F &#123;public:	glm::vec4 worldPos;	glm::vec4 windowPos;	glm::vec4 color;	glm::vec2 texcoord;	glm::vec3 normal;	glm::mat3 TBN;	float Z;	V2F() = default;	~V2F() = default;	V2F(		const glm::vec4&amp; _wPos,		const glm::vec4&amp; _pPos,		const glm::vec4&amp; _color,		const glm::vec2&amp; _tex,		const glm::vec3&amp; _normal,		const glm::mat3&amp; _tbn	) :		worldPos(_wPos), windowPos(_pPos), color(_color), texcoord(_tex), normal(_normal), TBN(_tbn) &#123;&#125;	V2F(const V2F&amp; v) :		worldPos(v.worldPos), windowPos(v.windowPos), color(v.color), texcoord(v.texcoord), normal(v.normal), TBN(v.TBN), Z(v.Z) &#123;&#125;	//两个顶点之间的插值	static V2F lerp(const V2F&amp; v1, const V2F&amp; v2, const float&amp; factor) &#123;		V2F result;		result.windowPos = Lerp(v1.windowPos, v2.windowPos, factor);		result.worldPos = Lerp(v1.worldPos, v2.worldPos, factor);		result.color = Lerp(v1.color, v2.color, factor);		result.normal = Lerp(v1.normal, v2.normal, factor);		result.texcoord = Lerp(v1.texcoord, v2.texcoord, factor);		result.TBN = v1.TBN;		result.Z = Lerp(v1.Z, v2.Z, factor);		return result;	&#125;&#125;;#endif

V2F 中一个重要的操作就是插值，为此我们新建一个 math.h 文件来存放需要用到的数学操作，首先是线性插值函数：
#pragma once#ifndef MATH_H#define MATH_H#include&quot;Global.h&quot;//插值glm::vec4 Lerp(const glm::vec4&amp; v1, const glm::vec4&amp; v2, float factor) &#123;	return (1.0f - factor) * v1 + factor * v2;&#125;glm::vec3 Lerp(const glm::vec3&amp; v1, const glm::vec3&amp; v2, float factor) &#123;	return (1.0f - factor) * v1 + factor * v2;&#125;glm::vec2 Lerp(const glm::vec2&amp; v1, const glm::vec2&amp; v2, float factor) &#123;	return (1.0f - factor) * v1 + factor * v2;&#125;float Lerp(const float&amp; f1, const float&amp; f2, float factor) &#123;	return (1.0f - factor) * f1 + factor * f2;&#125;#endif

6 Shader 类有了上面这些准备，现在我们可以用顶点着色器来对顶点进行处理了。先从简单的情况开始，我们首先渲染一个二维图形，因为画二维图形不需要三维到二维的变换，所以三个变换矩阵都置为单位矩阵，实际上等于没做变换直接输出。片元着色器也是直接将调用点的颜色进行输出即可。我们同样封装一个 Shader 类来管理顶点和片元着色器：
/** 着色器 Shader 类*/#pragma once#ifndef SHADER_H#define SHADER_H#include &quot;V2F.h&quot;#include &quot;Vertex.h&quot;class Shader &#123;public:	Shader()	&#123;		ModelMatrix = glm::mat4(1.0f);		ViewMatrix = glm::mat4(1.0f);		ProjectMatrix = glm::mat4(1.0f);	&#125;;	virtual ~Shader() = default;private:	glm::mat4 ModelMatrix;	glm::mat4 ViewMatrix;	glm::mat4 ProjectMatrix;public:	// 顶点着色器	virtual V2F VertexShader(const Vertex&amp; a2v) &#123;		V2F o;		// 变换到世界空间		o.worldPos = ModelMatrix * a2v.position;		// 变换到裁剪空间		o.windowPos = ProjectMatrix * ViewMatrix * o.worldPos;		// 法线变换		o.normal = glm::normalize(NormalMatrix * a2v.normal);		o.texcoord = a2v.texcoord;		o.color = a2v.color;		return o;	&#125;	// 片元着色器	virtual glm::vec4 FragmentShader(const V2F&amp; v) &#123;		return v.color;	&#125;	void setModelMatrix(const glm::mat4&amp; model) &#123;		ModelMatrix = model;	&#125;	void setViewMatrix(const glm::mat4&amp; view) &#123;		ViewMatrix = view;	&#125;	void setProjectMatrix(const glm::mat4&amp; project) &#123;		ProjectMatrix = project;	&#125;&#125;;#endif

7 视口变换现在我们可以在主函数中定义是三个顶点，由于 OpenGL 的 NDC 的坐标范围是[-1,1)，而我们目前并没有做任何的坐标变换，因此我们直接定义 NDC 下的顶点坐标：
Shader shader;FrameBuffer FrontBuffer(SCR_WIDTH, SCR_HEIGHT);Vertex V1(glm::vec3(-0.5, -0.5, 0), glm::vec4(255, 0, 0, 0));Vertex V2(glm::vec3(0.5, -0.5, 0), glm::vec4(0, 255, 0, 0));Vertex V3(glm::vec3(0, 0.5, 0), glm::vec4(0, 0, 255, 0));V2F o1 = shader.VertexShader(V1);V2F o2 = shader.VertexShader(V2);V2F o3 = shader.VertexShader(V3);

现在我们得到了处理后的顶点，但还在 NDC 当中，需要进一步转化为屏幕空间中的坐标，即需要进行视口变换。视口变换做的操作是将 X, Y 坐标从 [-1,1) 映射到屏幕坐标 [0,w) 和 [0,h) 上，同时将原点从屏幕中间移到左下角。注意，在 OpenGL 中，左下角是原点，右上角是 (w,h) ，而 DirectX 中左上角是原点。在我们的 math.h 中定义视口变换矩阵，该矩阵是一个缩放+平移的矩阵：
// glm 的矩阵是行矩阵，而我们一般使用的是列矩阵，所以存放的时候要转置// 行矩阵做变换是右乘 v * M  ，列矩阵是左乘 M * v//视口变换矩阵  ox oy是左下角的坐标  从[-1,1]的 NDC 变换到屏幕坐标 [0,0],[w,h]// Vp = [  w/2 ,   0  ,  0  , ox+w/2 ,//			0  ,  h/2 ,  0  , oy+h/2 ,//          0  ,   0  ,  1  ,   0    ,//          0  ,   0  ,  0  ,   1   ]glm::mat4 GetViewPortMatrix(int ox, int oy, int width, int height) &#123;	glm::mat4 result = glm::mat4(1.0f);	result[0][0] = width / 2.0f;	result[3][0] = ox + (width / 2.0f);	result[1][1] = height / 2.0f;	result[3][1] = oy + (height / 2.0f);	return result;&#125;

然后修改主函数：
// 获取视口变换矩阵glm::mat4 ViewPortMatrix = GetViewPortMatrix(0, 0, SCR_WIDTH, SCR_HEIGHT);Shader shader;FrameBuffer FrontBuffer(SCR_WIDTH, SCR_HEIGHT);Vertex V1(glm::vec3(-0.5, -0.5, 0), glm::vec4(255, 0, 0, 0));Vertex V2(glm::vec3(0.5, -0.5, 0), glm::vec4(0, 255, 0, 0));Vertex V3(glm::vec3(0, 0.5, 0), glm::vec4(0, 0, 255, 0));V2F o1 = shader.VertexShader(V1);V2F o2 = shader.VertexShader(V2);V2F o3 = shader.VertexShader(V3);// 视口变换o1.windowPos = ViewPortMatrix * o1.windowPos;o2.windowPos = ViewPortMatrix * o2.windowPos;o3.windowPos = ViewPortMatrix * o3.windowPos;

8 光栅化接下来需要计算我们的三角形覆盖了哪些屏幕像素，这里使用经典的扫描线算法。其思想很简单，从三角形最上面的点开始往下逐步画横线，两个交点之间的区域就是覆盖的区域。

朝向下侧的三角形原理也是一样的，只不过是对称过来了。有了这两种三角形，不难发现任意三角形都能最多分为一个平顶和一个平底三角形，如下图：

于是我们得到一般三角形的光栅化方法：

根据三个顶点的 y 坐标判定是否有两个相等，有则判断是平底还是平顶三角形，直接画
找到 y 值在中间的点，划分出上下两个三角形，画两个

代码实现：
/** 扫描线算法*/void ScanLineTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;	std::vector&lt;V2F&gt; arr = &#123; v1, v2, v3 &#125;;	//对顶点根据 y 坐标排序，arr[0] 在最下面  arr[2]在最上面	if (arr[0].windowPos.y &gt; arr[1].windowPos.y) &#123;		V2F tmp = arr[0];		arr[0] = arr[1];		arr[1] = tmp;	&#125;	if (arr[1].windowPos.y &gt; arr[2].windowPos.y) &#123;		V2F tmp = arr[1];		arr[1] = arr[2];		arr[2] = tmp;	&#125;	if (arr[0].windowPos.y &gt; arr[1].windowPos.y) &#123;		V2F tmp = arr[0];		arr[0] = arr[1];		arr[1] = tmp;	&#125;	//中间跟上面的 y 相等，是底三角形	if (equal(arr[1].windowPos.y, arr[2].windowPos.y)) &#123;		DownTriangle(arr[1], arr[2], arr[0]);	&#125;//否则是顶三角形	else if (equal(arr[1].windowPos.y, arr[0].windowPos.y)) &#123;		UpTriangle(arr[1], arr[0], arr[2]);	&#125;	// 其他情况划分为两个三角形	else &#123;		float weight = (arr[2].windowPos.y - arr[1].windowPos.y) / (arr[2].windowPos.y - arr[0].windowPos.y);		V2F newEdge = V2F::lerp(arr[2], arr[0], weight);		UpTriangle(arr[1], newEdge, arr[2]);		DownTriangle(arr[1], newEdge, arr[0]);	&#125;&#125;void UpTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;	// 分为左、右、上三个顶点	V2F left, right, top;	left = v1.windowPos.x &gt; v2.windowPos.x ? v2 : v1;	right = v1.windowPos.x &gt; v2.windowPos.x ? v1 : v2;	top = v3;	// 对左顶点 x 坐标取整	left.windowPos.x = int(left.windowPos.x);	// y 的垂直跨度，用于插值系数的计算	int dy = top.windowPos.y - left.windowPos.y;	//从上往下插值	int nowY = top.windowPos.y;	for (int i = dy; i &gt;= 0; --i) &#123;		float weight = 0;		if (dy != 0) &#123;			weight = float(i) / dy;		&#125;		V2F newLeft = V2F::lerp(left, top, weight);		V2F newRight = V2F::lerp(right, top, weight);		newLeft.windowPos.x = int(newLeft.windowPos.x);		newRight.windowPos.x = int(newRight.windowPos.x + 0.5);		newLeft.windowPos.y = newRight.windowPos.y = nowY;		ScanLine(newLeft, newRight);		nowY--;	&#125;&#125;void DownTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;	V2F left, right, bottom;	left = v1.windowPos.x &gt; v2.windowPos.x ? v2 : v1;	right = v1.windowPos.x &gt; v2.windowPos.x ? v1 : v2;	bottom = v3;	int dy = left.windowPos.y - bottom.windowPos.y;	//从上往下插值	int nowY = left.windowPos.y;	for (int i = 0; i &lt; dy; ++i) &#123;		float weight = 0;		if (dy != 0) &#123;			weight = float(i) / dy;		&#125;		V2F newLeft = V2F::lerp(left, bottom, weight);		V2F newRight = V2F::lerp(right, bottom, weight);		newLeft.windowPos.x = int(newLeft.windowPos.x);		newRight.windowPos.x = int(newRight.windowPos.x + 0.5);		newLeft.windowPos.y = newRight.windowPos.y = nowY;		ScanLine(newLeft, newRight);		nowY--;	&#125;&#125;void ScanLine(const V2F&amp; left, const V2F&amp; right) &#123;	int length = right.windowPos.x - left.windowPos.x;	for (int i = 0; i &lt; length; ++i) &#123;		V2F v = V2F::lerp(left, right, (float)i / length);		v.windowPos.x = left.windowPos.x + i;		v.windowPos.y = left.windowPos.y;		FrontBuffer.WritePoint(v.windowPos.x, v.windowPos.y, shader.FragmentShader(v));	&#125;&#125;

然后修改上一节的主函数：
#include &quot;Global.h&quot;#include &quot;FrameBuffer.h&quot;#include &quot;Shader.h&quot;Shader shader;FrameBuffer FrontBuffer;unsigned int SCR_WIDTH = 800;unsigned int SCR_HEIGHT = 600;int main()&#123;	// 获取视口变换矩阵	glm::mat4 ViewPortMatrix = GetViewPortMatrix(0, 0, SCR_WIDTH, SCR_HEIGHT);	FrontBuffer.Resize(SCR_WIDTH, SCR_HEIGHT);	Vertex V1(glm::vec3(-0.5, -0.5, 0), glm::vec4(255, 0, 0, 255));	Vertex V2(glm::vec3(0.5, -0.5, 0), glm::vec4(0, 255, 0, 255));	Vertex V3(glm::vec3(0, 0.5, 0), glm::vec4(0, 0, 255, 255));	V2F o1 = shader.VertexShader(V1);	V2F o2 = shader.VertexShader(V2);	V2F o3 = shader.VertexShader(V3);	// 视口变换	o1.windowPos = ViewPortMatrix * o1.windowPos;	o2.windowPos = ViewPortMatrix * o2.windowPos;	o3.windowPos = ViewPortMatrix * o3.windowPos;	// 渲染并写出图片	FrontBuffer.ClearColorBuffer(glm::vec4(0, 0, 0, 255));	ScanLineTriangle(o1, o2, o3);	std::string filepath = &quot;D:\\TechStack\\ComputerGraphics\\RenderEngine\\Results\\test.png&quot;;	stbi_write_png(filepath.c_str(), SCR_WIDTH, SCR_HEIGHT, 4, FrontBuffer.colorBuffer.data(), 0);	return 0;&#125;

