9 Draw 类我们成功渲染出了二维图形，不过目前我们的渲染流程全都写在主函数中，需要一定的封装，于是我们定义一个 Draw 类来封装渲染过程：
#pragma once#ifndef DRAW_H#define DRAW_H#include &quot;Global.h&quot;#include &quot;FrameBuffer.h&quot;#include &quot;Shader.h&quot;#include &quot;V2F.h&quot;class Draw &#123;private:	int Width;	int Height;	FrameBuffer* FrontBuffer;	Shader* shader;	glm::mat4 ViewPortMatrix;public:	Draw(const int&amp; w, const int&amp; h) :		Width(w), Height(h), FrontBuffer(nullptr), shader(nullptr) &#123;&#125;	~Draw() &#123;		if (FrontBuffer)			delete FrontBuffer;		if (shader)			delete shader;		FrontBuffer = nullptr;		shader = nullptr;	&#125;	void setModelMatrix(const glm::mat4&amp; model) &#123;		shader-&gt;setModelMatrix(model);	&#125;	void setViewMatrix(const glm::mat4&amp; view) &#123;		shader-&gt;setViewMatrix(view);	&#125;	void setProjectMatrix(const glm::mat4&amp; project) &#123;		shader-&gt;setProjectMatrix(project);	&#125;	// 初始化，设定帧缓冲区和 Shder	void Init() &#123;		if (FrontBuffer)			delete FrontBuffer;		if (shader)			delete shader;		ViewPortMatrix = GetViewPortMatrix(0, 0, Width, Height);		FrontBuffer = new FrameBuffer(Width, Height);		shader = new Shader();	&#125;	void Resize(const int&amp; w, const int&amp; h) &#123;		Width = w;		Height = h;		FrontBuffer-&gt;Resize(w, h);		ViewPortMatrix = GetViewPortMatrix(0, 0, w, h);	&#125;	void ClearBuffer(const glm::vec4&amp; color) &#123;		FrontBuffer-&gt;ClearColorBuffer(color);	&#125;	void show(std::string&amp; filepath) &#123;		stbi_write_png(filepath.c_str(), Width, Height, 4, FrontBuffer-&gt;colorBuffer.data(), 0);	&#125;	void DrawTriangle(const Vertex&amp; v1, const Vertex&amp; v2, const Vertex&amp; v3) &#123;		V2F o1 = shader-&gt;VertexShader(v1);		V2F o2 = shader-&gt;VertexShader(v2);		V2F o3 = shader-&gt;VertexShader(v3);		// 视口变换		o1.windowPos = ViewPortMatrix * o1.windowPos;		o2.windowPos = ViewPortMatrix * o2.windowPos;		o3.windowPos = ViewPortMatrix * o3.windowPos;		ScanLineTriangle(o1, o2, o3);	&#125;	/*	****************** 扫描线算法 *******************	*/	void ScanLine(const V2F&amp; left, const V2F&amp; right) &#123;		int length = right.windowPos.x - left.windowPos.x;		for (int i = 0; i &lt; length; ++i) &#123;			V2F v = V2F::lerp(left, right, (float)i / length);			v.windowPos.x = left.windowPos.x + i;			v.windowPos.y = left.windowPos.y;			FrontBuffer-&gt;WritePoint(v.windowPos.x, v.windowPos.y, shader-&gt;FragmentShader(v));		&#125;	&#125;	void UpTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;		// 分为左、右、上三个顶点		V2F left, right, top;		left = v1.windowPos.x &gt; v2.windowPos.x ? v2 : v1;		right = v1.windowPos.x &gt; v2.windowPos.x ? v1 : v2;		top = v3;		// 对左顶点 x 坐标取整		left.windowPos.x = int(left.windowPos.x);		// y 的垂直跨度，用于插值系数的计算		int dy = top.windowPos.y - left.windowPos.y;		//从上往下插值		int nowY = top.windowPos.y;		for (int i = dy; i &gt;= 0; --i) &#123;			float weight = 0;			if (dy != 0) &#123;				weight = float(i) / dy;			&#125;			V2F newLeft = V2F::lerp(left, top, weight);			V2F newRight = V2F::lerp(right, top, weight);			newLeft.windowPos.x = int(newLeft.windowPos.x);			newRight.windowPos.x = int(newRight.windowPos.x + 0.5);			newLeft.windowPos.y = newRight.windowPos.y = nowY;			ScanLine(newLeft, newRight);			nowY--;		&#125;	&#125;	void DownTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;		V2F left, right, bottom;		left = v1.windowPos.x &gt; v2.windowPos.x ? v2 : v1;		right = v1.windowPos.x &gt; v2.windowPos.x ? v1 : v2;		bottom = v3;		int dy = left.windowPos.y - bottom.windowPos.y;		//从上往下插值		int nowY = left.windowPos.y;		for (int i = 0; i &lt; dy; ++i) &#123;			float weight = 0;			if (dy != 0) &#123;				weight = float(i) / dy;			&#125;			V2F newLeft = V2F::lerp(left, bottom, weight);			V2F newRight = V2F::lerp(right, bottom, weight);			newLeft.windowPos.x = int(newLeft.windowPos.x);			newRight.windowPos.x = int(newRight.windowPos.x + 0.5);			newLeft.windowPos.y = newRight.windowPos.y = nowY;			ScanLine(newLeft, newRight);			nowY--;		&#125;	&#125;	void ScanLineTriangle(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;		std::vector&lt;V2F&gt; arr = &#123; v1, v2, v3 &#125;;		//对顶点根据 y 坐标排序，arr[0] 在最下面  arr[2]在最上面		if (arr[0].windowPos.y &gt; arr[1].windowPos.y) &#123;			V2F tmp = arr[0];			arr[0] = arr[1];			arr[1] = tmp;		&#125;		if (arr[1].windowPos.y &gt; arr[2].windowPos.y) &#123;			V2F tmp = arr[1];			arr[1] = arr[2];			arr[2] = tmp;		&#125;		if (arr[0].windowPos.y &gt; arr[1].windowPos.y) &#123;			V2F tmp = arr[0];			arr[0] = arr[1];			arr[1] = tmp;		&#125;		//中间跟上面的 y 相等，是底三角形		if (equal(arr[1].windowPos.y, arr[2].windowPos.y)) &#123;			DownTriangle(arr[1], arr[2], arr[0]);		&#125;//否则是顶三角形		else if (equal(arr[1].windowPos.y, arr[0].windowPos.y)) &#123;			UpTriangle(arr[1], arr[0], arr[2]);		&#125;		// 其他情况划分为两个三角形		else &#123;			float weight = (arr[2].windowPos.y - arr[1].windowPos.y) / (arr[2].windowPos.y - arr[0].windowPos.y);			V2F newEdge = V2F::lerp(arr[2], arr[0], weight);			UpTriangle(arr[1], newEdge, arr[2]);			DownTriangle(arr[1], newEdge, arr[0]);		&#125;	&#125;&#125;;#endif

然后主函数就变得非常简单了：
#include &quot;Global.h&quot;#include &quot;Draw.h&quot;unsigned int SCR_WIDTH = 800;const unsigned int SCR_HEIGHT = 600;const std::string OUT_PATH = &quot;D:\\TechStack\\ComputerGraphics\\RenderEngine\\Results\\&quot;;const std::string FILE_NAME = &quot;test.png&quot;;int main()&#123;	Draw dw(SCR_WIDTH, SCR_HEIGHT);	// 初始化渲染器	dw.Init();	// 三角形三个顶点	Vertex V1(glm::vec3(-0.5, -0.5, 0), glm::vec4(255, 0, 0, 128));	Vertex V2(glm::vec3(0.5, -0.5, 0), glm::vec4(0, 255, 0, 128));	Vertex V3(glm::vec3(0, 0.5, 0), glm::vec4(0, 0, 255, 128));	// 设定背景并画三角形，这次有透明效果	dw.ClearBuffer(glm::vec4(0, 0, 128, 128));	dw.DrawTriangle(V1, V2, V3);	// 写出图片	std::string filepath = OUT_PATH + FILE_NAME;	dw.show(filepath);	return 0;&#125;

最终的效果：

到此为止整个渲染器的框架就搭建完成，之后只需要在这个框架上添加算法和各种功能即可。

上一节我们搭建了整个渲染器的框架，并实现了最简单的渲染二维图形。这一节我们开始渲染真正的三维物体，实现一个基本的渲染管线。

1 Mesh 类网格（Mesh）是用于保存三维模型的数据结构，通常来说一个网格包含一系列顶点数据和索引，用它们就能绘制出一系列多边形。同时网格还包含该模型所使用的材质信息（贴图、光照等）。上一章中我们是直接用顶点来画图形的，相当于手动创建了一个 Mesh，但是当模型比较复杂的时候，就需要一个类来管理模型的 Mesh，于是我们创建一个 Mesh 类：
/** 网格类，基础单位是三角形*/#pragma once#ifndef MESH_H#define MESH_H#include &quot;Vertex.h&quot;class Mesh&#123;public:    std::vector&lt;Vertex&gt; VBO;        // 存放顶点数据    std::vector&lt;unsigned int&gt; EBO;    // 存放顶点索引顺序    Mesh() = default;    Mesh(const int&amp; vNum, const int&amp; iNum) &#123;        VBO.resize(vNum);        EBO.resize(iNum);    &#125;    ~Mesh() = default;    Mesh(const Mesh&amp; mesh)        :VBO(mesh.VBO), EBO(mesh.EBO) &#123;&#125;    Mesh&amp; operator=(const Mesh&amp; mesh)    &#123;        if (&amp;mesh == this)            return *this;        VBO = mesh.VBO;        EBO = mesh.EBO;        return *this;    &#125;    Mesh&amp; operator+=(const Mesh&amp; mesh)    &#123;        AddMesh(mesh);        return *this;    &#125;    // 向网格中加入其它网格    void AddMesh(const Mesh&amp; mesh) &#123;        int offset = VBO.size();        VBO.insert(VBO.end(), mesh.VBO.begin(), mesh.VBO.end());        EBO.reserve(EBO.size() + mesh.EBO.size());        for (int i = 0; i &lt; mesh.EBO.size(); i++) &#123;            EBO.push_back(mesh.EBO[i] + offset);        &#125;    &#125;    // 向网格中添加一一个三角形片面    void AddTriangle(const Vertex&amp; v1, const Vertex&amp; v2, const Vertex&amp; v3) &#123;        VBO.push_back(v1);        VBO.push_back(v2);        VBO.push_back(v3);        EBO.push_back(0);        EBO.push_back(1);        EBO.push_back(2);    &#125;&#125;;#endif

然后我们就可以在 Draw 类中将之前画三角形的函数 DrawTriangle 改为更一般的画网格的函数 DrawMesh 了：
// 画网格void DrawMesh(const Mesh&amp; mesh) &#123;    if (mesh.EBO.empty()) &#123;        return;    &#125;    for (int i = 0; i &lt; mesh.EBO.size(); i += 3) &#123;        Vertex p1, p2, p3;        p1 = mesh.VBO[mesh.EBO[i]];        p2 = mesh.VBO[mesh.EBO[i + 1]];        p3 = mesh.VBO[mesh.EBO[i + 2]];        // 顶点着色器        V2F v1, v2, v3;        v1 = shader-&gt;VertexShader(p1);        v2 = shader-&gt;VertexShader(p2);        v3 = shader-&gt;VertexShader(p3);        // 视口变换        v1.windowPos = ViewPortMatrix * v1.windowPos;        v2.windowPos = ViewPortMatrix * v2.windowPos;        v3.windowPos = ViewPortMatrix * v3.windowPos;        ScanLineTriangle(v1, v2, v3);    &#125;&#125;

2 三维变换接下来是重头戏，三维变换。虽然对三维坐标变换已经有过深入的理论学习，但是在实践之前还是有必要再复习一次，把理论和实际结合起来。之前的笔记参考【计算机图形学】（一）变换。
首先梳理一下整个从三维模型到屏幕上的图像变换过程：

模型定点定义在模型空间，需要将所有模型的顶点转换到世界空间
世界空间中有各种模型和观察整个场景的相机，因此要将世界空间变换到相机空间，也称观察空间
观察空间中的顶点位置还是三维坐标，因此要进行投影变换将所有物体顶点变换到裁剪空间，得到二维位置以及深度
裁剪空间经过透视除法变换到标准设备坐标系
标准设备坐标系最后经过视口变换到屏幕空间中

于是首先是世界空间到观察空间的变换，也就是将世界空间原点移动到相机位置，然后将世界空间的三个坐标轴和相机的 right、up、front 三个方向对齐。平移矩阵很好写出：

坐标轴对齐也很简单，要将 A 空间的坐标轴和 B 空间的坐标轴对齐，只需要将 A 空间下 B 空间的坐标轴按行排列即可，因此只要将世界坐标系下的相机的三个方向按行排列，就是从世界空间到相机空间的变换矩阵：

于是整个视角变换矩阵即为：

我们在 math.h 中加入视角变换矩阵：
// 视角变换矩阵，也称观察矩阵// V = R*T// T = [  1 , 0 , 0 , -eyex          R = [  Right , 0 //        0 , 1 , 0 , -eyey                   UP  , 0//        0 , 0 , 1 , -eyez               - Front , 0//        0 , 0 , 0 ,   1   ]                 0   , 1 ]//V =  [  Right  ,  - Right·eye//          UP   ,  - UP·eye//       -Front  ,   Front·eye//         0     ,       1        ]// OpenGL中观察空间是右手系，+z 轴指向屏幕外，为了让朝向保持不变，对Front向量取反glm::mat4 GetViewMatrix(glm::vec3 pos, glm::vec3 front, glm::vec3 right, glm::vec3 up) &#123;    glm::mat4 result = glm::mat4(1.0f);    result[0][0] = right.x;    result[1][0] = right.y;    result[2][0] = right.z;    result[3][0] = -glm::dot(right, pos);    result[0][1] = up.x;    result[1][1] = up.y;    result[2][1] = up.z;    result[3][1] = -glm::dot(up, pos);    result[0][2] = -front.x;    result[1][2] = -front.y;    result[2][2] = -front.z;    result[3][2] = glm::dot(front, pos);    return result;&#125;

接下来是透视投影矩阵，之前的笔记有详细推导，这里就不再赘述了，顺便再附上两篇透视投影的详细推导和理解的文章：

OpenGL投影矩阵(Projection Matrix)构造方法
写给大家看的“透视除法” —— 齐次坐标和投影

这里我们使用的透视投影矩阵为：

其中 r &#x3D; -l, t &#x3D; -b，因此投影矩阵最终为：

其中，r 是屏幕半宽，t 是屏幕半高，f 是远平面距离，n 是近平面距离。代码如下：
//透视投影 参数 fov(弧度) aspect near far//M = [   1/aspect*tan(fov/2),       0      ,         0      ,       0//               0  ,         1/tan(fov/2)  ,         0      ,       0 //               0  ,                0      ,  - (f+n)/(f-n) ,  -2fn/(f-n)//               0  ,                0      ,         -1     ,       0     ]// 投影之后从右手系变成了左手系，+Z指向屏幕内glm::mat4 GetPerspectiveMatrix(const float&amp; fovy, const float&amp; aspect, const float&amp; n, const float&amp; f)&#123;    glm::mat4 result = glm::mat4(0.0f);    const float tanHalfFov = tan(fovy * 0.5f);    result[0][0] = 1.0f / (aspect * tanHalfFov);    result[1][1] = 1.0f / (tanHalfFov);    result[2][2] = -(f + n) / (f - n);    result[2][3] = -1.0f;    result[3][2] = (-2.0f * n * f) / (f - n);    return result;&#125;

经过透视投影后，所有坐标都在 [-w, w] 之间，还需要经过透视除法将其变换到 NDC：
//透视除法void PerspectiveDivision(V2F&amp; v) &#123;    v.windowPos /= v.windowPos.w;    v.windowPos.w = 1.0f;    // OpenGL 的 NDC 中 Z 的范围是[0,1]    v.windowPos.z = (v.windowPos.z + 1.0) * 0.5;&#125;

 透视除法在顶点着色器变换到裁剪空间之后，视口变换之前进行，因此修改画网格的函数，加入透视除法：
// 画网格void DrawMesh(const Mesh&amp; mesh) &#123;    if (mesh.EBO.empty()) &#123;        return;    &#125;    for (int i = 0; i &lt; mesh.EBO.size(); i += 3) &#123;        Vertex p1, p2, p3;        p1 = mesh.VBO[mesh.EBO[i]];        p2 = mesh.VBO[mesh.EBO[i + 1]];        p3 = mesh.VBO[mesh.EBO[i + 2]];        //顶点着色器        V2F v1, v2, v3;        v1 = shader-&gt;VertexShader(p1);        v2 = shader-&gt;VertexShader(p2);        v3 = shader-&gt;VertexShader(p3);        //做透视除法，变换到NDC        PerspectiveDivision(v1);        PerspectiveDivision(v2);        PerspectiveDivision(v3);        // 视口变换        v1.windowPos = ViewPortMatrix * v1.windowPos;        v2.windowPos = ViewPortMatrix * v2.windowPos;        v3.windowPos = ViewPortMatrix * v3.windowPos;        ScanLineTriangle(v1, v2, v3);    &#125;&#125;

3 构建模型到此为止我们已经可以渲染一个三维物体了，我们使用 Mesh 构建一个立方体。一个立方体由 6 个面组成，每个面又可以分为两个三角形，于是我们写出三个函数：分别是构建三角形，构建平面和构建立方体：
//构建一个三角形Mesh CreateTriangle(const glm::vec3&amp; p1, const glm::vec3&amp; p2, const glm::vec3&amp; p3, const glm::vec3&amp; normal) &#123;    Mesh result(3, 3);    //逆时针的三角形    //顶点顺序 0 1 2    result.VBO[0].position = glm::vec4(p1, 1.0f);    result.VBO[0].normal = normal;    result.VBO[0].color = glm::vec4(255, 0, 0, 255);    result.VBO[0].texcoord = glm::vec2(0.0f, 1.0f);    result.VBO[1].position = glm::vec4(p2, 1.0f);    result.VBO[1].normal = normal;    result.VBO[1].color = glm::vec4(0, 255, 0, 255);    result.VBO[1].texcoord = glm::vec2(0.0f, 0.0f);    result.VBO[2].position = glm::vec4(p3, 1.0f);    result.VBO[2].normal = normal;    result.VBO[2].color = glm::vec4(0, 0, 255, 255);    result.VBO[2].texcoord = glm::vec2(1.0f, 0.0f);    result.EBO[0] = 0;    result.EBO[1] = 1;    result.EBO[2] = 2;    return result;&#125;//构建一个平面，顶点顺序为左上 左下 右下 右上Mesh CreatePlane(const glm::vec3&amp; leftTop, const glm::vec3&amp; leftBottom, const glm::vec3&amp; rightBottom, const glm::vec3&amp; rightTop, const glm::vec3&amp; normal) &#123;    Mesh result(4, 6);    result.VBO[0].position = glm::vec4(leftTop, 1.0f);    result.VBO[0].normal = normal;    result.VBO[0].color = glm::vec4(1.0f, 0, 0, 1.0f);    result.VBO[0].texcoord = glm::vec2(0.0f, 1.0f);    result.VBO[1].position = glm::vec4(rightTop, 1.0f);    result.VBO[1].normal = normal;    result.VBO[1].color = glm::vec4(0, 1.0f, 0, 1.0);    result.VBO[1].texcoord = glm::vec2(1.0f, 1.0f);    result.VBO[2].position = glm::vec4(rightBottom, 1.0f);    result.VBO[2].normal = normal;    result.VBO[2].color = glm::vec4(0, 0, 1.0f, 0);    result.VBO[2].texcoord = glm::vec2(1.0f, 0.0f);    result.VBO[3].position = glm::vec4(leftBottom, 1.0f);    result.VBO[3].normal = normal;    result.VBO[3].color = glm::vec4(1.0f, 0, 1.0, 1.0f);    result.VBO[3].texcoord = glm::vec2(0.0f, 0.0f);    // 两个逆时针三角形    result.EBO[0] = 0;    result.EBO[1] = 2;    result.EBO[2] = 1;    result.EBO[3] = 0;    result.EBO[4] = 3;    result.EBO[5] = 2;    return result;&#125;// 构建立方体Mesh CreateBox(const glm::vec3&amp; center, float radius) &#123;    Mesh result;    Mesh front = CreatePlane(        center + glm::vec3(-radius, radius, radius),        center + glm::vec3(-radius, -radius, radius),        center + glm::vec3(radius, -radius, radius),        center + glm::vec3(radius, radius, radius),        glm::vec3(0, 0, 1)    );    result.AddMesh(front);    Mesh left = CreatePlane(        center + glm::vec3(-radius, radius, -radius),        center + glm::vec3(-radius, -radius, -radius),        center + glm::vec3(-radius, -radius, radius),        center + glm::vec3(-radius, radius, radius),        glm::vec3(-1, 0, 0)    );    result.AddMesh(left);    Mesh right = CreatePlane(        center + glm::vec3(radius, radius, radius),        center + glm::vec3(radius, -radius, radius),        center + glm::vec3(radius, -radius, -radius),        center + glm::vec3(radius, radius, -radius),        glm::vec3(1, 0, 0)    );    result.AddMesh(right);    Mesh back = CreatePlane(        center + glm::vec3(radius, radius, -radius),        center + glm::vec3(radius, -radius, -radius),        center + glm::vec3(-radius, -radius, -radius),        center + glm::vec3(-radius, radius, -radius),        glm::vec3(0, 0, -1)    );    result.AddMesh(back);    Mesh up = CreatePlane(        center + glm::vec3(-radius, radius, -radius),        center + glm::vec3(-radius, radius, radius),        center + glm::vec3(radius, radius, radius),        center + glm::vec3(radius, radius, -radius),        glm::vec3(0, 1, 0)    );    result.AddMesh(up);    Mesh down = CreatePlane(        center + glm::vec3(-radius, -radius, radius),        center + glm::vec3(-radius, -radius, -radius),        center + glm::vec3(radius, -radius, -radius),        center + glm::vec3(radius, -radius, radius),        glm::vec3(0, -1, 0)    );    result.AddMesh(down);    return result;&#125;

注意到上面的颜色更加标准了，所有分量范围都在 [0 ,1]，因此需要修改对应的 FrameBuffer 中的写颜色函数：
// 使用给定的颜色清空颜色缓冲，不要使用vector下标访问，会很慢，直接使用指针操作void ClearColorBuffer(const glm::vec4&amp; color) &#123;    unsigned char* p = colorBuffer.data();    for (int i = 0; i &lt; Width * Height * 4; i += 4) &#123;        *(p + i) = saturate(color.r) * 255;        *(p + i + 1) = saturate(color.g) * 255;        *(p + i + 2) = saturate(color.b) * 255;        *(p + i + 3) = saturate(color.a) * 255;    &#125;&#125;// 将颜色写入对应位置void WritePoint(const int&amp; x, const int&amp; y, const glm::vec4&amp; color) &#123;    if (x &lt; 0 || x &gt;= Width || y &lt; 0 || y &gt;= Height)        return;    int xy = (y * Width + x);    unsigned char* p = colorBuffer.data();    *(p + xy * 4) = saturate(color.r) * 255;    *(p + xy * 4 + 1) = saturate(color.g) * 255;    *(p + xy * 4 + 2) = saturate(color.b) * 255;    *(p + xy * 4 + 3) = saturate(color.a) * 255;&#125;

其中 saturate 函数在 math.h 中定义，作用是将输入值截断在 [0, 1] 范围内：
float saturate(const float&amp; v) &#123;    if (v &gt; 1)        return 1;    if (v &lt; 0)        return 0;    return v;&#125;

修改主函数绘制立方体：
#include &quot;Global.h&quot;#include &quot;Draw.h&quot;unsigned int SCR_WIDTH = 800;const unsigned int SCR_HEIGHT = 600;const std::string OUT_PATH = &quot;D:\\TechStack\\ComputerGraphics\\RenderEngine\\Results\\&quot;;const std::string FILE_NAME = &quot;box.png&quot;;int main()&#123;    Draw dw(SCR_WIDTH, SCR_HEIGHT);    // 初始化渲染器    dw.Init();    dw.ClearBuffer(glm::vec4(0, 0, 0, 1));        // 设置观察矩阵    dw.setViewMatrix(        GetViewMatrix(glm::vec3(0, 0, 5), glm::vec3(0, 0, -1), glm::vec3(1, 0, 0), glm::vec3(0, 1, 0)));    // 设置投影矩阵    dw.setProjectMatrix(        GetPerspectiveMatrix(glm::radians(60.0f), (float)SCR_WIDTH / SCR_HEIGHT, 0.3f, 100));    // 创建一个立方体    Mesh Box = CreateBox(glm::vec3(0.0, 0.0, 0.0), 0.5);    // 让模型在原点绕着(1,1,0)旋转angle度    float angle = 30.0;    dw.setModelMatrix(glm::rotate(glm::mat4(1.0f), glm::radians(angle), glm::vec3(1.0, 1.0, 0.0)));    // 绘制    dw.DrawMesh(Box);    // 写出图片    std::string filepath = OUT_PATH + FILE_NAME;    dw.show(filepath);    return 0;&#125;

效果如下：

可以看出透视关系不正确，这是因为没有做深度测试的原因，因此我们需要实现深度测试。
4 深度测试我们首先需要在 FrameBuffer 类中加入深度缓冲：
/** FrameBuffer 类，管理颜色缓冲和深度缓冲*/#pragma once#include &quot;math.h&quot;class FrameBuffer &#123;public:    int Width, Height;    std::vector&lt;unsigned char&gt; colorBuffer;    std::vector&lt;float&gt; depthBuffer;    ~FrameBuffer() = default;    FrameBuffer(const int&amp; w = 800, const int&amp; h = 600) &#123;        Width = w;        Height = h;        //RGBA四个通道，数组大小为宽*高*4        colorBuffer.resize(w * h * 4, 0);        depthBuffer.resize(w * h, 1.0f);    &#125;    // 重设缓冲区大小    void Resize(const int&amp; w, const int&amp; h) &#123;        Width = w;        Height = h;        colorBuffer.resize(w * h * 4, 0);        depthBuffer.resize(w * h, 1.0f);    &#125;    // 使用给定的颜色清空颜色缓冲，不要使用vector下标访问，会很慢，直接使用指针操作    void ClearColorBuffer(const glm::vec4&amp; color) &#123;        unsigned char* p = colorBuffer.data();        for (int i = 0; i &lt; Width * Height * 4; i += 4) &#123;            *(p + i) = saturate(color.r) * 255;            *(p + i + 1) = saturate(color.g) * 255;            *(p + i + 2) = saturate(color.b) * 255;            *(p + i + 3) = saturate(color.a) * 255;        &#125;        // 同时重置深度缓冲        depthBuffer.assign(Width * Height, 1.0f);    &#125;        // 将颜色写入对应位置    void WritePoint(const int&amp; x, const int&amp; y, const glm::vec4&amp; color) &#123;        if (x &lt; 0 || x &gt;= Width || y &lt; 0 || y &gt;= Height)            return;        int xy = (y * Width + x);        unsigned char* p = colorBuffer.data();        *(p + xy * 4) = saturate(color.r) * 255;        *(p + xy * 4 + 1) = saturate(color.g) * 255;        *(p + xy * 4 + 2) = saturate(color.b) * 255;        *(p + xy * 4 + 3) = saturate(color.a) * 255;    &#125;    // 写入深度，Z-Buffer 中深度范围是 [0,1]    void WriteDepth(const int&amp; x, const int&amp; y, const float&amp; depth) &#123;        if (x &lt; 0 || x &gt;= Width || y &lt; 0 || y &gt;= Height)            return;        float* p = depthBuffer.data();        *(p + y * Width + x) = depth;    &#125;    // 获取深度    float GetDepth(const int&amp; x, const int&amp; y) &#123;        if (x &lt; 0 || x &gt;= Width || y &lt; 0 || y &gt;= Height)            return 1.0;        return *(depthBuffer.data() + y * Width + x);    &#125;&#125;;

正常深度测试应该在片元着色器之后，但是为了避免不必要的计算，可以在扫描线算法中加入深度测试，也相当于实现了 Early-Z 算法：
void ScanLine(const V2F&amp; left, const V2F&amp; right) &#123;    int length = right.windowPos.x - left.windowPos.x;    for (int i = 0; i &lt; length; ++i) &#123;        V2F v = V2F::lerp(left, right, (float)i / length);        v.windowPos.x = left.windowPos.x + i;        v.windowPos.y = left.windowPos.y;        //深度测试        float depth = FrontBuffer-&gt;GetDepth(v.windowPos.x, v.windowPos.y);        if (v.windowPos.z &lt;= depth) &#123;            FrontBuffer-&gt;WritePoint(v.windowPos.x, v.windowPos.y, shader-&gt;FragmentShader(v));            FrontBuffer-&gt;WriteDepth(v.windowPos.x, v.windowPos.y, v.windowPos.z);        &#125;    &#125;&#125;

效果如下：

上一节中我们完成了三维物体的渲染，显示了一个立方体，这一节我们为立方体加上一个图片纹理变为一个木箱。

1 OpenGL 中的纹理首先来看 OpenGL 中如何使用纹理有关的操作，可以参考官方教程：[纹理 - LearnOpenGL CN](https://learnopengl-cn.github.io/01 Getting started&#x2F;06 Textures&#x2F;)
2 实现纹理类然后我们自己手动实现一个简单的纹理类，纹理环绕方式使用 GL_REPEAT 的方式，即超过 1.0 的纹理坐标就直接重复，纹理过滤的方式采用最近邻方式，加载图片还是使用简单强大的 stbi 库，纹理类的实现如下：
/** 图片纹理类*/#pragma once#ifndef TEXTURE_H#define TEXTURE_H#include &quot;Global.h&quot;class Texture &#123;public:    int width;    int height;    int channels;    unsigned char* data;    Texture() : width(-1), height(-1), channels(-1), data(nullptr)    &#123;&#125;        Texture(const std::string&amp; Path) &#123;        LoadTexture(Path);    &#125;    virtual ~Texture() &#123;        if (data)            free(data);    &#125;    Texture(const Texture&amp; t) &#123;        width = t.width;        height = t.height;        channels = t.channels;        if (t.data) &#123;            data = (unsigned char*)malloc(width * height * channels);            memcpy(data, t.data, width * height * channels);        &#125;    &#125;    Texture&amp; operator=(const Texture&amp; t) &#123;        width = t.width;        height = t.height;        channels = t.channels;        if (t.data) &#123;            data = (unsigned char*)malloc(width * height * channels);            memcpy(data, t.data, width * height * channels);        &#125;        return *this;    &#125;    // 加载图片    virtual void LoadTexture(const std::string&amp; Path) &#123;        stbi_set_flip_vertically_on_load(false);        if (data)            free(data);        data = stbi_load(Path.c_str(), &amp;width, &amp;height, &amp;channels, 0);    &#125;    // 纹理采样，使用重复寻址方式,等同于OpenGL的GL_REPEAT	virtual glm::vec4 Sample2D(const glm::vec2&amp; texcoord) &#123;		float x = texcoord.x - (float)floor(texcoord.x);		float y = texcoord.y - (float)floor(texcoord.y);		x = x &lt; 0 ? -x : x;		y = y &lt; 0 ? -y : y;		return GetColor(x * (width - 1), y * (height - 1)) / 255.0f;	&#125;    // 获取颜色，对不同通道纹理图片分别处理，以便于加载法线、高度纹理等    glm::vec4 GetColor(int x, int y) &#123;        if (x &lt; 0 || x &gt;= width || y &lt; 0 || y &gt;= height)            return glm::vec4(0, 0, 0, 255);        switch (channels) &#123;        case 1:            return GetColor1(x, y);            break;        case 2:            return GetColor2(x, y);            break;        case 3:            return GetColor3(x, y);            break;        case 4:            return GetColor4(x, y);            break;        default:            return glm::vec4(0, 0, 0, 255);        &#125;    &#125;    glm::vec4 GetColor1(int x, int y) &#123;        int xy = y * width + x;        return glm::vec4(*(data + xy), 0, 0, 255);    &#125;    glm::vec4 GetColor2(int x, int y) &#123;        int xy = 2 * (y * width + x);        return glm::vec4(*(data + xy), *(data + xy + 1), 0, 255);    &#125;    glm::vec4 GetColor3(int x, int y) &#123;        int xy = 3 * (y * width + x);        return glm::vec4(*(data + xy), *(data + xy + 1), *(data + xy + 2), 255);    &#125;    glm::vec4 GetColor4(int x, int y) &#123;        int xy = 4 * (y * width + x);        return glm::vec4(*(data + xy), *(data + xy + 1), *(data + xy + 2), *(data + xy + 3));    &#125;&#125;;#endif

然后修改 Shader 类，加入纹理成员，并修改片元着色器，将颜色改为纹理采样：
/** 着色器 Shader 类*/#pragma once#ifndef SHADER_H#define SHADER_H#include &quot;V2F.h&quot;#include &quot;Vertex.h&quot;#include &quot;Texture.h&quot;class Shader &#123;public:    Shader()    &#123;        ModelMatrix = glm::mat4(1.0f);        ViewMatrix = glm::mat4(1.0f);        ProjectMatrix = glm::mat4(1.0f);        texture = new Texture();    &#125;;    virtual ~Shader() = default;private:    glm::mat4 ModelMatrix;    glm::mat4 ViewMatrix;    glm::mat4 ProjectMatrix;    Texture* texture;public:    // 顶点着色器    virtual V2F VertexShader(const Vertex&amp; a2v) &#123;        V2F o;        // 变换到世界空间        o.worldPos = ModelMatrix * a2v.position;        // 变换到裁剪空间        o.windowPos = ProjectMatrix * ViewMatrix * o.worldPos;        // 法线变换        o.normal = glm::normalize(NormalMatrix * a2v.normal);        o.texcoord = a2v.texcoord;        o.color = a2v.color;        return o;    &#125;    // 片元着色器    virtual glm::vec4 FragmentShader(const V2F&amp; v) &#123;        if (texture-&gt;data)        &#123;            glm::vec4 color = texture-&gt;Sample2D(v.texcoord);            return color;        &#125;        return v.color;    &#125;    void setModelMatrix(const glm::mat4&amp; model) &#123;        ModelMatrix = model;    &#125;    void setViewMatrix(const glm::mat4&amp; view) &#123;        ViewMatrix = view;    &#125;    void setProjectMatrix(const glm::mat4&amp; project) &#123;        ProjectMatrix = project;    &#125;    void setTexture(std::string path)    &#123;        texture-&gt;LoadTexture(path);    &#125;&#125;;#endif

然后在 Draw 类中加入纹理图片路径：
class Draw &#123;private:    int Width;    int Height;    FrameBuffer* FrontBuffer;    Shader* shader;    glm::mat4 ViewPortMatrix;    std::string TexturePath;public:        ...            Draw(const int&amp; w, const int&amp; h, const std::string tpath) :        Width(w), Height(h), FrontBuffer(nullptr), shader(nullptr), TexturePath(tpath) &#123;&#125;        ...    // 初始化，设定帧缓冲区和 Shder    void Init() &#123;        if (FrontBuffer)            delete FrontBuffer;        if (shader)            delete shader;        ViewPortMatrix = GetViewPortMatrix(0, 0, Width, Height);        FrontBuffer = new FrameBuffer(Width, Height);        shader = new Shader();        shader-&gt;setTexture(TexturePath);    &#125;        ...        &#125;;

然后修改主函数：
#include &quot;Global.h&quot;#include &quot;Draw.h&quot;unsigned int SCR_WIDTH = 800;const unsigned int SCR_HEIGHT = 600;const std::string TEXTURE_PATH = &quot;D:\\TechStack\\ComputerGraphics\\RenderEngine\\Assets\\Textures\\box.png&quot;;const std::string OUT_PATH = &quot;D:\\TechStack\\ComputerGraphics\\RenderEngine\\Results\\&quot;;const std::string FILE_NAME = &quot;texture_box2.png&quot;;int main()&#123;    Draw dw(SCR_WIDTH, SCR_HEIGHT, TEXTURE_PATH);    // 初始化渲染器    dw.Init();    dw.ClearBuffer(glm::vec4(0, 0, 0, 1));        // 设置观察矩阵    dw.setViewMatrix(        GetViewMatrix(glm::vec3(0, 0, 5), glm::vec3(0, 0, -1), glm::vec3(1, 0, 0), glm::vec3(0, 1, 0)));    // 设置投影矩阵    dw.setProjectMatrix(        GetPerspectiveMatrix(glm::radians(60.0f), (float)SCR_WIDTH / SCR_HEIGHT, 0.3f, 100));    // 创建一个立方体    Mesh Box = CreateBox(glm::vec3(0.0, 0.0, 0.0), 0.5);    // 让模型在原点绕着(0,1,0)旋转angle度    float angle = 45.0;    dw.setModelMatrix(glm::rotate(glm::mat4(1.0f), glm::radians(angle), glm::vec3(0.0, 1.0, 0.0)));    // 绘制    dw.DrawMesh(Box);    // 写出图片    std::string filepath = OUT_PATH + FILE_NAME;    dw.show(filepath);    return 0;&#125;

得到的效果：

3 透视纹理映射可以看出当立方体的面不正对我们的时候，纹理出现了变形。这是因为我们对顶点插值时使用的插值参数是通过顶点间的 x, y 坐标求出的，但是透视投影之后纹理坐标并不跟投影点 x , y 坐标线性相关。这种直接插值纹理坐标的方式被称为仿射映射，解决办法是做透视映射，具体可以查看深入探索透视纹理映射这篇文章。
总之实际的做法就是在透视除法时，将除了屏幕坐标之外的所有值都除以 w 值，然后再进行插值，这样就可以得到正确的纹理映射关系，最后在扫描线函数中，调用片元着色器之前再乘以 w 恢复即可：
//透视除法void PerspectiveDivision(V2F&amp; v) &#123;    // 记录下原本的 w    v.w = v.windowPos.w;    v.windowPos /= v.windowPos.w;    v.windowPos.w = 1.0f;    // OpenGL 的 NDC 中 Z 的范围是[0,1]    v.windowPos.z = (v.windowPos.z + 1.0) * 0.5;    //其他属性也要除以 w，以便于正确插值，之后在片元着色器之前再乘以原本的 w 恢复    v.worldPos /= v.w;    v.normal /= v.w;    v.texcoord /= v.w;    v.color /= v.w;&#125;...void ScanLine(const V2F&amp; left, const V2F&amp; right) &#123;    int length = right.windowPos.x - left.windowPos.x;    for (int i = 0; i &lt; length; ++i) &#123;        V2F v = V2F::lerp(left, right, (float)i / length);        v.windowPos.x = left.windowPos.x + i;        v.windowPos.y = left.windowPos.y;        //深度测试        float depth = FrontBuffer-&gt;GetDepth(v.windowPos.x, v.windowPos.y);        if (v.windowPos.z &lt;= depth) &#123;            v.worldPos *= v.w;            v.normal *= v.w;            v.texcoord *= v.w;            v.color *= v.w;            FrontBuffer-&gt;WritePoint(v.windowPos.x, v.windowPos.y, shader-&gt;FragmentShader(v));            FrontBuffer-&gt;WriteDepth(v.windowPos.x, v.windowPos.y, v.windowPos.z);        &#125;    &#125;&#125;

得到的效果：

目前我们已经基本实现了一个最简单的渲染管线，不过还有很多功能没有加入，这一节开始来完善我们的渲染管线。首先在之前的实现中，正方体大多数情况下都只有 3 个面正对我们，其他三个面是看不见的，也就完全不需要渲染，为了之后应对更复杂的模型和场景，提高渲染效率，我们需要先实现剔除和裁剪算法。

1 剔除和裁剪概览在整个渲染管线中，需要进行多次剔除与裁剪，分别是：视锥剔除、正面&#x2F;背面剔除、齐次裁剪。

视锥剔除一般发生在 CPU 阶段，通过 AABB、OBB 等将物体包围起来，然后与视锥体做碰撞检测，可以直接剔除掉完全不可见的物体，运算量较低但精度也较低。
正面&#x2F;背面剔除在顶点着色器之后，齐次裁剪之前进行，将不需要渲染的图元直接剔除掉；一般来说这一步也可以在齐次裁剪之后进行，因为操作比较简单，所以可以在世界空间运算也可以在 NDC 中运算，取决于管线的设计。
齐次裁剪自然是在裁剪空间中进行，即顶点着色器之后，透视除法之前。在透视除法之前是因为如果有物体在摄像机的位置，会出现 w &#x3D; 0 ，做透视除法的时候会出现除零错误。这一阶段是将在视口外的图元丢弃，一部分在视口内的图元，会进行裁剪，生成新的多边形。当然做裁剪的性能消耗也不小，很多情况下裁剪之后并不比直接把原来的多边形画出来丢弃一部分更快，尤其是 GPU 并不适合做这种判断条件比较多的工作。现代 GPU 通常是用一个比视口大很多（10倍以上？）的虚拟视口来裁剪，那种超出一点点的，就直接画了吧，GPU 性能没那么捉襟见肘。

2 视锥剔除视锥剔除首先要计算物体的包围盒，一般来说如果场景管理使用 BVH 的话，层次包围盒已经计算好了，直接遍历整个 BVH 树即可。然后获得视锥体的六个面的方程，用包围盒和六个面进行碰撞检测，具体实现可以有很多种方法，这里我们实现世界空间下的视锥剔除，流程如下：

计算包围要绘制物体的 AABB（世界空间），实际我们逐图元计算，剔除掉完全在视锥体外的图元，这样一来就和后面的齐次裁剪中的剔除所做的工作几乎一样了，但这里只是为了学习原理，实际的渲染管线中是利用 BVH 等来剔除掉完全不在视锥体内的物体，而图元是在齐次裁剪的时候剔除的
获得视锥体六个面的平面方程（世界空间）
判断 AABB 的顶点在六个面的内侧还是外侧，也可以判断最小点和最大点，实现方法不唯一
剔除掉所有顶点完全在某一面外侧的物体，我们这里是图元

2.1 获取视锥平面方程那么如何获取视锥体六个平面的方程呢？通过 MVP 变换矩阵就可以直接得出，并且使用 MVP 三个矩阵的不同组合可以得出不同空间下的视锥体平面方程。具体推导的原文可以查看：Fast Extraction of Viewing Frustum Planes from the WorldView-Projection Matrix
我们首先定义一个顶点 $v &#x3D; (x, y, z, w&#x3D;1)$，以及一个 4 * 4 的矩阵 $$M &#x3D; m_{ij}$$，这个矩阵可以是投影矩阵 P，也可以是 VP，还可以是 MVP，总之经过矩阵 $M$ 后，顶点 $v$ 就被转换到了一个规范立方体中变为 $v’ &#x3D; (x’, y’, z’, w’)$，这个过程可以写为：

规范立方体的范围是 [-w’, w’]，因此如果这个顶点在立方体内，那么必须满足：

-w’ &lt; x’ &lt; w’
-w’ &lt; y’ &lt; w’
-w’ &lt; z’ &lt; w’

这实际上描述了顶点和视锥体六个平面的关系，原文中以下表列出：

现在以顶点和左侧平面的关系为例，只需要判断 -w’ &lt; x’ 就可以了，根据矩阵乘法，可以得出：$$-w’ &lt; x’ \Rightarrow -(row4 · v) &lt; (row1 · v)$$于是可以进一步得到：$$(row1 + row4) · v &gt; 0$$将矩阵元素带入展开可以写成：$$(m_{11}+m_{41})*x + (m_{12}+m_{42})*y + (m_{13}+m_{43})*z + (m_{14}+m_{44})*w &gt; 0$$由于 $w &#x3D; 1$，因此可以写为：$$(m_{11}+m_{41})*x + (m_{12}+m_{42})*y + (m_{13}+m_{43})*z + (m_{14}+m_{44}) &gt; 0$$这实际上已经得到了视锥体左平面的方程，因为空间中一个平面可以表示为 $$Ax + By + Cz + D &#x3D; 0$$，所以视锥体左平面的方程中：$$A &#x3D; m_{11}+m_{41},\ B &#x3D; m_{12}+m_{42},\ C &#x3D; m_{13}+m_{43},\ D &#x3D; m_{14}+m_{44}$$类似的可以得出其他几个面的方程：


上面说过， 4 * 4 的矩阵 $$M$$ 可以是投影矩阵 P，也可以是 VP，还可以是 MVP，不同的组合得到的视锥体平面方程是不同空间下的：

当矩阵是 P 时，得到的是观察空间下的平面
当矩阵是 VP 时，得到的是世界空间下的平面
当矩阵是 MVP 时，得到的是模型空间下的平面

2.2 判断顶点与平面的关系顶点与平面的关系判断非常简单，类似于二维中点和直线的关系，将顶点坐标 $(x, y, z)$ 带入平面方程计算得到点到平面的距离 $$d &#x3D; Ax + By + Cz + D$$：

d &gt; 0 时，点在平面法向所指的区域
d &lt; 0 时，点在平面法向反方向所指的区域
d &#x3D; 0 时，点在平面上

2.3 实现我们使用世界空间下的视锥体剔除，首先在 math.h 中加入视锥体六个平面的方程以及点和平面的关系判断函数：
// 视锥体的六个平面方程（世界空间下，传入的是 VP 矩阵），用于视锥剔除// 所得的平面法向都是指向视锥体内部的void ViewingFrustumPlanes(std::vector&lt;glm::vec4&gt;&amp; result, const glm::mat4&amp; vp) &#123;    //左侧      result[0].x = vp[0][3] + vp[0][0];    result[0].y = vp[1][3] + vp[1][0];    result[0].z = vp[2][3] + vp[2][0];    result[0].w = vp[3][3] + vp[3][0];    //右侧    result[1].x = vp[0][3] - vp[0][0];    result[1].y = vp[1][3] - vp[1][0];    result[1].z = vp[2][3] - vp[2][0];    result[1].w = vp[3][3] - vp[3][0];    //上侧    result[2].x = vp[0][3] - vp[0][1];    result[2].y = vp[1][3] - vp[1][1];    result[2].z = vp[2][3] - vp[2][1];    result[2].w = vp[3][3] - vp[3][1];    //下侧    result[3].x = vp[0][3] + vp[0][1];    result[3].y = vp[1][3] + vp[1][1];    result[3].z = vp[2][3] + vp[2][1];    result[3].w = vp[3][3] + vp[3][1];    //Near    result[4].x = vp[0][3] + vp[0][2];    result[4].y = vp[1][3] + vp[1][2];    result[4].z = vp[2][3] + vp[2][2];    result[4].w = vp[3][3] + vp[3][2];    //Far    result[5].x = vp[0][3] - vp[0][2];    result[5].y = vp[1][3] - vp[1][2];    result[5].z = vp[2][3] - vp[2][2];    result[5].w = vp[3][3] - vp[3][2];&#125;//点到平面距离 d =  Ax + By + Cz + D;// d &lt; 0 点在平面法向反方向所指的区域// d &gt; 0 点在平面法向所指的区域// d = 0 在平面上// d &lt; 0 返回 falsebool Point2Plane(const glm::vec3&amp; v, const glm::vec4&amp; p) &#123;    float sb = p.x * v.x + p.y * v.y + p.z * v.z + p.w;    return sb &gt;= 0;&#125;

为了便于管理，我们新建一个 Cull.h 来管理各类剔除函数，目前只有视锥体剔除：
//世界空间的视锥剔除bool WorldFrustumCull(const std::vector&lt;glm::vec4&gt; ViewPlanes, const glm::vec4&amp; v1, const glm::vec4&amp; v2, const glm::vec4&amp; v3)&#123;    // 如果三个顶点都在某一个平面外侧，则剔除掉    if (!Point2Plane(v1, ViewPlanes[0]) &amp;&amp; !Point2Plane(v2, ViewPlanes[0]) &amp;&amp; !Point2Plane(v3, ViewPlanes[0])) &#123;        return false;    &#125;    if (!Point2Plane(v1, ViewPlanes[1]) &amp;&amp; !Point2Plane(v2, ViewPlanes[1]) &amp;&amp; !Point2Plane(v3, ViewPlanes[1])) &#123;        return false;    &#125;    if (!Point2Plane(v1, ViewPlanes[2]) &amp;&amp; !Point2Plane(v2, ViewPlanes[2]) &amp;&amp; !Point2Plane(v3, ViewPlanes[2])) &#123;        return false;    &#125;    if (!Point2Plane(v1, ViewPlanes[3]) &amp;&amp; !Point2Plane(v2, ViewPlanes[3]) &amp;&amp; !Point2Plane(v3, ViewPlanes[3])) &#123;        return false;    &#125;    if (!Point2Plane(v1, ViewPlanes[4]) &amp;&amp; !Point2Plane(v2, ViewPlanes[4]) &amp;&amp; !Point2Plane(v3, ViewPlanes[4])) &#123;        return false;    &#125;    // 远平面只保留完全在内的图元，部分在内的直接丢掉    if (!Point2Plane(v1, ViewPlanes[5]) || !Point2Plane(v2, ViewPlanes[5]) || !Point2Plane(v3, ViewPlanes[5])) &#123;        return false;    &#125;    return true;&#125;

然后在渲染流程中加入视锥体剔除，一般来说应该在 CPU 阶段进行，但是我们为了方便将视锥体剔除放在顶点着色器之后，因为顶点着色器之后才知道世界空间下的坐标：
class Draw &#123;private:    int Width;    int Height;    FrameBuffer* FrontBuffer;    Shader* shader;    glm::mat4 ViewPortMatrix;    std::string TexturePath;    // 视锥体剔除用到的视锥体平面    std::vector&lt;glm::vec4&gt; ViewPlanes;        // 剔除开关    bool FrustumCull;public:    Draw(const int&amp; w, const int&amp; h) :        Width(w), Height(h), FrontBuffer(nullptr), shader(nullptr), FrustumCull(true)    &#123;        ViewPlanes.resize(6, glm::vec4(0));    &#125;    Draw(const int&amp; w, const int&amp; h, const std::string tpath) :        Width(w), Height(h), FrontBuffer(nullptr), shader(nullptr), TexturePath(tpath), FrustumCull(true)    &#123;        ViewPlanes.resize(6, glm::vec4(0));    &#125;    ~Draw() &#123;        if (FrontBuffer)            delete FrontBuffer;        if (shader)            delete shader;        FrontBuffer = nullptr;        shader = nullptr;    &#125;    ...    void DisableFrustumCull()    &#123;        FrustumCull = false;    &#125;    void EnableFrustumCull()    &#123;        FrustumCull = true;    &#125;            // 获取视锥体六个平面    void UpdateViewPlanes() &#123;        ViewingFrustumPlanes(ViewPlanes, ProjectMatrix * ViewMatrix);    &#125;    // 画网格    void DrawMesh(const Mesh&amp; mesh) &#123;        if (mesh.EBO.empty()) &#123;            return;        &#125;        for (int i = 0; i &lt; mesh.EBO.size(); i += 3) &#123;            Vertex p1, p2, p3;            p1 = mesh.VBO[mesh.EBO[i]];            p2 = mesh.VBO[mesh.EBO[i + 1]];            p3 = mesh.VBO[mesh.EBO[i + 2]];            //顶点着色器变换到裁剪空间            V2F v1, v2, v3;            v1 = shader-&gt;VertexShader(p1);            v2 = shader-&gt;VertexShader(p2);            v3 = shader-&gt;VertexShader(p3);            // 视锥体剔除            UpdateViewPlanes();            if (FrustumCull &amp;&amp; !WorldFrustumCull(ViewPlanes, v1.worldPos / v1.w, v2.worldPos / v2.w, v3.worldPos / v3.w))            &#123;                continue;            &#125;            //做透视除法，变换到NDC            PerspectiveDivision(v1);            PerspectiveDivision(v2);            PerspectiveDivision(v3);            // 视口变换，变换到屏幕空间            v1.windowPos = ViewPortMatrix * v1.windowPos;            v2.windowPos = ViewPortMatrix * v2.windowPos;            v3.windowPos = ViewPortMatrix * v3.windowPos;            // 光栅化            ScanLineTriangle(v1, v2, v3);        &#125;    &#125;        ...&#125;

3 正面&#x2F;背面剔除经过视锥体剔除将所有完全不在视锥体内的图元剔除掉之后，剩下的图元要么完全在视锥体内，要么部分在视锥体内，对于部分在视锥体内的图元需要进行裁剪，但因为裁剪是计算量较大的操作，为了进一步减少无用的运算，在此之前还要根据需要将背面（有时也需要将正面的剔除）的图元剔除掉，这一步操作比较简单，我们在世界空间计算。根据观察方向和图元的法线方向的夹角来判断图元是正对我们还是背对我们，原理在之前的 RTR 总结中有介绍，这里不再赘述。
也可以先做齐次裁剪，透视除法之后在 NDC 中进行正面&#x2F;背面剔除，但要注意 NDC 是左手系，观察方向恒定为 (0, 0, 1)。无论在哪里计算，原理都是一样的。
在 Cull.h 中加入正面&#x2F;背面剔除函数：
// 正面/背面enum Face &#123;    Back,    Front&#125;;// 世界空间的面剔除，剔除正向面或者逆向面bool WorldFaceCull(Face face, const glm::vec4&amp; v1, const glm::vec4&amp; v2, const glm::vec4&amp; v3) &#123;    // 叉乘得到法向量    glm::vec3 tmp1 = glm::vec3(v2.x - v1.x, v2.y - v1.y, v2.z - v1.z);    glm::vec3 tmp2 = glm::vec3(v3.x - v1.x, v3.y - v1.y, v3.z - v1.z);    glm::vec3 normal = glm::normalize(glm::cross(tmp1, tmp2));    // 世界空间下的观察方向    glm::vec3 view = camera-&gt;Front;    // 也可以在NDC中剔除，这时观察方向恒定为(0, 0, 1)，但上面的叉乘顺序顺序要颠倒一下，因为NDC是左手系    //glm::vec3 view = glm::vec3(0, 0, 1);    if (face == Back)        return glm::dot(normal, view) &gt; 0;    else        return glm::dot(normal, view) &lt; 0;&#125;

然后在渲染流程中加入正面&#x2F;背面剔除：
...    // 剔除开关bool FrustumCull;bool FaceCull;Face CullMode;...    void DisableFaceCull()&#123;    FaceCull = false;&#125;void EnableFaceCull(Face f)&#123;    FaceCull = true;    CullMode = f;&#125;...void DrawMesh(const Mesh&amp; mesh) &#123;    if (mesh.EBO.empty()) &#123;        return;    &#125;    for (int i = 0; i &lt; mesh.EBO.size(); i += 3) &#123;        Vertex p1, p2, p3;        p1 = mesh.VBO[mesh.EBO[i]];        p2 = mesh.VBO[mesh.EBO[i + 1]];        p3 = mesh.VBO[mesh.EBO[i + 2]];        // 顶点着色器变换到裁剪空间        V2F v1, v2, v3;        v1 = shader-&gt;VertexShader(p1);        v2 = shader-&gt;VertexShader(p2);        v3 = shader-&gt;VertexShader(p3);        // 视锥体剔除        UpdateViewPlanes();        if (FrustumCull &amp;&amp; !WorldSpaceCull(ViewPlanes, v1.worldPos / v1.w, v2.worldPos / v2.w, v3.worldPos / v3.w))        &#123;            continue;        &#125;                // 正面/背面剔除        if (FaceCull &amp;&amp; WorldFaceCull(CullMode, v1.worldPos, v2.worldPos, v3.worldPos))        &#123;            continue;        &#125;        // 做透视除法，变换到NDC        PerspectiveDivision(v1);        PerspectiveDivision(v2);        PerspectiveDivision(v3);        // 视口变换，变换到屏幕空间        v1.windowPos = ViewPortMatrix * v1.windowPos;        v2.windowPos = ViewPortMatrix * v2.windowPos;        v3.windowPos = ViewPortMatrix * v3.windowPos;        // 光栅化        ScanLineTriangle(v1, v2, v3);    &#125;&#125;

然后修改主函数：
...        // 初始化渲染器    dw = new Draw(SCR_WIDTH, SCR_HEIGHT, TEXTURE_PATH);    dw-&gt;Init();    dw-&gt;ClearBuffer(glm::vec4(0, 0, 0, 1));    // 开启视锥体剔除,实际上默认已经开启    dw-&gt;EnableFrustumCull();    // 开启背面剔除，背面剔除默认关闭，需要手动开启并指定剔除模式    Face CullMode = Back;    dw-&gt;EnableFaceCull(CullMode);...

4 齐次裁剪最后是比较麻烦的齐次裁剪，之前说过，渲染管线中进行齐次裁剪的位置是投影之后，透视除法之前，我们知道，在世界空间和观察空间中，一个点的坐标是 (X, Y, Z, 1)，经过透视投影之后变为 (X’, Y’, Z’, -Z)，再除以 W 坐标变化到 NDC 中 (X’&#x2F;-Z, Y’&#x2F;-Z, Z’&#x2F;-Z, 1)。这其中，如果一个点在观察者的身后，其观察坐标 Z 会大于 0（观察空间是右手系），那么透视投影之后 W 会小于 0，进行透视除法会导致顶点的 X, Y 坐标上下左右翻转。如下图：

并且如果一个物体在相机平面上，会在透视除法时导致除零错误。
透视投影之后，透视除法之前的坐标空间被称为裁剪空间，也叫齐次（裁剪）空间，它实质上是一个四维空间，变换到齐次空间的顶点之间仍然是线性相关的（可以直接使用线性插值而不是透视插值）。这是因为透视除法将所有坐标除以 w 才会真正破坏顶点之间的线性关系，所以也有这种说法：真正的投影是通过透视除法完成的。
这时，在视锥体中的点一定满足如下条件：

$-w &lt; x,y,z &lt; w$
$near&lt;w&lt;far$

如果不满足这个条件的点，就需要被剔除，因此我们可以写出代码：
// 裁剪空间剔除bool ClipSpaceCull(const glm::vec4&amp; v1, const glm::vec4&amp; v2, const glm::vec4&amp; v3)&#123;    // 三个点的w都在near或far之外则需要剔除    if (v1.w &lt;= camera-&gt;Near &amp;&amp; v2.w &lt;= camera-&gt;Near &amp;&amp; v3.w &lt;= camera-&gt;Near)        return false;    if (v1.w &gt;= camera-&gt;Far &amp;&amp; v2.w &lt;= camera-&gt;Far &amp;&amp; v3.w &lt;= camera-&gt;Far)        return false;    // 任意一个点在规范立方体内则不需要剔除，等待进行下一步裁剪    if (v1.x &lt;= v1.w || v1.y &lt;= v1.w || v1.z &lt;= v1.w)        return true;    if (v2.x &lt;= v2.w || v2.y &lt;= v2.w || v2.z &lt;= v2.w)        return true;    if (v3.x &lt;= v3.w || v3.y &lt;= v3.w || v3.z &lt;= v3.w)        return true;    return false;&#125;

接下来是对没有被剔除的片元进行裁剪，使用 Sutherland-Hodgeman 裁剪算法，也叫做逐边裁剪算法，它的原理很简单，在二维中就是每次使用裁剪框的一条边去裁剪多边形的每一条边，生成新的顶点并作为下一条裁剪边的输入，如下图：

这个算法在齐次空间也同样适用（而且可以推广到任意维），与二维的区别是，裁剪平面变为了 6 个，而不是四条线了。
使用点到平面的距离来判断点在平面的内外，和之前的计算方法类似，之前的计算方法是：
bool Point2Plane(const glm::vec3&amp; v, const glm::vec4&amp; p) &#123;    float sb = p.x * v.x + p.y * v.y + p.z * v.z + p.w;    return sb &gt;= 0;&#125;

该函数只适用于世界空间或者观察空间等 w 为 1 的空间中，而我们现在是在裁剪空间，顶点的 w 值不为 1， 因此不能省略顶点的 w，所以需要重新写一个函数：
// 判断点是否在裁剪平面法线所指方向，即内部bool Inside(const glm::vec4&amp; line, const glm::vec4&amp; p) &#123;    return line.x * p.x + line.y * p.y + line.z * p.z + line.w * p.w &gt;= 0;&#125;

同时我们还需要一个函数直接判断三个顶点是否都在视口内，这样就无需裁剪了，也很简单：
// 判断是否所有顶点都在内部bool AllVertexsInside(const std::vector&lt;V2F&gt; v) &#123;    for (int i = 0; i &lt; v.size(); i++) &#123;        if (fabs(v[i].windowPos.x) &gt; fabs(v[i].windowPos.w))            return false;        if (fabs(v[i].windowPos.y) &gt; fabs(v[i].windowPos.w))            return false;        if (fabs(v[i].windowPos.z) &gt; fabs(v[i].windowPos.w))            return false;    &#125;    return true;&#125;

接下来是计算两个点连线与平面的交点，这可以通过插值实现，分别在一个平面两侧的两个点 A 和 B，它们连线与平面的交点 C 可以通过权重 da &#x2F; (da - db) 从 A 到 B 插值得到。其中 da 和 db 分别是点 A 和 B 到裁剪平面的距离，可以通过上面函数的方法计算得到：
//交点，通过端点插值得到V2F Intersect(const V2F&amp; v1, const V2F&amp; v2, const glm::vec4&amp; line) &#123;    float da = v1.windowPos.x * line.x + v1.windowPos.y * line.y + v1.windowPos.z * line.z + v1.windowPos.w * line.w;    float db = v2.windowPos.x * line.x + v2.windowPos.y * line.y + v2.windowPos.z * line.z + v2.windowPos.w * line.w;    float weight = da / (da - db);    return V2F::lerp(v1, v2, weight);&#125;

最后是 Sutherland-Hodgeman 裁剪算法，代码很好理解：
// SutherlandHodgeman裁剪算法// 输入三个顶点，输出裁剪后的顶点组std::vector&lt;V2F&gt; SutherlandHodgeman(const V2F&amp; v1, const V2F&amp; v2, const V2F&amp; v3) &#123;    std::vector&lt;V2F&gt; output = &#123; v1,v2,v3 &#125;;    if (AllVertexsInside(output)) &#123;        return output;    &#125;    for (int i = 0; i &lt; ViewLines.size(); ++i) &#123;        std::vector&lt;V2F&gt; input(output);        output.clear();        for (int j = 0; j &lt; input.size(); ++j) &#123;            V2F current = input[j];            V2F last = input[(j + input.size() - 1) % input.size()];            if (Inside(ViewLines[i], current.windowPos)) &#123;                if (!Inside(ViewLines[i], last.windowPos)) &#123;                    V2F intersecting = Intersect(last, current, ViewLines[i]);                    output.push_back(intersecting);                &#125;                output.push_back(current);            &#125;            else if (Inside(ViewLines[i], last.windowPos)) &#123;                V2F intersecting = Intersect(last, current, ViewLines[i]);                output.push_back(intersecting);            &#125;        &#125;    &#125;    return output;&#125;

最后，在渲染流程中加入裁剪，因为裁剪后生成了新的顶点，所以要做比较多的修改：
// 画网格void DrawMesh(const Mesh&amp; mesh) &#123;    if (mesh.EBO.empty()) &#123;        return;    &#125;    for (int i = 0; i &lt; mesh.EBO.size(); i += 3) &#123;        Vertex p1, p2, p3;        p1 = mesh.VBO[mesh.EBO[i]];        p2 = mesh.VBO[mesh.EBO[i + 1]];        p3 = mesh.VBO[mesh.EBO[i + 2]];        // 顶点着色器变换到裁剪空间        V2F v1, v2, v3;        v1 = shader-&gt;VertexShader(p1);        v2 = shader-&gt;VertexShader(p2);        v3 = shader-&gt;VertexShader(p3);        // 视锥体剔除        UpdateViewPlanes();        if (FrustumCull &amp;&amp; !WorldFrustumCull(ViewPlanes, v1.worldPos / v1.w, v2.worldPos / v2.w, v3.worldPos / v3.w))        &#123;            continue;        &#125;        // 正面/背面剔除        if (FaceCull &amp;&amp; WorldFaceCull(CullMode, v1.worldPos, v2.worldPos, v3.worldPos))        &#123;            continue;        &#125;        // 裁剪空间剔除        if (!ClipSpaceCull(v1.windowPos, v2.windowPos, v3.windowPos)) &#123;            continue;        &#125;        // 裁剪        std::vector&lt;V2F&gt; clipingVertexs = SutherlandHodgeman(v1, v2, v3);        // 做透视除法，变换到NDC        for (int i = 0; i &lt; clipingVertexs.size(); ++i) &#123;            PerspectiveDivision(clipingVertexs[i]);        &#125;        // 渲染        int n = clipingVertexs.size() - 3 + 1;        for (int i = 0; i &lt; n; ++i) &#123;            V2F tempv1 = clipingVertexs[0];            V2F tempv2 = clipingVertexs[i + 1];            V2F tempv3 = clipingVertexs[i + 2];            // 视口变换，变换到屏幕空间            tempv1.windowPos = ViewPortMatrix * tempv1.windowPos;            tempv2.windowPos = ViewPortMatrix * tempv2.windowPos;            tempv3.windowPos = ViewPortMatrix * tempv3.windowPos;            // 画线            if (renderMode == Line) &#123;                DrawLine(tempv1, tempv2);                DrawLine(tempv2, tempv3);                DrawLine(tempv3, tempv1);            &#125;            // 光栅化            else &#123;                ScanLineTriangle(tempv1, tempv2, tempv3);            &#125;        &#125;    &#125;&#125;

这里为了能更方便看出裁剪效果，我们加入了渲染模式选项：
// 渲染模式enum RenderMode &#123;    Line,    // 仅绘制边框    Fill    // 绘制图形&#125;;// 改变渲染模式void ChangeRenderMode()&#123;    if (renderMode == Fill)        renderMode = Line;    else        renderMode = Fill;&#125;

然后新增一个画线算法，使用 BresenhamLine 画线算法，原理比较简单，具体可以查看Bresenham 算法原理，代码如下：
/*    ****************** BresenhamLine画线算法 ********************/void DrawLine(const V2F&amp; from, const V2F&amp; to)&#123;    int dx = to.windowPos.x - from.windowPos.x;    int dy = to.windowPos.y - from.windowPos.y;    int Xstep = 1, Ystep = 1;    if (dx &lt; 0)    &#123;        Xstep = -1;        dx = -dx;    &#125;    if (dy &lt; 0)    &#123;        Ystep = -1;        dy = -dy;    &#125;    int currentX = from.windowPos.x;    int currentY = from.windowPos.y;    V2F tmp;    //斜率小于1    if (dy &lt;= dx)    &#123;        int P = 2 * dy - dx;        for (int i = 0; i &lt;= dx; ++i)        &#123;            tmp = V2F::lerp(from, to, ((float)(i) / dx));            FrontBuffer-&gt;WritePoint(currentX, currentY, glm::vec4(1, 0, 0, 1));            currentX += Xstep;            if (P &lt;= 0)                P += 2 * dy;            else            &#123;                currentY += Ystep;                P += 2 * (dy - dx);            &#125;        &#125;    &#125;    //斜率大于1，利用对称性画    else    &#123;        int P = 2 * dx - dy;        for (int i = 0; i &lt;= dy; ++i)        &#123;            tmp = V2F::lerp(from, to, ((float)(i) / dy));            FrontBuffer-&gt;WritePoint(currentX, currentY, glm::vec4(1, 0, 0, 1));            currentY += Ystep;            if (P &lt;= 0)                P += 2 * dx;            else            &#123;                currentX += Xstep;                P -= 2 * (dy - dx);            &#125;        &#125;    &#125;&#125;

5 测试现在来测试一下上面实现的裁剪吧，因为可以只渲染边框，可以清楚的看到每个面的渲染情况。
我们首先关闭背面剔除，得到的结果：

然后开启背面剔除：

试试开启正面剔除：

接下来将正方体移动到屏幕边缘，测试裁剪效果：

可以看到裁剪产生的新的图元。

到目前为止我们的渲染管线已经基本为完整了，从模型加载到顶点着色器，再经过裁剪到片元着色器，但在片元着色器中我们目前还只是输出顶点颜色或者纹理值，还没有加入光照计算，这一节我们就来加入光照的计算。最简单的 Blinn Phong 模型我们已经非常熟悉了，所以这一节的重点并不是光照的计算，而是了解三种光源是如何实现的。

1 光源概述在 RTR 一书中，作者将光源分为三种，分别是：平行光（direction）、点光源（point）和聚光灯（spot）。我们分别来实现这三种光源。
2 准备工作在实现光源之前我们需要一些函数和变量，首先是在 Global.h 中定义的环境光项：
// 环境光const glm::vec3 Ambient = glm::vec3(0.5, 0.5, 0.5);

还有计算反射方向的函数：
// 反射的计算 2n * cos(n,l) - l = r// lightDir是光指向片元的方向glm::vec3 reflect(const glm::vec3&amp; lightDir, const glm::vec3&amp; normal) &#123;    return lightDir - 2 * glm::dot(normal, lightDir) * normal;&#125;

3 平行光在实现各类光源之前我们先实现一个光源基类，这样其他光源都派生自该基类：
// 光源基类class Light &#123;public:    glm::vec3 Position;    glm::vec3 Color;    glm::vec3 Specular;    glm::vec3 Direction;    float Intensity;    virtual ~Light() &#123;    &#125;    Light(        const glm::vec3&amp; pos = glm::vec3(0, 0, 0),        const glm::vec3&amp; color = glm::vec3(1, 1, 1),        const glm::vec3&amp; specular = glm::vec3(1, 1, 1),        const glm::vec3&amp; dir = glm::vec3(0, -1, 0),        const float&amp; i = 1.0f) :        Position(pos),        Color(color),        Specular(specular),        Direction(dir),        Intensity(i)    &#123;&#125;&#125;;

然后是平行光，平行光不需要位置：
// 平行光，不需要位置class DirectionLight : public Light &#123;public:    DirectionLight(        const glm::vec3&amp; dir = glm::normalize(glm::vec3(0, -1, 1)),        const glm::vec3&amp; color = glm::vec3(1, 1, 1),        const glm::vec3&amp; specular = glm::vec3(1, 1, 1),        const float&amp; i = 1.0f) :         Light(glm::vec3(0, 0, 0), color, specular, dir, i)    &#123;&#125;&#125;;

然后我们新建一个 BlinnPhongShader 类继承于基本的 Shader 类，在其中实现平行光的计算，并修改片元着色器：
#pragma once#ifndef BLINNPHONG_H#define BLINNPHONG_H#include &quot;Shader.h&quot;#include &quot;Light.h&quot;#include &quot;Material.h&quot;#include &quot;Camera.h&quot;class BlinnPhongShader : public Shader &#123;public:    BlinnPhongShader() = default;    virtual ~BlinnPhongShader() = default;    // 向量都要是单位向量    // ViewDir是片元指向摄像机的方向    static glm::vec3 CalcDirLight(        const DirectionLight&amp; dirLight,        const glm::vec3&amp; worldNormal,        const glm::vec3&amp; worldViewDir,        const glm::vec3&amp; albedo    ) &#123;        float diff = max(glm::dot(worldNormal, -dirLight.Direction), 0);        glm::vec3 halfDir = glm::normalize(worldViewDir - dirLight.Direction);        float spec = pow(max(glm::dot(halfDir, worldNormal), 0), currentMat-&gt;Gloss);        glm::vec3 diffuse = dirLight.Color * diff * albedo;        glm::vec3 specular = dirLight.Specular * spec;        return (diffuse + specular) * dirLight.Intensity;    &#125;    glm::vec4 FragmentShader(const V2F&amp; v) &#123;        glm::vec3 albedo = texture-&gt;Sample2D(v.texcoord) * currentMat-&gt;Color;        glm::vec3 worldNormal = glm::normalize(v.normal);        glm::vec3 worldViewDir = glm::normalize(camera-&gt;Position - glm::vec3(v.worldPos));        glm::vec3 result = Ambient * albedo;        for (int i = 0; i &lt; dirLtNums; i++)            result += BlinnPhongShader::CalcDirLight(*(dirLights + i), worldNormal, worldViewDir, albedo);        return glm::vec4(result, 1.0);    &#125;&#125;;#endif

然后在主函数中加入一个平行光：
// 平行光源DirectionLight dir(glm::vec3(0, 0, 1), glm::vec3(1, 1, 1), glm::vec3(1, 1, 1), 1.0);dirLights = &amp;dir;dirLtNums = 1;// 使用光照ShaderBlinnPhongShader shader;// 加载模型...

查看效果：

4 点光源点光源无所谓方向，它向四周均匀发光，光照强度和距离成反比，我们使用常数项、一次项和二次项来控制光照衰减，首先是点光源类：
// 点光源，不需要方向class PointLight : public Light &#123;public:    float Constant;        //常数项    float Linear;        //一次项    float Quadratic;    // 二次项    PointLight(        const glm::vec3&amp; pos = glm::vec3(0, 0, 0),        const glm::vec3&amp; color = glm::vec3(1, 1, 1),        const glm::vec3&amp; specular = glm::vec3(1, 1, 1),        const float&amp; i = 1.0f,        const float&amp; c = 1.0f,        const float&amp; l = 0.09f,        const float&amp; q = 0.032f    ) : Light(pos, color, specular, glm::vec3(0, 0, 0), i), Constant(c), Linear(l), Quadratic(q)    &#123;&#125;&#125;;

然后是计算点光源：
// 计算点光源static glm::vec3 CalcPtLight(    const PointLight&amp; ptLight,    const glm::vec3&amp; worldPos,    const glm::vec3&amp; worldNormal,    const glm::vec3&amp; worldViewDir,    const glm::vec3&amp; albedo) &#123;    // 到光源的距离    float distance = glm::distance(worldPos, ptLight.Position);    // 强度衰减因子    float attenuation = 1.0 / (ptLight.Constant + ptLight.Linear * distance +                               ptLight.Quadratic * (distance * distance));    glm::vec3 lightDir = glm::normalize(worldPos - ptLight.Position);    float diff = max(glm::dot(worldNormal, -lightDir), 0);    glm::vec3 halfDir = glm::normalize(worldViewDir - lightDir);    float spec = pow(max(glm::dot(halfDir, worldNormal), 0), currentMat-&gt;Gloss);    glm::vec3 diffuse = ptLight.Color * diff * albedo;    glm::vec3 specular = ptLight.Specular * spec;    diffuse *= attenuation;    specular *= attenuation;    return  (diffuse + specular) * ptLight.Intensity;&#125;

在片元着色器中加入点光源贡献：
glm::vec4 FragmentShader(const V2F&amp; v) &#123;    glm::vec3 albedo = texture-&gt;Sample2D(v.texcoord) * currentMat-&gt;Color;    glm::vec3 worldNormal = glm::normalize(v.normal);    glm::vec3 worldViewDir = glm::normalize(camera-&gt;Position - glm::vec3(v.worldPos));    glm::vec3 result = Ambient * albedo;    for (int i = 0; i &lt; dirLtNums; i++)        result += BlinnPhongShader::CalcDirLight(*(dirLights + i), worldNormal, worldViewDir, albedo);    for (int i = 0; i &lt; ptLtNums; i++)        result += BlinnPhongShader::CalcPtLight(*(ptLights + i), glm::vec3(v.worldPos), worldNormal, worldViewDir, albedo);    return glm::vec4(result, 1.0);&#125;

然后在主函数中加入一个点光源：
PointLight pt(glm::vec3(1, 1, 1));ptLights = &amp;pt;ptLtNums = 1;

查看效果：

5 聚光灯聚光灯可以理解为手电筒，只有在与手电筒正方向夹角在一定范围内的像素才会被照亮。像素到光源位置的方向与光源正向夹角被称为切光角，切光角在设定范围内的像素，按照点光源的方式计算光照。切光角之外的像素不会被照亮。

为了避免边缘突变，可以设立一个外切光角，在内外切光角之间使用插值乘以计算结果。
// 聚光灯class SpotLight : public PointLight &#123;public:    float innerCutOff;        // 内切光角范围    float outterCutOff;        // 外切光角范围    SpotLight(        const glm::vec3&amp; pos = glm::vec3(0, 0, 0),        const glm::vec3&amp; dir = glm::vec3(0, 0, -1),        const glm::vec3&amp; color = glm::vec3(1, 1, 1),        const glm::vec3&amp; specular = glm::vec3(1, 1, 1),        const float&amp; i = 1.0f,        const float&amp; c = 1.0f,        const float&amp; l = 0.09f,        const float&amp; q = 0.032f,        const float&amp; icut = glm::cos(glm::radians(12.5f)),        const float&amp; ocut = glm::cos(glm::radians(17.5))    ) : PointLight(pos, color, specular, i, c, l, q), innerCutOff(icut), outterCutOff(ocut)    &#123;        Direction = dir;    &#125;&#125;;

计算聚光灯：
// 计算聚光灯，切光角以内按点光源计算static glm::vec3 CalcSpLight(    const SpotLight&amp; spLight,    const glm::vec3&amp; worldPos,    const glm::vec3&amp; worldNormal,    const glm::vec3&amp; worldViewDir,    const glm::vec3&amp; albedo) &#123;    glm::vec3 lightDir = glm::normalize(worldPos - spLight.Position);    // 切光角    float theta = glm::dot(lightDir, glm::normalize(spLight.Direction));    // 内外切光角插值系数    float weight = saturate((theta - spLight.outterCutOff) / (spLight.innerCutOff - spLight.outterCutOff));    float intensity = Lerp(0, 1, weight);    // 按点光源计算    float distance = glm::distance(worldPos, spLight.Position);    float attenuation = 1.0 / (spLight.Constant + spLight.Linear * distance +                               spLight.Quadratic * (distance * distance));    float diff = max(glm::dot(worldNormal, -lightDir), 0);    glm::vec3 halfDir = glm::normalize(worldViewDir - lightDir);    float spec = pow(max(glm::dot(halfDir, worldNormal), 0), currentMat-&gt;Gloss);    glm::vec3 diffuse = spLight.Color * diff * albedo;    glm::vec3 specular = spLight.Specular * spec;    diffuse *= (attenuation * intensity);    specular *= (attenuation * intensity);    return  (diffuse + specular) * spLight.Intensity;&#125;

在片元着色器中加入聚光灯贡献：
glm::vec4 FragmentShader(const V2F&amp; v) &#123;    glm::vec3 albedo = texture-&gt;Sample2D(v.texcoord) * currentMat-&gt;Color;    glm::vec3 worldNormal = glm::normalize(v.normal);    glm::vec3 worldViewDir = glm::normalize(camera-&gt;Position - glm::vec3(v.worldPos));    glm::vec3 result = Ambient * albedo;    for (int i = 0; i &lt; dirLtNums; i++)        result += BlinnPhongShader::CalcDirLight(*(dirLights + i), worldNormal, worldViewDir, albedo);    for (int i = 0; i &lt; ptLtNums; i++)        result += BlinnPhongShader::CalcPtLight(*(ptLights + i), glm::vec3(v.worldPos), worldNormal, worldViewDir, albedo);    for (int i = 0; i &lt; spLtNums; i++)        result += BlinnPhongShader::CalcSpLight(*(spLights + i), glm::vec3(v.worldPos), worldNormal, worldViewDir, albedo);    return glm::vec4(result, 1.0);&#125;

在主函数中加入聚光灯：
// 聚光灯SpotLight sp(camera-&gt;Position, camera-&gt;Front);spLights = &amp;sp;spLtNums = 1;

最终的效果：

现在我们的渲染管线已经基本具备了所有的要素，但是作为光栅化渲染器，我们目前的光栅化算法太过老旧，扫描线算法简单高效，但难以并行化（毕竟操作的单位是一条线），并且在实现时还存在由于多次插值的精度损失导致的多个三角形间存在接缝等问题。因此现在已经不被使用，之前在图形学中我们学习过另一种光栅化方法，这节我们来讨论该方法的一些具体实现细节。
1 边界函数算法关于边界函数算法，原理同样非常简单，就是用点和三角形三个顶点连线的向量叉乘来判断点是否在三角形内部，具体可以查看之前的笔记【计算机图形学】（三）光栅化，其中还包含了 C++ 代码实现。我们先照搬过来： /* Vector3f* _v存储三角形的三个顶点坐标，顶点顺序为逆时针*/static bool insideTriangle(int x, int y, const Vector3f* _v)&#123; //用像素中心坐标判断 Vector3f p(float(x) + 0.5, float(y) + 0.5, 1); //向量AB和AC叉乘的纵坐标 float signofTrig = (_v[1].x() - _v[0].x()) * (_v[2].y() - _v[0].y()) - (_v[1].y() - _v[0].y()) * (_v[2].x() - _v[0].x()); //向量AB和AP叉乘的纵坐标 float signOfAB = (_v[1].x() - _v[0].x()) * (p.y() - _v[0].y()) - (_v[1].y() - _v[0].y()) * (p.x() - _v[0].x()); //向量CA和CP叉乘的纵坐标 float signOfCA = (_v[0].x() - _v[2].x()) * (p.y() - _v[2].y()) - (_v[0].y() - _v[2].y()) * (p.x() - _v[2].x()); //向量BC和BP叉乘的纵坐标 float signOfBC = (_v[2].x() - _v[1].x()) * (p.y() - _v[2].y()) - (_v[2].y() - _v[1].y()) * (p.x() - _v[2].x()); bool d1 = (signOfAB * signofTrig &gt; 0); bool d2 = (signOfCA * signofTrig &gt; 0); bool d3 = (signOfBC * signofTrig &gt; 0); return d1 &amp;&amp; d2 &amp;&amp; d3;&#125;
所谓边界函数实际上就是上述代码中的 (signOfAB * signofTrig &gt; 0) 等这三个判断条件，因为这个条件判断了点和三角形的一条边界的位置关系，因此被称为边界函数。根据边界函数经过推导可以看出每次移动一个像素得到的边界函数和之前的边界函数的差值是固定的，具体推导过程可以查看图形学底层探秘 - 更现代的三角形光栅化与插值算法的实现与优化，因此我们不需要每次都计算叉乘，只需要在前一次的结果上加上差值即可。 另一个问题是，我们对每个三角形的 Bounding Box 内的像素进行遍历来判断其是否在三角形内部，那么至少会有一半的像素不在三角形内而造成计算浪费，因此出现了分块优化算法，即将 Bounding Box 进行分块，然后只判断每块四个角上的像素是否在三角形内，如果每块的四个像素都在三角形内部或者外部，其他像素就不需要再进行判断了，如果四个像素部分在内部部分在外部就执行正常的算法在块内逐像素判断。这个方法对于占屏幕面积较大的三角形优化效果明显，但如果是小三角形或是斜长的细三角形，反而不如不分块来得快。而且，太大的分块会进一步降低小三角形的绘制效率，而太小的分块又变回了逐像素算法，因此分块的大小需要仔细的权衡。 2 重心插值扫描线算法中使用线性插值就可以确定片元的各种属性值，而在边界函数算法中需要使用重心插值，关于重心坐标我们之前的笔记中也有具体的推导：【计算机图形学】（六）着色中的第4部分。 在实现中我们如何计算重心坐标呢？首先整个三角形的面积可以通过：$$S_{\Delta} &#x3D; \frac{1} {2}a·b·sin\theta$$来计算，也就是三角形两条边叉乘得到的向量模的一半，以 AB 和 BC 边为例，三角形的面积为：$$S_{\Delta} &#x3D; \frac{1} {2}(A_xB_y - A_yBx + B_xC_y - B_yCx + C_xA_y - C_yAx)$$而我们的三个边界函数相加：$$F_{AB}(P) + F_{BC}(P) + F_{CA}(P) &#x3D; A_xB_y - A_yBx + B_xC_y - B_yCx + C_xA_y - C_yAx$$刚好是三角形面积的二倍，即：$$\frac{F_{AB}(P) + F_{BC}(P) + F_{CA}(P)} {2S_{\Delta} } &#x3D; 1$$而重心坐标就是小三角形面积和整个三角形面积的比值，因此我们可以直接通过边界函数得到点 P 的重心坐标：$$\alpha &#x3D; \frac{F_{AB}(P)} { {2S_{\Delta} } },\beta &#x3D; \frac{F_{BC}(P)} { {2S_{\Delta} } },\gamma &#x3D; \frac{F_{CA}(P)} { {2S_{\Delta} } }$$这样整个光栅化算法就完成了。需要注意的是重心插值和之前的线性插值一样，都需要进行透视插值校正，即在透视除法中将所有属性都除以 w 值，最后在片元着色器之前再乘以 w 值恢复。关于透视插值校正我们将在下一节详细讨论。

本节主要了解 Piccolo 游戏引擎的代码框架、对象序列化的实现以及反射机制的实现。

1 引擎运行结果
2 代码整体框架Pilot 引擎除了第三方库之外，主要包含四部分，分别是编辑器、预编译、引擎运行时核心和 Shader 编译，如下图：

其中预编译部分负责预先生成一些文件，比如用来实现反射的文件，会在后文中提到，Shader 编译部分在之后的渲染系统代码中也会说到。编辑器负责整个引擎的界面、工具等的实现，需要引擎核心部分作为成员，是引擎核心功能对使用者的接口；引擎核心部分按照【游戏引擎】（一）游戏引擎架构中的分层结构实现，分别是核心层、功能层、平台层、资源层：

而 engine.cpp 负责将这些系统整合起来构成完整的运行时引擎。
整个引擎的主函数如下：
#include &lt;iostream&gt;#include &lt;string&gt;#include &lt;thread&gt;#include &lt;unordered_map&gt;#include &quot;runtime/engine.h&quot;#include &quot;editor/include/editor.h&quot;// https://gcc.gnu.org/onlinedocs/cpp/Stringizing.html#define PILOT_XSTR(s) PILOT_STR(s)#define PILOT_STR(s) #sint main(int argc, char** argv)&#123;    std::filesystem::path pilot_root_folder = std::filesystem::path(PILOT_XSTR(PILOT_ROOT_DIR));    Pilot::EngineInitParams params;    params.m_root_folder      = pilot_root_folder;    params.m_config_file_path = pilot_root_folder / &quot;PilotEditor.ini&quot;;    Pilot::PilotEngine* engine = new Pilot::PilotEngine();    engine-&gt;startEngine(params);    engine-&gt;initialize();    Pilot::PilotEditor* editor = new Pilot::PilotEditor();    editor-&gt;initialize(engine);    editor-&gt;run();    editor-&gt;clear();    engine-&gt;clear();    engine-&gt;shutdownEngine();    return 0;&#125;

从主函数出发可以大概了解引擎运行时的整体架构。主函数中首先初始化了运行时引擎，然后启动和初始化引擎，之后用运行时引擎初始化编辑器，再让编辑器运行，编辑器运行结束后先清理编辑器内容再清理引擎内容。
其中关键的函数就是 editor-&gt;run() 了，函数内容如下：
void PilotEditor::run()&#123;    assert(m_engine_runtime);    assert(m_editor_ui);    float delta_time;    while (true)    &#123;        delta_time = m_engine_runtime-&gt;calculateDeltaTime();        g_editor_global_context.m_scene_manager-&gt;tick(delta_time);        g_editor_global_context.m_input_manager-&gt;tick(delta_time);        if (!m_engine_runtime-&gt;tickOneFrame(delta_time))            return;    &#125;&#125;

首先判断了运行时引擎和引擎 UI 是否初始化成功，然后就是运行时主循环了，循环内就是各种 tick() 函数，其中最重要的是运行时引擎的 tickOneFrame 函数：
bool PilotEngine::tickOneFrame(float delta_time)&#123;    logicalTick(delta_time);    calculateFPS(delta_time);    // single thread    // exchange data between logic and render contexts    g_runtime_global_context.m_render_system-&gt;swapLogicRenderData();    rendererTick();    g_runtime_global_context.m_window_system-&gt;pollEvents();    g_runtime_global_context.m_window_system-&gt;setTile(        std::string(&quot;Pilot - &quot; + std::to_string(getFPS()) + &quot; FPS&quot;).c_str());    const bool should_window_close = g_runtime_global_context.m_window_system-&gt;shouldClose();    return !should_window_close;&#125;

可以看到其中包含 logicalTick() 和 rendererTick() 两部分，和我们之前笔记中描述的流程完全一致，当窗口关闭时函数返回 false，于是引擎主循环就会退出。
3 代码反射代码反射是指允许在运行时检查已知数据类型。 反射允许枚举给定程序集中的数据类型，并且可以发现给定类或值类型的成员。 无论类型在编译时是已知的还是引用的，都是如此。 这使得反射成为开发和代码管理工具的有用功能。
定义很抽象，通过一个实际场景来理解，比如引擎中对于不同对象要显示出它的组件，但是不同对象的属性不同，我们不可能为每个类都编写一个组件面板，这时通过反射，就可以快速方便的知道一个类中有哪些成员变量，他们都是什么类型。
反射的另一个作用是在对象序列化时使用，所谓序列化就是存储到磁盘上，将对象变成一定格式的二进制文件或者自定义格式的文件（如json），然后要用的时候再将保存在磁盘上的文件转化成一个内存中的对象，这个过程中总是需要有一个指示来告诉编译器要生成什么样的对象，最简单的方式当然就是类名了，例如：将一个 ClassXXX 对象存储到磁盘上，再从磁盘读取的时候让编译器根据 “ClassXXX” 名称来 new 一个对象。但问题是，C++ 语言本身不支持反射，也就是说不能通过类的名称字符串来生成一个对象，像下面这样：
ClassXXX object = new “ClassXXX”;

于是就需要反射机制来实现这个功能。
反射的实现方法是，提前处理需要反射的类型，生成一个类似配置文件的东西，在 Pilot 引擎中也是一个 C++ 文件，在预编译阶段生成，文件中包含一个类有哪些属性变量、父类。这些属性变量的 get 、set、getFieldName 获取变量的名字、getFieldTypeName 获取变量的类型、isArray_id 是不是数组等方法，都被封装成一个结构体，与类型的名字（字符串类型）做一个映射（map）。在运行的时候加载这些配置表，这样我们其实通过一个类型的名字就可以知道他有什么变量，以及这些变量的具体属性和方法，然后就可以把这个类型当做一个方法集，与类型的实例挂钩就可以方便的处理这个实例的各个属性。
接下来我们以常用的 Vector3 类为例，来看看 Pilot 中的反射实现。首先是类的声明：
REFLECTION_TYPE(Vector3)CLASS(Vector3, Fields)&#123;    REFLECTION_BODY(Vector3);    public:    float x &#123;0.f&#125;;    float y &#123;0.f&#125;;    float z &#123;0.f&#125;;    public:    ...&#125;

这里用到了三个宏定义，他们都在 reflection.h 中定义如下：
#define CLASS(class_name, ...) class class_name#define REFLECTION_BODY(class_name) \    friend class Reflection::TypeFieldReflectionOparator::Type##class_name##Operator; \    friend class PSerializer;    // public: virtual std::string getTypeName() override &#123;return #class_name;&#125;#define REFLECTION_TYPE(class_name) \    namespace Reflection \    &#123; \        namespace TypeFieldReflectionOparator \        &#123; \            class Type##class_name##Operator; \        &#125; \    &#125;;

可以看到首先声明了与类名称有关的 Type##class_name##Operator 类，## 是连接符，将两个字符串连接起来，这里生成的类就是 TypeVector3Operator，然后将该类和序列化类 PSerializer 作为了 Vector3 类的友元。
TypeVector3Operator 类在 vector3.reflection.gen.h 文件中定义，这个文件是预编译阶段生成的，其中定义的就是对该类的各种回调函数，包括返回类名称，序列化类对象，通过序列化的 json 文件构建该类的对象，获取该类的基类，以及上面说到的对成员变量的各种方法，代码如下：
#pragma once#include &quot;D:/TechStack/GamesEngine/PilotEngine/Pilot-main/engine/source/runtime/core/math/vector3.h&quot;namespace Pilot&#123;class Vector3;namespace Reflection&#123;namespace TypeFieldReflectionOparator&#123;   class TypeVector3Operator&#123;   public:       static const char* getClassName()&#123; return &quot;Vector3&quot;;&#125;       static void* constructorWithJson(const PJson&amp; json_context)&#123;          Vector3* ret_instance= new Vector3;          PSerializer::read(json_context, *ret_instance);          return ret_instance;       &#125;       static PJson writeByName(void* instance)&#123;          return PSerializer::write(*(Vector3*)instance);       &#125;       // base class       static int getVector3BaseClassReflectionInstanceList(ReflectionInstance* &amp;out_list, void* instance)&#123;            int count = 0;            return count;       &#125;       // fields       static const char* getFieldName_x()&#123; return &quot;x&quot;;&#125;       static const char* getFieldTypeName_x()&#123; return &quot;float&quot;;&#125;       static void set_x(void* instance, void* field_value)&#123; static_cast&lt;Vector3*&gt;(instance)-&gt;x = *static_cast&lt;float*&gt;(field_value);&#125;       static void* get_x(void* instance)&#123; return static_cast&lt;void*&gt;(&amp;(static_cast&lt;Vector3*&gt;(instance)-&gt;x));&#125;       static bool isArray_x()&#123; return 0;&#125;       static const char* getFieldName_y()&#123; return &quot;y&quot;;&#125;       static const char* getFieldTypeName_y()&#123; return &quot;float&quot;;&#125;       static void set_y(void* instance, void* field_value)&#123; static_cast&lt;Vector3*&gt;(instance)-&gt;y = *static_cast&lt;float*&gt;(field_value);&#125;       static void* get_y(void* instance)&#123; return static_cast&lt;void*&gt;(&amp;(static_cast&lt;Vector3*&gt;(instance)-&gt;y));&#125;       static bool isArray_y()&#123; return 0;&#125;       static const char* getFieldName_z()&#123; return &quot;z&quot;;&#125;       static const char* getFieldTypeName_z()&#123; return &quot;float&quot;;&#125;       static void set_z(void* instance, void* field_value)&#123; static_cast&lt;Vector3*&gt;(instance)-&gt;z = *static_cast&lt;float*&gt;(field_value);&#125;       static void* get_z(void* instance)&#123; return static_cast&lt;void*&gt;(&amp;(static_cast&lt;Vector3*&gt;(instance)-&gt;z));&#125;       static bool isArray_z()&#123; return 0;&#125;    &#125;;&#125;//namespace TypeFieldReflectionOparator   void TypeWrapperRegister_Vector3()&#123;       FieldFunctionTuple* f_field_function_tuple_x=new FieldFunctionTuple(           &amp;TypeFieldReflectionOparator::TypeVector3Operator::set_x,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::get_x,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getClassName,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldName_x,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldTypeName_x,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::isArray_x);       REGISTER_FIELD_TO_MAP(&quot;Vector3&quot;, f_field_function_tuple_x);       FieldFunctionTuple* f_field_function_tuple_y=new FieldFunctionTuple(           &amp;TypeFieldReflectionOparator::TypeVector3Operator::set_y,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::get_y,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getClassName,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldName_y,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldTypeName_y,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::isArray_y);       REGISTER_FIELD_TO_MAP(&quot;Vector3&quot;, f_field_function_tuple_y);       FieldFunctionTuple* f_field_function_tuple_z=new FieldFunctionTuple(           &amp;TypeFieldReflectionOparator::TypeVector3Operator::set_z,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::get_z,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getClassName,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldName_z,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getFieldTypeName_z,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::isArray_z);       REGISTER_FIELD_TO_MAP(&quot;Vector3&quot;, f_field_function_tuple_z);       ClassFunctionTuple* f_class_function_tuple_Vector3=new ClassFunctionTuple(           &amp;TypeFieldReflectionOparator::TypeVector3Operator::getVector3BaseClassReflectionInstanceList,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::constructorWithJson,           &amp;TypeFieldReflectionOparator::TypeVector3Operator::writeByName);       REGISTER_BASE_CLASS_TO_MAP(&quot;Vector3&quot;, f_class_function_tuple_Vector3);   &#125;namespace TypeWrappersRegister&#123;    void Vector3()&#123; TypeWrapperRegister_Vector3();&#125;&#125;//namespace TypeWrappersRegister&#125;//namespace Reflection&#125;//namespace Pilot

上面的代码中还有注册这些回调函数的函数 TypeWrapperRegister_Vector3，函数中就是对所有成员的方法进行了注册，所谓注册就是将这些函数和类型名称对应起来，放到哈希表中，实现方法是用变量的各种方法初始化一个 FieldFunctionTuple 元组，这个元组的声明同样在 reflection.h 中：
typedef std::function&lt;void(void*, void*)&gt;      SetFuncion;typedef std::function&lt;void*(void*)&gt;            GetFuncion;typedef std::function&lt;const char*()&gt;           GetNameFuncion;typedef std::function&lt;void(int, void*, void*)&gt; SetArrayFunc;typedef std::function&lt;void*(int, void*)&gt;       GetArrayFunc;typedef std::function&lt;int(void*)&gt;              GetSizeFunc;typedef std::function&lt;bool()&gt;                  GetBoolFunc;typedef std::function&lt;void*(const PJson&amp;)&gt;                          ConstructorWithPJson;typedef std::function&lt;PJson(void*)&gt;                                 WritePJsonByName;typedef std::function&lt;int(Reflection::ReflectionInstance*&amp;, void*)&gt; GetBaseClassReflectionInstanceListFunc;typedef std::tuple&lt;SetFuncion, GetFuncion, GetNameFuncion, GetNameFuncion, GetNameFuncion, GetBoolFunc&gt;    FieldFunctionTuple;typedef std::tuple&lt;GetBaseClassReflectionInstanceListFunc, ConstructorWithPJson, WritePJsonByName&gt;    ClassFunctionTuple;typedef std::tuple&lt;SetArrayFunc, GetArrayFunc, GetSizeFunc, GetNameFuncion, GetNameFuncion&gt; ArrayFunctionTuple;

元组中存放的就是各类函数的指针，然后通过一个宏定义 REGISTER_FIELD_TO_MAP 注册这些函数，该宏定义如下：
#define REGISTER_FIELD_TO_MAP(name, value) TypeMetaRegisterinterface::registerToFieldMap(name, value);#define REGISTER_BASE_CLASS_TO_MAP(name, value) TypeMetaRegisterinterface::registerToClassMap(name, value);#define REGISTER_ARRAY_TO_MAP(name, value) TypeMetaRegisterinterface::registerToArrayMap(name, value);#define UNREGISTER_ALL TypeMetaRegisterinterface::unregisterAll();

实际上宏定义就是调用了 TypeMetaRegisterinterface 类中的方法，该类是用来注册各种回调函数的接口，定义如下：
class TypeMetaRegisterinterface&#123;    public:    static void registerToClassMap(const char* name, ClassFunctionTuple* value);    static void registerToFieldMap(const char* name, FieldFunctionTuple* value);    static void registerToArrayMap(const char* name, ArrayFunctionTuple* value);    static void unregisterAll();&#125;;

类中的各种方法就是用来将给定的函数指针元组和类名称关联起来，存放到全局定义的哈希表中，以类名为键，这样之后使用时通过类名就可以找到类中各种成员变量的名称、类型、方法了，这部分在 reflection.cpp 中实现：
namespace Reflection&#123;    const char* k_unknown_type = &quot;UnknownType&quot;;    const char* k_unknown      = &quot;Unknown&quot;;    static std::map&lt;std::string, ClassFunctionTuple*&gt;      m_class_map;    static std::multimap&lt;std::string, FieldFunctionTuple*&gt; m_field_map;    static std::map&lt;std::string, ArrayFunctionTuple*&gt;      m_array_map;    void TypeMetaRegisterinterface::registerToFieldMap(const char* name, FieldFunctionTuple* value)    &#123;        m_field_map.insert(std::make_pair(name, value));    &#125;    void TypeMetaRegisterinterface::registerToArrayMap(const char* name, ArrayFunctionTuple* value)    &#123;        if (m_array_map.find(name) == m_array_map.end())        &#123;            m_array_map.insert(std::make_pair(name, value));        &#125;        else        &#123;            delete value;        &#125;    &#125;    void TypeMetaRegisterinterface::registerToClassMap(const char* name, ClassFunctionTuple* value)    &#123;        if (m_class_map.find(name) == m_class_map.end())        &#123;            m_class_map.insert(std::make_pair(name, value));        &#125;        else        &#123;            delete value;        &#125;    &#125;    void TypeMetaRegisterinterface::unregisterAll()    &#123;        for (const auto&amp; itr : m_field_map)        &#123;            delete itr.second;        &#125;        m_field_map.clear();        for (const auto&amp; itr : m_class_map)        &#123;            delete itr.second;        &#125;        m_class_map.clear();        for (const auto&amp; itr : m_array_map)        &#123;            delete itr.second;        &#125;        m_array_map.clear();    &#125;    ...        &#125;

所有需要反射的类都会在运行时引擎启动时进行注册，也就是之前主函数中的 engine-&gt;startEngine() 函数，该函数定义如下：
void PilotEngine::startEngine(const EngineInitParams&amp; param)&#123;    m_init_params = param;    Reflection::TypeMetaRegister::Register();    g_runtime_global_context.startSystems(param);    LOG_INFO(&quot;engine start&quot;);&#125;

其中 TypeMetaRegister 类就是用来注册函数的类：
#pragma oncenamespace Pilot&#123;    namespace Reflection    &#123;        class TypeMetaRegister        &#123;        public:            static void Register();            static void Unregister();        &#125;;    &#125; // namespace Reflection&#125; // namespace Pilot

Register() 函数就是调用了各个类的注册函数：
void TypeMetaRegister::Register()&#123;    TypeWrappersRegister::Transform();    TypeWrappersRegister::Quaternion();    TypeWrappersRegister::Vector3();    ...&#125;

关于对象序列化和反射的使用示例，Pilot 也提供了一个样例代码，在 meta/meta_example.cpp 中。

上一节中我们了解了引擎的整体运行流程以及反射机制的实现，这一节开始探究 Piccolo 的渲染系统是如何实现的，首先来了解渲染系统的整个流程。

回顾上一节中，引擎运行时最核心的函数 tickOneFrame()：
bool PilotEngine::tickOneFrame(float delta_time)&#123;    logicalTick(delta_time);    calculateFPS(delta_time);    // single thread    // exchange data between logic and render contexts    g_runtime_global_context.m_render_system-&gt;swapLogicRenderData();    rendererTick();    g_runtime_global_context.m_window_system-&gt;pollEvents();    g_runtime_global_context.m_window_system-&gt;setTile(        std::string(&quot;Pilot - &quot; + std::to_string(getFPS()) + &quot; FPS&quot;).c_str());    const bool should_window_close = g_runtime_global_context.m_window_system-&gt;shouldClose();    return !should_window_close;&#125;

可以看到引擎每一帧的流程就是先进行 logicalTick，然后通过 swapLogicRenderData 进行渲染系统的数据更新，最后进行渲染 rendererTick，之后还有一些窗口的事件响应。接下来我们从 logicalTick 开始看看整个系统是如何运行的。
1 logicalTicklogicalTick  的定义如下：
void PilotEngine::logicalTick(float delta_time)&#123;    g_runtime_global_context.m_world_manager-&gt;tick(delta_time);    g_runtime_global_context.m_input_system-&gt;tick();&#125;

 logicalTick  内部调用了世界管理系统的 tick 和输入管理系统的 tick。
1.1 世界管理系统世界管理系统 m_world_manager 属于 WorldManager 类，该类用于管理整个游戏世界，包括编辑世界和运行世界，世界中包含各种关卡（Level），于是  WorldManager 的 tick 实际上就是调用关卡的 tick：
void WorldManager::tick(float delta_time)&#123;    if (!m_is_world_loaded)    &#123;        loadWorld(m_current_world_url);    &#125;    // tick the active level    std::shared_ptr&lt;Level&gt; active_level = m_current_active_level.lock();    if (active_level)    &#123;        active_level-&gt;tick(delta_time);    &#125;&#125;

而关卡类 Level 就是用于管理游戏对象（GO）的类，包含多个 Game Objects，于是 Level 的 tick 函数自然就是调用每个 GO 的 tick：
void Level::tick(float delta_time)&#123;    if (!m_is_loaded)    &#123;        return;    &#125;    for (const auto&amp; id_object_pair : m_gobjects)    &#123;        assert(id_object_pair.second);        if (id_object_pair.second)        &#123;            id_object_pair.second-&gt;tick(delta_time);        &#125;    &#125;    if (m_current_active_character &amp;&amp; g_is_editor_mode == false)    &#123;        m_current_active_character-&gt;tick(delta_time);    &#125;&#125;

可以看到除了调用每个 GO 的 tick ，最后还判断了是否有当前激活的角色和是否在编辑模式，如果不在编辑模式且存在激活的角色（也就是可被控制的角色），就调用该角色的 tick。角色 Character 类可以通过游戏对象 GObject 类来创建，因此它们都属于游戏对象，而 GObject 类的成员如下：
protected:    GObjectID   m_id &#123;k_invalid_gobject_id&#125;;    std::string m_name;    std::string m_definition_url;    // we have to use the ReflectionPtr due to that the components need to be reflected     // in editor, and it&#x27;s polymorphism    std::vector&lt;Reflection::ReflectionPtr&lt;Component&gt;&gt; m_components;

每一个 GO 包含唯一的 GID 标识，名字，读取的链接以及各种组件，这些组件需要使用反射，因为组件有许多不同的类型，比如动画组件、mesh 组件、运动组件、相机组件等等，并且这些组件还要显示在组件面板，所以需要用到反射机制。于是每一个 GO 的 tick 就是调用它所有组件的 tick：
void GObject::tick(float delta_time)&#123;    for (auto&amp; component : m_components)    &#123;        if (shouldComponentTick(component.getTypeName()))        &#123;            component-&gt;tick(delta_time);        &#125;    &#125;&#125;

而不同组件的 tick 自然就是对应于动画、物理、相机运动、物体形变等各个逻辑系统的运算。
1.2 输入管理系统输入管理系统 InputSystem 类自然是用来管理鼠标、键盘的各种输入并作出响应，这里不多赘述。
2 swapLogicRenderData逻辑系统运算完毕后，这一帧的世界就构建完成了，但是逻辑运算是在当前世界上进行的，如果世界的资源发生了改变，那么逻辑系统告诉渲染系统更新了哪些资源，渲染系统要获取这些资源加入到渲染资源中，这是通过渲染系统中的 swapLogicRenderData 函数完成的：
void RenderSystem::swapLogicRenderData() &#123; m_swap_context.swapLogicRenderData(); &#125;

可以看到该函数调用了渲染系统的成员 m_swap_context 的 swapLogicRenderData 函数， m_swap_context 属于 RenderSwapContext 类，其中包含要交换的数据 RenderSwapData，RenderSwapData 的定义如下：
struct RenderSwapData&#123;    std::optional&lt;LevelResourceDesc&gt;      level_resource_desc;    std::optional&lt;GameObjectResourceDesc&gt; game_object_resource_desc;    std::optional&lt;GameObjectResourceDesc&gt; game_object_to_delete;    std::optional&lt;CameraSwapData&gt;         camera_swap_data;    void addDirtyGameObject(GameObjectDesc desc);    void addDeleteGameObject(GameObjectDesc desc);&#125;;

其中包含关卡资源、游戏对象、相机数据，这些都是在逻辑系统计算的。这里使用了 C++ 17 的新特性 optional，为了之后可以通过 has_value 函数快速判断是否需要在渲染系统中更新这些资源的数据。
m_swap_context 的 swapLogicRenderData 函数如下：
void RenderSwapContext::swapLogicRenderData()&#123;    if (isReadyToSwap())    &#123;        swap();    &#125;&#125;bool RenderSwapContext::isReadyToSwap() const&#123;    return !(m_swap_data[m_render_swap_data_index].level_resource_desc.has_value() ||             m_swap_data[m_render_swap_data_index].game_object_resource_desc.has_value() ||             m_swap_data[m_render_swap_data_index].game_object_to_delete.has_value() ||             m_swap_data[m_render_swap_data_index].camera_swap_data.has_value());&#125;void RenderSwapContext::swap()&#123;    resetLevelRsourceSwapData();    resetGameObjectResourceSwapData();    resetGameObjectToDelete();    resetCameraSwapData();    std::swap(m_logic_swap_data_index, m_render_swap_data_index);&#125;

其功能就是当需要在渲染系统中更新这些资源的数据时就进行数据交换操作。
3 rendererTick接下来就是最重要的 rendererTick 了，rendererTick 调用了渲染系统的 tick 函数：
bool PilotEngine::rendererTick()&#123;    g_runtime_global_context.m_render_system-&gt;tick();    return true;&#125;

渲染系统的 tick 函数如下：
void RenderSystem::tick()&#123;    // process swap data between logic and render contexts    processSwapData();    // prepare render command context    m_rhi-&gt;prepareContext();    // update per-frame buffer    m_render_resource-&gt;updatePerFrameBuffer(m_render_scene, m_render_camera);    // update per-frame visible objects    m_render_scene-&gt;updateVisibleObjects(std::static_pointer_cast&lt;RenderResource&gt;(m_render_resource),                                         m_render_camera);    // prepare pipeline&#x27;s render passes data    m_render_pipeline-&gt;preparePassData(m_render_resource);    // render one frame    if (m_render_pipeline_type == RENDER_PIPELINE_TYPE::FORWARD_PIPELINE)    &#123;        m_render_pipeline-&gt;forwardRender(m_rhi, m_render_resource);    &#125;    else if (m_render_pipeline_type == RENDER_PIPELINE_TYPE::DEFERRED_PIPELINE)    &#123;        m_render_pipeline-&gt;deferredRender(m_rhi, m_render_resource);    &#125;    else    &#123;        LOG_ERROR(__FUNCTION__, &quot;unsupported render pipeline type&quot;);    &#125;&#125;

首先是处理从逻辑系统交换来的数据，也就是根据场景或者 GO 是否有变化从硬盘加载对应的资源或者卸载部分资源，然后准备渲染的各种数据。这些数据包括：

变换矩阵、场景的光源数据，这通过 updatePerFrameBuffer 函数来设定，该函数根据场景和相机来获取矩阵和场景的光照信息，而整个渲染场景的光源在系统初始化的时候会进行构建，之后不会改变，相机会在逻辑 tick 中改变；
可见的物体数据，这通过 updateVisibleObjects 函数进行，实际上就是在进入渲染之前，把完全不可见的物体剔除掉。

数据准备完毕后准备渲染的 Pass，最后根据指定的渲染模式进行前向渲染或者延迟渲染。
下一节开始我们将学习这些流程的具体实现。

上一次我们了解了 Piccolo 引擎中渲染的基本流程，包括 Logic Tick 和 Render Tick 的数据交换和 RenderTick 的大致过程，这一节我们来详细看这些过程都是如何实现的，在此基础上下一节尝试为整个渲染流程加入一个 Color Grading Pass。
1 Render Tick 整体流程首先回顾上一节中看过的 Render Tick 整体流程： void RenderSystem::tick()&#123; // process swap data between logic and render contexts processSwapData(); // prepare render command context m_rhi-&gt;prepareContext(); // update per-frame buffer m_render_resource-&gt;updatePerFrameBuffer(m_render_scene, m_render_camera); // update per-frame visible objects m_render_scene-&gt;updateVisibleObjects(std::static_pointer_cast&lt;RenderResource&gt;(m_render_resource), m_render_camera); // prepare pipeline&#x27;s render passes data m_render_pipeline-&gt;preparePassData(m_render_resource); // render one frame if (m_render_pipeline_type == RENDER_PIPELINE_TYPE::FORWARD_PIPELINE) &#123; m_render_pipeline-&gt;forwardRender(m_rhi, m_render_resource); &#125; else if (m_render_pipeline_type == RENDER_PIPELINE_TYPE::DEFERRED_PIPELINE) &#123; m_render_pipeline-&gt;deferredRender(m_rhi, m_render_resource); &#125; else &#123; LOG_ERROR(__FUNCTION__, &quot;unsupported render pipeline type&quot;); &#125;&#125;
其中 processSwapData() 上一节中已经学习过， m_rhi-&gt;prepareContext() 用来准备渲染命令，其内部就是初始化 command buffer： void VulkanRHI::prepareContext()&#123; m_p_current_frame_index = &amp;m_current_frame_index; m_current_command_buffer = m_command_buffers[m_current_frame_index]; m_p_command_buffers = m_command_buffers; m_p_command_pools = m_command_pools;&#125;
下面是一些需要具体看的操作，我们一一探究。 2 updatePerFrameBufferm_render_resource-&gt;updatePerFrameBuffer(m_render_scene, m_render_camera) 负责准备每一帧渲染中的场景数据，包括 VP 矩阵，相机位置，环境光，点光源数量，每个点光源的强度、位置、半径衰减以及平行光属性，把这些数据存到 RenderResource 类的对应成员中用于之后渲染使用： void RenderResource::updatePerFrameBuffer(std::shared_ptr&lt;RenderScene&gt; render_scene, std::shared_ptr&lt;RenderCamera&gt; camera)&#123; Matrix4x4 view_matrix = camera-&gt;getViewMatrix(); Matrix4x4 proj_matrix = camera-&gt;getPersProjMatrix(); Vector3 camera_position = camera-&gt;position(); glm::mat4 proj_view_matrix = GLMUtil::fromMat4x4(proj_matrix * view_matrix); // ambient light Vector3 ambient_light = render_scene-&gt;m_ambient_light.m_irradiance; uint32_t point_light_num = static_cast&lt;uint32_t&gt;(render_scene-&gt;m_point_light_list.m_lights.size()); // set ubo data m_mesh_perframe_storage_buffer_object.proj_view_matrix = proj_view_matrix; m_mesh_perframe_storage_buffer_object.camera_position = GLMUtil::fromVec3(camera_position); m_mesh_perframe_storage_buffer_object.ambient_light = ambient_light; m_mesh_perframe_storage_buffer_object.point_light_num = point_light_num; m_mesh_point_light_shadow_perframe_storage_buffer_object.point_light_num = point_light_num; // point lights for (uint32_t i = 0; i &lt; point_light_num; i++) &#123; Vector3 point_light_position = render_scene-&gt;m_point_light_list.m_lights[i].m_position; Vector3 point_light_intensity = render_scene-&gt;m_point_light_list.m_lights[i].m_flux / (4.0f * glm::pi&lt;float&gt;()); float radius = render_scene-&gt;m_point_light_list.m_lights[i].calculateRadius(); m_mesh_perframe_storage_buffer_object.scene_point_lights[i].position = point_light_position; m_mesh_perframe_storage_buffer_object.scene_point_lights[i].radius = radius; m_mesh_perframe_storage_buffer_object.scene_point_lights[i].intensity = point_light_intensity; m_mesh_point_light_shadow_perframe_storage_buffer_object.point_lights_position_and_radius[i] = Vector4(point_light_position, radius); &#125; // directional light m_mesh_perframe_storage_buffer_object.scene_directional_light.direction = render_scene-&gt;m_directional_light.m_direction.normalisedCopy(); m_mesh_perframe_storage_buffer_object.scene_directional_light.color = render_scene-&gt;m_directional_light.m_color; // pick pass view projection matrix m_mesh_inefficient_pick_perframe_storage_buffer_object.proj_view_matrix = proj_view_matrix; m_particlebillboard_perframe_storage_buffer_object.proj_view_matrix = proj_view_matrix; m_particlebillboard_perframe_storage_buffer_object.eye_position = GLMUtil::fromVec3(camera_position); m_particlebillboard_perframe_storage_buffer_object.up_direction = GLMUtil::fromVec3(camera-&gt;up());&#125;
3 updateVisibleObjectsm_render_scene-&gt;updateVisibleObjects(std::static_pointer_cast&lt;RenderResource&gt;(m_render_resource), m_render_camera);
这个函数负责预先计算可见的物体，将完全不可见的物体剔除掉，不送入之后的渲染流程中，将可见物体的属性设置好便于之后使用： void RenderScene::updateVisibleObjects(std::shared_ptr&lt;RenderResource&gt; render_resource, std::shared_ptr&lt;RenderCamera&gt; camera)&#123; updateVisibleObjectsDirectionalLight(render_resource, camera); updateVisibleObjectsPointLight(render_resource); updateVisibleObjectsMainCamera(render_resource, camera); updateVisibleObjectsAxis(render_resource); updateVisibleObjectsParticle(render_resource);&#125;
可以看到其中调用了各种可见性检测函数，包括对平行光的物体可见性、对点光源的物体可见性，对相机的物体可见性以及坐标轴可见性，坐标轴可见性是为了我们在编辑模式选中物体的时候显示坐标轴，所以也要绘制，而最后一个 updateVisibleObjectsParticle 还没有实现， 我们以 updateVisibleObjectsMainCamera 为例来看可见性检测具体干了什么，其他的也是大同小异，最后会提到。 void RenderScene::updateVisibleObjectsMainCamera(std::shared_ptr&lt;RenderResource&gt; render_resource, std::shared_ptr&lt;RenderCamera&gt; camera)&#123; m_main_camera_visible_mesh_nodes.clear(); Matrix4x4 view_matrix = camera-&gt;getViewMatrix(); Matrix4x4 proj_matrix = camera-&gt;getPersProjMatrix(); Matrix4x4 proj_view_matrix = proj_matrix * view_matrix; ClusterFrustum f = CreateClusterFrustumFromMatrix(GLMUtil::fromMat4x4(proj_view_matrix), -1.0, 1.0, -1.0, 1.0, 0.0, 1.0); for (const RenderEntity&amp; entity : m_render_entities) &#123; BoundingBox mesh_asset_bounding_box &#123;entity.m_bounding_box.getMinCorner(), entity.m_bounding_box.getMaxCorner()&#125;; if (TiledFrustumIntersectBox(f, BoundingBoxTransform(mesh_asset_bounding_box, GLMUtil::fromMat4x4(entity.m_model_matrix)))) &#123; m_main_camera_visible_mesh_nodes.emplace_back(); RenderMeshNode&amp; temp_node = m_main_camera_visible_mesh_nodes.back(); temp_node.model_matrix = GLMUtil::fromMat4x4(entity.m_model_matrix); assert(entity.m_joint_matrices.size() &lt;= m_mesh_vertex_blending_max_joint_count); for (size_t joint_index = 0; joint_index &lt; entity.m_joint_matrices.size(); joint_index++) &#123; temp_node.joint_matrices[joint_index] = GLMUtil::fromMat4x4(entity.m_joint_matrices[joint_index]); &#125; temp_node.node_id = entity.m_instance_id; VulkanMesh&amp; mesh_asset = render_resource-&gt;getEntityMesh(entity); temp_node.ref_mesh = &amp;mesh_asset; temp_node.enable_vertex_blending = entity.m_enable_vertex_blending; VulkanPBRMaterial&amp; material_asset = render_resource-&gt;getEntityMaterial(entity); temp_node.ref_material = &amp;material_asset; &#125; &#125;&#125;
首先是获取相机的 PV 矩阵，然后根据矩阵构建世界空间下的视锥体，这部分内容我们在之前学过，具体可以查看之前的笔记【光栅化渲染器】（六）剔除与裁剪第 2 部分，有了视锥体就可以利用视锥体和 bounding box 求交来判断是否可见了，如果可见就将该物体的模型矩阵，骨骼矩阵、材质等属性记录下来。 对于平行光的可见性检测，需要先计算平行光覆盖的范围的 Bounding Box，然后后后续的操作都一样；对于点光源，需要分别计算每一个点光源覆盖的球体范围，计算一个 Bounding Sphere，然后逐点光源进行上述步骤即可。 至于求交函数，分为视锥体与 Bounding Box 求交以及 Bounding Box 与 Bounding Sphere 求交，前者我们学习过，利用点和视锥体六个平面的关系判断，后者利用球心到 Bounding Box 六个面的距离和球的半径判断即可，具体函数实现可以自行查看工程中的代码。 4 preparePassDatam_render_pipeline-&gt;preparePassData(m_render_resource) 负责准备渲染所需的 pass 数据，包括相机的 pass，编辑模式下选中物体时的显示 pass（主要是绘制坐标轴），平行光的 shadow pass，点光源的 shadow pass 等： void RenderPipelineBase::preparePassData(std::shared_ptr&lt;RenderResourceBase&gt; render_resource)&#123; m_main_camera_pass-&gt;preparePassData(render_resource); m_pick_pass-&gt;preparePassData(render_resource); m_directional_light_pass-&gt;preparePassData(render_resource); m_point_light_shadow_pass-&gt;preparePassData(render_resource);&#125;
5 forwardRender经过上面的场景光源信息、相机信息、物体信息和渲染的 pass 的准备，我们就可以进行渲染了，于是接下来根据渲染路径选择不同的渲染 pipeline： // render one frameif (m_render_pipeline_type == RENDER_PIPELINE_TYPE::FORWARD_PIPELINE)&#123; m_render_pipeline-&gt;forwardRender(m_rhi, m_render_resource);&#125;else if (m_render_pipeline_type == RENDER_PIPELINE_TYPE::DEFERRED_PIPELINE)&#123; m_render_pipeline-&gt;deferredRender(m_rhi, m_render_resource);&#125;else&#123; LOG_ERROR(__FUNCTION__, &quot;unsupported render pipeline type&quot;);&#125;
我们首先来看前向渲染 forwardRender： void RenderPipeline::forwardRender(std::shared_ptr&lt;RHI&gt; rhi, std::shared_ptr&lt;RenderResourceBase&gt; render_resource)&#123; VulkanRHI* vulkan_rhi = static_cast&lt;VulkanRHI*&gt;(rhi.get()); RenderResource* vulkan_resource = static_cast&lt;RenderResource*&gt;(render_resource.get()); vulkan_resource-&gt;resetRingBufferOffset(vulkan_rhi-&gt;m_current_frame_index); vulkan_rhi-&gt;waitForFences(); vulkan_rhi-&gt;resetCommandPool(); bool recreate_swapchain = vulkan_rhi-&gt;prepareBeforePass(std::bind(&amp;RenderPipeline::passUpdateAfterRecreateSwapchain, this)); if (recreate_swapchain) &#123; return; &#125; static_cast&lt;DirectionalLightShadowPass*&gt;(m_directional_light_pass.get())-&gt;draw(); static_cast&lt;PointLightShadowPass*&gt;(m_point_light_shadow_pass.get())-&gt;draw(); ColorGradingPass&amp; color_grading_pass = *(static_cast&lt;ColorGradingPass*&gt;(m_color_grading_pass.get())); FXAAPass&amp; fxaa_pass = *(static_cast&lt;FXAAPass*&gt;(m_tone_mapping_pass.get())); ToneMappingPass&amp; tone_mapping_pass = *(static_cast&lt;ToneMappingPass*&gt;(m_tone_mapping_pass.get())); UIPass&amp; ui_pass = *(static_cast&lt;UIPass*&gt;(m_ui_pass.get())); CombineUIPass&amp; combine_ui_pass = *(static_cast&lt;CombineUIPass*&gt;(m_combine_ui_pass.get())); static_cast&lt;MainCameraPass*&gt;(m_main_camera_pass.get()) -&gt;drawForward(color_grading_pass, fxaa_pass, tone_mapping_pass, ui_pass, combine_ui_pass, vulkan_rhi-&gt;m_current_swapchain_image_index); vulkan_rhi-&gt;submitRendering(std::bind(&amp;RenderPipeline::passUpdateAfterRecreateSwapchain, this));&#125;
可以看到在一切准备工作完成之后，首先进行了平行光的 shadow pass 和点光源的 shadow pass 生成光照阴影，然后是主相机的 pass，在主相机 pass 的 drawForward(...) 函数中依次执行了：
drawMeshLighting() drawSkybox() drawBillboardParticle()（未实现） tone_mapping_pass.draw() color_grading_pass.draw() if (m_enable_fxaa) fxaa_pass.draw() drawAxis() ui_pass.draw()（未实现） combine_ui_pass.draw()（未实现）
6 deferredRender延迟渲染的代码和前向渲染基本一致，只是最后调用的是主相机 pass 中的 draw(...) 函数： void RenderPipeline::deferredRender(std::shared_ptr&lt;RHI&gt; rhi, std::shared_ptr&lt;RenderResourceBase&gt; render_resource)&#123; VulkanRHI* vulkan_rhi = static_cast&lt;VulkanRHI*&gt;(rhi.get()); RenderResource* vulkan_resource = static_cast&lt;RenderResource*&gt;(render_resource.get()); vulkan_resource-&gt;resetRingBufferOffset(vulkan_rhi-&gt;m_current_frame_index); vulkan_rhi-&gt;waitForFences(); vulkan_rhi-&gt;resetCommandPool(); bool recreate_swapchain = vulkan_rhi-&gt;prepareBeforePass(std::bind(&amp;RenderPipeline::passUpdateAfterRecreateSwapchain, this)); if (recreate_swapchain) &#123; return; &#125; static_cast&lt;DirectionalLightShadowPass*&gt;(m_directional_light_pass.get())-&gt;draw(); static_cast&lt;PointLightShadowPass*&gt;(m_point_light_shadow_pass.get())-&gt;draw(); ColorGradingPass&amp; color_grading_pass = *(static_cast&lt;ColorGradingPass*&gt;(m_color_grading_pass.get())); FXAAPass&amp; fxaa_pass = *(static_cast&lt;FXAAPass*&gt;(m_fxaa_pass.get())); ToneMappingPass&amp; tone_mapping_pass = *(static_cast&lt;ToneMappingPass*&gt;(m_tone_mapping_pass.get())); UIPass&amp; ui_pass = *(static_cast&lt;UIPass*&gt;(m_ui_pass.get())); CombineUIPass&amp; combine_ui_pass = *(static_cast&lt;CombineUIPass*&gt;(m_combine_ui_pass.get())); static_cast&lt;MainCameraPass*&gt;(m_main_camera_pass.get()) -&gt;draw(color_grading_pass, fxaa_pass, tone_mapping_pass, ui_pass, combine_ui_pass, vulkan_rhi-&gt;m_current_swapchain_image_index); vulkan_rhi-&gt;submitRendering(std::bind(&amp;RenderPipeline::passUpdateAfterRecreateSwapchain, this));&#125;
主相机 pass 的 draw(...) 函数中依次执行了：
drawMeshGbuffer() drawDeferredLighting() drawBillboardParticle()（未实现） tone_mapping_pass.draw() color_grading_pass.draw() if (m_enable_fxaa) fxaa_pass.draw() drawAxis() ui_pass.draw()（未实现） combine_ui_pass.draw()（未实现）

这一节来学习 Vulkan 多线程渲染的设计理念和执行过程，学习过程中可以深入理解 Vulkan 中 Queue 和 Command Buffer 的关系与作用。
1 Vulkan 多线程设计理念Vulkan 不仅仅是图形 API，而是一个面向图形和计算的编程接口。支持 Vulkan 的设备可以是 GPU，也可以是 DSP 或者固定功能的硬件。 Vulkan 中的计算模型主要基于并行计算，因此支持多线程是 Vulkan 设计的核心理念之一。 为了减少 Vulkan 内部因为互斥同步等操作造成的卡顿问题，Vulkan 内部默认认为对任何资源的访问不存在多线程竞争，所有的资源同步操作由应用开发者去负责，因为对资源的访问和使用没有人比应用开发者自己更加清楚。Vulkan 称之为外部同步（external synchronization）。 因为这个原因，资源管理和线程同步工作成为编写 Vulkan 程序的最大难点之一。想要让 Vulkan 多线程正常运行，你需要做大量的工作。当然，换来的是 Vulkan 有了更加干净的线程模型以及比其它 CG API 高得多的性能。 2 Instances、Devices 和 QueuesVulkan 多线程模型与几个概念紧密相关，我们再次回顾这些概念：
Instances 可以看做是应用的子系统，从逻辑上把 Vulkan 与应用程序上下文中的其他逻辑隔开。Instances 可以看做是 Vulkan 的上下文，它会跟踪所有状态，从逻辑上把所有支持 Vulkan 的设备整合在一起。 Physical devices 和 Logical device 都是 Devices，Physical devices 通常代表一个或者多个支持 Vulkan 的硬件设备，这些设备具有特定功能，可以提供一系列 Queues。图形显卡、加速器、DSP 等都可以是 Vulkan 的 Physical devices。Logical device 是 Physical devices 的软件抽象，用于预订一些硬件资源。 Queues 可以理解为一个“GPU 线程”，它是实现 Vulkan 多线程的关键元素之一，用于响应应用的请求，大部分时间，应用都在与其进行交互。
三者之间的层次关系如下图所示：
3 Queues 和 Command Buffer3.1 QueuesQueue 代表一个 GPU 线程，Vulkan 设备执行的就是提交到 Queues 中的工作。物理设备中 Queue 可能不止一个，每一个 Queue 都被包含在 Queue Families 中。 Queue Families 是一个有相同功能的 Queues 的集合，它们的性能水平和对系统资源的访问是相同的，并且在它们之间数据传输工作没有任何成本（同步之外）。 一个物理设备中可以存在多个 Queue Families，不同的 Queue Families 有不同的特性。相同 Queue Families 中的 Queues 的功能相同，并且可以并行运行。如下图：
按照 Queue 的能力，可以将其划分为：
Graphics（图形）：该系列中的 Queues 支持图形操作，例如绘制点，线和三角形。
Compute（计算）：该系列中的 Queues 支持诸如 computer shader 之类的计算操作。
Transfer（传输，拷贝）：该系列中的 Queues 支持传输操作，例如复制缓冲区和图像内容。
Sparse binding（稀疏绑定）：该系列中的 Queues 支持用于更新稀疏资源（sparse resource）的内存绑定操作。
3.2 Command Buffer传统 CG API 是单线程的，性能的提升只能依赖于 CPU 主频的提高。能有的优化方案也不外乎主线程和渲染线程分开，或者某些资源的异步加载、离线处理。
Vulkan 为了充分发挥 CPU 多核多线程的作用，引入了 command buffer 的概念。多个线程可以同时协作，每个 CPU 线程都可以往自己的 command buffer 中提交渲染命令，然后统一提交到对应的 Queue 中，大大提高了 CPU 的利用率。
应用在绘制时会提交一系列绘制命令给 GPU 驱动，但是这些绘制命令不会立刻被执行，而是被简单的添加到 Command Buffer 的末尾。 在其他 CG APIs 中，驱动程序在应用不感知的情况下，把 API 调用翻译成 GPU command 并储存在 command buffer 中，最终提交给 GPU 处理。command buffer 的创建和销毁都由驱动负责。 而在 Vulkan 中，你需要自己从 Command Buffer Pool 中申请 command buffer，将想要记录的命令放入 command buffer 中。
Command Buffer 可以记录（Record）很多命令，比如设置状态、绘制操作、数据拷贝等等，如下图所示：
理论上，一个线程可以把 Command 记录到多个 Command Buffer 中，多个线程也可以共享同一个 Command Buffer，但是一般不鼓励多个线程共享一个 Command Buffer。 Vulkan 的关键设计原则之一就是做到高效的多线程。想实现这一点，应用程序要注意因为资源竞争导致的多线程彼此阻塞。因此，每个线程最好有一个或者多个 Command Buffer，不要尝试共享一个。另外，Command Buffer 由 Command Buffer Pool 分配，应用可以为每一个线程创建一个 Command Buffer Pool，让各个工作线程从 Command Buffer Pool 中分配 Command Buffer，无需参与竞争。 3.3 Command Buffer 生命周期从 Command Buffer 创建开始，会经历不同的状态，如下图所示：
Initial 状态：在 Command-Buffer 刚刚创建时，它就是处于初始化的状态。从此状态，可以达到 Recording 状态，另外，如果重置之后，也会回到该状态。 Recording 状态：调用 vkBeginCommandBuffer 方法从 Initial 状态进入到该状态。一旦进入该状态后，就可以调用 vkCmd* 等系列方法记录命令。 Executable 状态：调用 vkEndCommandBuffer 方法从 Recording 状态进入到该状态，此状态下，Command-Buffer 可以提交或者重置。 Pending 状态：把 Command-Buffer 提交到 Queue 之后，就会进入到该状态。此状态下，物理设备可能正在处理记录的命令，因此不要在此时更改 Command-Buffer，当处理结束后，Command-Buffer 可能会回到 Executable 状态或者 Invalid 状态。 Invalid 状态：一些操作会使得 Command-Buffer 进入到此状态，该状态下，Command-Buffer 只能重置、或者释放。
4 Vulkan 同步机制4.1 显式同步操作Vulkan 把同步的操作交给了我们的应用程序（external synchronization），绝大多数的 Vulkan 命令根本不提供同步，需要应用自己负责。Vulkan 给应用提供了同步原语，帮助应用进行同步操作。 Vulkan 中主要有四种同步原语（synchronization primitives）：
Fences：最大颗粒度的同步原语，用来保证物理设备和应用程序之间的同步，比如说向 Queue 中提交了 Command-Buffer 后，具体的执行交由物理设备去完成了，这是一个异步的过程，而应用程序如果要等待执行结束，就要使用 Fence 机制。因此 Fences 给 CPU 端提供了一种方法，可以使其知道 GPU 或者其他 Vulkan Device 什么时候把提交的工作全部做完。
Semaphores：颗粒度比 Fences 更小一点，主要是用来向 Queue 中提交 Command-Buffer 时实现同步。比如说某个 Command-Buffer-B 在执行的某个阶段中需要等待另一个 Command-Buffer-A 执行成功后的结果，同时 Command-Buffer-C 在某阶段又要等待 Command-Buffer-B 的执行结果，那么就应该使用 Semaphore 机制实现同步；此时 Command-Buffer-B 提交到 Queue 时就需要两个 VkSemaphor ，一个表示它需要等待的 Semaphore，并且指定在哪个阶段等待；一个是它执行结束后发出通知的 Semaphore。
Events：颗粒度更小，可以用于 Command Buffer 之间的同步工作
Barriers：Vulkan 流水线（Pipeline）阶段内用于内存访问管理和资源状态移动的同步机制
4.2 隐式执行顺序在没有同步原语的情况下，Vulkan 的执行顺序其实是有一定的潜规则的：
Command Buffer 中的 Command，先记录的先执行 先提交的 Command Buffer 先执行 同一个 Queue 中，一起提交的 Command Buffer1 和 Command Buffer2 按照下标的顺序执行，即 Command Buffer1 先执行
4.3 BarriersBarriers 需要开发者了解渲染管线的各个阶段，能清晰的把握管线中每个步骤对资源的读写顺序。 Vulkan 中将 Pipeline 的各个阶段定义为：
TOP_OF_PIPE_BIT DRAW_INDIRECT_BIT VERTEX_INPUT_BIT VERTEX_SHADER_BIT TESSELLATION_CONTROL_SHADER_BIT TESSELLATION_EVALUATION_SHADER_BIT GEOMETRY_SHADER_BIT FRAGMENT_SHADER_BIT EARLY_FRAGMENT_TESTS_BIT LATE_FRAGMENT_TESTS_BIT COLOR_ATTACHMENT_OUTPUT_BIT TRANSFER_BIT COMPUTE_SHADER_BIT BOTTOM_OF_PIPE_BIT
对应于管线流程图：
假设我们有个两个渲染管线 P1 和 P2，P1 会通过 Vertex Shader 往 buffer 写入顶点数据，P2 需要在 Compute Shader 中使用这些数据。 如果使用 fence 去同步，我们的流程应该是这样：P1 的 Command 提交后，P2 通过 fence 确保 P1 的操作已经被全部执行完，再开始工作。
但是这种大颗粒度的同步操作无疑造成了耗时操作：P1 的数据在 Vertex Shader 阶段就已经准备好了，我们为什么要等到它所有操作执行完再开始？P2 平白多等待了很长时间，而且在这个期间 P2 的其他阶段并没有使用到 P1 的数据，也是可以同步执行的。 Barriers 的引入完全解决了这个问题，我们只需要告诉 Vulkan，我们在 P2 的 Compute Shader 阶段才会等待 P1 Vertex Shader 里面的数据，其他阶段并不关心，可以同步进行。
5 具体用法接下来总结上述 4 种组件的具体用法。首先回顾 Vulkan 中重要的组件及其工作流程：
在 Vulkan 的 API 中有一些固定的调用套路 ：
要创建某个对象，先提供一个包含创建信息的对象。 创建时通过传递引用的方式来传参。
5.1 Instance 组件在 vkCreateInstance 函数中有个名为 VkInstanceCreateInfo 类型的参数，这就是包含了 VKInstance 要创建的信息： typedef struct VkInstanceCreateInfo &#123; VkStructureType sType; // 一般为方法对应的类型 const void* pNext; // 一般为 null 就好了 VkInstanceCreateFlags flags; // 留着以后用的，设为 0 就好了 const VkApplicationInfo* pApplicationInfo; // 对应新的一个结构体 VkApplicationInfo uint32_t enabledLayerCount; // layer 和 extension 用于调试和拓展 const char* const* ppEnabledLayerNames; uint32_t enabledExtensionCount; const char* const* ppEnabledExtensionNames;&#125; VkInstanceCreateInfo;
除此之外还需要创建一个 VkApplicationInfo 对象： typedef struct VkApplicationInfo &#123; VkStructureType sType; const void* pNext; const char* pApplicationName; uint32_t applicationVersion; const char* pEngineName; uint32_t engineVersion; uint32_t apiVersion;&#125; VkApplicationInfo;
下面是创建一个 instance 的代码： VkApplicationInfo app_info = &#123;&#125;;app_info.apiVersion = VK_API_VERSION_1_0;app_info.applicationVersion = 1;app_info.engineVersion = 1;app_info.pNext = nullptr;app_info.sType = VK_STRUCTURE_TYPE_APPLICATION_INFO;app_info.pEngineName = APPLICATION_NAME;app_info.pApplicationName = APPLICATION_NAME;VkInstanceCreateInfo instance_info = &#123;&#125;;// type 就是结构体的类型instance_info.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO;instance_info.pNext = nullptr;instance_info.pApplicationInfo = &amp;app_info;instance_info.flags = 0;// Extension and Layer 暂时不用,可空instance_info.enabledExtensionCount = 0;instance_info.ppEnabledExtensionNames = nullptr;instance_info.ppEnabledLayerNames = nullptr;instance_info.enabledLayerCount = 0;VkResult result = vkCreateInstance(&amp;instance_info, nullptr, &amp;instance);
当每调用一个创建函数后，返回的类型都是 VkResult ，只要 VkResult 大于 0 ，那么执行就是成功的。 5.2 Device 组件有了 Instance 组件，就可以创建 Device 组件了，按照调用的套路，肯定还会有一个 VkDeviceCreateInfo 的结构体表示 Device 的创建信息。 Device 具体指的是逻辑上的设备，可以说是对物理设备的一个逻辑上的封装，而物理设备就是 VkPhysicalDevice 对象。 在某些情况下，可能会具有多个物理设备，因此要先枚举一下所有的物理设备： uint32_t gpu_size = 0;// 第一次调用只为了获得个数VkResult res = vkEnumeratePhysicalDevices(instance, &amp;gpu_size, nullptr);
在 vkEnumeratePhysicalDevices 方法中，传入的第二个参数为 GPU 的个数，第三个参数为 null，这样的一次调用会返回 GPU 的个数到 gpu_size 变量。 vector&lt;VkPhysicalDevice&gt; gpus;gpus.resize(gpu_size);// 第二次调用获得所有的数据，vector.data() 方法转换成指针类型res = vkEnumeratePhysicalDevices(instance, &amp;gpu_size, gpus.data());
当再一次调用 vkEnumeratePhysicalDevices 函数时，第三个参数不为 null，而是相应的 VkPhysicalDevice 容器，那么 gpus 会填充 gpu_size 个的 VkPhysicalDevice 对象。 有了 VkPhysicalDevice 对象之后，可以查询 VkPhysicalDevice 上的一些属性，以下函数都可以查询相关信息：
vkGetPhysicalDeviceQueueFamilyProperties vkGetPhysicalDeviceMemoryProperties vkGetPhysicalDeviceProperties vkGetPhysicalDeviceImageFormatProperties vkGetPhysicalDeviceFormatProperties
以 QueueFamilyProperties 为例，获得该属性的方法调用方式和获得 VkPhysicalDevice 数据方式一样，也是一个两次调用： // 第一次调用，获得个数uint32_t queue_family_count = 0;vkGetPhysicalDeviceQueueFamilyProperties(gpus[0], &amp;queue_family_count, nullptr);assert(queue_family_count != 0);// 第二次调用，获得实际数据vector&lt;VkQueueFamilyProperties&gt; queue_family_props;queue_family_props.resize(queue_family_count);vkGetPhysicalDeviceQueueFamilyProperties(gpus[0], &amp;queue_family_count, queue_family_props.data());assert(queue_family_count != 0);
QueueFamilyProperties 的结构体含义如下： typedef struct VkQueueFamilyProperties &#123; VkQueueFlags queueFlags; // 标识位：表示 Queue 的功能 uint32_t queueCount; uint32_t timestampValidBits; VkExtent3D minImageTransferGranularity;&#125; VkQueueFamilyProperties;
其中的 queueFlags 表示该 Queue 的能力，有的 Queue 是用来渲染图像的，还有的 Queue 是用来计算的，具体的 Flag 标识如下： typedef enum VkQueueFlagBits &#123; VK_QUEUE_GRAPHICS_BIT = 0x00000001, // 图像相关 VK_QUEUE_COMPUTE_BIT = 0x00000002, // 计算相关 VK_QUEUE_TRANSFER_BIT = 0x00000004, // 传输，拷贝 VK_QUEUE_SPARSE_BINDING_BIT = 0x00000008, // 稀疏绑定 VK_QUEUE_FLAG_BITS_MAX_ENUM = 0x7FFFFFFF&#125; VkQueueFlagBits;typedef VkFlags VkQueueFlags;
接下来是创建一个 Device，在 VkDeviceCreateInfo 结构体中需要一个参数是 VkDeviceQueueCreateInfo ，因此要先创建 VkDeviceQueueCreateInfo，再创建 VkDeviceCreateInfo，最后调用 vkCreateDevice 创建一个 Device： // 创建 Queue 所需的相关信息VkDeviceQueueCreateInfo queue_info = &#123;&#125;;// 找到属性为 VK_QUEUE_GRAPHICS_BIT 的索引bool found = false; for (unsigned int i = 0; i &lt; queue_family_count; ++i) &#123; if (queue_family_props[i].queueFlags &amp; VK_QUEUE_GRAPHICS_BIT) &#123; queue_info.queueFamilyIndex = i; found = true; break; &#125;&#125;float queue_priorities[1] = &#123;0.0&#125;;// 结构体的类型queue_info.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;queue_info.pNext = nullptr;queue_info.queueCount = 1;// Queue 的优先级queue_info.pQueuePriorities = queue_priorities;// 创建 Device 所需的相关信息类VkDeviceCreateInfo device_info = &#123;&#125;;device_info.sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO;device_info.pNext = nullptr;// Device 所需的 Queue 相关信息device_info.queueCreateInfoCount = 1; // Queue 个数device_info.pQueueCreateInfos = &amp;queue_info; // Queue 相关信息// Layer 和 Extension 暂时为空，不影响运行，后续再补上device_info.enabledExtensionCount = 0;device_info.ppEnabledExtensionNames = NULL;device_info.enabledLayerCount = 0;device_info.ppEnabledLayerNames = NULL;device_info.pEnabledFeatures = NULL;VkResult res = vkCreateDevice(gpus[0], &amp;device_info, nullptr, &amp;device);
5.3 Queue 组件完成了 Device 创建之后，Queue 的创建也简单多了，直接调用如下函数就好了： typedef void (VKAPI_PTR *PFN_vkGetDeviceQueue)(VkDevice device, // 创建的 Device 对象uint32_t queueFamilyIndex, // queueFlags 为 VK_QUEUE_GRAPHICS_BIT 的索引uint32_t queueIndex, VkQueue* pQueue); // 要创建的 Queue// 代码示例vkGetDeviceQueue(info.device, info.graphics_queue_family_index, 0, &amp;info.queue);
完成了 Instance、Device、Queue 组件的创建之后，还有一件要做的事情就是释放它们，销毁组件。 按照先进后出的方式进行销毁，Instance 最先创建因此最后销毁，和 Device 相关联的 Queue 在 Device 销毁时就随之销毁了。 // 销毁 DevicevkDestroyDevice(info.device, nullptr);// 销毁 InstancevkDestroyInstance(info.instance, nullptr);
5.4 Command Buffer 组件在前面的学习中，我们已经创建了 Instance、Device、Queue 三个组件，并且知道了 Queue 组件是用来和物理设备沟通的桥梁，而具体的沟通过程就需要 Command-Buffer 组件，它是若干命令的集合，我们向 Queue 提交 Command-Buffer，然后才交由物理设备 GPU 进行处理。 5.4.1 创建 Command Pool在创建 Command-Buffer 之前，需要创建 Command-Pool 组件，从 Command-Pool 中去分配 Command-Buffer 。还是老套路，我们需要先创建一个 VkCommandPoolCreateInfo 的结构体，结构体每个参数的释义还是要多参考官方的文档。 // 创建 Command-Pool 组件VkCommandPool command_pool;VkCommandPoolCreateInfo poolCreateInfo = &#123;&#125;;poolCreateInfo.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO;// 可以看到 Command-Pool 还和 Queue 相关联poolCreateInfo.queueFamilyIndex = info.graphics_queue_family_index;// 标识命令缓冲区的一些行为poolCreateInfo.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;// 具体创建函数的调用vkCreateCommandPool(info.device, &amp;poolCreateInfo, nullptr, &amp;command_pool);
有几个参数需要注意：
queueFamilyIndex 参数表示创建 Queue 时选择的那个 queueFlags 为 VK_QUEUE_GRAPHICS_BIT 的索引，从 Command-Pool 中分配的的 Command-Buffer 必须提交到同一个 Queue 中。 flags 有如下的选项，分别指定了 Command-Buffer 的不同特性：
typedef enum VkCommandPoolCreateFlagBits &#123; VK_COMMAND_POOL_CREATE_TRANSIENT_BIT = 0x00000001, VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT = 0x00000002, VK_COMMAND_POOL_CREATE_FLAG_BITS_MAX_ENUM = 0x7FFFFFFF&#125; VkCommandPoolCreateFlagBits;
VK_COMMAND_POOL_CREATE_TRANSIENT_BIT：表示该 Command-Buffer 的寿命很短，可能在短时间内被重置或释放 VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT：表示从 Command-Pool 中分配的 Command-Buffer 可以通过 vkResetCommandBuffer 或者 vkBeginCommandBuffer 方法进行重置，如果没有设置该标识位，就不能调用 vkResetCommandBuffer 方法进行重置。
5.4.2 创建 Command Buffer接下来就是从 Command-Pool 中分配 Command-Buffer，通过 VkCommandBufferAllocateInfo 函数。首先需要一个 VkCommandBufferAllocateInfo 结构体表示分配所需要的信息： typedef struct VkCommandBufferAllocateInfo &#123; VkStructureType sType; const void* pNext; VkCommandPool commandPool; // 对应上面创建的 command-pool VkCommandBufferLevel level; uint32_t commandBufferCount; // 创建的个数&#125; VkCommandBufferAllocateInfo;
这里有个参数也要注意：
VkCommandBufferLevel 指定 Command-Buffer 的级别。
有如下级别可以使用： typedef enum VkCommandBufferLevel &#123; VK_COMMAND_BUFFER_LEVEL_PRIMARY = 0, VK_COMMAND_BUFFER_LEVEL_SECONDARY = 1, VK_COMMAND_BUFFER_LEVEL_BEGIN_RANGE = VK_COMMAND_BUFFER_LEVEL_PRIMARY, VK_COMMAND_BUFFER_LEVEL_END_RANGE = VK_COMMAND_BUFFER_LEVEL_SECONDARY, VK_COMMAND_BUFFER_LEVEL_RANGE_SIZE = (VK_COMMAND_BUFFER_LEVEL_SECONDARY - VK_COMMAND_BUFFER_LEVEL_PRIMARY + 1), VK_COMMAND_BUFFER_LEVEL_MAX_ENUM = 0x7FFFFFFF&#125; VkCommandBufferLevel;
一般来说，使用 VK_COMMAND_BUFFER_LEVEL_PRIMARY 就好了。 具体创建代码如下： VkCommandBuffer commandBuffer[2];VkCommandBufferAllocateInfo command_buffer_allocate_info&#123;&#125;;command_buffer_allocate_info.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO;command_buffer_allocate_info.commandPool = command_pool;command_buffer_allocate_info.commandBufferCount = 2;command_buffer_allocate_info.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;vkAllocateCommandBuffers(info.device, &amp;command_buffer_allocate_info, commandBuffer);
5.4.3 Command Buffer 记录与提交命令回顾上面的 Command Buffer 记录命令流程图：
在 vkBeginCommandBuffer 和 vkEndCommandBuffer 方法之间可以记录和渲染相关的命令，我们先不考虑中间的过程，直接创建提交。 首先，还是需要创建一个 VkCommandBufferBeginInfo 结构体用来表示 Command-Buffer 开始的信息： VkCommandBufferBeginInfo beginInfo = &#123;&#125;;beginInfo.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;beginInfo.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;vkBeginCommandBuffer(commandBuffer[0], &amp;beginInfo);
这里要注意的参数是 flags ，表示 Command-Buffer 的用途： typedef enum VkCommandBufferUsageFlagBits &#123; VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT = 0x00000001, VK_COMMAND_BUFFER_USAGE_RENDER_PASS_CONTINUE_BIT = 0x00000002, VK_COMMAND_BUFFER_USAGE_SIMULTANEOUS_USE_BIT = 0x00000004, VK_COMMAND_BUFFER_USAGE_FLAG_BITS_MAX_ENUM = 0x7FFFFFFF&#125; VkCommandBufferUsageFlagBits;
我们用的 VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT 表示该 Command-Buffer 只使用提交一次，用完之后就会被重置，并且每次提交时都需要重新记录。 直接调用 vkEndCommandBuffer 方法就可以结束记录，此时就可以提交了： vkEndCommandBuffer(commandBuffer[0]);
接下来通过 vkQueueSubmit 方法将 Command-Buffer 提交到 Queue 上。同样的还是需要创建一个 VkSubmitInfo 结构体： typedef struct VkSubmitInfo &#123; VkStructureType sType; const void* pNext; uint32_t waitSemaphoreCount; // 等待的 Semaphore 数量 const VkSemaphore* pWaitSemaphores; // 等待的 Semaphore 数组指针 const VkPipelineStageFlags* pWaitDstStageMask; // 在哪个阶段进行等待 uint32_t commandBufferCount; // 提交的 Command-Buffer 数量 const VkCommandBuffer* pCommandBuffers; // 具体的 Command-Buffer 数组指针 uint32_t signalSemaphoreCount; //执行结束后通知的 Semaphore 数量 const VkSemaphore* pSignalSemaphores; //执行结束后通知的 Semaphore 数组指针&#125; VkSubmitInfo;
它的参数比较多，并且涉及到 Command-Buffer 之间的同步关系了，上面已经提到过 Semaphore 和 Fence 的相关内容。 如果只是简单的提交 Command-Buffer，那就不需要考虑 Semaphore 这些同步机制了，把相应的参数都设置为 nullptr，或者直接不设置也行，最后提交就好了，代码如下： // 简单的提交过程// 开始记录VkCommandBufferBeginInfo beginInfo1 = &#123;&#125;;beginInfo1.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;beginInfo1.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;vkBeginCommandBuffer(commandBuffer[0], &amp;beginInfo1);...// 省略中间的 vkCmdXXXX 系列方法// 结束记录vkEndCommandBuffer(commandBuffer[0]);VkSubmitInfo submitInfo1 = &#123;&#125;;submitInfo1.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;// pWaitSemaphores 和 pSignalSemaphores 都不设置，只是提交submitInfo1.commandBufferCount = 1;submitInfo1.pCommandBuffers = &amp;commandBuffer[0];// 注意最后的参数 临时设置为 VK_NULL_HANDLE，也可以设置为 Fence 来同步vkQueueSubmit(info.queue, 1, &amp;submitInfo1, VK_NULL_HANDLE);
以上就完成了 Command-Buffer 提交到 Queue 的过程，省略了 Semaphores 和 Fences 的同步机制，当然也可以把它们加上。 我们在 vkQueueSubmit 的最后一个参数设置为了 VK_NULL_HANDLE ，这是 Vulkan 中设置为 NULL 的一个方法（其实是设置了一个整数 0 ），也可以设置 Fence ，表示我们要等待该 Command-Buffer 在 Queue 执行结束，当 vkQueueSubmit 的最后参数传入 Fence 后，就可以通过 Fence 等待该 Command-Buffer 执行结束： // 创建 FenceVkFence drawFence;VkFenceCreateInfo fenceCreateInfo = &#123;&#125;;fenceCreateInfo.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO;// 该参数表示 Fence 的状态，如果不设置或者为 0 表示 unsignaled statefence_info.flags = 0; vkCreateFence(info.device, &amp;fenceCreateInfo, nullptr, &amp;drawFence);... // 最后的参数设置为 Fence 来同步vkQueueSubmit(info.queue, 1, &amp;submitInfo1, &amp;drawFence);// 等待 Command buffer 执行结束VkResult res;do &#123; res = vkWaitForFences(info.device, 1, &amp;drawFence, VK_TRUE, UINT64_MAX);&#125; while (res == VK_TIMEOUT);

本篇介绍了策略模式及相关的面向对象设计原则。策略模式定义了一族算法，将它们分别封装起来，让它们之间可以相互替换，此模式让算法的变化独立于使用算法的用户。
1 引例鸭子模拟游戏中会出现各种鸭子，一边游泳，一边呱呱叫，此系统内部使用了标准的面向对象技术，设计了一个鸭子父类，并让各种鸭子继承此父类。
此时如果希望鸭子能飞起来，最简单的方法就是在父类中加上一个fly()方法：
但并不是所有鸭子都会飞，于是想到可以在子类中重写fly()方法，让其什么也不做，从而覆盖掉父类的fly()方法。同样，也是不所有鸭子都会嘎嘎叫，比如橡皮鸭子是吱吱叫，同样可以通过重写quack()方法覆盖掉父类的方法来实现。
之后，如果我们想新加入一个木头假鸭类型，它既不会飞也不会叫，那么用同样的方式覆盖父类对应的方法就可以实现。但是当我们需要不断地新增不同类型的鸭子，或者不断地修改不同类型鸭子的行为时，就需要不停的新建子类，重写并覆盖原来的方法，显然这样的实现方式使得我们虽然利用了面向对象的“继承”这一特性，但却并没有实现代码的复用。 转变思路，我们可以将fly()方法从鸭子类中分离出来，放进一个Flyable的接口（抽象类）中，只有会飞的鸭子才继承此抽象类，并实现其中的fly()方法，quack()方法同样分离出来放在Quackable的抽象类中，只有会叫的鸭子才继承此抽象类并实现其中的quack()方法。
这样的设计看似更加巧妙，但重复的代码会变得更多，且代码依然无法复用，我们要为每一个会叫的鸭子写一套quack()代码，即使他们叫的方式是相同的。 对于上面这个例子，似乎继承和接口都不能很好的解决问题，而恰好有一个设计模式，可以适用于这种情况。 2 策略模式 设计原则：将变化的部分单独封装起来 找出程序中可能需要变化的地方，把他们独立出来并进行封装，使他们和那些不会变化的代码分开，以便之后可以轻易的修改或扩充这一部分代码，而不影响那些不需要变化的部分。
对于上面的例子，显然fly()和quack()就是代码中需要变化的部分，因为他们会随着不同的鸭子类型或者不同的用户需求随时发生变化，所以我们可以将他们从鸭子类中独立出来，分别建立两个抽象类FlyBehavior和QuackBehavior： class FlyBehavior &#123;public: virtual void fly() = 0;&#125;;class QuackBehavior &#123;public: virtual void quack() = 0;&#125;;
这两个抽象类代表飞和叫这两种行为，至于怎么飞，怎么叫，通过具体的行为类继承于这两个抽象类来实现，比如飞的行为可以分为用翅膀飞和不会飞这两种： class FlyWithWings : public FlyBehavior &#123;public: virtual void fly() &#123; cout &lt;&lt; &quot;用翅膀飞&quot; &lt;&lt; endl; &#125;&#125;;class FlyNoWay : public FlyBehavior &#123;public: virtual void fly() &#123; cout &lt;&lt; &quot;不会飞&quot; &lt;&lt; endl; &#125;&#125;;
叫的行为也类似，比如可以实现嘎嘎叫和不会叫： class Quack : public QuackBehavior &#123;public: virtual void quack() &#123; cout &lt;&lt; &quot;嘎嘎叫&quot; &lt;&lt; endl; &#125;&#125;;class MuteQuack : public QuackBehavior &#123;public: virtual void quack() &#123; cout &lt;&lt; &quot;不会叫&quot; &lt;&lt; endl; &#125;&#125;;
之后我们在鸭子类中加入这两种行为类的对象，然后将原本的fly()和quack()方法改为PerformFly()和PerformQuack()方法： class Duck&#123;public: FlyBehavior* flyBehavior; QuackBehavior* quackBehavior; //其他成员 void PerformFly()&#123; flyBehavior-&gt;fly(); &#125; void PerformQuack()&#123; quackBehavior-&gt;quack(); &#125;&#125;
当我们想要构造一个鸭子子类的时候，只需要继承鸭子父类，并在构造函数中指定该子类的具体行为对象，就可以控制鸭子子类的行为了： class MallardDuck : public Duck&#123;public: MallardDuck()&#123; flyBehavior = new FlyWithWings(); // 绿头鸭会用翅膀飞 quackBehavior = new Quack(); // 绿头鸭会嘎嘎叫 &#125;&#125;;
利用上面的设计方法可以让我们在编程时不需要关注鸭子是什么具体类型，因为我们可以利用多态，比如有一个getDuck()函数会返回一个具体类型的鸭子，至于是什么类型，可能在程序运行时才能确定，那么我们的主函数就可以这样写： int main()&#123; Duck* duck = getDuck(); duck-&gt;PerformFly(); duck-&gt;PerformQuack(); return 0;&#125;
当然，上面的设计依然不够有弹性，因为每一个子类的鸭子具有什么行为是在构造函数中指定的，如果我们希望同一类鸭子也能自由的设定不同的行为，那么只需要在鸭子父类中加上一个设定行为的方法就可以了： class Duck&#123;public: FlyBehavior* flyBehavior; QuackBehavior* quackBehavior; //其他成员 void PerformFly()&#123; flyBehavior-&gt;fly(); &#125; void PerformQuack()&#123; quackBehavior-&gt;quack(); &#125; //动态设定行为 void SetFlyBehavior(FlyBehavior* fb)&#123; flyBehavior = fb; &#125; void SetQuackBehavior(QuackBehavior* qb)&#123; quackBehavior = qb; &#125;&#125;;
这样我们通过调用鸭子的SetFlyBehavior()和SetQuackBehavior()方法就可以随时改变鸭子的行为了。 纵观上面的设计过程，我们把鸭子类中经常变化的部分独立出来，封装成了单独的抽象类，也就是一个接口，然后用不同的代码去实现这个接口（抽象类的子类），这些不同的代码就是“一族算法”，而在鸭子类中，只要包含这一族算法的统一接口就可以灵活地使用他们当中的任何一个。
设计原则：面向接口编程，而不是面向实现编程。
能够实现这样灵活的效果的原因在于，所有鸭子的行为并不是从父类继承而来的，而是与不同的行为对象组合而来的，因此恰当的使用类的组合有时要比一味的使用类的继承灵活的多。而进行组合的类也不一定是行为，也可以是物品、属性等等，比如游戏中不同的角色有不同的武器，那么一个角色就可以由角色类和武器类组合而来。
设计原则：多用组合，少用继承。
利用组合构建系统具有很大的弹性，不仅可以将一族算法封装成类，还可以在运行时动态的改变类对象的行为或属性，只要组合的类符合接口标准即可。因此在面向对象程序设计中，简单的使用继承和多态不一定能降低代码量和代码维护成本，灵活使用类的组合也可以达到代码复用的目的。 上面的设计还有一个好处就是，每一族算法或者其中的每一个算法都可以有自己的成员，比如算法要用到的参数，状态和其他辅助函数等等，只要最终实现了接口就可以，这可以让算法的设计更加灵活。 上面的设计模式就是策略模式，策略模式定义了一族算法，将它们分别封装起来，让它们之间可以相互替换，此模式让算法的变化独立于使用算法的用户。

本篇介绍了装饰者模式及相关的面向对象设计原则。装饰者模式动态的将责任附加到对象身上，扩展功能时，装饰者模式相比于继承能为系统带来更好的弹性。
1 引例一个咖啡饮料系统需要为所有类型的饮料定义各自的类，最原始的设计是这样：
在购买饮料时，顾客可以在某种饮料的基础上加入各种调料，比如奶泡、摩卡等，不同调料的价格也不同，组合而成的饮料价格也就不同，不同的调料搭配不同的饮料可能会出现无数种组合，如果一味的使用继承，将会使饮料子类的数量急剧膨胀，难以管理的同时还会出现大量的重复代码。因此我们希望能有一种设计模式来解决这种问题。 2 装饰者模式 设计原则：开放-关闭原则，对扩展开放，对修改关闭。
开放-关闭原则是指当一个类设计好之后，尽可能不对他进行修改，但又能允许该类进行扩展，也就是在不修改现有代码的前提下，扩展新的行为。装饰者模式就实现了这一目的。 以一杯加了奶泡和摩卡的深焙咖啡为例，构建这样一种饮品的流程是：
这就是一个装饰者模式的流程，装饰者模式的类图结构如下：
按着上面的类图，饮料就作为组件，具体的饮料类型对应于具体组件，而调料作为装饰器，具体的调料对应不同的具体装饰器，于是我们可以开始用装饰者模式实现上面的饮料系统。 首先是组件（饮料）类： class Component &#123;public: // 其他内容... string discription = &quot;Unknow Beverage&quot;; string getDiscription() &#123; return discription; &#125; virtual double cost() = 0;&#125;;
装饰器（调料）要和组件是同一类，这样才能保证所有装饰器都能代替组件，调用同一个接口，因此需要继承于组件类： class Decorator : public Component &#123;public: // 所有调料都要有自己的描述，这样才能输出完整的配料 virtual string getDiscription() = 0;&#125;;
接下来实现一个具体组件类，比如浓缩咖啡（Espresso）类： class Espresso : public Component &#123;public: Espresso() &#123; discription = &quot;Espresso&quot;; &#125; virtual double cost() &#123; return 1.99; &#125;&#125;;
然后实现一个具体装饰器，比如摩卡（Mocha）类： class Mocha : public Decorator &#123;private: Component* beverage; //被装饰者public: Mocha(Component* b) : beverage(b) &#123;&#125; virtual string getDiscription() &#123; return beverage-&gt;getDiscription() + &quot;, Mocha&quot;; &#125; virtual double cost() &#123; return beverage-&gt;cost() + 0.2; &#125; &#125;;
按照上面的方法可以构建不同的饮料和调料，之后就可以随意组合了，在调用的时候也会变得无比方便： int main() &#123; Component* beverage = new Espresso(); // 一杯浓缩咖啡 beverage = new Mocha(beverage); // 加入一份摩卡 beverage = new Whip(beverage); // 加入一份奶泡 beverage = new Sugar(beverage); // 加入一份糖 cout &lt;&lt; beverage.getDiscription() &lt;&lt; endl; cout &lt;&lt; beverage.cost() &lt;&lt; endl; return 0;&#125;
总结来看，装饰者类是一个组件类，也就是和被装饰者是 is-a 的关系，但同时装饰者类中又包含组件类，对组件类进行扩展，因此二者之间还存在 has-a 的关系。装饰者模式利用组合解决了继承带来的子类膨胀和灵活性差的问题。

本篇介绍了观察者模式及相关的面向对象设计原则。观察者模式定义了对象之间的一对多依赖，当一个对象的状态改变时，他的所有依赖者都会收到通知并自动更新。
1 引例有一个气象站系统需要构建，系统中包含三部分：
其中气象站负责感应气象数据，WeatherData 对象从气象站获取数据并更新气象显示装置，气象显示装置有不同的显示界面，比如目前状况、气象统计、天气预报等等，未来还可能加入新的显示界面。 一种实现方式是： class WeatherData&#123; //其他内容... void measurementsChanged()&#123; float temp = getTemperature(); float humidity = getHumidity(); float pressure = getPressure(); // 调用各显示面板的更新函数，以更新各显示界面 currentConditionsDisplay.update(temp, humidity, pressure); statisticsDisplay.update(temp, humidity, pressure); forecastDisplay.update(temp, humidity, pressure); &#125;&#125;;
显然这样的实现方式违背了上一节提到的诸多设计原则，比如没有把不变和变化的代码分开，如果后续需要加入新的显示面板，就要更改 WeatherData 的代码，再比如调用面板的update()方法没有面向接口编程，而是一个一个的调用了具体面板的接口。因此这样的设计会为后续的系统维护带来巨大的成本。 2 观察者模式观察者模式定义了对象之间的一对多依赖，当一个对象的状态改变时，他的所有依赖者都会收到通知并自动更新。
观察者模式通常通过构建 Subject 接口 Observer 接口来实现：
观察者模式提供了一种对象设计，让主题对象和观察者对象之间松耦合。所谓松耦合是指两个对象之间依然可以交互，但彼此不清楚对方的细节。松耦合的好处在于，主题对象只知道观察者实现了 Observer 接口，而无需关注观察者具体是谁，做了什么或者任何其他细节。在代码运行的任何时候都可以增加或者删除观察者，主题不会受到任何影响，它只在状态改变时，遍历观察者列表并通知他们。当我们改变主题或者观察者任意一方时，另一方都不会受到任何影响，只要它们之间的接口依然被遵守。因此使用松耦合设计系统会更有的弹性，更容易应对变化，因为对象之间的互相依赖降到了最低。
设计原则：为了交互对象之间的松耦合而努力。
回顾上面的气象站项目，显然 WeatherData 对象就是主题，主题在实现的时候通常也被称为 Observable（可观察对象），也就是被观察者，而不同的显示面板就是观察者。 于是我们首先需要实现两个接口： // 观察者class Observer &#123;public: virtual void update(float temp, float humidity, float pressure) = 0;&#125;;// 可观察者class Observable &#123;public: virtual void registerObserver(Observer* o) = 0; virtual void removeObserver(Observer* o) = 0; virtual void notifyObservers() = 0;&#125;;
然后实现 WeatherData 类： class WeatherData : public Observable &#123;private: std::list&lt;Observer*&gt; observers; float temperature; float humidity; float pressure;public: virtual void registerObserver(Observer* o) &#123; observers.push_back(o); &#125; virtual void removeObserver(Observer* o) &#123; observers.remove(o); &#125; virtual void notifyObservers() &#123; std::list&lt;Observer*&gt;::iterator it = observers.begin(); while (it != observers.end()) &#123; (*it)-&gt;update(temperature, humidity, pressure); ++it; &#125; &#125; void measurementsChanged() &#123; notifyObservers(); &#125; // 其他方法...&#125;;
某个观察者显示面板的实现更为简单： class CurrentConditionsDisplay : public Observer &#123;private: float temperature; float humidity; Observable* weatherData; //绑定一个被观察者，用于注册或者取消观察public: CurrentConditionsDisplay(Observable* o) : weatherData(o) &#123;&#125; virtual void update(float temp, float humidity, float pressure) &#123; this-&gt;temperature = temp; this-&gt;humidity = humidity; display(); &#125; void display() &#123; // 显示信息 &#125;&#125;;
这样一个简单的观察者模式就是实现完毕了，这是经典的观察者模式实现，但存在一些缺陷：
需要继承，继承是强对象关系，只能对特定的观察者才有效，即必须是Observer抽象类的派生类才行 观察者被通知的接口参数不支持变化，导致观察者不能应付接口的变化，并且这个观察者还不能带参数
3 改进的观察者模式C++11 提供的仿函数和模板等特性可以解决上述问题。C++11 实现的观察者模式，内部维护了一个泛型函数列表，观察者只需要将观察者函数注册进来即可，消除了继承导致的强耦合。通知接口还使用了可变参数模板，支持任意数量的参数，消除了接口变化的影响。 改进之后的观察者模式和 C# 中的 event 类似，通过定义观察者的模板类型来限定观察者，即不要求观察者必须为某个派生类，只要求所有观察者使用相同的函数模板即可，当需要和原来不同的观察者时，只需要定义一个新的 event 类型即可。 需要注意的是 event 对象不能拷贝和复制，这可以通过 delete 关键字来实现。 一个改进的观察者模式实现如下： observer.hpp #ifndef _OBSERVER_HPP_#define _OBSERVER_HPP_ #include &lt;iostream&gt;#include &lt;string&gt;#include &lt;functional&gt;#include &lt;map&gt; using std::cout;using std::endl;using std::string;using std::map; class NonCopyable &#123;public: //禁用复制构造函数 NonCopyable(const NonCopyable&amp; n) = delete; // deleted //禁用赋值构造函数 NonCopyable&amp; operator=(const NonCopyable&amp; n) = delete; // deleted NonCopyable() = default; // available&#125;; template &lt;typename Func&gt;class Events : public NonCopyable &#123;private: int m_observerId = 0; //观察者对应编号 map&lt;int, Func&gt; m_connections; // 观察者列表 // 保存观察者并分配观察者编号 template &lt;typename F&gt; int Assign(F&amp;&amp; f) &#123; int k = m_observerId++; m_connections.emplace(k, std::forward&lt;F&gt;(f)); return k; &#125;public: // 注册观察者，支持右值引用 int Connect(Func&amp;&amp; f) &#123; return Assign(f); &#125; // 注册观察者，左值 int Connect(const Func&amp; f) &#123; return Assign(f); &#125; // 移除观察者 void Disconnect(int key) &#123; m_connections.erase(key); &#125; // 通知所有观察者 template &lt;typename ... Args&gt; void Notify(Args&amp;&amp; ... args) &#123; for(auto &amp;it : m_connections) &#123; auto&amp; func = it.second; func(std::forward&lt;Args&gt;(args)...); &#125; &#125;&#125;; #endif
main.cpp #include &quot;observer.hpp&quot; using ObserverFunc = std::function&lt;int(int, int)&gt;; class Observer &#123;public: int operator() (int a, int b) &#123; cout &lt;&lt; &quot;Observer函数对象的事件2被调用&quot; &lt;&lt; endl; int res = a + b; return res; &#125;&#125;; class Observer2 &#123;public: int observerFunc(int a, int b) &#123; cout &lt;&lt; &quot;Observer2成员函数事件3被调用&quot; &lt;&lt; endl; int res = a + b; return res; &#125;&#125;; int gobserverFunc(int a, int b) &#123; cout &lt;&lt; &quot;全局的gobserverFunc事件4被调用&quot; &lt;&lt; endl; int res = a + b; return res; &#125; int main(void) &#123; Events&lt;ObserverFunc&gt; e; // 调用基于lambda表达式的观察者函数 int lambdaID = e.Connect([](int a, int b)&#123; int res = a+b; cout &lt;&lt; &quot;lambda函数的事件1被调用&quot; &lt;&lt; endl; return res; &#125;); // 调用仿函数的观察者函数 int obsID = e.Connect(Observer()); // 调用成员函数的观察者函数 Observer2 o2; int obsID1 = e.Connect(std::bind(&amp;Observer2::observerFunc, o2, std::placeholders::_1, std::placeholders::_2)); // 调用全局观察者函数 int gID4 = e.Connect(gobserverFunc); e.Notify(1, 2); return 0;&#125;

本篇介绍了单例模式及相关的面向对象设计原则。单例模式保证一个类仅有一个实例，并提供一个该实例的全局访问点。重点在于如何实现线程安全的单例模式。
1 经典单例模式许多时候，我们程序中的某些对象只需要一个或者只能存在一个，比如线程池、缓存、硬件的驱动等，如果存在多个实例就会造成逻辑错误或程序异常。因此作为类的设计者，就需要保证这个类在程序中只能存在一个实例对象。 显然，利用全局静态变量似乎就可以做到，但是全局静态变量并不完美。比如我们需要唯一的一个全局静态对象，那么这个全局对象在程序一开始就会被分配内存，如果后续并没有使用到这个全局对象，就造成了资源的浪费。而使用单例模式，可以随时在需要时才创建这个唯一的对象，并保证不会出现第二个对象。 经典的单例模式实现非常简单，在类中设定一个该类的静态对象成员，将构造函数设置为 private，然后提供一个静态的 getInstance()方法来获取全局唯一的对象： class Singleton &#123;private: static Singleton* uniqueInstance; // 防止外部构造、析构、拷贝和移动 Singleton() = default; ~Singleton() = default; Singleton(const Singleton&amp;) = delete; Singleton(Singleton&amp;&amp;) = delete; Singleton &amp;operator=(const Singleton&amp;) = delete; Singleton &amp;operator=(Singleton&amp;&amp;) = delete;public: // 全局的对象访问接口 static Singleton* getInstance() &#123; if(uniqueInstance == nullptr) &#123; uniqueInstance = new Singleton(); &#125; return uniqueInstance; &#125; // 全局的对象删除接口 static void deleteInstance() &#123; if(uniqueInstance) &#123; delete uniqueInstance; uniqueInstance = nullptr; &#125; &#125;&#125;;// 静态对象初始化static Singleton* Singleton::uniqueInstance = nullptr;
2 线程安全的单例模式上面的经典实现在多线程的情况下会出现问题，有可能创建出两个实例对象，例如：
因此上述实现不是线程安全的。要实现线程安全的单例模式有多种方法。 2.1 DCLP一种经典的方法是 Double-Checked Locking Pattern (DCLP)，在构造对象时使用互斥锁： class Singleton &#123;private: static Singleton* uniqueInstance; static std::mutex m_mutex; //互斥锁 // 防止外部构造、析构和拷贝 Singleton() = default; ~Singleton() = default; Singleton(const Singleton &amp;) = delete; Singleton(Singleton &amp;&amp;) = delete; Singleton &amp;operator=(const Singleton &amp;) = delete; Singleton &amp;operator=(Singleton &amp;&amp;) = delete;public: // 全局的对象访问接口 static Singleton* getInstance() &#123; // DCLP if(uniqueInstance == nullptr) &#123; std::lock_guard&lt;std::mutex&gt; lock(m_mutex); if(uniqueInstance == nullptr) &#123; uniqueInstance = new Singleton(); &#125; &#125; return uniqueInstance; &#125; // 全局的对象删除接口 static void deleteInstance() &#123; if(uniqueInstance) &#123; delete uniqueInstance; uniqueInstance = nullptr; &#125; &#125;&#125;;// 静态对象初始化static Singleton* Singleton::uniqueInstance = nullptr;static std::mutex Singleton::m_mutex;
但 DCLP 也不是绝对安全的，问题出在uniqueInstance = new Singleton()这一句上，我们知道 C++ 中 new 一个对象实际上进行了三次操作：
首先调用 operator new 申请一块内存 然后调用构造函数在该内存上构造对象 最后将该内存地址赋值给指针
但由于编译器优化的原因，C++ 编译器可能会在构造函数不抛出异常的前提下调整语句的执行顺序，也就是上面的三步可能变成：
首先调用 operator new 申请一块内存 然后将该内存地址赋值给指针 最后调用构造函数在该内存上构造对象
在单线程的情况下，这样的顺序变化不会影响程序的结果，但在多线程情况下就不一定了，比如：
这种情况下，线程 A 恰好完成内存申请，并且将内存地址赋给指针，但是还没有调用构造函数，此时线程 B 执行到指针判断，判断指针不为空，于是返回该对象指针，然后调用该对象的函数，但是这时该对象还没有进行构造，就产生了错误。 DCLP 产生该问题的关键在于 new 的操作不是原子的，虽然使用互斥锁对指针的写操作uniqueInstance = new Singleton()加了锁，但没有对之前的读操作if(uniqueInstance == nullptr) 加锁，从而产生了线程不安全问题。 因此一种解决方案是利用原子变量std::atomic将对象指针变为原子类型，并使用std::memory_order_acquire和std::memory_order_release强制对该指针的内存操作顺序不变，从而避免线程不安全： class Singleton &#123;private: static std::atomic&lt;Singleton*&gt; uniqueInstance; static std::mutex m_mutex; //互斥锁 // 防止外部构造、析构和拷贝 Singleton() = default; ~Singleton() = default; Singleton(const Singleton &amp;) = delete; Singleton(Singleton &amp;&amp;) = delete; Singleton &amp;operator=(const Singleton &amp;) = delete; Singleton &amp;operator=(Singleton &amp;&amp;) = delete;public: // 全局的对象访问接口 static Singleton* getInstance() &#123; // 保证内存命令的顺序不会被重排 Singleton* ins = uniqueInstance.load(std::memory_order_acquire); if(ins == nullptr) &#123; std::lock_guard&lt;std::mutex&gt; lock(m_mutex); ins = uniqueInstance.load(std::memory_order_acquire); if(ins == nullptr) &#123; ins = new Singleton(); uniqueInstance.store(ins, std::memory_order_release); &#125; &#125; return uniqueInstance; &#125; // 全局的对象删除接口 static void deleteInstance() &#123; if(uniqueInstance) &#123; delete uniqueInstance; uniqueInstance = nullptr; &#125; &#125;&#125;;// 静态对象初始化static std::atomic&lt;Singleton*&gt; Singleton::uniqueInstance = nullptr;static std::mutex Singleton::m_mutex;
2.2 call_once除了 DCLP 之外，还有一种更简单的实现线程安全的单例模式的方法，利用 C++ 的 std::call_once() 来实现，std::call_once() 可以保证函数只被线程安全的调用一次： class Singleton &#123;private: static Singleton* uniqueInstance; static std::once_flag m_flag; // 函数调用标识 // 防止外部构造、析构和拷贝 Singleton() = default; ~Singleton() = default; Singleton(const Singleton &amp;) = delete; Singleton(Singleton &amp;&amp;) = delete; Singleton &amp;operator=(const Singleton &amp;) = delete; Singleton &amp;operator=(Singleton &amp;&amp;) = delete; // 创建对象 static void createInstance() &#123; uniqueInstance = new Singleton(); &#125;public: // 全局的对象访问接口 static Singleton* getInstance() &#123; std::call_once(m_flag, createInstance); return uniqueInstance; &#125; // 全局的对象删除接口 static void deleteInstance() &#123; if(uniqueInstance) &#123; delete uniqueInstance; uniqueInstance = nullptr; &#125; &#125;&#125;;// 静态对象初始化static Singleton* Singleton::uniqueInstance = nullptr;static std::once_flag Singleton::m_flag;
2.3 Meyers 单例模型最后还有一种最为简单的实现，利用 C++ 的局部静态变量机制，C++ 的局部静态变量在第一次被调用时进行初始化，且保证只初始化一次，因此可以直接在 getInstance() 方法中初始化一个局部静态对象： class Singleton &#123;private: // 防止外部构造、析构和拷贝 Singleton() = default; ~Singleton() = default; Singleton(const Singleton &amp;) = delete; Singleton(Singleton &amp;&amp;) = delete; Singleton &amp;operator=(const Singleton &amp;) = delete; Singleton &amp;operator=(Singleton &amp;&amp;) = delete;public: // 全局的对象访问接口 static Singleton* getInstance() &#123; static Singleton* uniqueInstance; return uniqueInstance; &#125; // 全局的对象删除接口 static void deleteInstance() &#123; if(uniqueInstance) &#123; delete uniqueInstance; uniqueInstance = nullptr; &#125; &#125;&#125;;

本篇介绍了工厂模式及相关的面向对象设计原则。工厂模式分为工厂方法（Factory Method）和抽象工厂（Abstract Factory）两类：
工厂方法定义了一个用于创建对象的接口，让子类决定实例化哪一个类。 工厂方法使得一个类的实例化延迟到子类。 抽象工厂提供了一个接口，让该接口负责创建一系列相关或者相互依赖的对象，而无需在主程序中指定它们具体的类型。
1 引例假设有一个披萨店，整个披萨店的工作流程可以表示为下面的代码： Pizza* orderPizza() &#123; Pizza* pizza = new Pizza(); pizza-&gt;prepare(); pizza-&gt;bake(); pizza-&gt;cut(); pizza-&gt;box(); return pizza;&#125;
当我们需要更多类型的披萨的时候，就需要加上一些判断： Pizza* orderPizza(string&amp; type) &#123; Pizza* pizza; if(type == &quot;cheese&quot;) &#123; pizza = new CheesePizza(); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new GreekPizza(); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new PepperoinPizza(); &#125; pizza-&gt;prepare(); pizza-&gt;bake(); pizza-&gt;cut(); pizza-&gt;box(); return pizza;&#125;
当我们之后想要去掉或加上某些类型的披萨时，就需要不断地删改上面的代码，因为我们违背了前面提到过的一些设计原则：应该把代码中需要变化的部分封装起来。 于是我们将创建披萨对象的代码提取出来，放到一个单独的对象中，这个对象称之为“工厂”，因为它只负责生成披萨对象，而orderPizza()方法就不需要再关注披萨对象的具体类型了，它只知道会从工厂拿到一个披萨，然后对披萨进行处理即可。于是工厂类的定义可能像下面这样： class PizzaFactory &#123;public: Pizza* createPizza(string&amp; type) &#123; Pizza* pizza; if(type == &quot;cheese&quot;) &#123; pizza = new CheesePizza(); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new GreekPizza(); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new PepperoinPizza(); &#125; return pizza; &#125;&#125;;
之后orderPizza()方法就变得非常简洁，并且与具体的披萨类型解耦开来： Pizza* orderPizza(string&amp; type) &#123; PizzaFactory* factory = new PizzaFactory(); Pizza* pizza; pizza = factory-&gt;createPizza(type); pizza-&gt;prepare(); pizza-&gt;bake(); pizza-&gt;cut(); pizza-&gt;box(); return pizza;&#125;
这是一种常见的代码优化思路，但还称不上是设计模式，因为这更像是一种好的编程习惯，这种方法被称为简单工厂。 当我们要在不同地区开连锁店时，虽然我们希望所有店都使用相同的流程，但是不同地区的披萨风味可能有所不同，因此不同店的披萨类型也有所不同，此时如果使用简单工厂，我们需要为不同地区编写各自的工厂类，然后在orderPizza()方法中判断当前所处哪一个地区，再实例化对应的工厂，生产对应的披萨。这样一来又回到了一开始的问题，因此简单工厂并不足够灵活。 2 工厂方法解决上述问题的方法是我们可以设计一个披萨店的抽象类PizzaStore，那么orderPizza()自然是该类中的一个方法，同时该类“抽象”的地方在于拥有一个创建披萨的纯虚函数createPizza(string&amp; type)，所有不同地区的连锁店都是对该抽象类的一个具体实现，都拥有自己的创建披萨方法，也就是说，这个纯虚函数是一个工厂方法，负责生成不同类型的披萨对象，而所有类的orderPizza()方法都无需关注披萨对象的类型。 class PizzaStore &#123;public: Pizza* orderPizza(string&amp; type) &#123; Pizza* pizza; pizza = createPizza(type); pizza-&gt;prepare(); pizza-&gt;bake(); pizza-&gt;cut(); pizza-&gt;box(); return pizza; &#125; virtual Pizza* createPizza(string&amp; type) = 0;&#125;;// 纽约的分店class NewYorkPizzaStore : public PizzaStore &#123;public: virtual Pizza* createPizza(string&amp; type)&#123; Pizza* pizza; if(type == &quot;cheese&quot;) &#123; pizza = new CheesePizza(); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new GreekPizza(); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new PepperoinPizza(); &#125; return pizza; &#125;&#125;;// 芝加哥的分店class ChicagoPizzaStore : public PizzaStore &#123;public: virtual Pizza* createPizza(string&amp; type)&#123; Pizza* pizza; // 创建其它类型的披萨 return pizza; &#125;&#125;;
上述代码的好处在于，使用了工厂方法负责对象的创建，并且把具体的创建行为封装在子类中，只要顾客决定了到哪家分店吃披萨，就决定了将会创建哪些披萨对象，也就是把具体对象的创建延迟到了子类中去决定，而客户代码中统一调用披萨店的orderPizza()方法即可，这样一来无论是新开分店，还是某个分店改变了披萨类型，都不会对客户代码产生任何影响，这就是解耦。另一个潜在的好处是继承关系使得每一家分店还可以自己定义披萨的制作流程，而无需局限在基类orderPizza()方法所定义的流程框架中。 上面的披萨店是披萨的“创建者”，那么自然还需要有被创建的“产品”披萨，披萨类的设计很简单：
于是工厂方法模式的类图一目了然：
工厂方法模式定义了一个创建对象的接口，但由子类来实现该接口，从而决定实例化的类是哪一个。工厂方法让类把实例化推迟到子类。需要注意的是，这里所说的“让子类决定”并不是指子类能够在运行时做决定，而是指在实际编写创建者类时，不需要知道实际创建的产品是哪一个，选择使用了哪个子类，就决定了创建的产品是哪些。另外，工厂方法模式中，基类不必须是抽象的，我们可以定义一些默认的对象创建行为，这样即使没有具体的子类，基类本身也可以创建对象。 回到一开始，如果不使用工厂方法，而是使用一种最直观的方式来实现，可能的代码会是这样： class PizzaStore &#123;public: Pizza* orderPizza(string&amp; area, string&amp; type) &#123; Pizza* pizza; pizza = createPizza(area, type); pizza-&gt;prepare(); pizza-&gt;bake(); pizza-&gt;cut(); pizza-&gt;box(); return pizza; &#125; Pizza* createPizza(string&amp; area, string&amp; type) &#123; Pizza* pizza; if(area == &quot;NewYork&quot;) &#123; if(type == &quot;cheese&quot;) &#123; pizza = new NYCheesePizza(); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new NYGreekPizza(); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new NYPepperoinPizza(); &#125; &#125; if(area == &quot;Chicago&quot;) &#123; if(type == &quot;cheese&quot;) &#123; pizza = new CCheesePizza(); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new CGreekPizza(); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new CPepperoinPizza(); &#125; &#125; return pizza; &#125;&#125;;
这样实现的披萨店的类图如下：
显然披萨店这一个类，依赖于所有的具体披萨类，当任何一个披萨的具体实现改变了，都会影响到披萨店。这是因为这样的设计使得“高层”的组件披萨店依赖了“低层”的组件披萨，违背了依赖倒置原则。
设计原则：依赖倒置原则 不能让高层组依赖低层组件，也就是要让类依赖于抽象，而不是依赖于具体的其他类。
相比之下，上面的工厂方法模式所实现的类图如下：
所有披萨店只依赖于披萨基类这一个类，而披萨基类正是一个抽象类，而所有的具体披萨类也只依赖于披萨基类这一个类，因此满足了依赖倒置原则。 工厂方法模式可以解决单个对象的需求变化，但是要求创建对象的工厂方法必须参数一致。但有些情况下，我们面对的可能是更复杂的情况，当一系列互相依赖或互相作用的多个对象发生变化时，工厂方法就不能很好地解决问题了。 3 抽象工厂继续以披萨店为例，不同地区可能会制作同一类型的披萨，但是不同地区对同样的披萨使用的原料都不同，不过制作披萨所需要的原料都是同一组，比如都需要一种面团、一种酱料和一种芝士，只是不同地区对这些原料组件都有不同的实现方式。具体来说，在任何地方制作披萨都需要使用一个原料家族，不同地方的家族中，都包含同样的成员，但这些成员的具体实现不同，比如纽约使用一种芝士，而芝加哥使用另一种芝士。 于是我们需要创建一些原料工厂来负责生产不同的原料家族，但它们都需要继承自同一个抽象基类： // 原料工厂抽象类class IngredientFactory &#123;public: virtual Dough* createDough() = 0; virtual Sauce* createSauce() = 0; virtual Cheese* createCheese() = 0; ...&#125;;// 纽约的原料工厂class NewYorkIngredientFactory : public IngredientFactory&#123;public: virtual Dough* createDough() &#123; return new NYDough(); &#125; virtual Sauce* createSauce() &#123; return new NYSauce(); &#125; virtual Cheese* createCheese() &#123; return new NYCheese(); &#125;&#125;;// 芝加哥的原料工厂class ChicagoIngredientFactory : public IngredientFactory&#123;public: virtual Dough* createDough() &#123; return new CDough(); &#125; virtual Sauce* createSauce() &#123; return new CSauce(); &#125; virtual Cheese* createCheese() &#123; return new CCheese(); &#125;&#125;;
然后就可以在披萨类中加入这些原料： class Pizza &#123;public: Dough* dough; Sauce* sauce; Cheese* cheese; virtual void prepare() = 0; void bake() &#123;&#125; void cut() &#123;&#125; void box() &#123;&#125;&#125;;
而所有的具体披萨类型都要和原料工厂绑定，从而使用该工厂的原料制作披萨： class CheesePizza : public Pizza &#123;public: IngredientFactory* ingredientFactory; CheesePizza(IngredientFactory* if) : ingredientFactory(if) &#123;&#125; virtual void prepare() &#123; dough = ingredientFactory-&gt;createDough(); sauce = ingredientFactory-&gt;createSauce(); cheese = ingredientFactory-&gt;createCheese(); &#125;&#125;;
然后在披萨店中制作披萨的时候就需要选择一个原料工厂来创建披萨： // 纽约的分店class NewYorkPizzaStore : public PizzaStore &#123;public: virtual Pizza* createPizza(string&amp; type)&#123; Pizza* pizza; // 使用纽约原料工厂的原料 IngredientFactory* ingredientFactory = new NewYorkIngredientFactory(); if(type == &quot;cheese&quot;) &#123; pizza = new CheesePizza(ingredientFactory); &#125; else if(type == &quot;greek&quot;) &#123; pizza = new GreekPizza(ingredientFactory); &#125; else if(type == &quot;pepperoin&quot;)&#123; pizza = new PepperoinPizza(ingredientFactory); &#125; return pizza; &#125;&#125;;// 芝加哥的分店class ChicagoPizzaStore : public PizzaStore &#123;public: virtual Pizza* createPizza(string&amp; type)&#123; Pizza* pizza; // 使用芝加哥原料工厂的原料 IngredientFactory* ingredientFactory = new ChicagoIngredientFactory(); // 创建其它类型的披萨 return pizza; &#125;&#125;;
上面的整个过程我们创建了一个抽象的原料工厂，用来创造原料家族，而原料家族就是由一系列相互关联、相互依赖的对象构成的，这些对象都有可能发生变化，但通过抽象工厂，我们把这种变化约束在了具体的工厂当中，而不会影响代码的其他部分。此外，还可以通过替换不同的工厂使得同一类对象产生不同的行为，比如我们可以将披萨类中的原料工厂替换成其他的原料工厂，从而实现通过组合来创建不同的披萨对象的功能。 抽象工厂模式定义了一个接口，用于创建一系列相关或依赖的对象，而不需要明确指定他们的具体类型。抽象工厂允许客户代码使用一个抽象的接口来创建一系列产品，而不需要关注产生的具体产品是什么，这样一来客户和产品就被解耦开来。抽象工厂的类图如下：
在上面的例子中，各种原料就是一系列相关的产品，原料工厂是负责生成这一系列产品的抽象工厂，而披萨店则是原料工厂的客户。在披萨店的代码中我们不需要关注原料具体是哪些，只负责制作披萨就可以了。 4 总结与对比两种工厂模式的异同总结如下：
工厂方法用于应对“单个对象”的需求变化，而抽象工厂用于应对“一个系列”的需求变化。 工厂方法通过继承来实现，把对象创建委托给子类，子类实现工厂方法来创建对象；而抽象工厂通过对象组合来实现，对象的创建被实现在抽象工厂所声明的方法中。 所有工厂模式都是通过减少客户程序（主程序）和具体类之间的依赖来实现松耦合的。 所用工厂模式都遵循依赖倒置原则，指导我们要避免依赖具体类，而要尽量依赖抽象。

本篇介绍了命令模式及相关的面向对象设计原则。命令模式将请求封装成对象，以便使用不同的请求来参数化其他对象，从而实现请求发出者和请求执行者之间的解耦。

1 引例我们需要设计这样一个系统，有一个遥控器，遥控器有一个插槽和三个按钮，其中两个按钮对应“开”和“关”，一个按钮对应“撤销”操作，插槽中可以插入不同的控制模块来控制不同的电器，比如电灯、热水器、电动窗帘、空调等等，也就是说遥控器的功能取决于插槽内的控制模块。而不同电器的“开”和“关”操作都有各自的实现，他们是毫无关联的单独的类。
直观的方式是判断当前插槽内是什么模块，然后为按钮调用对应的电器的命令，但是当出现更多的电器时，需要不停的修改遥控器的代码。因为此时请求发出者（遥控器）和请求执行者（被操控的电器）是紧耦合的，如果能将它们解耦，那么系统将具有更好的弹性来应对各种变化。
2 命令模式我们可以将遥控器的命令封装成一系列统一的命令对象，让命令对象和具体的命令执行者绑定，负责执行对应的命令，而命令发出者只需要调用命令对象的统一接口就可以实现对不同执行者的控制。
在上例中，遥控器的命令只有三种：开、关和撤销。接下来以电灯为例，按照上述思路来设计一个遥控器。电灯类非常简单，只具有开和关两种操作：
class Light &#123;public:    void on() &#123;        // 开灯    &#125;        void off() &#123;        // 关灯    &#125;&#125;;

接下来是遥控器系统的实现，按照上面的思路，首先设计一个命令对象的接口，所有命令对象只有一个方法，那就是执行操作：
class Command &#123;public:    virtual void execute() = 0;	// 执行命令    virtual void undo() = 0;	// 撤销命令&#125;;

接下来，开和关是两种命令，因此要定义为两类命令对象，命令对象需要包含命令的执行对象：
// 开灯命令class LightOnCommand : public Command &#123;public:    Light* light;    LightOnCommand(Light* lt) : light(lt) &#123;&#125;        virtual void execute() &#123;        light-&gt;on();    &#125;    // 撤销开灯即为关灯    virtual void undo() &#123;        light-&gt;off();    &#125;&#125;;// 关灯命令class LightOffCommand : public Command &#123;public:    Light* light;    LightOffCommand(Light* lt) : light(lt) &#123;&#125;        virtual void execute() &#123;        light-&gt;off();    &#125;    // 撤销关灯即为开灯    virtual void undo() &#123;        light-&gt;on();    &#125;&#125;;

最后是遥控器，遥控器需要包含命令对象：
class RemoteControl &#123;public:    Command* OnCommand;		// 开按钮对应的命令对象    Command* OffCommand;	// 关按钮对应的命令对象    Command* undoCommand;	// 记录上一次按的按钮对应的命令，用于撤销按钮    // 初始为按钮绑定一个默认命令对象，该命令不做任何操作，这样可以避免对象是否为空的判断    RemoteControl() &#123;        OnCommand = new noCommand();        OffCommand = new noCommand();        undoCommand = new noCommand();    &#125;    // 为按钮绑定对应的命令对象    void setCommand(Command* on, Command* off) &#123;        delete OnCommand;        OnCommand = on;        delete OffCommand;        OffCommand = off;    &#125;        void PressOnButton() &#123;        OnCommand-&gt;execute();        undoCommand = OnCommand;    &#125;        void PressOffButton() &#123;        OffCommand-&gt;execute();        undoCommand = OffCommand;    &#125;        void PressUndoButton() &#123;        undoCommand-&gt;undo();    &#125;&#125;;

然后就可以使用这个遥控器了：
int main() &#123;    RemoteControl* rc = new RemoteControl();    Light* lt = new light();    Command* OnCommand = new LightOnCommand(lt);    Command* OffCommand = new LightOffCommand(lt);        rc.setCommand(OnCommand, OffCommand);    rc.PressOnButton();    rc.PressOffButton();    rc.PressUndoButton();    // delete ...    return 0;&#125;

这样一来遥控器不需要知道命令的执行者是谁，只要为按钮绑定好对应的命令对象，然后发出命令，命令对象就会让对应的命令执行者执行对应的动作。同时，遥控器、命令和电器这三者之间是组合的关系，组合意味着可以随意替换，也就是说遥控器可以更换不同的命令对象，而命令对象同样可以更换不同的电器，只要这个电器符合该命令的接口就可以，比如客厅的电灯和卧室的电灯就可以分别绑定到两个不同的 LightXXXCommand 对象上，而无需重新编码。
命令模式将请求封装成对象，以便使用不同的请求来参数化其他对象。命令模式的类图如下所示：

当然，具体命令对象的实现非常灵活，命令要实现什么功能完全取决于 execute() 方法的实现，比如要打开电视，同时将电视的音量设定为 10，那么命令对象可以设计成这样：
class TVOnCommand : public Command &#123;public:    TV* tv;    TVOnCommand(TV* t) : tv(t) &#123;&#125;    virtual void execute() &#123;        tv-&gt;on();        tv-&gt;setVolume(10);    &#125;    virtual void undo() &#123;        tv-&gt;off();    &#125;&#125;;

此外，命令对象还可以实现复合命令，来执行一系列命令：
class MacroCommand : public Command &#123;public:    vector&lt;Command*&gt; commands;    MacroCommand(const vector&lt;Command*&gt;&amp; cs) : commands(cs) &#123;&#125;    virtual void execute() &#123;        for(auto&amp; c : commands) &#123;            c-&gt;execute();        &#125;    &#125;    virtual void undo() &#123;        for(auto&amp; c : commands) &#123;            c-&gt;undo();        &#125;    &#125;&#125;;

命令模式应用非常广泛，比如可以实现命令队列，让多个线程从队列中获取命令对象并执行，这样一来线程无需知道命令执行的具体对象是谁，只要调用命令对象的执行方法即可；再比如软件中的执行日志，可以将软件运行时执行过的命令对象序列化到磁盘上，在软件异常中断恢复数据时，只需要按顺序再从磁盘读取该对象并执行命令就可以恢复到中断前的状态了。

本篇介绍了状态模式及相关的面向对象设计原则。状态模式允许对象在内部状态改变时改变它的行为，从而使对象看起来像是修改了它的行为。
1 引例一些情况下某些对象的状态如果改变，那么它的行为也会随着发生变化。比如一个网络管理器，存在三种状态：网络开启、关闭和连接。通过某些操作能在这些状态间进行转换，但是在不同状态下时，同样的操作导致的结果可能不同（行为发生变化），下面是一个简单的实现，利用枚举存储了三种状态，然后通过最直接的 if-else 来判断当前状态并实现不同的操作： enum NetworkState &#123; Network_Open, Network_Close, Network_Connect,&#125;;class NetworkProcessor &#123;private: NetworkState state;public: void Operation1()&#123; if (state == Network_Open) &#123; // 其他操作 state = Network_Close; &#125; else if (state == Network_Close) &#123; // 其他操作 state = Network_Connect; &#125; else if (state == Network_Connect) &#123; // 其他操作 state = Network_Open; &#125; &#125; void Operation2() &#123; if (state == Network_Open) &#123; // 其他操作 state = Network_Connect; &#125; else if (state == Network_Close) &#123; // 其他操作 state = Network_Open; &#125; else if (state == Network_Connect) &#123; // 其他操作 state = Network_Close; &#125; &#125; public void Operation3()&#123; // ... &#125;&#125;;
按照这种实现方式，当我们要加入新的状态或者新的操作的时候，就大量需要修改类中的代码，当状态复杂的时候很容易就出现各种错误，带来维护问题。 2 状态模式状态模式将所有的状态打包成一个状态族，每一个具体的状态只负责当前状态下的操作，而原本对象的所有操作都委托给当前的状态对象去进行。对于客户来说，就好像原本的对象在不同状态下改变了它本身的行为，但实际上是通过和状态对象的组合来实现的。 状态模式的类图如下： 形式上与策略模式一模一样，但策略模式是将操作打包成为一族算法，与对象进行组合从而使对象能够切换行为。而状态模式将状态独立出来，使对象可以随着客户的操作自动切换状态并改变行为，而对象本身对此无需知情，只要将对应的操作委托给当前的状态对象去执行即可。 接下来我们将上面的例子使用状态模式进行实现。首先需要实现一个状态接口，其中包含了系统中的所有操作，每个状态都要实现这些操作： class NetworkState &#123;public: NetworkState* pNext; // 记录转换后的状态 virtual void Operation1()=0; virtual void Operation2()=0; virtual void Operation3()=0; virtual ~NetworkState()&#123;&#125;&#125;;
然后每一个具体的状态都实现自己的操作，这里以网络开状态为例，其他两个状态同理： class OpenState :public NetworkState&#123;private: static NetworkState* m_instance;public: // 状态对象只能有一个，使用简单单例模式 static NetworkState* getInstance()&#123; if (m_instance == nullptr) &#123; m_instance = new OpenState(); &#125; return m_instance; &#125; // 实现操作并进行状态转换 void Operation1() &#123; // 其他操作 pNext = CloseState::getInstance(); &#125; void Operation2() &#123; // 其他操作 pNext = ConnectState::getInstance(); &#125; void Operation3() &#123; // 其他操作 pNext = OpenState::getInstance(); &#125; &#125;;
然后网络管理器的代码也需要修改： class NetworkProcessor&#123;private: NetworkState* pState; // 管理器的当前状态 public: // 构造的时候要初始化一个状态 NetworkProcessor(NetworkState* pState) &#123; this-&gt;pState = pState; &#125; void Operation1()&#123; // 委托给当前状态执行 pState-&gt;Operation1(); // 切换状态 pState = pState-&gt;pNext; &#125; void Operation2()&#123; // 委托给当前状态执行 pState-&gt;Operation2(); // 切换状态 pState = pState-&gt;pNext; &#125; void Operation3()&#123; // 委托给当前状态执行 pState-&gt;Operation3(); // 切换状态 pState = pState-&gt;pNext; &#125;&#125;;
这样一来，当新增状态或者操作有变化时，网络管理器对象的代码完全不需要更改，只需修改对应的状态对象的部分就可以了，实现了对象和其状态之间的解耦，或者说实现了具体操作和状态转换之间的解耦。状态模式的另一个潜在好处是，为不同状态引入不同的对象使得状态转换更加明确，可以保证不会出现状态不一致的情况，因为状态的转换是原子的，即要么彻底转换为另一状态，要么不转换。

本篇介绍了迭代器模式和组合模式及相关的面向对象设计原则。这两种模式都是面向数据结构的设计模式。

迭代器模式（Iterator）提供一种方法顺序访问一个聚合对象中的各个元素，而又不暴露其内部的表示。
组合模式（Composite）将对象组合成树形结构来表示“整体-部分”的层次关系，从而让客户对单个对象和组合对象的使用具有一致性。


1 迭代器模式我们对迭代器的概念非常熟悉，许多情况下面对不同的对象集合，我们希望能有统一的方式遍历他们，但不对外暴露其内部的实现方式。比如 C++ 的 vector、list、map 等容器都支持迭代器，利用迭代器我们可以使用统一的方法，比如 first()、end()、next() 等，对不同集合的对象进行统一的操作。
迭代器模式的类图如下：

首先实现迭代器接口：
template&lt;typename T&gt;class Iterator&#123;public:    virtual void first() = 0;    virtual void next() = 0;    virtual bool end() const = 0;    virtual T&amp; current() = 0;&#125;;

然后实现一个和自己的元素容器，该容器需要有一个迭代器对象，并能够返回该迭代器：
template&lt;typename T&gt;class MyCollection&#123;public:     Iterator&lt;T&gt; GetIterator()&#123;        // 提供当前容器的迭代器    &#125; &#125;;

然后实现我们容器的具体迭代器：
template&lt;typename T&gt;class CollectionIterator : public Iterator&lt;T&gt;&#123;    MyCollection&lt;T&gt; mc;public:    CollectionIterator(const MyCollection&lt;T&gt; &amp; c): mc(c) &#123;&#125;       void first() override &#123;        // 指向第一个元素    &#125;    void next() override &#123;        // 指向下一个元素    &#125;    bool end() const override&#123;        // 是否指向最后一个元素    &#125;    T&amp; current() override&#123;        // 返回当前指向的元素    &#125;&#125;;

最后调用时：
void MyAlgorithm()&#123;    MyCollection&lt;int&gt; mc;    Iterator&lt;int&gt; iter = mc.GetIterator();    for (iter.first(); !iter.end(); iter.next())&#123;        cout &lt;&lt; iter.current() &lt;&lt; endl;    &#125;&#125;

迭代器模式把元素之间游走的责任交给迭代器去处理，这样一来元素容器本身就不需要关注如何处理对象的遍历，而是专注于对象的管理操作上。迭代器模式不仅让客户遍历不同的容器更加方便，也会让元素容器的接口更加简洁。
那么为什么不让元素容器本身去实现各自的遍历操作呢，因为一个类的每个责任都有发生变化的可能，容器管理对象是一个责任，负责对象的遍历和访问又是一个责任，责任越多，意味着未来发生变化的可能性越大，要修改的代码也就越多。因此迭代器模式引出了一个重要的设计原则：

设计原则：单一责任原则
一个类应该只有一个引起变化的原因，尽量让每个类保持单一责任。

2 组合模式在一些情况下，对象内部的结构可能较为复杂，不再是单一的容器了。比如一个容器内部的每一个元素又是一个可以容纳多个对象的容器，此时使用迭代器模式就没有办法直接遍历这样的复杂结构了，因此需要使用组合模式。
组合模式将对象组合成树形结构来表示“整体-部分”的层次关系，从而让客户对单个对象和组合对象的使用具有一致性。上面的例子中，一级容器的每个元素相当于树的一个中间节点，节点包含二级容器中的各个元素，因此我们可以将这个树状结构构建出来，并让每一级容器中的元素都继承自同一个父类，这个父类被称为基本的组件（Component），这样在客户代码中就无需关注对象是叶子节点（单一对象）还是中间节点（组合对象）了，因为他们都有相同的接口。
组合模式的类图如下：

首先是实现 Component 接口：
class Component &#123;public:    virtual void process() = 0;    virtual ~Component() &#123;&#125;&#125;;

然后实现叶子节点，叶子节点不包含其他子节点，只实现对应的操作：
// 叶子节点class Leaf : public Component &#123;    string name;public:    Leaf(string s) : name(s) &#123;&#125;                void process() &#123;        // process current node    &#125;&#125;;

然后是中间节点，也就是组合对象，中间节点包含其他叶子节点，执行操作时就是先处理自身，然后遍历所有叶子节点，按顺序调用叶子节点的操作：
// 中间节点class Composite : public Component &#123;    string name;    list&lt;Component*&gt; elements;		// 包含的子节点集合，子节点可以是其他组合对象，也可以是叶子节点public:    Composite(const string &amp; s) : name(s) &#123;&#125;    // 组合对象还支持增加或删除节点的操作    void add(Component* element) &#123;        elements.push_back(element);    &#125;    void remove(Component* element) &#123;        elements.remove(element);    &#125;    // 组合节点的操作就是处理自身，并依次调用叶子节点    void process() &#123;        //1. process current node                //2. process leaf nodes        for (auto &amp;e : elements)            e-&gt;process();  // 递归多态调用    &#125;&#125;;

然后为该对象的处理写一个统一的接口供客户代码使用：
void Invoke(Component &amp; c)&#123;    //...    c.process();    //...&#125;

然后写一个测试程序：
int main()&#123;    // 构建对象关系    Composite root(&quot;root&quot;);    Composite treeNode1(&quot;treeNode1&quot;);    Composite treeNode2(&quot;treeNode2&quot;);    Composite treeNode3(&quot;treeNode3&quot;);    Composite treeNode4(&quot;treeNode4&quot;);    Leaf leat1(&quot;left1&quot;);    Leaf leat2(&quot;left2&quot;);        root.add(&amp;treeNode1);    treeNode1.add(&amp;treeNode2);    treeNode2.add(&amp;leaf1);        root.add(&amp;treeNode3);    treeNode3.add(&amp;treeNode4);    treeNode4.add(&amp;leaf2);        // 对组合对象和单一对象的调用是统一的    Invoke(root);    Invoke(leaf2);    Invoke(treeNode3);  &#125;

同样，我们也可以结合组合模式和迭代器，实现组合迭代器，只要为每个组件加上一个迭代器对象，然后递归的遍历即可。之前在实现光线追踪时的 BVH 结构就是组合模式的典型例子，可以回顾一下【RayTracer】（十）实现 BVH。
组合模式采用树形结构来表达层次关系，将“一对多”的关系转变为“一对一”的关系，使客户代码可以一致的处理对象本身和对象容器，而无需关心处理的是单个对象还是组合对象。组合模式将客户代码和复杂的对象容器结构解耦，客户代码只与纯粹的抽象接口发生依赖，而不是具体的对象容器，从而更能应对变化。

本篇介绍了其他常用设计模式并对所有设计模式及相关设计原则进行了总结。

1 其他常用设计模式1.1 桥模式（Bridge）桥模式与装饰者模式类似，都是执行“单一职责”原则的模式。在某些情况下，有些类的实现可能包含多个维度的变化，例如一个信息发送器类：
class Messager&#123;public:    // 第一部分，由具体业务实现    virtual void Login(string username, string password)=0;    virtual void SendMessage(string message)=0;    virtual void SendPicture(Image image)=0;    // 第二部分，由平台实现    virtual void PlaySound()=0;    virtual void DrawShape()=0;    virtual void WriteText()=0;    virtual void Connect()=0;        virtual ~Messager()&#123;&#125;&#125;;

该类中第一部分方法需要调用第二部分方法，但每一部分方法都有不同的实现，比如PC平台下：
// PC平台实现具体方法class PCMessagerBase : public Messager&#123;public:     virtual void PlaySound()&#123;        //**********    &#125;    virtual void DrawShape()&#123;        //**********    &#125;    virtual void WriteText()&#123;        //**********    &#125;    virtual void Connect()&#123;        //**********    &#125;&#125;;// 基于PC平台实现不同业务逻辑class PCMessagerLite : public PCMessagerBase &#123;public:        virtual void Login(string username, string password)&#123;        PCMessagerBase::Connect();        //........    &#125;    virtual void SendMessage(string message)&#123;        PCMessagerBase::WriteText();        //........    &#125;    virtual void SendPicture(Image image)&#123;                PCMessagerBase::DrawShape();        //........    &#125;&#125;;class PCMessagerPerfect : public PCMessagerBase &#123;public:        virtual void Login(string username, string password)&#123;                PCMessagerBase::PlaySound();        //********        PCMessagerBase::Connect();        //........    &#125;    virtual void SendMessage(string message)&#123;                PCMessagerBase::PlaySound();        //********        PCMessagerBase::WriteText();        //........    &#125;    virtual void SendPicture(Image image)&#123;                PCMessagerBase::PlaySound();        //********        PCMessagerBase::DrawShape();        //........    &#125;&#125;;

而当我们想要加入一个移动平台时，移动平台的业务逻辑也需要全部重写，从而产生大量重复代码，并且在修改业务逻辑时，也要对每个平台的代码进行修改。
使用桥模式，将抽象部分（业务）和实现部分（平台）分离，使他们可以独立的变化。因此将业务和平台分离成两个基类：
// 业务部分class Messager&#123;protected:     MessagerImp* messagerImp;//...public:    virtual void Login(string username, string password)=0;    virtual void SendMessage(string message)=0;    virtual void SendPicture(Image image)=0;        virtual ~Messager()&#123;&#125;&#125;;// 平台部分class MessagerImp&#123;public:    virtual void PlaySound()=0;    virtual void DrawShape()=0;    virtual void WriteText()=0;    virtual void Connect()=0;        virtual MessagerImp()&#123;&#125;&#125;;

然后平台的实现：
// PC平台class PCMessagerImp : public MessagerImp&#123;public:        virtual void PlaySound()&#123;        //**********    &#125;    virtual void DrawShape()&#123;        //**********    &#125;    virtual void WriteText()&#123;        //**********    &#125;    virtual void Connect()&#123;        //**********    &#125;&#125;;// 移动平台class MobileMessagerImp : public MessagerImp&#123;public:        virtual void PlaySound()&#123;        //==========    &#125;    virtual void DrawShape()&#123;        //==========    &#125;    virtual void WriteText()&#123;        //==========    &#125;    virtual void Connect()&#123;        //==========    &#125;&#125;;

之后业务部分包含一个平台对象，就无需关注具体的平台是谁了：
class MessagerLite :public Messager &#123;   public:        virtual void Login(string username, string password)&#123;                messagerImp-&gt;Connect();        //........    &#125;    virtual void SendMessage(string message)&#123;                messagerImp-&gt;WriteText();        //........    &#125;    virtual void SendPicture(Image image)&#123;                messagerImp-&gt;DrawShape();        //........    &#125;&#125;;class MessagerPerfect  :public Messager &#123;   public:        virtual void Login(string username, string password)&#123;                messagerImp-&gt;PlaySound();        //********        messagerImp-&gt;Connect();        //........    &#125;    virtual void SendMessage(string message)&#123;                messagerImp-&gt;PlaySound();        //********        messagerImp-&gt;WriteText();        //........    &#125;    virtual void SendPicture(Image image)&#123;                messagerImp-&gt;PlaySound();        //********        messagerImp-&gt;DrawShape();        //........    &#125;&#125;;

这样就实现了抽象和实现的解耦，每个类只具有单一的职责。
桥模式使用“对象间的组合关系”解耦了抽象和实现之间固有的绑定关系，使得抽象和实现可以沿着各自的维度来变化。所谓抽象和实现沿着各自维度的变化，即“子类化”它们。桥模式有时候类似于多继承方案，但是多继承方案往往违背单一职责原则，因此复用性比较差。桥模式是比多继承方案更好的解决方法。
1.2 生成器模式（Builder）生成器模式与工厂模式同属于对象创建模式，都是用来管理对象创建的模式。在软件系统中，有时候面临着“一个复杂对象”的创建工作，其通常由各个部分的子对象用一定的算法构成，但由于需求的变化，这个复杂对象的各个部分经常面临着剧烈的变化，但是将它们组合在 一起的算法却相对稳定。生成器模式将一个复杂对象的构建与其表示相分离，使得同样的构建过程可以创建不同的表示。
以搭建房子为例，生成器模式会很好理解，代码如下：
class House&#123;    //....&#125;;class HouseBuilder &#123;public:    House* GetResult()&#123;        return pHouse;    &#125;    virtual ~HouseBuilder()&#123;&#125;protected:       House* pHouse;	virtual void BuildPart1()=0;    virtual void BuildPart2()=0;    virtual void BuildPart3()=0;    virtual void BuildPart4()=0;    virtual void BuildPart5()=0;	&#125;;class StoneHouse: public House&#123;    &#125;;class StoneHouseBuilder: public HouseBuilder&#123;protected:      virtual void BuildPart1()&#123;        //pHouse-&gt;Part1 = ...;    &#125;    virtual void BuildPart2()&#123;            &#125;    virtual void BuildPart3()&#123;            &#125;    virtual void BuildPart4()&#123;            &#125;    virtual void BuildPart5()&#123;            &#125;    &#125;;class HouseDirector&#123;   public:    HouseBuilder* pHouseBuilder;        HouseDirector(HouseBuilder* pHouseBuilder)&#123;        this-&gt;pHouseBuilder=pHouseBuilder;    &#125;        House* Construct()&#123;                pHouseBuilder-&gt;BuildPart1();                for (int i = 0; i &lt; 4; i++)&#123;            pHouseBuilder-&gt;BuildPart2();        &#125;                bool flag=pHouseBuilder-&gt;BuildPart3();                if(flag)&#123;            pHouseBuilder-&gt;BuildPart4();        &#125;                pHouseBuilder-&gt;BuildPart5();                return pHouseBuilder-&gt;GetResult();    &#125;&#125;;

从上面的代码可见，Builder 模式主要用于“分步骤构建一个复杂的对象”。在这其中“分步骤”是一个稳定的算法，而复杂对象的各个部分则经常变化。
1.3 职责链模式（Chain of Resposibility）职责链模式与组合模式、迭代器模式类似，都属于面向数据结构的设计模式。在软件设计中，一个请求可能被多个对象处理，但是每个请求在运行时只能有一个接收者，如果显式指定，将带来发送者和接收者之间的紧耦合。职责链模式将对象连成一条链，并沿着这条链传递请求，直到有一个对象处理它为止。
代码实现也非常直观：
#include &lt;iostream&gt;#include &lt;string&gt;using namespace std;// 请求类型，不同的接收者只能处理一个类型的请求enum class RequestType&#123;    REQ_HANDLER1,    REQ_HANDLER2,    REQ_HANDLER3&#125;;// 请求发出者class Reqest&#123;    string description;    RequestType reqType;public:    Reqest(const string &amp; desc, RequestType type) : description(desc), reqType(type) &#123;&#125;    RequestType getReqType() const &#123; return reqType; &#125;    const string&amp; getDescription() const &#123; return description; &#125;&#125;;// 责任链对象基类class ChainHandler&#123;       ChainHandler *nextChain;    void sendReqestToNextHandler(const Reqest &amp; req)    &#123;        if (nextChain != nullptr)            nextChain-&gt;handle(req);    &#125;protected:    virtual bool canHandleRequest(const Reqest &amp; req) = 0;    virtual void processRequest(const Reqest &amp; req) = 0;public:    ChainHandler() &#123; nextChain = nullptr; &#125;    void setNextChain(ChainHandler *next) &#123; nextChain = next; &#125;    // 能处理请求则处理，否则将请求发送给链上的下一个对象      void handle(const Reqest &amp; req)    &#123;        if (canHandleRequest(req))            processRequest(req);        else            sendReqestToNextHandler(req);    &#125;&#125;;// 请求接收对象1class Handler1 : public ChainHandler&#123;protected:    bool canHandleRequest(const Reqest &amp; req) override    &#123;        return req.getReqType() == RequestType::REQ_HANDLER1;    &#125;    void processRequest(const Reqest &amp; req) override    &#123;        cout &lt;&lt; &quot;Handler1 is handle reqest: &quot; &lt;&lt; req.getDescription() &lt;&lt; endl;    &#125;&#125;;// 请求接收对象2 class Handler2 : public ChainHandler&#123;protected:    bool canHandleRequest(const Reqest &amp; req) override    &#123;        return req.getReqType() == RequestType::REQ_HANDLER2;    &#125;    void processRequest(const Reqest &amp; req) override    &#123;        cout &lt;&lt; &quot;Handler2 is handle reqest: &quot; &lt;&lt; req.getDescription() &lt;&lt; endl;    &#125;&#125;;// 请求接收对象3class Handler3 : public ChainHandler&#123;protected:    bool canHandleRequest(const Reqest &amp; req) override    &#123;        return req.getReqType() == RequestType::REQ_HANDLER3;    &#125;    void processRequest(const Reqest &amp; req) override    &#123;        cout &lt;&lt; &quot;Handler3 is handle reqest: &quot; &lt;&lt; req.getDescription() &lt;&lt; endl;    &#125;&#125;;int main()&#123;    Handler1 h1;    Handler2 h2;    Handler3 h3;    h1.setNextChain(&amp;h2);    h2.setNextChain(&amp;h3);        Reqest req(&quot;process task ... &quot;, RequestType::REQ_HANDLER3);    h1.handle(req);    return 0;&#125;

职责链模式使多个对象都有处理请求的机会，从而避免了请求发送者和接受者的紧耦合。应用职责链模式可以使对象的指责分派更加灵活，可以在运行时动态的添加或者修改请求处理的职责。
1.4 享元模式（Flyweight）在软件运行中，大量相同的对象会带来很大的运行开销，降低软件运行效率。享元模式通过共享技术减少运行时实例对象的个数从而提升性能。所谓共享技术就是使用一个对象工厂来管理许多虚拟对象，这些虚拟对象只要状态一样就只会存在一个，从而达到了减少对象数量的目的：
class Font &#123;private:    //unique object key    string key;        //object state    //....    public:    Font(const string&amp; key)&#123;        //...    &#125;&#125;;class FontFactory&#123;private:    map&lt;string,Font* &gt; fontPool;    public:    Font* GetFont(const string&amp; key)&#123;        map&lt;string,Font*&gt;::iterator item=fontPool.find(key);                if(item!=footPool.end())&#123;            return fontPool[key];        &#125;        else&#123;            Font* font = new Font(key);            fontPool[key]= font;            return font;        &#125;    &#125;        void clear()&#123;        //...    &#125;&#125;;

1.5 备忘录模式（Memento）备忘录模式与状态模式类似，属于应对状态变化的模式。在软件设计中，某些对象在状态转换过程中，由于某种需要可能要求程序能够回溯到对象之前的某个状态，如果使用一些公有接口来实现，则会暴露对象的实现细节。备忘录模式在不破坏封装的前提下，捕获一个对象的内部状态，并在对象外保存这个状态，这样就可以在之后需要的时候将对象恢复到原先保存的状态。
class Memento&#123;    string state;    //..public:    Memento(const string &amp; s) : state(s) &#123;&#125;    string getState() const &#123; return state; &#125;    void setState(const string &amp; s) &#123; state = s; &#125;&#125;;class Originator&#123;    string state;    //....public:    Originator() &#123;&#125;    Memento createMomento() &#123;        Memento m(state);        return m;    &#125;    void setMomento(const Memento &amp; m) &#123;        state = m.getState();    &#125;&#125;;int main()&#123;    Originator orginator;        //捕获对象状态，存储到备忘录    Memento mem = orginator.createMomento();        //... 改变orginator状态        //从备忘录中恢复    orginator.setMomento(memento);    &#125;

1.6 访问者模式（Visitor）在软件构建过程中，由于需求变化，某些类层次结构中常常需要增加新的行为（方法），如果直接在基类中更改，将会给子类带来繁重的变更负担，甚至破坏原有设计。访问者模式定义一个访问者对象来表示一个作用于某对象结构中各元素的操作，使得可以在不改变各元素类的前提下定义作用于这些元素的新操作。
#include &lt;iostream&gt;using namespace std;class Visitor;class Element&#123;public:    virtual void accept(Visitor&amp; visitor) = 0;    virtual ~Element()&#123;&#125;&#125;;class ElementA : public Element&#123;public:    void accept(Visitor &amp;visitor) override &#123;        visitor.visitElementA(*this);    &#125;&#125;;class ElementB : public Element&#123;public:    void accept(Visitor &amp;visitor) override &#123;        visitor.visitElementB(*this);    &#125;&#125;;class Visitor&#123;public:    virtual void visitElementA(ElementA&amp; element) = 0;    virtual void visitElementB(ElementB&amp; element) = 0;        virtual ~Visitor()&#123;&#125;&#125;;//==================================//扩展1class Visitor1 : public Visitor&#123;public:    void visitElementA(ElementA&amp; element) override&#123;        cout &lt;&lt; &quot;Visitor1 is processing ElementA&quot; &lt;&lt; endl;    &#125;            void visitElementB(ElementB&amp; element) override&#123;        cout &lt;&lt; &quot;Visitor1 is processing ElementB&quot; &lt;&lt; endl;    &#125;&#125;;     //扩展2class Visitor2 : public Visitor&#123;public:    void visitElementA(ElementA&amp; element) override&#123;        cout &lt;&lt; &quot;Visitor2 is processing ElementA&quot; &lt;&lt; endl;    &#125;        void visitElementB(ElementB&amp; element) override&#123;        cout &lt;&lt; &quot;Visitor2 is processing ElementB&quot; &lt;&lt; endl;    &#125;&#125;;             int main()&#123;    Visitor2 visitor;    ElementB elementB;    elementB.accept(visitor);        ElementA elementA;    elementA.accept(visitor);       return 0;&#125;

1.7 解释器模式（Interpreter）在软件构建过程中，如果某一特定领域的问题比较复杂，类似的结构不断重复出现，使用普通编程方式将面临非常频繁的变化，此时将特定领域的问题表达为某种语法规则下的句子，然后构建一个解释器来解释这样的句子，就可以解决问题。
1.8 中介者模式（Mediator）中介者模式与适配器、外观、代理模式类似，是用于接口隔离的模式。在软件设计中，经常会出现多个对象互相关联交互的情况，对象之间经常会维持一种复杂的引用关系，如果遇到一些需求的更改，这样复杂的关系将面临不断地变化。中介者模式使用一个中介对象管理这种复杂关系，使这些对象之间不需要显式的引用彼此，避免相互交互的对象之间的紧耦合。
1.9 原型模式（Prototype）当创建给定类的实例的过程很复杂或者代价很大时，就可以使用原型模式。原型模式允许通过复制现有的实例来创建性的实例。
2 设计模式总结到此为止已经学习了全部常用的设计模式，但是模式并不代表是一成不变的，以上只是前人的经验总结出来的解决通用问题的通用技法，在具体任务中，最重要的还是利用面向对象的设计原则和思路，来使用适合当前任务的”模式“，这里的模式不一定是已经存在的模式，而是我们利用设计原则让复杂问题简单化的方法，是我们自己的”模式“，最好的模式就是忘掉模式，只记住原则。因此这里总结前面设计到的所有面向对象设计原则：

依赖倒置原则（DIP）：高层模块(稳定)不应该依赖于低层模块(变化)，二者都应该依赖于抽象(稳定) 。抽象(稳定)不应该依赖于实现细节(变化) ，实现细节应该依赖于抽象(稳定)。
开放封闭原则（OCP）：对扩展开放，对更改封闭。类模块应该是可扩展的，但是不可修改。
单一职责原则（SRP）：一个类应该仅有一个引起它变化的原因。变化的方向隐含着类的责任。
Liskov 替换原则（LSP）：子类必须能够替换它们的基类(IS-A)。
接口隔离原则（ISP）：不应该强迫客户程序依赖它们不用的方法。接口应该小而完备。
优先使用对象组合，而不是继承：继承在某种程度上破坏了封装性，子类父类耦合度高。而对象组合则只要求被组合的对象具有良好定义的接口，耦合度低。
封装变化：使用封装来创建对象之间的分界层，让设计者可以在分界层的一侧进行修改，而不会对另一侧产生不良的影响，从而实现层次间的松耦合。
针对接口编程，而不是针对实现编程：客户程序无需获知对象的具体类型，只需要知道对象所具有的接口。减少系统中各部分的依赖关系，从而实现“高内聚、松耦合”的类型设计方案。

最后，所有设计原则都有一个共同的目标，就是管理变化，提高复用。

本篇全面总结了 C++ 与 Lua 脚本交互的相关内容。内容目录：
