然后写一个测试程序测试是否配置成功： #include &lt;iostream&gt; #include &lt;string.h&gt; using namespace std; extern &quot;C&quot; &#123; #include &quot;lua.h&quot; #include &quot;lauxlib.h&quot; #include &quot;lualib.h&quot; &#125;// 也可直接 #include lua.hppvoid main() &#123; // 1.创建一个 Lua state lua_State *L = luaL_newstate(); // 2.入栈操作 lua_pushstring(L, &quot;I am so cool~&quot;); lua_pushnumber(L, 20); // 3.取值操作 if(lua_isstring(L, 1)) &#123; //判断是否可以转为string cout &lt;&lt; lua_tostring(L,1) &lt;&lt; endl; //转为string并返回 &#125; if(lua_isnumber(L, 2)) &#123; cout &lt;&lt; lua_tonumber(L, 2) &lt;&lt; endl; &#125; // 4.关闭 Lua state lua_close(L); return; &#125;
输出：
就表明配置完成了。 2 Lua 与 C++ 交互原理Lua 与 C&#x2F;C++ 交互是通过一个虚拟栈来实现的，这个虚拟栈实际上就是一个 struct，具体实现可以从 Lua 源码中 lstate.c 文件中的 static void stack_init (lua_State *L1, lua_State *L) 函数看起。 与常规栈不同的是 Lua 虚拟栈不仅有正向索引（正数），还有反向索引（负数），其中正数索引 1 表示栈底，负数索引 -1 表示栈顶：
于是 Lua 和 C++ 程序交互时，如果要传递值，基本原理就是：
当 C++ 要调用 Lua 数据时，Lua 把值压入栈中，C++ 再从栈中取值
当 Lua 调用 C++ 数据时，C++ 要将数据压入栈中，让 Lua 从栈中取值
而如果要发生函数交互，过程会稍微复杂一点：
当 C++ 要调用 Lua 函数时，Lua 先将 Lua 函数压入栈中，C++ 再将数据（作为参数）继续压入栈中，然后用 API 调用栈上的 Lua 函数 + 参数，调用完后，Lua 函数和参数都会出栈，而函数计算后的值会压入栈中：
当 Lua 要调用 C++ 函数时，需要通过 API 注册符合 Lua 规范的 C++ 函数，来让 Lua 知道该 C++ 函数的定义。
存入栈中的数据可以是 Lua 中的任何数据类型，包括数值, 字符串, 指针, talbe, 闭包等等，因为 Lua 的虚拟栈在源码中是这样定义的： // lobject.htypedef union StackValue &#123; TValue val; struct &#123; TValuefields; unsigned short delta; &#125; tbclist;&#125; StackValue;
其中的数据都是用一个名为 TValue 的结构体来存储的，这个结构体中就包含了 Lua 中的所有数据类型： /*** Union of all Lua values*/typedef union Value &#123; struct GCObject *gc; /* collectable objects */ void *p; /* light userdata */ lua_CFunction f; /* light C functions */ lua_Integer i; /* integer numbers */ lua_Number n; /* float numbers */&#125; Value;/*** Tagged Values. This is the basic representation of values in Lua:** an actual value plus a tag with its type.*/#define TValuefields Value value_; lu_byte tt_typedef struct TValue &#123;TValuefields;&#125; TValue;
更多的实现可以查看源码中的 lobject.h 文件。 Lua 和 C++ 通信时有一个符合设计原则的约定：所有的 Lua 中的值由 Lua 来管理，C&#x2F;C++ 中产生的值 Lua 不知道, 类似表达了这样一种意思：”如果你（C&#x2F;C++）想要什么，你告诉我（Lua），我来产生，然后放到栈上，你只能通过 api 来操作这个值，而我负责管好我的世界“。这样的解耦很有必要，因为这可以保证只要是 Lua 中的变量，Lua 就要负责这些变量的生命周期和垃圾回收，而 C&#x2F;C++ 程序就无需多虑。所以，必须由 Lua 来创建这些值。 3 C++ 调用 Lua 脚本根据以上原理，C++ 调用 Lua 脚本时一般步骤是：
使用 luaL_newstate() 创建 Lua 状态机，返回指向虚拟栈的指针 使用 luaL_loadfile() 加载 Lua 脚本文件 使用 lua_pcall() 运行 Lua 脚本文件 需要获取 Lua 中的值时： 使用 lua_getglobal 获取值 使用 lua_toXXX 将值转化为对应的 C++ 数据类型 如果获取的值为 table 的话，可以使用 lua_getfield 和 lua_setfield 来获取和修改 table 中的元素
需要获取 Lua 中的函数时： 使用 lua_getglobal 获取函数 如果函数有参数的话，使用 lua_pushXXX 将参数依次入栈 使用 lua_pcall() 调用函数，然后从栈顶取出函数返回值即可
接下来我们创建一个简单的 Lua 脚本： str = &quot;Test Lua script.&quot;tbl = &#123;name = &quot;LYC&quot;, id = 2020262914&#125;function add(a,b) return a + bend
然后使用 C++ 程序来调用脚本： #include &lt;iostream&gt;#include &lt;string.h&gt;#include &quot;lua.hpp&quot;using namespace std;int main()&#123; // 创建 Lua 状态，返回一个指向堆栈的指针 lua_State* L = luaL_newstate(); if (L == NULL) &#123; return -1; &#125; // 加载 Lua 文件 int bRet = luaL_loadfile(L, &quot;test.lua&quot;); if (bRet) &#123; cout &lt;&lt; &quot;load file error&quot; &lt;&lt; endl; return -1; &#125; // 运行 Lua 文件 bRet = lua_pcall(L, 0, 0, 0); if (bRet) &#123; cout &lt;&lt; &quot;pcall error&quot; &lt;&lt; endl; return -1; &#125; /* * 读取 Lua 全局变量，内部实现过程为： * 1.把 str 压栈 * 2.由 Lua 去寻找全局变量 str 的值，并将 str 的值返回栈顶（替换 str） * 如果存在相同命名的其他变量、table 或函数，就会报错（读取位置发生访问冲突） */ lua_getglobal(L, &quot;str&quot;); // 通过索引 -1 取出栈顶元素，转化为 C++ 的 string 类型 string str = lua_tostring(L, -1); cout &lt;&lt; &quot;str = &quot; &lt;&lt; str.c_str() &lt;&lt; endl; // 读取 table lua_getglobal(L, &quot;tbl&quot;); // 使用栈顶（-1）的 table 获取 table 中键为 name 的值，将其返回栈顶，替换掉 name lua_getfield(L, -1, &quot;name&quot;); // 也可以使用下面的写法，先把 name 压入栈中，然后此时 table 元素在 -2 位置，使用 lua_gettable 获取对应值 //lua_pushstring(L, &quot;name&quot;); //lua_gettable(L, -2); // 获取栈顶的 name 值 str = lua_tostring(L, -1); // 因为此时 table 在栈顶的下面，所以取 -2，把 id 压栈，由 Lua 找到 table 中 id 键的值，并返回栈顶（替换id） lua_getfield(L, -2, &quot;id&quot;); // 获取 id 的值，此时 id 在栈顶，所以取 -1 int id = lua_tonumber(L, -1); cout &lt;&lt; &quot;tbl:name = &quot; &lt;&lt; str.c_str() &lt;&lt; endl; cout &lt;&lt; &quot;tbl:id = &quot; &lt;&lt; id &lt;&lt; endl; // 读取函数 // 将函数 add 放入栈中，由 Lua 去寻找名为 add 的函数，并将该函数返回栈顶（替换add） lua_getglobal(L, &quot;add&quot;); // 分别将函数参数压入栈中 lua_pushnumber(L, 10); lua_pushnumber(L, 20); // 调用函数，调用完成以后，会将返回值压入栈中，2 表示参数个数，1 表示返回结果个数 // 栈中的过程：参数出栈-&gt;保存参数-&gt;参数出栈-&gt;保存参数-&gt;函数出栈-&gt;调用函数-&gt;返回结果入栈 int iRet = lua_pcall(L, 2, 1, 0); if (iRet) // 返回值为 0 表示调用成功 &#123; // 取出错误信息 const char* pErrorMsg = lua_tostring(L, -1); cout &lt;&lt; pErrorMsg &lt;&lt; endl; lua_close(L); return -1; &#125; if (lua_isnumber(L, -1)) // 取值输出 &#123; int fValue = lua_tonumber(L, -1); cout &lt;&lt; &quot;Result is &quot; &lt;&lt; fValue &lt;&lt; endl; &#125; //至此，栈中的情况是： //=================== 栈顶 =================== // 索引 类型 值 // 5或-1 int 30 // 4或-2 int 2020262914 // 3或-3 string LYC // 2或-4 table tbl // 1或-5 string Test Lua script. //=================== 栈底 =================== // push 一个 string lua_pushstring(L, &quot;Master&quot;); // 修改 table 中的键值，注意索引值的使用，此时使用正向索引，因为 1 永远表示栈底元素 // 会将&quot;Master&quot;值出栈，保存值，找到到 table 的 name 键，如果键存在，存储到 name 键中 lua_setfield(L, 2, &quot;name&quot;); // 读取 lua_getfield(L, 2, &quot;name&quot;); str = lua_tostring(L, -1); cout &lt;&lt; &quot;tbl:name = &quot; &lt;&lt; str.c_str() &lt;&lt; endl; // 创建新的 table lua_newtable(L); lua_pushstring(L, &quot;A New Table&quot;); lua_setfield(L, -2, &quot;name&quot;); // 读取 lua_getfield(L, -1, &quot;name&quot;); str = lua_tostring(L, -1); cout &lt;&lt; &quot;newtbl:name = &quot; &lt;&lt; str.c_str() &lt;&lt; endl; // 关闭state，会销毁指定 Lua 状态机中的所有对象， 并且释放状态机中使用的所有动态内存。 lua_close(L); return 0;&#125;
输出：
当我们修改 Lua 脚本的内容： str = &quot;A new Lua script.&quot;tbl = &#123;name = &quot;New&quot;, id = 6666666&#125;function add(a, b) for i = 10, 1, -1 do a = a + b end return aend
重新运行的结果：
4 Lua 调用 C++ 函数Lua 中使用 C++ 函数的一般步骤是：
将 C++ 函数包装成 Lua 环境认可的 Lua_CFunction 格式 将包装好的函数注册到 Lua 环境中 像使用普通 Lua 函数那样使用注册函数
Lua_CFunction 的基本格式如下： static int xxxxx(lua_State *L) &#123; // 函数功能 return 一个数字;&#125;
函数的返回值代表函数返回结果的个数，而要获取参数则是通过将栈中某个位置的元素转换成 C++ 数据类型来实现，比如一个 3 个输入参数，2 个返回值的函数实现为： static int average(lua_State *L)&#123; /* 得到参数个数 */ int n = lua_gettop(L); double sum = 0; int i; /* 循环求参数之和 */ for (i = 1; i &lt;= n; i++) &#123; /* 求和 */ sum += lua_tonumber(L, i); &#125; /* 压入平均值 */ lua_pushnumber(L, sum / n); /* 压入和 */ lua_pushnumber(L, sum); /* 返回返回值的个数 */ return 2;&#125;
然后将其注册到 Lua 环境中： // 第二个参数为 Lua 中的函数名称，第三个参数为 C++ 中的函数指针lua_register(L, &quot;func&quot;, average);
之后我们编写一个 Lua 脚本： --全局变量，在C++中赋值，Lua中直接使用print(&quot;age&quot;, age)--新表，在C++中赋值，Lua中直接使用for k,v in pairs(newTable) do print(&quot;k = &quot;,k,&quot; v = &quot;,v)endprint(&quot;name&quot;, newTable.name)--直接调用C++中的函数avg, sum = func(10, 20, 30, 40, 50)print(&quot;The average is &quot;, avg)print(&quot;The sum is &quot;, sum)
接下来是 C++ 部分： #include &lt;iostream&gt;#include &lt;string.h&gt;#include &quot;lua.hpp&quot;using namespace std;static int average(lua_State* L)&#123; /* 得到参数个数 */ int n = lua_gettop(L); double sum = 0; int i; /* 循环求参数之和 */ for (i = 1; i &lt;= n; i++) &#123; /* 求和 */ sum += lua_tonumber(L, i); &#125; /* 压入平均值 */ lua_pushnumber(L, sum / n); /* 压入和 */ lua_pushnumber(L, sum); /* 返回返回值的个数 */ return 2;&#125;int main()&#123; lua_State* L = luaL_newstate(); /* 载入Lua基本库 */ luaL_openlibs(L); /* 注册函数 */ lua_register(L, &quot;func&quot;, average); // 设置 Lua 中的全局变量 lua_pushinteger(L, 18); // 入栈 lua_setglobal(L, &quot;age&quot;); // 1.先将18值出栈，保存值，2.在Lua中，把值存储到全局变量age中 // 设置 Lua 中的 table lua_newtable(L); //创建一张空表，并将其压栈 lua_pushstring(L, &quot;lili&quot;);// 入栈 lua_setfield(L, -2, &quot;name&quot;);//栈顶是lili，新创建的table在lili下，所以是-2，赋值后lili出栈 // table出栈，保存到Lua中的newTable变量中 lua_setglobal(L, &quot;newTable&quot;); /* 运行脚本 */ luaL_dofile(L, &quot;test.lua&quot;); /* 清除Lua */ lua_close(L); return 0;&#125;
运行结果：
5 Lua 调用 C++ 函数模块当 Lua 中需要调用多个 C++ 函数时，可以将这些函数封装成一个模块，模块实际上是一个 table，然后使用 luaL_newlib 就可以将该模块压入栈中，之后将自定义的模块注册到 Lua 环境中就可以使用了。 依然以上面的函数为例： #include &lt;iostream&gt;#include &lt;string.h&gt;#include &quot;lua.hpp&quot;using namespace std;static int average(lua_State* L)&#123; /* 得到参数个数 */ int n = lua_gettop(L); double sum = 0; int i; /* 循环求参数之和 */ for (i = 1; i &lt;= n; i++) &#123; /* 求和 */ sum += lua_tonumber(L, i); &#125; /* 压入平均值 */ lua_pushnumber(L, sum / n); /* 压入和 */ lua_pushnumber(L, sum); /* 返回返回值的个数 */ return 2;&#125;// 列出需要封装的C++函数，luaL_Reg 为 Lua 中注册函数的数组类型static const luaL_Reg mylibs_funcs[] = &#123; &#123; &quot;func&quot;, average &#125;, &#123; NULL, NULL &#125;&#125;;// 将所有函数放到一个table中，并压入栈中，直接使用 luaL_newlib 即可int lua_openmylib(lua_State* L) &#123; // luaL_newlib的内部实现为： // 创建一个新的表，将所有函数放到一个 table 中，将这个table压到stack里 luaL_newlib(L, mylibs_funcs); return 1;&#125;// 将自定义模块加到注册列表里static const luaL_Reg lua_reg_libs[] = &#123; &#123; &quot;base&quot;, luaopen_base &#125;, &#123; &quot;mylib&quot;, lua_openmylib &#125;, &#123; NULL, NULL &#125;&#125;;int main(int argc, char* argv[])&#123; lua_State* L = luaL_newstate(); luaL_openlibs(L); // 注册让 Lua 使用的模块 const luaL_Reg* lua_reg = lua_reg_libs; for (; lua_reg-&gt;func; ++lua_reg) &#123; // 加载模块 // 首先查找 package.loaded 表， 检测 modname 是否被加载过。 // 如果被加载过，require 返回 package.loaded[modname] 中保存的值。 // 如果 modname 不在 package.loaded 中， 则调用函数 openf ，并传入字符串 modname。 // 将其返回值置入 package.loaded[modname]。 // 如果最后一个参数为真， 同时也将模块设到全局变量 modname 里。在栈上留下该模块的副本。 luaL_requiref(L, lua_reg-&gt;name, lua_reg-&gt;func, 1); // 从栈中弹出 1 个元素 lua_pop(L, 1); &#125; /* 运行脚本 */ luaL_dofile(L, &quot;test.lua&quot;); lua_close(L); return 0;&#125;
在 Lua 中使用自定义模块中的函数时需要加上模块名字： --调用C++自定义模块中的函数avg, sum = mylib.func(10, 20, 30, 40, 50)print(&quot;The average is &quot;, avg)print(&quot;The sum is &quot;, sum)
运行结果：
6 Lua 以模块形式使用 C++ 类Lua 中还可以调用 C++ 中的类。我们可以将 C++ 中的类封装成函数模块，供 Lua 使用。 例如一个 Student 类：
Student.h
#pragma once#include &lt;iostream&gt;#include &lt;string&gt;using namespace std;class Student&#123;public: Student(); ~Student(); string get_name(); void set_name(string name); unsigned int get_age(); void set_age(unsigned int age); void print();private: string _name; unsigned int _age;&#125;;
Student.cpp
#include &quot;Student.h&quot;using namespace std;Student::Student() :_name(&quot;Empty&quot;), _age(0)&#123; cout &lt;&lt; &quot;Student Constructor&quot; &lt;&lt; endl;&#125;Student::~Student()&#123; cout &lt;&lt; &quot;Student Destructor&quot; &lt;&lt; endl;&#125;string Student::get_name()&#123; return _name;&#125;void Student::set_name(string name)&#123; _name = name;&#125;unsigned int Student::get_age()&#123; return _age;&#125;void Student::set_age(unsigned int age)&#123; _age = age;&#125;void Student::print()&#123; cout &lt;&lt; &quot;name :&quot; &lt;&lt; _name &lt;&lt; &quot; age : &quot; &lt;&lt; _age &lt;&lt; endl;&#125;
然后我们需要将这个类的各种方法以及创建这个类对象的方法注册成为 Lua 的全局函数：
StudentRegFunc.h
#pragma once#include &quot;Student.h&quot;#include &quot;lua.hpp&quot;//------定义相关的全局函数------//创建对象int lua_create_new_student(lua_State* L);//get/set函数int lua_get_name(lua_State* L);int lua_set_name(lua_State* L);int lua_get_age(lua_State* L);int lua_set_age(lua_State* L);//打印函数int lua_print(lua_State* L);//------注册全局函数供Lua使用------static const luaL_Reg lua_reg_student_funcs[] = &#123; &#123; &quot;create&quot;, lua_create_new_student &#125;, &#123; &quot;get_name&quot;, lua_get_name &#125;, &#123; &quot;set_name&quot;, lua_set_name &#125;, &#123; &quot;get_age&quot;, lua_get_age &#125;, &#123; &quot;set_age&quot;, lua_set_age &#125;, &#123; &quot;print&quot;, lua_print &#125;, &#123; NULL, NULL &#125;,&#125;;int luaopen_student_libs(lua_State* L);
StudentRegFunc.cpp
#include &quot;StudentRegFunc.h&quot;int lua_create_new_student(lua_State* L)&#123; //创建一个对象指针放到stack里，返回给Lua中使用 Student** s = (Student**)lua_newuserdata(L, sizeof(Student*)); *s = new Student(); return 1;&#125;int lua_get_name(lua_State* L)&#123; //得到第一个传入的对象参数（在stack最底部） Student** s = (Student**)lua_touserdata(L, 1); luaL_argcheck(L, s != NULL, 1, &quot;invalid user data&quot;); //清空stack lua_settop(L, 0); //将数据放入stack中，供Lua使用 lua_pushstring(L, (*s)-&gt;get_name().c_str()); return 1;&#125;int lua_set_name(lua_State* L)&#123; //得到第一个传入的对象参数 Student** s = (Student**)lua_touserdata(L, 1); luaL_argcheck(L, s != NULL, 1, &quot;invalid user data&quot;); //检查当前栈顶元素是否符合类型要求 luaL_checktype(L, -1, LUA_TSTRING); std::string name = lua_tostring(L, -1); (*s)-&gt;set_name(name); return 0;&#125;int lua_get_age(lua_State* L)&#123; Student** s = (Student**)lua_touserdata(L, 1); luaL_argcheck(L, s != NULL, 1, &quot;invalid user data&quot;); lua_pushinteger(L, (*s)-&gt;get_age()); return 1;&#125;int lua_set_age(lua_State* L)&#123; Student** s = (Student**)lua_touserdata(L, 1); luaL_argcheck(L, s != NULL, 1, &quot;invalid user data&quot;); luaL_checktype(L, -1, LUA_TNUMBER); (*s)-&gt;set_age((unsigned int)lua_tointeger(L, -1)); return 0;&#125;int lua_print(lua_State* L)&#123; Student** s = (Student**)lua_touserdata(L, 1); luaL_argcheck(L, s != NULL, 1, &quot;invalid user data&quot;); (*s)-&gt;print(); return 0;&#125;int luaopen_student_libs(lua_State* L)&#123; // 创建一张新的表，并把列表的函数注册进去 luaL_newlib(L, lua_reg_student_funcs); return 1;&#125;
然后来编写脚本： --调用由C++类封装成的模块--创建Student对象local student_obj = Student.create()--调用对象的函数Student.print(student_obj)Student.set_name(student_obj,&quot;Jack&quot;)Student.set_age(student_obj,25)Student.print(student_obj)
最后是主函数： #include &lt;iostream&gt;#include &lt;string.h&gt;#include &quot;Student.h&quot;#include &quot;StudentRegFunc.h&quot;#include &quot;lua.hpp&quot;using namespace std;static const luaL_Reg lua_reg_libs[] = &#123; &#123; &quot;base&quot;, luaopen_base &#125;, //基础模块 &#123; &quot;Student&quot;, luaopen_student_libs&#125;, //自定义Student模块，注册函数是luaopen_student_libs &#123; NULL, NULL &#125;&#125;;int main(int argc, char* argv[])&#123; if (lua_State* L = luaL_newstate()) &#123; //注册让lua使用的库 const luaL_Reg* lua_reg = lua_reg_libs; for (; lua_reg-&gt;func; ++lua_reg) &#123; luaL_requiref(L, lua_reg-&gt;name, lua_reg-&gt;func, 1); lua_pop(L, 1); &#125; //加载脚本，如果出错，则打印错误 if (luaL_dofile(L, &quot;test.lua&quot;)) &#123; cout &lt;&lt; lua_tostring(L, -1) &lt;&lt; endl; &#125; lua_close(L); &#125; else &#123; cout &lt;&lt; &quot;luaL_newstate error !&quot; &lt;&lt; endl; &#125; return 0;&#125;
运行结果：
7 Lua 以面向对象方式使用 C++ 类上述将 C++ 类注册为函数模块的形式有一个严重的问题，那就是我们无法保证 userdata 的合法性。因为在 C++ 中，我们只是简单的判断了一下传进来的 userdata 是否为 NULL，并没有办法判断传进来的 userdata 参数是通过 Student.create 函数得到的，如果我传一个错误的 userdata 进去，程序也会继续运行，但有可能使内存遭到破坏。 一种可行的方案是，为每种类型创建一个唯一的元表。每当创建了一个 userdata 后，就用相应的元表来标记它。而每当得到一个 userdata 后，就检查它是否拥有正确的元表。由于 Lua 代码不能改变 userdata 的元表，因此也就无法传一个错误的 userdata 进去。 为每个 userdata 都创建一个元表，那就需要有个地方来存储这个新的元表。在 Lua 中，通常习惯是将所有新的 C++ 类型注册到注册表中，以一个类型名作为 key，元表作为 value。由于注册表中还有其它的内容，所以必须小心地选择类型名，以避免与 key 冲突。 具体的实现可以查看：Lua和C++交互：在Lua中以面向对象的方式使用C++注册的类 8 Lua 与 C++ 全局数组交互具体查看：Lua和C++交互：全局数组交互 9 常用 API 总结9.1 虚拟栈基本操作int lua_gettop (lua_State *L); //返回栈顶索引（即栈长度）// lua_settop将栈顶设置为一个指定的位置，即修改栈中元素的数量。// 如果值比原栈顶高，则高的部分nil补足，如果值比原栈低，则原栈高出的部分舍弃。// 所以可以用lua_settop(0)来清空栈。void lua_settop (lua_State *L, int idx); void lua_pushvalue (lua_State *L, int idx); //将idx索引上的值的副本压入栈顶void lua_remove (lua_State *L, int idx); //移除idx索引上的值void lua_insert (lua_State *L, int idx); //弹出栈顶元素，并插入索引idx位置void lua_replace (lua_State *L, int idx); //弹出栈顶元素，并替换索引idx位置的值// 确保堆栈上至少有 n 个额外空位。 如果不能把堆栈扩展到相应的尺寸，// 函数返回假。 失败的原因包括将把栈扩展到比固定最大尺寸还大 （至少是几// 千个元素）或分配内存失败。 这个函数永远不会缩小堆栈； 如果堆栈已经// 比需要的大了，那么就保持原样int lua_checkstack (lua_State *L, int n);
